#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum DebugNodeStyleCompareCategory {
    Content,
    Geometry,
    Layout,
    Visual,
    Input,
    Scroll,
    Paint,
    Accessibility,
}

impl DebugNodeStyleCompareCategory {
    pub const fn label(self) -> &'static str {
        match self {
            Self::Content => "content",
            Self::Geometry => "geometry",
            Self::Layout => "layout",
            Self::Visual => "visual",
            Self::Input => "input",
            Self::Scroll => "scroll",
            Self::Paint => "paint",
            Self::Accessibility => "accessibility",
        }
    }

    pub const fn title(self) -> &'static str {
        match self {
            Self::Content => "Content",
            Self::Geometry => "Geometry",
            Self::Layout => "Layout",
            Self::Visual => "Visual",
            Self::Input => "Input",
            Self::Scroll => "Scroll",
            Self::Paint => "Paint",
            Self::Accessibility => "Accessibility",
        }
    }
}

