#[derive(Debug, Clone, PartialEq)]
pub struct DebugNodeStyleCompareTrace {
    pub left_node: UiNodeId,
    pub right_node: UiNodeId,
    pub left_name: String,
    pub right_name: String,
    pub status: DebugFrameTraceStatus,
    pub difference_count: usize,
    pub content_difference_count: usize,
    pub geometry_difference_count: usize,
    pub layout_difference_count: usize,
    pub visual_difference_count: usize,
    pub input_difference_count: usize,
    pub scroll_difference_count: usize,
    pub paint_difference_count: usize,
    pub accessibility_difference_count: usize,
    pub records: Vec<DebugNodeStyleCompareRecord>,
    pub summary: String,
}

impl DebugNodeStyleCompareTrace {
    pub fn from_snapshot(
        snapshot: &DebugInspectorSnapshot,
        left_name: &str,
        right_name: &str,
    ) -> Option<Self> {
        let left = snapshot.node(left_name)?;
        let right = snapshot.node(right_name)?;
        Some(Self::from_nodes(left, right))
    }

    pub fn from_nodes(left: &DebugLayoutInspectorNode, right: &DebugLayoutInspectorNode) -> Self {
        let records = debug_node_style_compare_records(left, right);
        let content_difference_count = debug_node_style_compare_category_count(
            &records,
            DebugNodeStyleCompareCategory::Content,
        );
        let geometry_difference_count = debug_node_style_compare_category_count(
            &records,
            DebugNodeStyleCompareCategory::Geometry,
        );
        let layout_difference_count = debug_node_style_compare_category_count(
            &records,
            DebugNodeStyleCompareCategory::Layout,
        );
        let visual_difference_count = debug_node_style_compare_category_count(
            &records,
            DebugNodeStyleCompareCategory::Visual,
        );
        let input_difference_count =
            debug_node_style_compare_category_count(&records, DebugNodeStyleCompareCategory::Input);
        let scroll_difference_count = debug_node_style_compare_category_count(
            &records,
            DebugNodeStyleCompareCategory::Scroll,
        );
        let paint_difference_count =
            debug_node_style_compare_category_count(&records, DebugNodeStyleCompareCategory::Paint);
        let accessibility_difference_count = debug_node_style_compare_category_count(
            &records,
            DebugNodeStyleCompareCategory::Accessibility,
        );
        let difference_count = records.len();
        let status = if records.is_empty() {
            DebugFrameTraceStatus::Ok
        } else {
            DebugFrameTraceStatus::Info
        };
        let summary = debug_node_style_compare_summary(
            status,
            difference_count,
            layout_difference_count,
            geometry_difference_count,
            visual_difference_count,
            input_difference_count,
        );

        Self {
            left_node: left.id,
            right_node: right.id,
            left_name: left.name.clone(),
            right_name: right.name.clone(),
            status,
            difference_count,
            content_difference_count,
            geometry_difference_count,
            layout_difference_count,
            visual_difference_count,
            input_difference_count,
            scroll_difference_count,
            paint_difference_count,
            accessibility_difference_count,
            records,
            summary,
        }
    }

    pub fn is_empty(&self) -> bool {
        self.records.is_empty()
    }

    pub fn record(&self, field: &str) -> Option<&DebugNodeStyleCompareRecord> {
        self.records.iter().find(|record| record.field == field)
    }
}

