#[derive(Debug, Clone, PartialEq)]
pub struct DebugAnimationActivityTrace {
    pub status: DebugFrameTraceStatus,
    pub animation_count: usize,
    pub active_count: usize,
    pub warning_count: usize,
    pub records: Vec<DebugAnimationActivityRecord>,
    pub summary: String,
}

impl DebugAnimationActivityTrace {
    pub fn from_document(document: &UiDocument, text_measurer: &mut impl TextMeasurer) -> Self {
        let snapshot = DebugInspectorSnapshot::from_document(document, text_measurer);
        Self::from_snapshot(&snapshot)
    }

    pub fn from_snapshot(snapshot: &DebugInspectorSnapshot) -> Self {
        let mut records = snapshot
            .animations
            .iter()
            .map(debug_animation_activity_record)
            .collect::<Vec<_>>();
        records.sort_by(|left, right| {
            debug_animation_activity_status_rank(left.status)
                .cmp(&debug_animation_activity_status_rank(right.status))
                .then_with(|| right.score.cmp(&left.score))
                .then_with(|| left.name.cmp(&right.name))
        });
        let active_count = records
            .iter()
            .filter(|record| record.active_transition.is_some() || record.active_edge_count > 0)
            .count();
        let warning_count = records
            .iter()
            .filter(|record| {
                matches!(
                    record.status,
                    DebugFrameTraceStatus::Warning | DebugFrameTraceStatus::Error
                )
            })
            .count();
        let status = debug_animation_activity_trace_status(&records);
        let summary = debug_animation_activity_trace_summary(
            status,
            records.len(),
            active_count,
            warning_count,
        );
        Self {
            status,
            animation_count: records.len(),
            active_count,
            warning_count,
            records,
            summary,
        }
    }

    pub fn record(&self, name: &str) -> Option<&DebugAnimationActivityRecord> {
        self.records.iter().find(|record| record.name == name)
    }
}

