#[derive(Debug, Clone, PartialEq)]
pub struct DebugAccessibilityTreeTrace {
    pub node_count: usize,
    pub focusable_count: usize,
    pub warning_count: usize,
    pub modal_scope: Option<UiNodeId>,
    pub modal_scope_name: Option<String>,
    pub nodes: Vec<DebugAccessibilityTreeNode>,
    pub summary: String,
}

impl DebugAccessibilityTreeTrace {
    pub fn from_snapshot(snapshot: &DebugInspectorSnapshot) -> Self {
        let nodes = snapshot
            .accessibility_overlay
            .iter()
            .map(|node| debug_accessibility_tree_node(snapshot, node))
            .collect::<Vec<_>>();
        let node_count = nodes.len();
        let focusable_count = nodes.iter().filter(|node| node.focusable).count();
        let warning_count = nodes.iter().filter(|node| node.warning_count > 0).count();
        let modal_scope = snapshot.accessibility_overlay.iter().find_map(|node| {
            let accessibility = node.accessibility.as_ref()?;
            (accessibility.modal && accessibility.enabled).then_some(node.id)
        });
        let modal_scope_name = modal_scope.and_then(|id| debug_snapshot_name(snapshot, id));
        let summary = if warning_count == 0 {
            format!("{node_count} accessibility nodes; {focusable_count} focusable; no warnings")
        } else {
            format!(
                "{node_count} accessibility nodes; {focusable_count} focusable; {warning_count} warning nodes"
            )
        };
        Self {
            node_count,
            focusable_count,
            warning_count,
            modal_scope,
            modal_scope_name,
            nodes,
            summary,
        }
    }

    pub fn node(&self, name: &str) -> Option<&DebugAccessibilityTreeNode> {
        self.nodes.iter().find(|node| node.name == name)
    }
}

