#[derive(Debug, Clone, PartialEq)]
pub struct DebugVisualEffectTrace {
    pub selected: Option<UiNodeId>,
    pub selected_name: Option<String>,
    pub effect_count: usize,
    pub issue_count: usize,
    pub records: Vec<DebugVisualEffectRecord>,
    pub summary: String,
}

impl DebugVisualEffectTrace {
    pub fn from_snapshot(snapshot: &DebugInspectorSnapshot, selected_name: Option<&str>) -> Self {
        let selected_node = selected_name.and_then(|name| snapshot.node(name));
        let selected = selected_node.map(|node| node.id);
        let selected_name = selected_node.map(|node| node.name.clone());
        let nodes = snapshot
            .nodes
            .iter()
            .map(|node| (node.id, node))
            .collect::<HashMap<_, _>>();
        let mut records = snapshot
            .hitboxes
            .iter()
            .filter_map(|hitbox| {
                let node = nodes.get(&hitbox.id)?;
                let record = debug_visual_effect_record(node, hitbox);
                (debug_visual_effect_record_relevant(&record) || selected == Some(hitbox.id))
                    .then_some(record)
            })
            .collect::<Vec<_>>();
        records.sort_by(|left, right| {
            (selected != Some(left.id))
                .cmp(&(selected != Some(right.id)))
                .then_with(|| {
                    debug_visual_effect_status_rank(left.status)
                        .cmp(&debug_visual_effect_status_rank(right.status))
                })
                .then_with(|| left.order.cmp(&right.order))
                .then_with(|| left.id.0.cmp(&right.id.0))
        });
        let effect_count = records.len();
        let issue_count = records
            .iter()
            .filter(|record| {
                matches!(
                    record.status,
                    DebugFrameTraceStatus::Warning | DebugFrameTraceStatus::Error
                )
            })
            .count();
        let summary = debug_visual_effect_trace_summary(effect_count, issue_count);
        Self {
            selected,
            selected_name,
            effect_count,
            issue_count,
            records,
            summary,
        }
    }

    pub fn record(&self, name: &str) -> Option<&DebugVisualEffectRecord> {
        self.records.iter().find(|record| record.name == name)
    }
}

