#[derive(Debug, Clone, PartialEq)]
pub struct DebugBoundsAutopsyTrace {
    pub node: UiNodeId,
    pub name: String,
    pub status: DebugFrameTraceStatus,
    pub layout_rect: UiRect,
    pub transformed_rect: UiRect,
    pub clip_rect: UiRect,
    pub visible_rect: Option<UiRect>,
    pub paint_rect: Option<UiRect>,
    pub hit_rect: Option<UiRect>,
    pub declared_visual_outset: f32,
    pub measured_paint_outset: DebugRectOutset,
    pub measured_hit_outset: DebugRectOutset,
    pub warning_count: usize,
    pub records: Vec<DebugBoundsAutopsyRecord>,
    pub summary: String,
}

impl DebugBoundsAutopsyTrace {
    pub fn from_document(
        document: &UiDocument,
        text_measurer: &mut impl TextMeasurer,
        selected_name: Option<&str>,
    ) -> Option<Self> {
        let snapshot = DebugInspectorSnapshot::from_document(document, text_measurer);
        Self::from_snapshot(&snapshot, selected_name)
    }

    pub fn from_snapshot(
        snapshot: &DebugInspectorSnapshot,
        selected_name: Option<&str>,
    ) -> Option<Self> {
        let selected_id = selected_name
            .and_then(|name| snapshot.node(name).map(|node| node.id))
            .or_else(|| selected_name.and_then(|name| snapshot.hitbox(name).map(|node| node.id)))
            .or_else(|| debug_bounds_autopsy_default_id(snapshot))?;
        let node = snapshot.node_by_id(selected_id)?;
        let hitbox = snapshot.hitbox_by_id(selected_id);
        Some(Self::from_parts(node, hitbox))
    }

    pub fn from_parts(node: &DebugLayoutInspectorNode, hitbox: Option<&DebugHitboxNode>) -> Self {
        let effect = hitbox.map(|hitbox| debug_visual_effect_record(node, hitbox));
        let transformed_rect = hitbox
            .map(|hitbox| hitbox.transformed_rect)
            .unwrap_or(node.rect);
        let clip_rect = hitbox
            .map(|hitbox| hitbox.clip_rect)
            .unwrap_or(node.clip_rect);
        let visible_rect = hitbox.and_then(|hitbox| hitbox.visible_rect);
        let paint_rect = hitbox.and_then(|hitbox| hitbox.paint_rect);
        let hit_rect = hitbox.and_then(|hitbox| hitbox.hit_rect);
        let declared_visual_outset = effect
            .as_ref()
            .map(|effect| effect.declared_visual_outset)
            .unwrap_or_else(|| {
                node.visual
                    .material_visual_outset
                    .max(node.visual.shader_visual_outset)
            });
        let measured_paint_outset = effect
            .as_ref()
            .map(|effect| effect.measured_paint_outset)
            .unwrap_or_default();
        let measured_hit_outset = effect
            .as_ref()
            .map(|effect| effect.measured_hit_outset)
            .unwrap_or_default();
        let records = vec![
            debug_bounds_autopsy_layout_record(node),
            debug_bounds_autopsy_transformed_record(node, hitbox),
            debug_bounds_autopsy_clip_record(node, hitbox, transformed_rect, clip_rect),
            debug_bounds_autopsy_visible_record(node, hitbox, transformed_rect),
            debug_bounds_autopsy_paint_record(node, hitbox, effect.as_ref()),
            debug_bounds_autopsy_hit_record(node, hitbox, effect.as_ref()),
            debug_bounds_autopsy_effect_record(node, effect.as_ref(), declared_visual_outset),
        ];
        finish_debug_bounds_autopsy_trace(
            node,
            transformed_rect,
            clip_rect,
            visible_rect,
            paint_rect,
            hit_rect,
            declared_visual_outset,
            measured_paint_outset,
            measured_hit_outset,
            records,
        )
    }

    pub fn record(&self, source: DebugBoundsAutopsySource) -> Option<&DebugBoundsAutopsyRecord> {
        self.records.iter().find(|record| record.source == source)
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct DebugInspectorSnapshot {
    pub nodes: Vec<DebugLayoutInspectorNode>,
    pub animations: Vec<DebugAnimationInspectorNode>,
    pub hitboxes: Vec<DebugHitboxNode>,
    pub overlaps: Vec<DebugOverlapRecord>,
    pub constraints: Vec<DebugConstraintIssue>,
    pub accessibility_overlay: Vec<DebugAccessibilityOverlayNode>,
    pub audits: Vec<AuditWarning>,
}

impl DebugInspectorSnapshot {
    pub fn from_document(document: &UiDocument, text_measurer: &mut impl TextMeasurer) -> Self {
        let layout = document.layout_snapshot();
        let paint = document.paint_list();
        let paint_stats = paint_stats_by_node(&paint);
        let accessibility = document.accessibility_snapshot();
        let accessibility_by_node = accessibility
            .nodes
            .iter()
            .cloned()
            .map(|node| (node.id, node))
            .collect::<HashMap<_, _>>();
        let focus_order = accessibility
            .focus_order
            .iter()
            .copied()
            .enumerate()
            .map(|(index, id)| (id, index))
            .collect::<HashMap<_, _>>();
        let audits = document.audit_layout();
        let audits_by_node = audits_by_node(&audits);

        let mut nodes = Vec::new();
        collect_layout_inspector_nodes(
            document,
            &layout,
            &paint_stats,
            &accessibility_by_node,
            &audits_by_node,
            text_measurer,
            &mut nodes,
        );

        let animations = document
            .nodes()
            .iter()
            .enumerate()
            .filter_map(|(index, node)| {
                let animation = node.animation.as_ref()?;
                Some(DebugAnimationInspectorNode {
                    id: UiNodeId(index),
                    name: node.name.clone(),
                    current_state: animation.current_state_name().to_owned(),
                    values: animation.values(),
                    active_transition: animation.active_transition(),
                    inputs: sorted_animation_inputs(animation.inputs()),
                    states: animation.states().to_vec(),
                    transitions: animation.transitions().to_vec(),
                    blend_bindings: animation.blend_bindings().to_vec(),
                })
            })
            .collect::<Vec<_>>();

        let accessibility_overlay = nodes
            .iter()
            .filter(|node| {
                node.accessibility.is_some()
                    || !node.audit_warnings.is_empty()
                    || focus_order.contains_key(&node.id)
            })
            .map(|node| DebugAccessibilityOverlayNode {
                id: node.id,
                name: node.name.clone(),
                rect: node.rect,
                focus_index: focus_order.get(&node.id).copied(),
                accessibility: node.accessibility.clone(),
                warnings: node.audit_warnings.clone(),
            })
            .collect();

        let overlap_report = DebugOverlapReport::from_document(document);
        let constraints = DebugConstraintReport::from_parts(
            &audits,
            &overlap_report.nodes,
            &overlap_report.overlaps,
        )
        .issues;

        Self {
            nodes,
            animations,
            hitboxes: overlap_report.nodes,
            overlaps: overlap_report.overlaps,
            constraints,
            accessibility_overlay,
            audits,
        }
    }

    pub fn node(&self, name: &str) -> Option<&DebugLayoutInspectorNode> {
        self.nodes.iter().find(|node| node.name == name)
    }

    pub fn animation(&self, name: &str) -> Option<&DebugAnimationInspectorNode> {
        self.animations
            .iter()
            .find(|animation| animation.name == name)
    }

    pub fn hitbox(&self, name: &str) -> Option<&DebugHitboxNode> {
        self.hitboxes.iter().find(|hitbox| hitbox.name == name)
    }

    pub fn node_by_id(&self, id: UiNodeId) -> Option<&DebugLayoutInspectorNode> {
        self.nodes.iter().find(|node| node.id == id)
    }

    pub fn hitbox_by_id(&self, id: UiNodeId) -> Option<&DebugHitboxNode> {
        self.hitboxes.iter().find(|hitbox| hitbox.id == id)
    }

    pub fn overlaps_for(&self, id: UiNodeId) -> impl Iterator<Item = &DebugOverlapRecord> {
        self.overlaps
            .iter()
            .filter(move |overlap| overlap.back.id == id || overlap.front.id == id)
    }
}

