#[derive(Debug, Clone, PartialEq)]
pub struct DebugLayoutTree {
    pub root: Option<UiNodeId>,
    pub nodes: Vec<DebugLayoutTreeNode>,
    pub max_depth: usize,
    pub issue_count: usize,
    pub summary: String,
}

impl DebugLayoutTree {
    pub fn from_snapshot(snapshot: &DebugInspectorSnapshot) -> Self {
        let by_id = snapshot
            .nodes
            .iter()
            .map(|node| (node.id, node))
            .collect::<HashMap<_, _>>();
        let root = snapshot
            .nodes
            .iter()
            .find(|node| node.parent.is_none())
            .map(|node| node.id);
        let nodes = snapshot
            .nodes
            .iter()
            .map(|node| debug_layout_tree_node(snapshot, node, &by_id))
            .collect::<Vec<_>>();
        let max_depth = nodes.iter().map(|node| node.depth).max().unwrap_or(0);
        let issue_count = nodes
            .iter()
            .filter(|node| {
                matches!(
                    node.status,
                    DebugFrameTraceStatus::Warning | DebugFrameTraceStatus::Error
                )
            })
            .count();
        let summary = if nodes.is_empty() {
            "empty layout tree".to_owned()
        } else if issue_count == 0 {
            format!("{} layout nodes; no issues", nodes.len())
        } else {
            format!(
                "{} layout nodes; {} nodes need review; max depth {}",
                nodes.len(),
                issue_count,
                max_depth
            )
        };
        Self {
            root,
            nodes,
            max_depth,
            issue_count,
            summary,
        }
    }

    pub fn node(&self, name: &str) -> Option<&DebugLayoutTreeNode> {
        self.nodes.iter().find(|node| node.name == name)
    }
}

