#[derive(Debug, Clone, PartialEq)]
pub struct DebugNodeHotspotTrace {
    pub status: DebugFrameTraceStatus,
    pub node_count: usize,
    pub record_count: usize,
    pub warning_count: usize,
    pub max_score: u32,
    pub records: Vec<DebugNodeHotspotRecord>,
    pub summary: String,
}

impl DebugNodeHotspotTrace {
    pub fn from_document(document: &UiDocument, text_measurer: &mut impl TextMeasurer) -> Self {
        let snapshot = DebugInspectorSnapshot::from_document(document, text_measurer);
        Self::from_snapshot(&snapshot)
    }

    pub fn from_snapshot(snapshot: &DebugInspectorSnapshot) -> Self {
        let descendant_counts = debug_hotspot_descendant_counts(snapshot);
        let mut records = snapshot
            .nodes
            .iter()
            .filter_map(|node| debug_node_hotspot_record(snapshot, node, &descendant_counts))
            .collect::<Vec<_>>();
        records.sort_by(|left, right| {
            debug_hotspot_status_rank(left.status)
                .cmp(&debug_hotspot_status_rank(right.status))
                .then_with(|| right.score.cmp(&left.score))
                .then_with(|| left.name.cmp(&right.name))
        });
        let warning_count = records
            .iter()
            .filter(|record| {
                matches!(
                    record.status,
                    DebugFrameTraceStatus::Warning | DebugFrameTraceStatus::Error
                )
            })
            .count();
        let max_score = records.iter().map(|record| record.score).max().unwrap_or(0);
        let status = debug_node_hotspot_trace_status(&records);
        let summary =
            debug_node_hotspot_trace_summary(status, records.len(), warning_count, max_score);
        Self {
            status,
            node_count: snapshot.nodes.len(),
            record_count: records.len(),
            warning_count,
            max_score,
            records,
            summary,
        }
    }

    pub fn record(&self, name: &str) -> Option<&DebugNodeHotspotRecord> {
        self.records.iter().find(|record| record.name == name)
    }
}

