#[derive(Debug, Clone, PartialEq)]
pub struct DebugFocusNavigationTrace {
    pub focused: Option<UiNodeId>,
    pub focused_name: Option<String>,
    pub previous: Option<UiNodeId>,
    pub previous_name: Option<String>,
    pub next: Option<UiNodeId>,
    pub next_name: Option<String>,
    pub modal_scope: Option<UiNodeId>,
    pub modal_scope_name: Option<String>,
    pub focusable_count: usize,
    pub skipped_count: usize,
    pub warning_count: usize,
    pub candidates: Vec<DebugFocusCandidate>,
    pub summary: String,
}

impl DebugFocusNavigationTrace {
    pub fn from_document(document: &UiDocument, text_measurer: &mut impl TextMeasurer) -> Self {
        let snapshot = DebugInspectorSnapshot::from_document(document, text_measurer);
        Self::from_snapshot(&snapshot, document.focus_state().focused)
    }

    pub fn from_snapshot(snapshot: &DebugInspectorSnapshot, focused: Option<UiNodeId>) -> Self {
        let modal_scope = debug_focus_modal_scope(snapshot);
        let navigation_order = debug_focus_navigation_order(snapshot, modal_scope);
        let current_index = focused.and_then(|focused| {
            navigation_order
                .iter()
                .position(|candidate| *candidate == focused)
        });
        let next = debug_focus_next(&navigation_order, current_index);
        let previous = debug_focus_previous(&navigation_order, current_index);
        let accessibility_order = debug_focus_accessibility_order(snapshot, modal_scope);
        let candidates = snapshot
            .nodes
            .iter()
            .filter_map(|node| {
                debug_focus_candidate(
                    snapshot,
                    node,
                    focused,
                    next,
                    previous,
                    modal_scope,
                    &navigation_order,
                    &accessibility_order,
                )
            })
            .collect::<Vec<_>>();
        let focusable_count = navigation_order.len();
        let skipped_count = candidates
            .iter()
            .filter(|candidate| candidate.navigation_index.is_none())
            .count();
        let warning_count = candidates
            .iter()
            .filter(|candidate| candidate.status == DebugFrameTraceStatus::Warning)
            .count();
        let summary =
            debug_focus_summary(focusable_count, skipped_count, warning_count, focused, next);
        Self {
            focused,
            focused_name: focused.and_then(|id| debug_snapshot_name(snapshot, id)),
            previous,
            previous_name: previous.and_then(|id| debug_snapshot_name(snapshot, id)),
            next,
            next_name: next.and_then(|id| debug_snapshot_name(snapshot, id)),
            modal_scope,
            modal_scope_name: modal_scope.and_then(|id| debug_snapshot_name(snapshot, id)),
            focusable_count,
            skipped_count,
            warning_count,
            candidates,
            summary,
        }
    }
}

