#[derive(Debug, Clone, Default, PartialEq)]
pub struct DebugResourceReport {
    pub records: Vec<DebugResourceRecord>,
}

impl DebugResourceReport {
    pub fn from_render_frame_request(
        request: &RenderFrameRequest,
        resolver: &dyn ResourceResolver,
    ) -> Self {
        Self::from_paint_and_updates_with_resolver(
            &request.paint,
            &request.resource_updates,
            Some(resolver),
        )
    }

    pub fn from_render_frame_request_without_resolver(request: &RenderFrameRequest) -> Self {
        Self::from_paint_and_updates(&request.paint, &request.resource_updates)
    }

    pub fn from_paint_and_updates(paint: &PaintList, updates: &[ResourceUpdate]) -> Self {
        Self::from_paint_and_updates_with_resolver(paint, updates, None)
    }

    pub fn from_paint_and_updates_with_resolver(
        paint: &PaintList,
        updates: &[ResourceUpdate],
        resolver: Option<&dyn ResourceResolver>,
    ) -> Self {
        let mut references = Vec::new();
        collect_debug_resource_references(paint, &mut references);

        let mut builders = Vec::<DebugResourceRecordBuilder>::new();
        for reference in references {
            debug_resource_builder_for(&mut builders, &reference.handle)
                .references
                .push(reference.reference);
        }
        for update in updates {
            let resolved_descriptor = resolver
                .and_then(|resolver| resolver.resolve_resource(update.descriptor.handle.id()));
            let summary = debug_resource_update_summary(
                update,
                resolved_descriptor.as_ref(),
                resolver.is_some(),
            );
            let builder = debug_resource_builder_for(&mut builders, &update.descriptor.handle);
            if builder.resolved_descriptor.is_none() {
                builder.resolved_descriptor = resolved_descriptor;
            }
            builder.updates.push(summary);
        }
        if let Some(resolver) = resolver {
            for builder in &mut builders {
                if builder.resolved_descriptor.is_none() {
                    builder.resolved_descriptor = resolver.resolve_resource(builder.handle.id());
                }
            }
        }

        let mut records = builders
            .into_iter()
            .map(DebugResourceRecordBuilder::finish)
            .collect::<Vec<_>>();
        records.sort_by(|left, right| {
            debug_resource_status_order(right.status)
                .cmp(&debug_resource_status_order(left.status))
                .then_with(|| left.handle_label().cmp(&right.handle_label()))
        });
        Self { records }
    }

    pub fn record(&self, key: &str) -> Option<&DebugResourceRecord> {
        self.records
            .iter()
            .find(|record| record.handle.id().key == key)
    }

    pub fn count_by_status(&self, status: DebugResourceStatus) -> usize {
        self.records
            .iter()
            .filter(|record| record.status == status)
            .count()
    }

    pub fn missing_count(&self) -> usize {
        self.count_by_status(DebugResourceStatus::Missing)
    }

    pub fn invalid_count(&self) -> usize {
        self.count_by_status(DebugResourceStatus::Invalid)
    }

    pub fn unused_update_count(&self) -> usize {
        self.count_by_status(DebugResourceStatus::UnusedUpdate)
    }

    pub fn summary(&self) -> String {
        if self.records.is_empty() {
            return "no resources referenced".to_owned();
        }
        format!(
            "{} resources ({} missing, {} invalid, {} unused)",
            self.records.len(),
            self.missing_count(),
            self.invalid_count(),
            self.unused_update_count()
        )
    }
}

