#[derive(Debug, Clone, PartialEq)]
pub struct DebugFrameTrace {
    pub label: String,
    pub frame_index: Option<u64>,
    pub viewport: UiSize,
    pub snapshot: DebugInspectorSnapshot,
    pub paint: DebugPaintDump,
    pub paint_batches: DebugPaintBatchTrace,
    pub timing: FrameTimingExplanation,
    pub dirty: DirtyStateExplanation,
    pub focus: DebugFocusNavigationTrace,
    pub routes: Vec<DebugEventRouteTrace>,
    pub resources: DebugResourceReport,
    pub interaction_state: Option<DebugInteractionStateTrace>,
    pub selected_node_request: Option<String>,
    pub selected_node: Option<DebugNodeExplanation>,
    pub summary: DebugFrameTraceSummary,
}

impl DebugFrameTrace {
    pub fn from_document(
        document: &UiDocument,
        text_measurer: &mut impl TextMeasurer,
        context: DebugFrameTraceContext,
    ) -> Self {
        let snapshot = DebugInspectorSnapshot::from_document(document, text_measurer);
        let paint = DebugPaintDump::from_document(document);
        let paint_batches = DebugPaintBatchTrace::from_document(document);
        let focus =
            DebugFocusNavigationTrace::from_snapshot(&snapshot, document.focus_state().focused);
        let resources = context.resources.unwrap_or_default();
        let interaction_state = context.interaction_state;
        let selected_node_request = context.selected_node.clone();
        let selected_node = DebugNodeExplanation::from_context(
            &snapshot,
            context.selected_node.as_deref(),
            context.routes.first(),
            Some(&resources),
        );
        let timing =
            FrameTimingExplanation::from_frame_timing(&context.timing, context.timing_budget);
        let dirty = context
            .dirty_state
            .unwrap_or_else(|| DirtyStateExplanation::from_flags(context.dirty_flags));
        let summary = debug_frame_trace_summary(
            &snapshot,
            &timing,
            &context.routes,
            &resources,
            selected_node.as_ref(),
        );
        Self {
            label: context.label,
            frame_index: context.frame_index,
            viewport: context.viewport,
            snapshot,
            paint,
            paint_batches,
            timing,
            dirty,
            focus,
            routes: context.routes,
            resources,
            interaction_state,
            selected_node_request,
            selected_node,
            summary,
        }
    }

    pub fn compact_summary(&self) -> String {
        self.summary.summary.clone()
    }
}

