impl DebugFrameBudgetTrace {
    pub fn from_frame_timing(
        timing: &FrameTiming,
        budget: Option<Duration>,
        dirty: DirtyStateExplanation,
    ) -> Self {
        Self::from_explanations(
            FrameTimingExplanation::from_frame_timing(timing, budget),
            dirty,
        )
    }

    pub fn from_trace(trace: &DebugFrameTrace) -> Self {
        Self::from_explanations(trace.timing.clone(), trace.dirty.clone())
    }

    pub fn from_explanations(timing: FrameTimingExplanation, dirty: DirtyStateExplanation) -> Self {
        let over_budget_by = timing
            .budget
            .and_then(|budget| (timing.total > budget).then(|| timing.total - budget));
        let slowest_stage = timing
            .slowest_stage_explanation()
            .map(|stage| stage.label.clone());
        let primary_dirty_cause = dirty.primary_cause().map(|cause| cause.summary.clone());
        let recompute_order = dirty
            .recompute_order
            .iter()
            .map(|subsystem| subsystem.display_label().to_owned())
            .collect::<Vec<_>>();
        let stages = timing
            .stages
            .iter()
            .map(|stage| debug_frame_budget_stage(stage, timing.budget, &dirty))
            .collect::<Vec<_>>();
        let status = debug_frame_budget_status(&timing, over_budget_by);
        let summary =
            debug_frame_budget_summary(status, &timing, over_budget_by, slowest_stage.as_deref());
        Self {
            status,
            timing,
            dirty,
            over_budget_by,
            slowest_stage,
            primary_dirty_cause,
            recompute_order,
            stages,
            summary,
        }
    }

    pub fn compact_summary(&self) -> String {
        self.summary.clone()
    }
}

impl DebugFrameTimingWaterfallTrace {
    pub fn from_trace(trace: &DebugFrameTrace) -> Self {
        Self::from_explanations(
            trace.label.clone(),
            trace.frame_index,
            &trace.timing,
            &trace.dirty,
        )
    }

    pub fn from_frame_timing(
        label: impl Into<String>,
        timing: &FrameTiming,
        budget: Option<Duration>,
        dirty: DirtyStateExplanation,
    ) -> Self {
        let timing = FrameTimingExplanation::from_frame_timing(timing, budget);
        Self::from_explanations(label.into(), None, &timing, &dirty)
    }

    pub fn from_explanations(
        frame_label: impl Into<String>,
        frame_index: Option<u64>,
        timing: &FrameTimingExplanation,
        dirty: &DirtyStateExplanation,
    ) -> Self {
        let over_budget_by = timing
            .budget
            .and_then(|budget| (timing.total > budget).then(|| timing.total - budget));
        let mut records = timing
            .sections
            .iter()
            .map(|section| debug_frame_timing_waterfall_record(section, timing, dirty))
            .collect::<Vec<_>>();
        let budget_crossed_at = records
            .iter()
            .find(|record| record.crosses_budget)
            .map(|record| record.label.clone());
        let status = debug_frame_timing_waterfall_status(timing, over_budget_by, &records);
        let section_count = records.len();
        let missing_required_stage_count = timing.missing_required_stages.len();
        let missing_required_stages = timing.missing_required_stages.clone();
        let frame_label = frame_label.into();
        let summary = debug_frame_timing_waterfall_summary(
            status,
            &frame_label,
            timing.total,
            timing.budget,
            over_budget_by,
            section_count,
            missing_required_stage_count,
            budget_crossed_at.as_deref(),
        );
        records.sort_by(|left, right| left.index.cmp(&right.index));
        Self {
            frame_label,
            frame_index,
            status,
            total: timing.total,
            budget: timing.budget,
            over_budget_by,
            section_count,
            missing_required_stage_count,
            missing_required_stages,
            budget_crossed_at,
            records,
            summary,
        }
    }

    pub fn record(&self, label: &str) -> Option<&DebugFrameTimingWaterfallRecord> {
        self.records.iter().find(|record| record.label == label)
    }
}

impl DebugSlowFrameTrace {
    pub fn from_trace(trace: &DebugFrameTrace) -> Self {
        Self::from_trace_with_slow_nodes_and_cache(trace, None, None)
    }

    pub fn from_trace_with_slow_nodes(
        trace: &DebugFrameTrace,
        slow_nodes: &DebugSlowNodeTrace,
    ) -> Self {
        Self::from_trace_with_slow_nodes_and_cache(trace, Some(slow_nodes), None)
    }

    pub fn from_trace_with_slow_nodes_and_cache(
        trace: &DebugFrameTrace,
        slow_nodes: Option<&DebugSlowNodeTrace>,
        cache: Option<&DebugCacheReuseTrace>,
    ) -> Self {
        let budget = DebugFrameBudgetTrace::from_trace(trace);
        let invalidation = DebugInvalidationBlameTrace::from_frame_trace(trace);
        let mut records = vec![
            debug_slow_frame_timing_record(&budget),
            debug_slow_frame_dirty_record(&budget, &invalidation),
        ];
        if let Some(slow_nodes) = slow_nodes {
            records.extend(
                slow_nodes
                    .records
                    .iter()
                    .map(|record| debug_slow_frame_node_record(record, budget.over_budget_by)),
            );
        }
        if let Some(cache) = cache {
            records.push(debug_slow_frame_cache_record(cache));
        }
        records.retain(|record| {
            record.source != DebugSlowFrameSource::DirtyState
                || record.status != DebugFrameTraceStatus::Ok
                || budget.status != DebugFrameTraceStatus::Ok
        });
        records.sort_by(|left, right| {
            debug_slow_frame_status_rank(left.status)
                .cmp(&debug_slow_frame_status_rank(right.status))
                .then_with(|| right.score.cmp(&left.score))
                .then_with(|| {
                    debug_slow_frame_source_rank(left.source)
                        .cmp(&debug_slow_frame_source_rank(right.source))
                })
                .then_with(|| left.node_name.cmp(&right.node_name))
        });
        let record_count = records.len();
        let warning_count = records
            .iter()
            .filter(|record| {
                matches!(
                    record.status,
                    DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
                )
            })
            .count();
        let slow_node_count = slow_nodes.map(|trace| trace.record_count).unwrap_or(0);
        let max_score = records.iter().map(|record| record.score).max().unwrap_or(0);
        let status = debug_slow_frame_trace_status(&records, budget.status);
        let summary = debug_slow_frame_trace_summary(
            status,
            &trace.label,
            budget.timing.total,
            budget.timing.budget,
            budget.over_budget_by,
            budget.slowest_stage.as_deref(),
            slow_node_count,
            warning_count,
        );
        Self {
            frame_label: trace.label.clone(),
            frame_index: trace.frame_index,
            status,
            total: budget.timing.total,
            budget: budget.timing.budget,
            over_budget_by: budget.over_budget_by,
            slowest_stage: budget.slowest_stage,
            slow_node_count,
            record_count,
            warning_count,
            max_score,
            records,
            summary,
        }
    }

    pub fn record(&self, source: DebugSlowFrameSource) -> Option<&DebugSlowFrameRecord> {
        self.records.iter().find(|record| record.source == source)
    }

    pub fn node_record(&self, name: &str) -> Option<&DebugSlowFrameRecord> {
        self.records
            .iter()
            .find(|record| record.node_name.as_deref() == Some(name))
    }
}

impl DebugFrameBottleneckTrace {
    pub fn from_trace(trace: &DebugFrameTrace) -> Self {
        Self::from_trace_with_slow_nodes_and_cache(trace, None, None)
    }

    pub fn from_trace_with_slow_nodes(
        trace: &DebugFrameTrace,
        slow_nodes: &DebugSlowNodeTrace,
    ) -> Self {
        Self::from_trace_with_slow_nodes_and_cache(trace, Some(slow_nodes), None)
    }

    pub fn from_trace_with_slow_nodes_and_cache(
        trace: &DebugFrameTrace,
        slow_nodes: Option<&DebugSlowNodeTrace>,
        cache: Option<&DebugCacheReuseTrace>,
    ) -> Self {
        let budget = DebugFrameBudgetTrace::from_trace(trace);
        let invalidation = DebugInvalidationBlameTrace::from_frame_trace(trace);
        let layout_cost = DebugLayoutCostTrace::from_snapshot(&trace.snapshot);
        let mut records = Vec::new();
        records.extend(
            budget
                .stages
                .iter()
                .map(|stage| debug_frame_bottleneck_timing_stage_record(stage, &budget)),
        );
        if let Some(record) = debug_frame_bottleneck_dirty_record(&budget, &invalidation) {
            records.push(record);
        }
        if let Some(record) = debug_frame_bottleneck_layout_cost_record(&budget, &layout_cost) {
            records.push(record);
        }
        if let Some(slow_nodes) = slow_nodes {
            records.extend(
                slow_nodes
                    .records
                    .iter()
                    .map(|record| debug_frame_bottleneck_slow_node_record(record, &budget)),
            );
        }
        if let Some(record) = debug_frame_bottleneck_paint_record(trace) {
            records.push(record);
        }
        if let Some(record) = debug_frame_bottleneck_resource_record(&trace.resources) {
            records.push(record);
        }
        if let Some(cache) = cache {
            if let Some(record) = debug_frame_bottleneck_cache_record(cache) {
                records.push(record);
            }
        }
        if let Some(record) = debug_frame_bottleneck_route_record(&trace.routes) {
            records.push(record);
        }
        if let Some(record) = debug_frame_bottleneck_constraint_record(&trace.snapshot.constraints)
        {
            records.push(record);
        }
        if let Some(record) = debug_frame_bottleneck_overlap_record(&trace.snapshot.overlaps) {
            records.push(record);
        }

        records.sort_by(|left, right| {
            debug_frame_bottleneck_status_rank(left.status)
                .cmp(&debug_frame_bottleneck_status_rank(right.status))
                .then_with(|| right.score.cmp(&left.score))
                .then_with(|| {
                    debug_frame_bottleneck_source_rank(left.source)
                        .cmp(&debug_frame_bottleneck_source_rank(right.source))
                })
                .then_with(|| left.label.cmp(&right.label))
        });
        let timing_stage_count = budget.stages.len();
        let slow_node_count = slow_nodes.map(|trace| trace.record_count).unwrap_or(0);
        let record_count = records.len();
        let warning_count = records
            .iter()
            .filter(|record| {
                matches!(
                    record.status,
                    DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
                )
            })
            .count();
        let max_score = records.iter().map(|record| record.score).max().unwrap_or(0);
        let top_label = records.first().map(|record| record.label.clone());
        let status = debug_frame_bottleneck_trace_status(&records, budget.status);
        let summary = debug_frame_bottleneck_trace_summary(
            status,
            &trace.label,
            budget.timing.total,
            budget.timing.budget,
            budget.over_budget_by,
            top_label.as_deref(),
            record_count,
            warning_count,
        );

        Self {
            frame_label: trace.label.clone(),
            frame_index: trace.frame_index,
            status,
            total: budget.timing.total,
            budget: budget.timing.budget,
            over_budget_by: budget.over_budget_by,
            timing_stage_count,
            slow_node_count,
            record_count,
            warning_count,
            max_score,
            top_label,
            records,
            summary,
        }
    }

    pub fn record(
        &self,
        source: DebugFrameBottleneckSource,
    ) -> Option<&DebugFrameBottleneckRecord> {
        self.records.iter().find(|record| record.source == source)
    }

    pub fn record_label(&self, label: &str) -> Option<&DebugFrameBottleneckRecord> {
        self.records.iter().find(|record| record.label == label)
    }
}

impl DebugFrameAutopsyTrace {
    pub fn from_trace(trace: &DebugFrameTrace) -> Self {
        Self::from_trace_with_cache(trace, None)
    }

    pub fn from_trace_with_cache(
        trace: &DebugFrameTrace,
        cache: Option<&DebugCacheReuseTrace>,
    ) -> Self {
        let budget = DebugFrameBudgetTrace::from_trace(trace);
        let layout_cost = DebugLayoutCostTrace::from_snapshot(&trace.snapshot);
        let invalidation = DebugInvalidationBlameTrace::from_frame_trace(trace);
        let issues = DebugIssueReport::from_frame_trace_with_budget(trace, &budget);
        let mut records = vec![
            debug_frame_autopsy_timing_record(&budget),
            debug_frame_autopsy_dirty_record(&invalidation),
            debug_frame_autopsy_layout_cost_record(&layout_cost),
            debug_frame_autopsy_paint_record(trace),
            debug_frame_autopsy_resource_record(&trace.resources),
            debug_frame_autopsy_route_record(&trace.routes),
            debug_frame_autopsy_constraint_record(&trace.snapshot.constraints),
            debug_frame_autopsy_overlap_record(&trace.snapshot.overlaps),
            debug_frame_autopsy_selected_record(trace.selected_node.as_ref()),
            debug_frame_autopsy_cache_record(cache),
        ];
        records.sort_by(|left, right| {
            debug_frame_autopsy_status_rank(left.status)
                .cmp(&debug_frame_autopsy_status_rank(right.status))
                .then_with(|| {
                    debug_frame_autopsy_source_rank(left.source)
                        .cmp(&debug_frame_autopsy_source_rank(right.source))
                })
        });
        let status = debug_frame_autopsy_trace_status(&records);
        let record_count = records.len();
        let warning_count = records
            .iter()
            .filter(|record| {
                matches!(
                    record.status,
                    DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
                )
            })
            .count();
        let summary =
            debug_frame_autopsy_summary(trace, &issues, status, record_count, warning_count);

        Self {
            frame_label: trace.label.clone(),
            frame_index: trace.frame_index,
            status,
            record_count,
            warning_count,
            records,
            summary,
        }
    }

    pub fn record(&self, source: DebugFrameAutopsySource) -> Option<&DebugFrameAutopsyRecord> {
        self.records.iter().find(|record| record.source == source)
    }
}

