impl DebugQuestionGuideTrace {
    pub fn from_frame_trace(trace: &DebugFrameTrace) -> Self {
        let mut records = vec![
            debug_question_clickability_record(trace),
            debug_question_overlap_record(trace),
            debug_question_performance_record(trace),
            debug_question_paint_hit_record(trace),
            debug_question_text_fit_record(trace),
            debug_question_clipping_record(trace),
            debug_question_resources_record(trace),
            debug_question_selected_node_record(trace),
        ];
        records.sort_by(|left, right| {
            debug_question_status_rank(left.status)
                .cmp(&debug_question_status_rank(right.status))
                .then_with(|| {
                    debug_question_kind_rank(left.kind).cmp(&debug_question_kind_rank(right.kind))
                })
        });
        let question_count = records.len();
        let warning_count = records
            .iter()
            .filter(|record| {
                matches!(
                    record.status,
                    DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
                )
            })
            .count();
        let status = debug_question_trace_status(&records);
        let summary = debug_question_trace_summary(status, question_count, warning_count);
        Self {
            frame_label: trace.label.clone(),
            status,
            question_count,
            warning_count,
            records,
            summary,
        }
    }

    pub fn record(&self, kind: DebugQuestionGuideKind) -> Option<&DebugQuestionGuideRecord> {
        self.records.iter().find(|record| record.kind == kind)
    }
}

