#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DebugWhyTrace {
    pub scope: DebugWhyScope,
    pub subject: String,
    pub status: DebugFrameTraceStatus,
    pub record_count: usize,
    pub warning_count: usize,
    pub records: Vec<DebugWhyRecord>,
    pub summary: String,
}

impl DebugWhyTrace {
    pub fn from_frame_trace(trace: &DebugFrameTrace) -> Self {
        let questions = DebugQuestionGuideTrace::from_frame_trace(trace);
        let issues = DebugIssueReport::from_frame_trace(trace);
        let bottlenecks = DebugFrameBottleneckTrace::from_trace(trace);
        let autopsy = DebugFrameAutopsyTrace::from_trace(trace);
        let mut records = Vec::new();

        records.extend(questions.records.iter().map(debug_why_record_from_question));
        records.extend(
            issues
                .issues
                .iter()
                .take(5)
                .map(debug_why_record_from_issue),
        );
        records.extend(
            bottlenecks
                .records
                .iter()
                .take(5)
                .map(debug_why_record_from_bottleneck),
        );
        records.extend(
            autopsy
                .records
                .iter()
                .take(5)
                .map(debug_why_record_from_frame_autopsy),
        );

        debug_finish_why_trace(
            DebugWhyScope::Frame,
            debug_why_frame_subject(trace),
            records,
        )
    }

    pub fn from_point_autopsy(autopsy: &DebugPointAutopsyTrace) -> Self {
        let records = autopsy
            .records
            .iter()
            .map(|record| debug_why_record_from_point_autopsy(record, autopsy))
            .collect();
        debug_finish_why_trace(
            DebugWhyScope::Point,
            debug_why_point_subject(autopsy),
            records,
        )
    }

    pub fn from_inspect_node(trace: &DebugInspectNodeTrace) -> Self {
        let records = trace
            .records
            .iter()
            .map(|record| debug_why_record_from_inspect_node(record, trace))
            .collect();
        debug_finish_why_trace(DebugWhyScope::Node, debug_why_node_subject(trace), records)
    }

    pub fn record(&self, source: DebugWhySource) -> Option<&DebugWhyRecord> {
        self.records.iter().find(|record| record.source == source)
    }

    pub fn trail(&self) -> Vec<DebugWhyTrailStep> {
        debug_why_trail_steps(self.scope, &self.subject, &self.records)
    }

    pub fn overlay_layers(&self) -> Vec<DebugWhyOverlayLayer> {
        let mut layers = Vec::new();
        for step in self.trail() {
            for layer in step.overlays {
                if !layers.contains(&layer) {
                    layers.push(layer);
                }
            }
        }
        layers
    }

    pub fn overlay_plan(&self) -> DebugWhyOverlayPlan {
        debug_why_overlay_plan(self.scope, &self.subject, &self.trail())
    }

    pub fn first_step(&self) -> Option<DebugWhyTrailStep> {
        self.trail().into_iter().next()
    }

    pub fn step(&self, action: impl AsRef<str>) -> Option<DebugWhyTrailStep> {
        let action = action.as_ref();
        self.trail().into_iter().find(|step| step.action == action)
    }
}

