impl DebugPanelRecommendationTrace {
    pub fn from_frame_trace(trace: &DebugFrameTrace) -> Self {
        let why = DebugWhyTrace::from_frame_trace(trace);
        let invariants = DebugInvariantTrace::from_snapshot(&trace.snapshot);
        let contract = DebugContractReport::from_frame_trace(trace);
        let mut records = Vec::new();

        for step in why.trail().into_iter().filter(|step| {
            matches!(
                step.status,
                DebugFrameTraceStatus::Error
                    | DebugFrameTraceStatus::Warning
                    | DebugFrameTraceStatus::Info
            )
        }) {
            debug_panel_recommendation_push(
                &mut records,
                DebugPanelRecommendationSource::WhyTrace,
                &step.panel,
                step.title,
                step.action,
                step.status,
                debug_panel_recommendation_score(step.status, 0),
                Some(step.subject),
                step.overlays,
                step.summary,
                step.evidence,
                step.fix,
            );
        }

        for record in invariants
            .records
            .iter()
            .filter(|record| !record.passed || !record.checked)
        {
            let subject = if record.subjects.is_empty() {
                trace.label.clone()
            } else {
                record.subjects.join(", ")
            };
            let action = format!("panel.{}", record.panel);
            debug_panel_recommendation_push(
                &mut records,
                DebugPanelRecommendationSource::Invariant,
                &record.panel,
                record.kind.title().to_owned(),
                action,
                record.status,
                debug_panel_recommendation_score(record.status, record.issue_count as u32),
                Some(subject),
                debug_panel_recommendation_overlays(
                    &record.panel,
                    record.kind.title(),
                    &record.summary,
                    &record.cause,
                    &record.fix,
                ),
                record.summary.clone(),
                record.cause.clone(),
                record.fix.clone(),
            );
        }

        for check in contract
            .checks
            .iter()
            .filter(|check| !check.passed || !check.checked)
        {
            let panel = debug_panel_recommendation_contract_panel(check.kind);
            let action = format!("panel.{panel}");
            debug_panel_recommendation_push(
                &mut records,
                DebugPanelRecommendationSource::Contract,
                panel,
                check.kind.title().to_owned(),
                action,
                check.status,
                debug_panel_recommendation_score(check.status, check.issue_count as u32),
                Some(trace.label.clone()),
                debug_panel_recommendation_overlays(
                    panel,
                    check.kind.title(),
                    &check.summary,
                    &check.cause,
                    &check.fix,
                ),
                check.summary.clone(),
                check.cause.clone(),
                check.fix.clone(),
            );
        }

        finish_debug_panel_recommendations(trace.label.clone(), records)
    }

    pub fn record(&self, panel: &str) -> Option<&DebugPanelRecommendationRecord> {
        self.records.iter().find(|record| record.panel == panel)
    }

    pub fn compact_summary(&self) -> String {
        self.summary.clone()
    }
}

impl DebugOverlayRecommendationTrace {
    pub fn from_frame_trace(trace: &DebugFrameTrace) -> Self {
        let why = DebugWhyTrace::from_frame_trace(trace);
        let issues = DebugIssueReport::from_frame_trace(trace);
        let invariants = DebugInvariantTrace::from_snapshot(&trace.snapshot);
        let contract = DebugContractReport::from_frame_trace(trace);
        let mut records = Vec::new();

        for overlay in why.overlay_plan().records {
            debug_overlay_recommendation_push(
                &mut records,
                DebugOverlayRecommendationSource::WhyTrace,
                overlay.layer,
                overlay.action,
                overlay.status,
                debug_overlay_recommendation_score(overlay.status, overlay.step_count as u32),
                overlay.subjects,
                overlay.panels,
                overlay.summary.clone(),
                overlay.summary,
                overlay.fix,
            );
        }

        for issue in &issues.issues {
            let panel = debug_issue_source_inspect(issue.source);
            let mut overlays = debug_panel_recommendation_overlays(
                panel,
                issue.source.title(),
                &issue.summary,
                &issue.cause,
                &issue.fix,
            );
            debug_overlay_recommendation_extend_unique(
                &mut overlays,
                debug_overlay_recommendation_issue_layers(issue.source),
            );
            let subjects = issue
                .node_name
                .clone()
                .map(|name| vec![name])
                .unwrap_or_else(|| vec![trace.label.clone()]);
            for layer in overlays {
                debug_overlay_recommendation_push(
                    &mut records,
                    DebugOverlayRecommendationSource::IssueReport,
                    layer,
                    format!("issue.{}.{}", issue.source.label(), issue.label),
                    issue.status,
                    debug_overlay_recommendation_score(issue.status, 1),
                    subjects.clone(),
                    vec![panel.to_owned()],
                    issue.summary.clone(),
                    issue.cause.clone(),
                    issue.fix.clone(),
                );
            }
        }

        for invariant in invariants
            .records
            .iter()
            .filter(|record| !record.passed || !record.checked)
        {
            let mut overlays = debug_panel_recommendation_overlays(
                &invariant.panel,
                invariant.kind.title(),
                &invariant.summary,
                &invariant.cause,
                &invariant.fix,
            );
            debug_overlay_recommendation_extend_unique(
                &mut overlays,
                debug_overlay_recommendation_invariant_layers(invariant.kind),
            );
            let subjects = if invariant.subjects.is_empty() {
                vec![trace.label.clone()]
            } else {
                invariant.subjects.clone()
            };
            for layer in overlays {
                debug_overlay_recommendation_push(
                    &mut records,
                    DebugOverlayRecommendationSource::Invariant,
                    layer,
                    format!("invariant.{}", invariant.kind.label()),
                    invariant.status,
                    debug_overlay_recommendation_score(
                        invariant.status,
                        invariant.issue_count as u32,
                    ),
                    subjects.clone(),
                    vec![invariant.panel.clone()],
                    invariant.summary.clone(),
                    invariant.cause.clone(),
                    invariant.fix.clone(),
                );
            }
        }

        for check in contract
            .checks
            .iter()
            .filter(|check| !check.passed || !check.checked)
        {
            let panel = debug_panel_recommendation_contract_panel(check.kind);
            let mut overlays = debug_panel_recommendation_overlays(
                panel,
                check.kind.title(),
                &check.summary,
                &check.cause,
                &check.fix,
            );
            debug_overlay_recommendation_extend_unique(
                &mut overlays,
                debug_overlay_recommendation_contract_layers(check.kind),
            );
            for layer in overlays {
                debug_overlay_recommendation_push(
                    &mut records,
                    DebugOverlayRecommendationSource::Contract,
                    layer,
                    format!("contract.{}", check.kind.label()),
                    check.status,
                    debug_overlay_recommendation_score(check.status, check.issue_count as u32),
                    vec![trace.label.clone()],
                    vec![panel.to_owned()],
                    check.summary.clone(),
                    check.cause.clone(),
                    check.fix.clone(),
                );
            }
        }

        finish_debug_overlay_recommendations(trace.label.clone(), trace.frame_index, records)
    }

    pub fn record(&self, layer: DebugWhyOverlayLayer) -> Option<&DebugOverlayRecommendationRecord> {
        self.records.iter().find(|record| record.layer == layer)
    }

    pub fn compact_summary(&self) -> String {
        self.summary.clone()
    }
}

impl DebugDiagnosticsCoverageTrace {
    pub fn from_frame_trace(trace: &DebugFrameTrace) -> Self {
        Self::from_frame_trace_with_context(trace, None, None, None)
    }

    pub fn from_frame_trace_with_context(
        trace: &DebugFrameTrace,
        text_fit: Option<&DebugTextFitTrace>,
        action_map: Option<&DebugActionMapTrace>,
        cache: Option<&DebugCacheReuseTrace>,
    ) -> Self {
        let mut records = vec![
            debug_diagnostics_coverage_snapshot_record(trace),
            debug_diagnostics_coverage_timing_record(trace),
            debug_diagnostics_coverage_budget_record(trace),
            debug_diagnostics_coverage_dirty_record(trace),
            debug_diagnostics_coverage_route_record(trace),
            debug_diagnostics_coverage_resource_record(trace),
            debug_diagnostics_coverage_selected_record(trace),
            debug_diagnostics_coverage_text_record(trace, text_fit),
            debug_diagnostics_coverage_action_record(trace, action_map),
            debug_diagnostics_coverage_cache_record(trace, cache),
        ];
        records.sort_by(|left, right| {
            debug_frame_timeline_status_rank(left.status)
                .cmp(&debug_frame_timeline_status_rank(right.status))
                .then_with(|| left.captured.cmp(&right.captured))
                .then_with(|| right.required.cmp(&left.required))
                .then_with(|| left.area.cmp(&right.area))
        });
        finish_debug_diagnostics_coverage(trace.label.clone(), trace.frame_index, records)
    }

    pub fn record(
        &self,
        area: DebugDiagnosticsCoverageArea,
    ) -> Option<&DebugDiagnosticsCoverageRecord> {
        self.records.iter().find(|record| record.area == area)
    }

    pub fn compact_summary(&self) -> String {
        self.summary.clone()
    }
}

impl DebugInvestigationPlanTrace {
    pub fn from_frame_trace(trace: &DebugFrameTrace) -> Self {
        let coverage = DebugDiagnosticsCoverageTrace::from_frame_trace(trace);
        let panels = DebugPanelRecommendationTrace::from_frame_trace(trace);
        let overlays = DebugOverlayRecommendationTrace::from_frame_trace(trace);
        let why = DebugWhyTrace::from_frame_trace(trace);
        Self::from_parts(trace, &coverage, &panels, &overlays, &why)
    }

    pub fn from_parts(
        trace: &DebugFrameTrace,
        coverage: &DebugDiagnosticsCoverageTrace,
        panels: &DebugPanelRecommendationTrace,
        overlays: &DebugOverlayRecommendationTrace,
        why: &DebugWhyTrace,
    ) -> Self {
        let mut records = Vec::new();
        for record in coverage
            .records
            .iter()
            .filter(|record| !record.captured)
            .take(3)
        {
            debug_investigation_plan_push_coverage(&mut records, record);
        }
        if let Some(record) = overlays.records.first() {
            debug_investigation_plan_push_overlay(&mut records, record);
        }
        if let Some(record) = panels.records.first() {
            debug_investigation_plan_push_panel(&mut records, record);
        }
        if let Some(step) = why.first_step() {
            debug_investigation_plan_push_why(&mut records, &step);
        }
        debug_investigation_plan_push_verify(&mut records, trace, panels, overlays);
        finish_debug_investigation_plan(trace, coverage, panels, overlays, records)
    }

    pub fn record(
        &self,
        kind: DebugInvestigationStepKind,
    ) -> Option<&DebugInvestigationStepRecord> {
        self.records.iter().find(|record| record.kind == kind)
    }

    pub fn step(&self, action: impl AsRef<str>) -> Option<&DebugInvestigationStepRecord> {
        let action = action.as_ref();
        self.records.iter().find(|record| record.action == action)
    }

    pub fn compact_summary(&self) -> String {
        self.summary.clone()
    }
}

impl DebugNodeRecommendationTrace {
    pub fn from_frame_trace(trace: &DebugFrameTrace) -> Self {
        Self::from_frame_trace_with_slow_nodes(trace, None)
    }

    pub fn from_frame_trace_with_slow_nodes(
        trace: &DebugFrameTrace,
        slow_nodes: Option<&DebugSlowNodeTrace>,
    ) -> Self {
        let issues = DebugIssueReport::from_frame_trace(trace);
        let hotspots = DebugNodeHotspotTrace::from_snapshot(&trace.snapshot);
        let mut records = Vec::new();

        for issue in &issues.issues {
            let Some(name) = issue.node_name.clone() else {
                continue;
            };
            let panel = debug_issue_source_inspect(issue.source);
            let overlays = debug_node_recommendation_issue_overlays(issue);
            debug_node_recommendation_push(
                &mut records,
                DebugNodeRecommendationSource::Issue,
                issue.node,
                name,
                issue.status,
                debug_node_recommendation_score(issue.status, 80),
                vec![panel.to_owned()],
                overlays,
                issue.summary.clone(),
                issue.cause.clone(),
                issue.fix.clone(),
            );
        }

        for hotspot in hotspots.records.iter().take(8) {
            debug_node_recommendation_push(
                &mut records,
                DebugNodeRecommendationSource::Hotspot,
                Some(hotspot.node),
                hotspot.name.clone(),
                hotspot.status,
                debug_node_recommendation_score(hotspot.status, hotspot.score),
                vec!["node_hotspots_panel".to_owned()],
                debug_node_recommendation_hotspot_overlays(hotspot),
                hotspot.summary.clone(),
                hotspot.cause.clone(),
                hotspot.fix.clone(),
            );
        }

        if let Some(slow_nodes) = slow_nodes {
            for slow in slow_nodes.records.iter().take(8) {
                debug_node_recommendation_push(
                    &mut records,
                    DebugNodeRecommendationSource::SlowNode,
                    Some(slow.node),
                    slow.name.clone(),
                    slow.status,
                    debug_node_recommendation_score(slow.status, slow.score),
                    vec!["slow_nodes_panel".to_owned()],
                    vec![
                        DebugWhyOverlayLayer::LayoutBounds,
                        DebugWhyOverlayLayer::PaintBounds,
                        DebugWhyOverlayLayer::Performance,
                    ],
                    slow.summary.clone(),
                    slow.cause.clone(),
                    slow.fix.clone(),
                );
            }
        }

        if let Some(selected) = &trace.selected_node {
            debug_node_recommendation_push(
                &mut records,
                DebugNodeRecommendationSource::SelectedNode,
                Some(selected.node),
                selected.name.clone(),
                DebugFrameTraceStatus::from(selected.status),
                debug_node_recommendation_score(DebugFrameTraceStatus::from(selected.status), 60),
                vec!["inspect_node_panel".to_owned()],
                vec![
                    DebugWhyOverlayLayer::LayoutBounds,
                    DebugWhyOverlayLayer::Hitboxes,
                    DebugWhyOverlayLayer::PaintBounds,
                ],
                selected.summary.clone(),
                selected.layout.cause.clone(),
                debug_selected_node_issue_fix(selected),
            );
        }

        finish_debug_node_recommendations(trace, records)
    }

    pub fn record(&self, name: &str) -> Option<&DebugNodeRecommendationRecord> {
        self.records.iter().find(|record| record.name == name)
    }

    pub fn compact_summary(&self) -> String {
        self.summary.clone()
    }
}

impl DebugFindingInboxTrace {
    pub fn from_frame_trace(trace: &DebugFrameTrace) -> Self {
        let issues = DebugIssueReport::from_frame_trace(trace);
        let coverage = DebugDiagnosticsCoverageTrace::from_frame_trace(trace);
        let panels = DebugPanelRecommendationTrace::from_frame_trace(trace);
        let overlays = DebugOverlayRecommendationTrace::from_frame_trace(trace);
        let nodes = DebugNodeRecommendationTrace::from_frame_trace(trace);
        Self::from_parts(trace, &issues, &coverage, &panels, &overlays, &nodes)
    }

    pub fn from_parts(
        trace: &DebugFrameTrace,
        issues: &DebugIssueReport,
        coverage: &DebugDiagnosticsCoverageTrace,
        panels: &DebugPanelRecommendationTrace,
        overlays: &DebugOverlayRecommendationTrace,
        nodes: &DebugNodeRecommendationTrace,
    ) -> Self {
        let mut records = Vec::new();

        for issue in &issues.issues {
            let panel = debug_issue_source_inspect(issue.source).to_owned();
            let overlay = debug_node_recommendation_issue_overlays(issue)
                .first()
                .copied();
            debug_finding_inbox_push(
                &mut records,
                DebugFindingSource::Issue,
                format!(
                    "issue.{}.{}.{}",
                    issue.source.label(),
                    issue.label,
                    issue
                        .node_name
                        .as_deref()
                        .map(debug_action_id_part)
                        .unwrap_or_else(|| "frame".to_owned())
                ),
                format!("{} issue", issue.source.title()),
                issue.status,
                debug_finding_inbox_score(issue.status, 120),
                issue.node,
                issue.node_name.clone(),
                Some(panel.clone()),
                overlay,
                format!("issue.{}.{}", issue.source.label(), issue.label),
                issue.summary.clone(),
                issue.cause.clone(),
                issue.fix.clone(),
            );
        }

        for record in coverage.records.iter().filter(|record| !record.captured) {
            debug_finding_inbox_push(
                &mut records,
                DebugFindingSource::Coverage,
                format!("coverage.{}", record.area.label()),
                format!("Missing {}", record.area.title()),
                record.status,
                debug_finding_inbox_score(record.status, if record.required { 80 } else { 40 }),
                None,
                Some(record.area.title().to_owned()),
                record.panels.first().cloned(),
                None,
                format!("coverage.{}", record.area.label()),
                record.summary.clone(),
                record.cause.clone(),
                record.fix.clone(),
            );
        }

        for record in panels.records.iter().take(8) {
            debug_finding_inbox_push(
                &mut records,
                DebugFindingSource::PanelRecommendation,
                format!("panel.{}", record.panel),
                format!("Open {}", record.title),
                record.status,
                debug_finding_inbox_score(record.status, record.score.min(400)),
                None,
                record.subjects.first().cloned(),
                Some(record.panel.clone()),
                record.overlays.first().copied(),
                record.action.clone(),
                record.summary.clone(),
                record.cause.clone(),
                record.fix.clone(),
            );
        }

        for record in overlays.records.iter().take(8) {
            debug_finding_inbox_push(
                &mut records,
                DebugFindingSource::OverlayRecommendation,
                format!("overlay.{}", record.layer.label()),
                format!("Show {}", record.layer.title()),
                record.status,
                debug_finding_inbox_score(record.status, record.score.min(400)),
                None,
                record.subjects.first().cloned(),
                record.panels.first().cloned(),
                Some(record.layer),
                record.action.clone(),
                record.summary.clone(),
                record.cause.clone(),
                record.fix.clone(),
            );
        }

        for record in nodes.records.iter().take(8) {
            debug_finding_inbox_push(
                &mut records,
                DebugFindingSource::NodeRecommendation,
                format!("node.{}", debug_action_id_part(&record.name)),
                format!("Inspect {}", record.name),
                record.status,
                debug_finding_inbox_score(record.status, record.score.min(400)),
                record.node,
                Some(record.name.clone()),
                record.panels.first().cloned(),
                record.overlays.first().copied(),
                record.action.clone(),
                record.summary.clone(),
                record.cause.clone(),
                record.fix.clone(),
            );
        }

        finish_debug_finding_inbox(trace, coverage.missing_count, records)
    }

    pub fn record(&self, key: &str) -> Option<&DebugFindingRecord> {
        self.records.iter().find(|record| record.key == key)
    }

    pub fn compact_summary(&self) -> String {
        self.summary.clone()
    }
}

impl DebugHealthScoreTrace {
    pub fn from_frame_trace(trace: &DebugFrameTrace) -> Self {
        let contract = DebugContractReport::from_frame_trace(trace);
        let coverage = DebugDiagnosticsCoverageTrace::from_frame_trace(trace);
        let issues = DebugIssueReport::from_frame_trace(trace);
        Self::from_parts(trace, &contract, &coverage, &issues)
    }

    pub fn from_parts(
        trace: &DebugFrameTrace,
        contract: &DebugContractReport,
        coverage: &DebugDiagnosticsCoverageTrace,
        issues: &DebugIssueReport,
    ) -> Self {
        let mut records = [
            DebugHealthArea::Performance,
            DebugHealthArea::Layout,
            DebugHealthArea::Input,
            DebugHealthArea::Paint,
            DebugHealthArea::Text,
            DebugHealthArea::Resources,
            DebugHealthArea::Accessibility,
            DebugHealthArea::Instrumentation,
        ]
        .into_iter()
        .map(|area| debug_health_score_record(area, contract, coverage, issues))
        .collect::<Vec<_>>();
        records.sort_by(|left, right| {
            debug_frame_timeline_status_rank(left.status)
                .cmp(&debug_frame_timeline_status_rank(right.status))
                .then_with(|| left.score.cmp(&right.score))
                .then_with(|| {
                    debug_health_area_rank(left.area).cmp(&debug_health_area_rank(right.area))
                })
        });
        finish_debug_health_score(trace, records)
    }

    pub fn record(&self, area: DebugHealthArea) -> Option<&DebugHealthScoreRecord> {
        self.records.iter().find(|record| record.area == area)
    }

    pub fn compact_summary(&self) -> String {
        self.summary.clone()
    }
}

impl DebugRootCauseClusterTrace {
    pub fn from_frame_trace(trace: &DebugFrameTrace) -> Self {
        let findings = DebugFindingInboxTrace::from_frame_trace(trace);
        let nodes = DebugNodeRecommendationTrace::from_frame_trace(trace);
        let health = DebugHealthScoreTrace::from_frame_trace(trace);
        Self::from_parts(trace, &findings, &nodes, &health)
    }

    pub fn from_parts(
        trace: &DebugFrameTrace,
        findings: &DebugFindingInboxTrace,
        nodes: &DebugNodeRecommendationTrace,
        health: &DebugHealthScoreTrace,
    ) -> Self {
        let mut records = Vec::new();

        for finding in &findings.records {
            let subject = debug_root_cause_subject_from_finding(finding);
            debug_root_cause_cluster_push(
                &mut records,
                DebugRootCauseClusterSource::Finding,
                subject,
                finding.status,
                debug_root_cause_score(finding.status, finding.score.min(800)),
                finding.node,
                finding.node_name.clone(),
                finding.panel.clone().into_iter().collect(),
                finding.overlay.into_iter().collect(),
                vec![finding.action.clone()],
                finding.summary.clone(),
                finding.cause.clone(),
                finding.fix.clone(),
            );
        }

        for node in &nodes.records {
            debug_root_cause_cluster_push(
                &mut records,
                DebugRootCauseClusterSource::NodeRecommendation,
                DebugRootCauseSubject::Node(node.name.clone()),
                node.status,
                debug_root_cause_score(node.status, node.score.min(800)),
                node.node,
                Some(node.name.clone()),
                node.panels.clone(),
                node.overlays.clone(),
                vec![node.action.clone()],
                node.summary.clone(),
                node.cause.clone(),
                node.fix.clone(),
            );
        }

        for record in health.records.iter().filter(|record| {
            record.status != DebugFrameTraceStatus::Ok
                || record.issue_count > 0
                || record.missing_evidence_count > 0
        }) {
            debug_root_cause_cluster_push(
                &mut records,
                DebugRootCauseClusterSource::HealthScore,
                DebugRootCauseSubject::Area(record.area),
                record.status,
                debug_root_cause_score(
                    record.status,
                    (100u32.saturating_sub(record.score as u32)).saturating_mul(8),
                ),
                None,
                None,
                record.panels.clone(),
                record.overlays.clone(),
                vec![record.action.clone()],
                record.summary.clone(),
                record.cause.clone(),
                record.fix.clone(),
            );
        }

        finish_debug_root_cause_clusters(trace, records)
    }

    pub fn record(&self, key: &str) -> Option<&DebugRootCauseClusterRecord> {
        self.records.iter().find(|record| record.key == key)
    }

    pub fn compact_summary(&self) -> String {
        self.summary.clone()
    }
}

impl DebugRootCauseTimelineTrace {
    pub fn from_traces<'a>(traces: impl IntoIterator<Item = &'a DebugFrameTrace>) -> Self {
        let traces = traces.into_iter().collect::<Vec<_>>();
        let clusters = traces
            .iter()
            .map(|trace| DebugRootCauseClusterTrace::from_frame_trace(trace))
            .collect::<Vec<_>>();
        let mut records = BTreeMap::<String, DebugRootCauseTimelineRecord>::new();
        let mut frames = Vec::new();
        let mut previous_keys = BTreeSet::<String>::new();
        let mut previous_seen = false;

        for (index, (trace, cluster_trace)) in traces.iter().zip(clusters.iter()).enumerate() {
            let label = debug_frame_timeline_label(trace, index);
            let active_records = debug_root_cause_timeline_active_records(cluster_trace);
            let current_keys = active_records
                .iter()
                .map(|record| record.key.clone())
                .collect::<BTreeSet<_>>();
            let new_cluster_count = if previous_seen {
                current_keys.difference(&previous_keys).count()
            } else {
                current_keys.len()
            };
            let resolved_cluster_count = if previous_seen {
                previous_keys.difference(&current_keys).count()
            } else {
                0
            };
            let persistent_cluster_count = if previous_seen {
                current_keys.intersection(&previous_keys).count()
            } else {
                0
            };

            for record in active_records.iter().copied() {
                debug_root_cause_timeline_push_record(
                    &mut records,
                    &label,
                    record,
                    previous_seen && previous_keys.contains(&record.key),
                );
            }
            if previous_seen {
                for resolved_key in previous_keys.difference(&current_keys) {
                    if let Some(record) = records.get_mut(resolved_key) {
                        record.resolved_cluster_count += 1;
                        if record.status == DebugFrameTraceStatus::Ok {
                            record.status = DebugFrameTraceStatus::Info;
                        }
                    }
                }
            }

            frames.push(debug_root_cause_timeline_frame_record(
                index,
                trace,
                &label,
                &active_records,
                new_cluster_count,
                persistent_cluster_count,
                resolved_cluster_count,
            ));
            previous_keys = current_keys;
            previous_seen = true;
        }

        let mut records = records.into_values().collect::<Vec<_>>();
        for record in &mut records {
            record.summary = debug_root_cause_timeline_record_summary(record);
        }
        records.sort_by(|left, right| {
            debug_frame_timeline_status_rank(left.status)
                .cmp(&debug_frame_timeline_status_rank(right.status))
                .then_with(|| right.frame_count.cmp(&left.frame_count))
                .then_with(|| right.score.cmp(&left.score))
                .then_with(|| right.new_cluster_count.cmp(&left.new_cluster_count))
                .then_with(|| left.key.cmp(&right.key))
        });

        let frame_count = frames.len();
        let cluster_frame_count = frames
            .iter()
            .filter(|frame| frame.cluster_count > 0)
            .count();
        let changed_frame_count = frames
            .iter()
            .filter(|frame| frame.new_cluster_count > 0 || frame.resolved_cluster_count > 0)
            .count();
        let cluster_count = records.len();
        let warning_cluster_count = records
            .iter()
            .filter(|record| debug_contract_status_fails(record.status))
            .count();
        let warning_frame_count = frames
            .iter()
            .filter(|frame| debug_contract_status_fails(frame.status))
            .count();
        let occurrence_count = records.iter().map(|record| record.occurrence_count).sum();
        let new_cluster_count = frames.iter().map(|frame| frame.new_cluster_count).sum();
        let persistent_cluster_count = frames
            .iter()
            .map(|frame| frame.persistent_cluster_count)
            .sum();
        let resolved_cluster_count = frames
            .iter()
            .map(|frame| frame.resolved_cluster_count)
            .sum();
        let top_cluster = records.first().map(|record| record.title.clone());
        let top_action = records
            .first()
            .and_then(|record| record.actions.first().cloned());
        let mut status = frames
            .iter()
            .map(|frame| frame.status)
            .max()
            .unwrap_or(DebugFrameTraceStatus::Ok);
        if status == DebugFrameTraceStatus::Ok
            && (new_cluster_count > 0 || persistent_cluster_count > 0 || resolved_cluster_count > 0)
        {
            status = DebugFrameTraceStatus::Info;
        }
        let summary = debug_root_cause_timeline_summary(
            status,
            frame_count,
            cluster_frame_count,
            changed_frame_count,
            cluster_count,
            warning_cluster_count,
            new_cluster_count,
            persistent_cluster_count,
            resolved_cluster_count,
            top_cluster.as_deref(),
        );
        Self {
            status,
            frame_count,
            cluster_frame_count,
            changed_frame_count,
            cluster_count,
            warning_cluster_count,
            warning_frame_count,
            occurrence_count,
            new_cluster_count,
            persistent_cluster_count,
            resolved_cluster_count,
            top_cluster,
            top_action,
            records,
            frames,
            summary,
        }
    }

    pub fn record(&self, key: &str) -> Option<&DebugRootCauseTimelineRecord> {
        self.records.iter().find(|record| record.key == key)
    }

    pub fn frame(&self, label: &str) -> Option<&DebugRootCauseTimelineFrameRecord> {
        self.frames.iter().find(|frame| frame.label == label)
    }

    pub fn compact_summary(&self) -> String {
        self.summary.clone()
    }
}

impl DebugSessionNarrativeTrace {
    pub fn from_traces<'a>(traces: impl IntoIterator<Item = &'a DebugFrameTrace>) -> Self {
        let traces = traces.into_iter().collect::<Vec<_>>();
        let records = traces
            .iter()
            .enumerate()
            .map(|(index, &trace)| {
                let previous = index.checked_sub(1).map(|previous| traces[previous]);
                debug_session_narrative_record(index, trace, previous)
            })
            .collect::<Vec<_>>();
        let frame_count = traces.len();
        let event_count = records.len();
        let warning_event_count = records
            .iter()
            .filter(|record| debug_contract_status_fails(record.status))
            .count();
        let changed_frame_count = records
            .iter()
            .filter(|record| record.changed_node_count > 0)
            .count();
        let panel_change_count = records.iter().filter(|record| record.panel_changed).count();
        let slow_frame_count = records
            .iter()
            .filter(|record| record.over_budget_by.is_some())
            .count();
        let new_overlap_count = records.iter().map(|record| record.new_overlap_count).sum();
        let resolved_overlap_count = records
            .iter()
            .map(|record| record.resolved_overlap_count)
            .sum();
        let new_invariant_failure_count = records
            .iter()
            .map(|record| record.new_invariant_failure_count)
            .sum();
        let resolved_invariant_failure_count = records
            .iter()
            .map(|record| record.resolved_invariant_failure_count)
            .sum();
        let status = debug_session_narrative_trace_status(&records);
        let top_panel = records
            .iter()
            .rev()
            .find_map(|record| record.top_panel.clone());
        let primary_node = records
            .iter()
            .rev()
            .find_map(|record| record.primary_node.clone());
        let summary = debug_session_narrative_trace_summary(
            status,
            frame_count,
            warning_event_count,
            changed_frame_count,
            panel_change_count,
            slow_frame_count,
            new_overlap_count,
            new_invariant_failure_count,
            top_panel.as_deref(),
            primary_node.as_deref(),
        );

        Self {
            status,
            frame_count,
            event_count,
            warning_event_count,
            changed_frame_count,
            panel_change_count,
            slow_frame_count,
            new_overlap_count,
            resolved_overlap_count,
            new_invariant_failure_count,
            resolved_invariant_failure_count,
            top_panel,
            primary_node,
            records,
            summary,
        }
    }

    pub fn record(&self, label: &str) -> Option<&DebugSessionNarrativeRecord> {
        self.records.iter().find(|record| record.label == label)
    }
}

impl DebugPointerSessionTrace {
    pub fn from_traces<'a>(traces: impl IntoIterator<Item = &'a DebugFrameTrace>) -> Self {
        let traces = traces.into_iter().collect::<Vec<_>>();
        let mut records = Vec::new();
        let mut previous_route = None;
        let mut previous_record_label = None;
        for (frame_index, trace) in traces.iter().copied().enumerate() {
            let frame_label = debug_frame_timeline_label(trace, frame_index);
            for (route_index, route) in trace.routes.iter().enumerate() {
                let index = records.len();
                let record = debug_pointer_session_record(
                    index,
                    trace,
                    frame_label.clone(),
                    route_index,
                    route,
                    previous_route,
                    previous_record_label.as_deref(),
                );
                previous_route = Some(route);
                previous_record_label = Some(record.label.clone());
                records.push(record);
            }
        }
        let frame_count = traces.len();
        let route_count = records.len();
        let issue_route_count = records
            .iter()
            .filter(|record| debug_contract_status_fails(record.status))
            .count();
        let target_change_count = records
            .iter()
            .filter(|record| record.target_changed)
            .count();
        let miss_count = records
            .iter()
            .filter(|record| record.target.is_none())
            .count();
        let rejected_candidate_count = records.iter().map(|record| record.rejected_count).sum();
        let geometry_rejection_count = records
            .iter()
            .map(|record| record.geometry_rejection_count)
            .sum();
        let occluded_candidate_count = records.iter().map(|record| record.occluded_count).sum();
        let latest_target_name = records
            .iter()
            .rev()
            .find_map(|record| record.target_name.clone());
        let top_panel = records
            .iter()
            .rev()
            .find_map(|record| (!record.panel.is_empty()).then(|| record.panel.clone()));
        let status = debug_pointer_session_trace_status(&records);
        let summary = debug_pointer_session_trace_summary(
            status,
            frame_count,
            route_count,
            issue_route_count,
            target_change_count,
            miss_count,
            rejected_candidate_count,
            latest_target_name.as_deref(),
            top_panel.as_deref(),
        );

        Self {
            status,
            frame_count,
            route_count,
            issue_route_count,
            target_change_count,
            miss_count,
            rejected_candidate_count,
            geometry_rejection_count,
            occluded_candidate_count,
            latest_target_name,
            top_panel,
            records,
            summary,
        }
    }

    pub fn record(&self, label: &str) -> Option<&DebugPointerSessionRecord> {
        self.records.iter().find(|record| record.label == label)
    }
}

impl DebugWhyTimelineTrace {
    pub fn from_traces<'a>(traces: impl IntoIterator<Item = &'a DebugFrameTrace>) -> Self {
        let traces = traces.into_iter().collect::<Vec<_>>();
        let mut records = traces
            .iter()
            .enumerate()
            .map(|(index, trace)| debug_why_timeline_record(index, trace))
            .collect::<Vec<_>>();
        records.sort_by(|left, right| {
            debug_question_status_rank(left.status)
                .cmp(&debug_question_status_rank(right.status))
                .then_with(|| right.warning_count.cmp(&left.warning_count))
                .then_with(|| left.index.cmp(&right.index))
        });
        let frame_count = records.len();
        let warning_frame_count = records
            .iter()
            .filter(|record| {
                matches!(
                    record.status,
                    DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
                )
            })
            .count();
        let why_record_count = records.iter().map(|record| record.why_record_count).sum();
        let overlay_layers = debug_why_timeline_overlay_layers(&records);
        let overlay_layer_count = overlay_layers.len();
        let top = records.first();
        let top_panel = top.and_then(|record| record.top_panel.clone());
        let primary_overlay = top.and_then(|record| record.primary_overlay);
        let status = debug_why_timeline_status(&records);
        let summary = debug_why_timeline_summary(
            status,
            frame_count,
            warning_frame_count,
            why_record_count,
            overlay_layer_count,
        );
        Self {
            status,
            frame_count,
            warning_frame_count,
            why_record_count,
            overlay_layer_count,
            top_panel,
            primary_overlay,
            records,
            summary,
        }
    }

    pub fn record(&self, label: &str) -> Option<&DebugWhyTimelineRecord> {
        self.records.iter().find(|record| record.label == label)
    }
}

