impl DebugInvalidationBlameTrace {
    pub fn from_dirty_state(dirty: &DirtyStateExplanation) -> Self {
        let mut records = dirty
            .invalidations
            .iter()
            .enumerate()
            .map(|(index, invalidation)| debug_invalidation_blame_record(index, invalidation))
            .collect::<Vec<_>>();
        records.sort_by(|left, right| {
            debug_invalidation_status_rank(left.status)
                .cmp(&debug_invalidation_status_rank(right.status))
                .then_with(|| right.blast_radius.cmp(&left.blast_radius))
                .then_with(|| left.index.cmp(&right.index))
        });
        let invalidation_count = dirty.invalidations.len();
        let dirty_subsystem_count = dirty.recompute_order.len();
        let status = debug_invalidation_trace_status(dirty, &records);
        let summary = debug_invalidation_trace_summary(
            dirty.clean,
            invalidation_count,
            dirty_subsystem_count,
            status,
        );
        Self {
            flags: dirty.flags,
            clean: dirty.clean,
            status,
            invalidation_count,
            dirty_subsystem_count,
            recompute_order: dirty.recompute_order.clone(),
            records,
            summary,
        }
    }

    pub fn from_frame_trace(trace: &DebugFrameTrace) -> Self {
        Self::from_dirty_state(&trace.dirty)
    }

    pub fn primary(&self) -> Option<&DebugInvalidationBlameRecord> {
        self.records.first()
    }
}

impl DebugInvalidationBlastTrace {
    pub fn from_dirty_state(dirty: &DirtyStateExplanation) -> Self {
        debug_invalidation_blast_trace(dirty)
    }

    pub fn from_frame_trace(trace: &DebugFrameTrace) -> Self {
        Self::from_dirty_state(&trace.dirty)
    }

    pub fn record(&self, subsystem: DirtyStateSubsystem) -> Option<&DebugInvalidationBlastRecord> {
        self.records
            .iter()
            .find(|record| record.subsystem == subsystem)
    }
}

impl DebugInvalidationTimelineTrace {
    pub fn from_traces<'a>(traces: impl IntoIterator<Item = &'a DebugFrameTrace>) -> Self {
        Self::from_dirty_states(traces.into_iter().enumerate().map(|(index, trace)| {
            (
                debug_frame_timeline_label(trace, index),
                trace.frame_index,
                &trace.dirty,
            )
        }))
    }

    pub fn from_dirty_states<'a, L>(
        states: impl IntoIterator<Item = (L, Option<u64>, &'a DirtyStateExplanation)>,
    ) -> Self
    where
        L: Into<String>,
    {
        debug_invalidation_timeline_trace(states)
    }

    pub fn record(
        &self,
        reason: RuntimeInvalidationReason,
    ) -> Option<&DebugInvalidationTimelineReasonRecord> {
        self.records.iter().find(|record| record.reason == reason)
    }

    pub fn frame(&self, label: &str) -> Option<&DebugInvalidationTimelineFrameRecord> {
        self.frames.iter().find(|frame| frame.label == label)
    }
}

