impl DebugCacheReuseTrace {
    pub fn from_performance(snapshot: &PerformanceSnapshot) -> Self {
        Self::from_performance_and_display_lists(
            snapshot,
            std::iter::empty::<&DisplayListReuseReport>(),
        )
    }

    pub fn from_performance_and_display_lists<'a>(
        snapshot: &PerformanceSnapshot,
        display_reports: impl IntoIterator<Item = &'a DisplayListReuseReport>,
    ) -> Self {
        let mut records = snapshot
            .caches
            .iter()
            .map(debug_cache_reuse_record)
            .collect::<Vec<_>>();
        records.extend(
            snapshot
                .missing_required_cache_kinds()
                .into_iter()
                .map(debug_missing_cache_reuse_record),
        );
        records.sort_by(|left, right| {
            debug_cache_reuse_status_rank(left.status)
                .cmp(&debug_cache_reuse_status_rank(right.status))
                .then_with(|| left.name.cmp(&right.name))
        });

        let mut display_lists = display_reports
            .into_iter()
            .map(debug_display_list_reuse_record)
            .collect::<Vec<_>>();
        display_lists.sort_by(|left, right| {
            debug_cache_reuse_status_rank(left.status)
                .cmp(&debug_cache_reuse_status_rank(right.status))
                .then_with(|| left.key.cmp(&right.key))
        });

        let cache_count = snapshot.caches.len();
        let missing_required_count = records
            .iter()
            .filter(|record| record.missing_required)
            .count();
        let total_lookups = snapshot.caches.iter().map(|cache| cache.lookups).sum();
        let total_hits = snapshot.caches.iter().map(|cache| cache.hits).sum();
        let total_misses = snapshot.caches.iter().map(|cache| cache.misses).sum();
        let total_evictions = snapshot.caches.iter().map(|cache| cache.evictions).sum();
        let overall_hit_rate =
            (total_lookups > 0).then(|| total_hits as f32 / total_lookups as f32);
        let status = debug_cache_reuse_trace_status(&records, &display_lists);
        let summary = debug_cache_reuse_trace_summary(
            cache_count,
            missing_required_count,
            total_lookups,
            total_hits,
            total_misses,
            total_evictions,
            display_lists.len(),
            status,
        );

        Self {
            frame: snapshot.frame,
            status,
            cache_count,
            missing_required_count,
            total_lookups,
            total_hits,
            total_misses,
            total_evictions,
            overall_hit_rate,
            records,
            display_lists,
            summary,
        }
    }

    pub fn record(&self, name: &str) -> Option<&DebugCacheReuseRecord> {
        self.records.iter().find(|record| record.name == name)
    }
}

