#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DebugIssueTimelineTrace {
    pub status: DebugFrameTraceStatus,
    pub frame_count: usize,
    pub issue_frame_count: usize,
    pub changed_frame_count: usize,
    pub issue_count: usize,
    pub error_count: usize,
    pub warning_count: usize,
    pub info_count: usize,
    pub new_issue_count: usize,
    pub resolved_issue_count: usize,
    pub top_source: Option<DebugIssueSource>,
    pub records: Vec<DebugIssueTimelineSourceRecord>,
    pub frames: Vec<DebugIssueTimelineFrameRecord>,
    pub summary: String,
}

impl DebugIssueReport {
    pub fn from_frame_trace(trace: &DebugFrameTrace) -> Self {
        Self::from_frame_trace_with_budget(trace, &DebugFrameBudgetTrace::from_trace(trace))
    }

    pub fn from_frame_trace_with_budget(
        trace: &DebugFrameTrace,
        budget: &DebugFrameBudgetTrace,
    ) -> Self {
        let mut issues = Vec::new();
        collect_debug_budget_issues(budget, &mut issues);
        collect_debug_constraint_issues(&trace.snapshot.constraints, &mut issues);
        collect_debug_overlap_issues(&trace.snapshot.overlaps, &mut issues);
        collect_debug_resource_issues(&trace.resources.records, &mut issues);
        collect_debug_route_issues(&trace.routes, &mut issues);
        if let Some(selected) = &trace.selected_node {
            collect_debug_selected_node_issue(selected, &mut issues);
        }
        finish_debug_issue_report(trace.label.clone(), issues)
    }

    pub fn compact_summary(&self) -> String {
        self.summary.clone()
    }
}

impl DebugIssueTimelineTrace {
    pub fn from_traces<'a>(traces: impl IntoIterator<Item = &'a DebugFrameTrace>) -> Self {
        let traces = traces.into_iter().collect::<Vec<_>>();
        let reports = traces
            .iter()
            .map(|trace| DebugIssueReport::from_frame_trace(trace))
            .collect::<Vec<_>>();
        let frames = traces
            .iter()
            .zip(reports.iter())
            .enumerate()
            .map(|(index, (trace, report))| debug_issue_timeline_frame_record(index, trace, report))
            .collect::<Vec<_>>();
        let mut records =
            debug_issue_timeline_source_records(traces.as_slice(), reports.as_slice());
        records.sort_by(|left, right| {
            debug_frame_timeline_status_rank(left.status)
                .cmp(&debug_frame_timeline_status_rank(right.status))
                .then_with(|| right.new_issue_count.cmp(&left.new_issue_count))
                .then_with(|| right.issue_count.cmp(&left.issue_count))
                .then_with(|| left.source.cmp(&right.source))
        });
        let frame_count = frames.len();
        let issue_frame_count = frames.iter().filter(|frame| frame.issue_count > 0).count();
        let changed_frame_count = frames
            .windows(2)
            .filter(|pair| pair[0].source_counts != pair[1].source_counts)
            .count();
        let issue_count = reports.iter().map(|report| report.issue_count).sum();
        let error_count = reports.iter().map(|report| report.error_count).sum();
        let warning_count = reports.iter().map(|report| report.warning_count).sum();
        let info_count = reports.iter().map(|report| report.info_count).sum();
        let new_issue_count = records.iter().map(|record| record.new_issue_count).sum();
        let resolved_issue_count = records
            .iter()
            .map(|record| record.resolved_issue_count)
            .sum();
        let top_source = records.first().map(|record| record.source);
        let status = frames
            .iter()
            .map(|frame| frame.status)
            .max()
            .unwrap_or(DebugFrameTraceStatus::Ok);
        let summary = debug_issue_timeline_summary(
            status,
            frame_count,
            issue_frame_count,
            changed_frame_count,
            issue_count,
            new_issue_count,
            resolved_issue_count,
            top_source,
        );
        Self {
            status,
            frame_count,
            issue_frame_count,
            changed_frame_count,
            issue_count,
            error_count,
            warning_count,
            info_count,
            new_issue_count,
            resolved_issue_count,
            top_source,
            records,
            frames,
            summary,
        }
    }

    pub fn record(&self, source: DebugIssueSource) -> Option<&DebugIssueTimelineSourceRecord> {
        self.records.iter().find(|record| record.source == source)
    }

    pub fn frame(&self, label: &str) -> Option<&DebugIssueTimelineFrameRecord> {
        self.frames.iter().find(|frame| frame.label == label)
    }
}

