#[derive(Debug, Clone, PartialEq)]
pub struct DebugCaptureReport {
    pub title: String,
    pub status: DebugFrameTraceStatus,
    pub frame_label: String,
    pub frame_index: Option<u64>,
    pub frame_summary: String,
    pub timeline_summary: Option<String>,
    pub issue_summary: String,
    pub selected_node_summary: Option<String>,
    pub top_issues: Vec<DebugIssueRecord>,
    pub timeline_records: Vec<DebugFrameTimelineRecord>,
    pub sections: Vec<DebugCaptureReportSection>,
    pub summary: String,
}

impl DebugCaptureReport {
    pub fn from_frame_trace(trace: &DebugFrameTrace) -> Self {
        Self::from_frame_trace_and_timeline(trace, None)
    }

    pub fn from_frame_trace_and_timeline(
        trace: &DebugFrameTrace,
        timeline: Option<&DebugFrameTimelineTrace>,
    ) -> Self {
        let issues = DebugIssueReport::from_frame_trace(trace);
        let title = debug_capture_report_title(trace);
        let frame_label = debug_frame_timeline_label(trace, 0);
        let timeline_records = timeline
            .map(|timeline| timeline.records.iter().take(5).cloned().collect())
            .unwrap_or_default();
        let top_issues = issues.issues.iter().take(5).cloned().collect::<Vec<_>>();
        let timeline_summary = timeline.map(|timeline| timeline.summary.clone());
        let selected_node_summary = trace
            .selected_node
            .as_ref()
            .map(|selected| selected.summary.clone());
        let status = trace.summary.status.max(issues.status).max(
            timeline
                .map(|timeline| timeline.status)
                .unwrap_or(DebugFrameTraceStatus::Ok),
        );
        let mut report = Self {
            title,
            status,
            frame_label,
            frame_index: trace.frame_index,
            frame_summary: trace.summary.summary.clone(),
            timeline_summary,
            issue_summary: issues.summary.clone(),
            selected_node_summary,
            top_issues,
            timeline_records,
            sections: Vec::new(),
            summary: String::new(),
        };
        report.sections = debug_capture_report_sections(trace, timeline, &issues, &report);
        report.summary = debug_capture_report_summary(&report);
        report
    }

    pub fn compact_summary(&self) -> String {
        self.summary.clone()
    }

    pub fn markdown_line_count(&self) -> usize {
        self.to_markdown().lines().count()
    }

    pub fn to_markdown(&self) -> String {
        let mut lines = vec![format!("# {}", self.title), String::new()];
        lines.push(format!("- Status: {}", self.status.label()));
        lines.push(format!("- Summary: {}", self.summary));
        lines.push(format!("- Frame: {}", self.frame_label));
        if let Some(frame) = self.frame_index {
            lines.push(format!("- Frame index: {frame}"));
        }
        lines.push(String::new());
        for section in &self.sections {
            lines.push(format!("## {}", section.title));
            for line in &section.lines {
                lines.push(format!("- {line}"));
            }
            lines.push(String::new());
        }
        while lines.last().is_some_and(|line| line.is_empty()) {
            lines.pop();
        }
        lines.join("\n")
    }
}

