#[derive(Debug, Clone, PartialEq)]
pub struct DebugClipChainTrace {
    pub status: DebugFrameTraceStatus,
    pub node_count: usize,
    pub clipped_count: usize,
    pub fully_clipped_count: usize,
    pub interactive_clipped_count: usize,
    pub paint_clipped_count: usize,
    pub max_clipped_ratio: f32,
    pub records: Vec<DebugClipChainRecord>,
    pub summary: String,
}

impl DebugClipScrollTrace {
    pub fn from_snapshot(
        snapshot: &DebugInspectorSnapshot,
        selected_name: Option<&str>,
    ) -> Option<Self> {
        let selected = selected_debug_snapshot_node(snapshot, selected_name)?;
        let mut chain_ids = Vec::new();
        let mut current = Some(selected.id);
        while let Some(id) = current {
            let node = snapshot.node_by_id(id)?;
            chain_ids.push(id);
            current = node.parent;
        }
        chain_ids.reverse();

        let mut visible_rect = Some(selected.rect);
        let mut clipped_by = None;
        let mut clipped_by_name = None;
        let mut chain = Vec::new();
        for (depth, id) in chain_ids.iter().copied().enumerate() {
            let node = snapshot.node_by_id(id)?;
            let role = if id == selected.id {
                DebugLayoutCauseRole::Selected
            } else if depth == 0 {
                DebugLayoutCauseRole::Root
            } else {
                DebugLayoutCauseRole::Ancestor
            };
            let step = debug_clip_scroll_step(node, selected, role, depth, visible_rect);
            visible_rect = step.visible_rect_after;
            if clipped_by.is_none() && step.clips_selected {
                clipped_by = Some(step.node);
                clipped_by_name = Some(step.name.clone());
            }
            chain.push(step);
        }
        let scroll_ancestor_count = chain.iter().filter(|step| step.scroll.is_some()).count();
        let status = debug_clip_scroll_status(selected, visible_rect, clipped_by);
        let summary = debug_clip_scroll_summary(
            selected,
            status,
            visible_rect,
            clipped_by_name.as_deref(),
            scroll_ancestor_count,
        );

        Some(Self {
            selected: selected.id,
            selected_name: selected.name.clone(),
            status,
            rect: selected.rect,
            clip_rect: selected.clip_rect,
            visible_rect,
            clipped_by,
            clipped_by_name,
            scroll_ancestor_count,
            chain,
            summary,
        })
    }
}

impl DebugClipChainTrace {
    pub fn from_document(document: &UiDocument) -> Self {
        let snapshot = DebugHitboxSnapshot::from_document(document);
        let sources = debug_clip_chain_sources_from_document(document, &snapshot.nodes);
        Self::from_hitboxes_with_sources(&snapshot.nodes, &sources)
    }

    pub fn from_snapshot(snapshot: &DebugInspectorSnapshot) -> Self {
        let sources = debug_clip_chain_sources_from_snapshot(snapshot);
        Self::from_hitboxes_with_sources(&snapshot.hitboxes, &sources)
    }

    pub fn from_hitboxes(hitboxes: &[DebugHitboxNode]) -> Self {
        Self::from_hitboxes_with_sources(hitboxes, &HashMap::new())
    }

    fn from_hitboxes_with_sources(
        hitboxes: &[DebugHitboxNode],
        sources: &HashMap<UiNodeId, DebugClipChainSource>,
    ) -> Self {
        let names = hitboxes
            .iter()
            .map(|hitbox| (hitbox.id, hitbox.name.as_str()))
            .collect::<HashMap<_, _>>();
        let mut records = hitboxes
            .iter()
            .filter_map(|hitbox| debug_clip_chain_record(hitbox, &names, sources))
            .collect::<Vec<_>>();
        records.sort_by(|left, right| {
            debug_clip_chain_status_rank(left.status)
                .cmp(&debug_clip_chain_status_rank(right.status))
                .then_with(|| right.fully_clipped.cmp(&left.fully_clipped))
                .then_with(|| {
                    debug_bool_rank(right.pointer || right.focusable)
                        .cmp(&debug_bool_rank(left.pointer || left.focusable))
                })
                .then_with(|| right.clipped_ratio.total_cmp(&left.clipped_ratio))
                .then_with(|| left.name.cmp(&right.name))
        });

        let node_count = hitboxes.len();
        let clipped_count = records.len();
        let fully_clipped_count = records.iter().filter(|record| record.fully_clipped).count();
        let interactive_clipped_count = records
            .iter()
            .filter(|record| record.pointer || record.focusable)
            .count();
        let paint_clipped_count = records
            .iter()
            .filter(|record| record.paint_impacted)
            .count();
        let max_clipped_ratio = records
            .iter()
            .map(|record| record.clipped_ratio)
            .fold(0.0_f32, f32::max);
        let status = debug_clip_chain_trace_status(&records);
        let summary = debug_clip_chain_trace_summary(
            status,
            node_count,
            clipped_count,
            fully_clipped_count,
            interactive_clipped_count,
            paint_clipped_count,
            max_clipped_ratio,
        );

        Self {
            status,
            node_count,
            clipped_count,
            fully_clipped_count,
            interactive_clipped_count,
            paint_clipped_count,
            max_clipped_ratio,
            records,
            summary,
        }
    }

    pub fn record(&self, name: &str) -> Option<&DebugClipChainRecord> {
        self.records.iter().find(|record| record.name == name)
    }
}

