impl DebugLayoutAutopsyTrace {
    pub fn from_document(
        document: &UiDocument,
        text_measurer: &mut impl TextMeasurer,
        selected_name: Option<&str>,
    ) -> Option<Self> {
        let snapshot = DebugInspectorSnapshot::from_document(document, text_measurer);
        Self::from_snapshot(&snapshot, selected_name)
    }

    pub fn from_snapshot(
        snapshot: &DebugInspectorSnapshot,
        selected_name: Option<&str>,
    ) -> Option<Self> {
        let layout = DebugLayoutCauseTrace::from_snapshot(snapshot, selected_name)?;
        let selected = snapshot.node_by_id(layout.selected)?;
        let selected_step = layout
            .chain
            .iter()
            .find(|step| step.role == DebugLayoutCauseRole::Selected)?;
        let parent = selected
            .parent
            .and_then(|parent| snapshot.node_by_id(parent));
        let pressure = DebugLayoutPressureTrace::from_snapshot(snapshot)
            .records
            .into_iter()
            .find(|record| record.node == selected.id);
        let mut records = vec![
            debug_layout_autopsy_size_record(selected_step, pressure.as_ref(), &layout.constraints),
            debug_layout_autopsy_position_record(selected_step, parent),
            debug_layout_autopsy_parent_record(selected_step, parent),
            debug_layout_autopsy_siblings_record(&layout.siblings),
            debug_layout_autopsy_pressure_record(pressure.as_ref()),
            debug_layout_autopsy_clipping_record(selected_step, parent, pressure.as_ref()),
            debug_layout_autopsy_constraints_record(&layout.constraints),
        ];
        records.push(debug_layout_autopsy_next_step_record(&records));
        Some(finish_debug_layout_autopsy_trace(
            layout, pressure, selected, parent, records,
        ))
    }

    pub fn record(&self, source: DebugLayoutAutopsySource) -> Option<&DebugLayoutAutopsyRecord> {
        self.records.iter().find(|record| record.source == source)
    }
}

