impl DebugScrollRangeTrace {
    pub fn from_document(document: &UiDocument, text_measurer: &mut impl TextMeasurer) -> Self {
        let snapshot = DebugInspectorSnapshot::from_document(document, text_measurer);
        Self::from_snapshot(&snapshot)
    }

    pub fn from_snapshot(snapshot: &DebugInspectorSnapshot) -> Self {
        let mut records = snapshot
            .nodes
            .iter()
            .filter_map(debug_scroll_range_record)
            .collect::<Vec<_>>();
        records.sort_by(|left, right| {
            debug_scroll_range_status_rank(left.status)
                .cmp(&debug_scroll_range_status_rank(right.status))
                .then_with(|| {
                    let left_range = left.horizontal_range + left.vertical_range;
                    let right_range = right.horizontal_range + right.vertical_range;
                    right_range
                        .partial_cmp(&left_range)
                        .unwrap_or(std::cmp::Ordering::Equal)
                })
                .then_with(|| left.name.cmp(&right.name))
        });

        let scroll_node_count = records
            .iter()
            .filter(|record| record.scroll.is_some())
            .count();
        let overflow_node_count = records
            .iter()
            .filter(|record| record.horizontal_overflow || record.vertical_overflow)
            .count();
        let horizontal_range_count = records
            .iter()
            .filter(|record| record.horizontal_range > DEBUG_SCROLL_RANGE_EPSILON)
            .count();
        let vertical_range_count = records
            .iter()
            .filter(|record| record.vertical_range > DEBUG_SCROLL_RANGE_EPSILON)
            .count();
        let out_of_range_count = records
            .iter()
            .filter(|record| record.offset_out_of_range)
            .count();
        let scrollbar_count = records.iter().filter(|record| record.has_scrollbar).count();
        let status = debug_scroll_range_trace_status(&records);
        let summary = debug_scroll_range_trace_summary(
            status,
            records.len(),
            scroll_node_count,
            overflow_node_count,
            horizontal_range_count,
            vertical_range_count,
            out_of_range_count,
            scrollbar_count,
        );

        Self {
            status,
            node_count: snapshot.nodes.len(),
            scroll_node_count,
            overflow_node_count,
            horizontal_range_count,
            vertical_range_count,
            out_of_range_count,
            scrollbar_count,
            records,
            summary,
        }
    }

    pub fn record(&self, name: &str) -> Option<&DebugScrollRangeRecord> {
        self.records.iter().find(|record| record.name == name)
    }
}

