#[derive(Debug, Clone, PartialEq)]
pub struct DebugTextFitTrace {
    pub status: DebugFrameTraceStatus,
    pub text_node_count: usize,
    pub issue_count: usize,
    pub overflow_count: usize,
    pub clipped_count: usize,
    pub multi_line_count: usize,
    pub intrinsic_text_count: usize,
    pub records: Vec<DebugTextFitRecord>,
    pub summary: String,
}

impl DebugTextFitTrace {
    pub fn from_document(document: &UiDocument, text_measurer: &mut impl TextMeasurer) -> Self {
        let mut records = document
            .nodes()
            .iter()
            .enumerate()
            .filter_map(|(index, node)| {
                matches!(node.content(), UiContent::Text(_)).then_some(UiNodeId(index))
            })
            .filter_map(|node| debug_text_layout_trace(document, text_measurer, node))
            .map(|trace| debug_text_fit_record(&trace))
            .collect::<Vec<_>>();
        records.sort_by(|left, right| {
            debug_text_fit_status_rank(left.status)
                .cmp(&debug_text_fit_status_rank(right.status))
                .then_with(|| {
                    debug_text_fit_overflow_amount(right)
                        .total_cmp(&debug_text_fit_overflow_amount(left))
                })
                .then_with(|| right.estimated_line_count.cmp(&left.estimated_line_count))
                .then_with(|| left.name.cmp(&right.name))
        });

        let text_node_count = records.len();
        let issue_count = records
            .iter()
            .filter(|record| {
                matches!(
                    record.status,
                    DebugFrameTraceStatus::Warning | DebugFrameTraceStatus::Error
                )
            })
            .count();
        let overflow_count = records
            .iter()
            .filter(|record| record.horizontal_overflow || record.vertical_overflow)
            .count();
        let clipped_count = records
            .iter()
            .filter(|record| record.clip_reduces_text)
            .count();
        let multi_line_count = records
            .iter()
            .filter(|record| record.estimated_line_count > 1)
            .count();
        let intrinsic_text_count = records
            .iter()
            .filter(|record| record.uses_intrinsic_text)
            .count();
        let status = debug_text_fit_trace_status(&records);
        let summary = debug_text_fit_trace_summary(
            status,
            text_node_count,
            issue_count,
            overflow_count,
            clipped_count,
            multi_line_count,
        );

        Self {
            status,
            text_node_count,
            issue_count,
            overflow_count,
            clipped_count,
            multi_line_count,
            intrinsic_text_count,
            records,
            summary,
        }
    }

    pub fn record(&self, name: &str) -> Option<&DebugTextFitRecord> {
        self.records.iter().find(|record| record.name == name)
    }
}

