#[derive(Debug, Clone, PartialEq)]
pub struct DebugNodeProvenanceTrace {
    pub node: UiNodeId,
    pub name: String,
    pub status: DebugFrameTraceStatus,
    pub record_count: usize,
    pub warning_count: usize,
    pub records: Vec<DebugNodeProvenanceRecord>,
    pub summary: String,
}

impl DebugNodeExplanation {
    pub fn from_snapshot(
        snapshot: &DebugInspectorSnapshot,
        selected_name: Option<&str>,
    ) -> Option<Self> {
        Self::from_context(snapshot, selected_name, None, None)
    }

    pub fn from_context(
        snapshot: &DebugInspectorSnapshot,
        selected_name: Option<&str>,
        route: Option<&DebugEventRouteTrace>,
        resources: Option<&DebugResourceReport>,
    ) -> Option<Self> {
        let node = selected_debug_snapshot_node(snapshot, selected_name)?;
        let hitbox = snapshot.hitbox_by_id(node.id);
        let route_candidate = route.and_then(|trace| {
            trace
                .candidates
                .iter()
                .find(|candidate| candidate.id == node.id)
        });
        let route_explanation =
            route.map(|trace| debug_node_route_explanation(trace, node.id, route_candidate));
        let constraints = snapshot
            .constraints
            .iter()
            .filter(|issue| issue.node == Some(node.id) || issue.related_nodes.contains(&node.id))
            .cloned()
            .collect::<Vec<_>>();
        let overlaps = snapshot
            .overlaps_for(node.id)
            .map(|overlap| debug_node_overlap_explanation(node.id, overlap))
            .collect::<Vec<_>>();
        let resources = resources
            .map(|resources| {
                resources
                    .records
                    .iter()
                    .filter(|record| {
                        record
                            .references
                            .iter()
                            .any(|reference| reference.node == node.id)
                    })
                    .cloned()
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        let layout = debug_node_layout_explanation(node);
        let geometry = debug_node_geometry_explanation(node, hitbox);
        let input = debug_node_input_explanation(node, route_candidate, route_explanation.as_ref());
        let status =
            debug_node_explanation_status(&constraints, &resources, &overlaps, &geometry, &input);
        let summary = debug_node_explanation_summary(
            node,
            status,
            &constraints,
            &resources,
            &overlaps,
            route_explanation.as_ref(),
        );

        Some(Self {
            node: node.id,
            name: node.name.clone(),
            status,
            summary,
            layout,
            geometry,
            input,
            route: route_explanation,
            overlaps,
            constraints,
            resources,
        })
    }
}

impl DebugNodeProvenanceTrace {
    pub fn from_snapshot(
        snapshot: &DebugInspectorSnapshot,
        selected_name: Option<&str>,
    ) -> Option<Self> {
        Self::from_context(snapshot, selected_name, None)
    }

    pub fn from_context(
        snapshot: &DebugInspectorSnapshot,
        selected_name: Option<&str>,
        resources: Option<&DebugResourceReport>,
    ) -> Option<Self> {
        let node = selected_debug_snapshot_node(snapshot, selected_name)?;
        let hitbox = snapshot.hitbox_by_id(node.id);
        let animation = snapshot
            .animations
            .iter()
            .find(|animation| animation.id == node.id);
        let constraints = snapshot
            .constraints
            .iter()
            .filter(|issue| issue.node == Some(node.id) || issue.related_nodes.contains(&node.id))
            .collect::<Vec<_>>();
        let overlaps = snapshot.overlaps_for(node.id).collect::<Vec<_>>();
        let resource_records = resources
            .map(|resources| {
                resources
                    .records
                    .iter()
                    .filter(|record| {
                        record
                            .references
                            .iter()
                            .any(|reference| reference.node == node.id)
                    })
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();

        let mut records = vec![
            debug_node_provenance_content_record(node),
            debug_node_provenance_layout_record(node),
            debug_node_provenance_clip_scroll_record(node),
            debug_node_provenance_geometry_record(node, hitbox),
            debug_node_provenance_paint_record(snapshot, node),
            debug_node_provenance_input_record(node, hitbox),
            debug_node_provenance_accessibility_record(node),
            debug_node_provenance_animation_record(animation),
            debug_node_provenance_resource_record(resources.is_some(), &resource_records),
            debug_node_provenance_constraint_record(&constraints),
            debug_node_provenance_overlap_record(&overlaps),
        ];
        records.sort_by(|left, right| {
            debug_node_provenance_status_rank(left.status)
                .cmp(&debug_node_provenance_status_rank(right.status))
                .then_with(|| {
                    debug_node_provenance_source_rank(left.source)
                        .cmp(&debug_node_provenance_source_rank(right.source))
                })
        });
        let status = debug_node_provenance_trace_status(&records);
        let record_count = records.len();
        let warning_count = records
            .iter()
            .filter(|record| {
                matches!(
                    record.status,
                    DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
                )
            })
            .count();
        let summary =
            debug_node_provenance_trace_summary(node, status, record_count, warning_count);

        Some(Self {
            node: node.id,
            name: node.name.clone(),
            status,
            record_count,
            warning_count,
            records,
            summary,
        })
    }

    pub fn record(&self, source: DebugNodeProvenanceSource) -> Option<&DebugNodeProvenanceRecord> {
        self.records.iter().find(|record| record.source == source)
    }
}

