#[derive(Debug, Clone, PartialEq)]
pub struct DebugFrameNodeChange {
    pub name: String,
    pub before_id: Option<UiNodeId>,
    pub after_id: Option<UiNodeId>,
    pub kinds: Vec<DebugFrameChangeKind>,
    pub before_rect: Option<UiRect>,
    pub after_rect: Option<UiRect>,
    pub before_hit_rect: Option<UiRect>,
    pub after_hit_rect: Option<UiRect>,
    pub before_paint_rect: Option<UiRect>,
    pub after_paint_rect: Option<UiRect>,
    pub before_paint_count: Option<usize>,
    pub after_paint_count: Option<usize>,
    pub details: Vec<String>,
}

impl DebugFrameNodeChange {
    fn new(name: impl Into<String>) -> Self {
        Self {
            name: name.into(),
            before_id: None,
            after_id: None,
            kinds: Vec::new(),
            before_rect: None,
            after_rect: None,
            before_hit_rect: None,
            after_hit_rect: None,
            before_paint_rect: None,
            after_paint_rect: None,
            before_paint_count: None,
            after_paint_count: None,
            details: Vec::new(),
        }
    }

    fn push_kind(&mut self, kind: DebugFrameChangeKind) {
        if !self.kinds.contains(&kind) {
            self.kinds.push(kind);
        }
    }

    pub fn kind_labels(&self) -> Vec<&'static str> {
        self.kinds.iter().map(|kind| kind.label()).collect()
    }

    pub fn summary(&self) -> String {
        let labels = self.kind_labels();
        if labels.is_empty() {
            "unchanged".to_owned()
        } else {
            labels.join(", ")
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct DebugFrameDiff {
    pub before_node_count: usize,
    pub after_node_count: usize,
    pub changed_nodes: Vec<DebugFrameNodeChange>,
}

impl DebugFrameDiff {
    pub fn from_snapshots(before: &DebugInspectorSnapshot, after: &DebugInspectorSnapshot) -> Self {
        let before_nodes = debug_nodes_by_name(&before.nodes);
        let after_nodes = debug_nodes_by_name(&after.nodes);
        let before_hitboxes = debug_hitboxes_by_name(&before.hitboxes);
        let after_hitboxes = debug_hitboxes_by_name(&after.hitboxes);
        let before_animations = debug_animations_by_name(&before.animations);
        let after_animations = debug_animations_by_name(&after.animations);
        let before_accessibility =
            debug_accessibility_overlay_by_name(&before.accessibility_overlay);
        let after_accessibility = debug_accessibility_overlay_by_name(&after.accessibility_overlay);

        let mut names = BTreeSet::new();
        extend_debug_names(&mut names, before_nodes.keys().copied());
        extend_debug_names(&mut names, after_nodes.keys().copied());
        extend_debug_names(&mut names, before_hitboxes.keys().copied());
        extend_debug_names(&mut names, after_hitboxes.keys().copied());
        extend_debug_names(&mut names, before_animations.keys().copied());
        extend_debug_names(&mut names, after_animations.keys().copied());
        extend_debug_names(&mut names, before_accessibility.keys().copied());
        extend_debug_names(&mut names, after_accessibility.keys().copied());

        let mut changed_nodes = names
            .into_iter()
            .filter_map(|name| {
                debug_frame_node_change(
                    &name,
                    before_nodes.get(name.as_str()).copied(),
                    after_nodes.get(name.as_str()).copied(),
                    before_hitboxes.get(name.as_str()).copied(),
                    after_hitboxes.get(name.as_str()).copied(),
                    before_animations.get(name.as_str()).copied(),
                    after_animations.get(name.as_str()).copied(),
                    before_accessibility.get(name.as_str()).copied(),
                    after_accessibility.get(name.as_str()).copied(),
                )
            })
            .collect::<Vec<_>>();
        changed_nodes.sort_by(|left, right| {
            debug_frame_change_priority(right)
                .cmp(&debug_frame_change_priority(left))
                .then_with(|| left.name.cmp(&right.name))
        });

        Self {
            before_node_count: before.nodes.len(),
            after_node_count: after.nodes.len(),
            changed_nodes,
        }
    }

    pub fn is_empty(&self) -> bool {
        self.changed_nodes.is_empty()
    }

    pub fn changed_count(&self) -> usize {
        self.changed_nodes.len()
    }

    pub fn added_count(&self) -> usize {
        self.count_kind(DebugFrameChangeKind::Added)
    }

    pub fn removed_count(&self) -> usize {
        self.count_kind(DebugFrameChangeKind::Removed)
    }

    pub fn count_kind(&self, kind: DebugFrameChangeKind) -> usize {
        self.changed_nodes
            .iter()
            .filter(|change| change.kinds.contains(&kind))
            .count()
    }

    pub fn change(&self, name: &str) -> Option<&DebugFrameNodeChange> {
        self.changed_nodes.iter().find(|change| change.name == name)
    }

    pub fn summary(&self) -> String {
        if self.changed_nodes.is_empty() {
            return "no frame changes".to_owned();
        }
        let added = self.added_count();
        let removed = self.removed_count();
        let changed = self.changed_nodes.len().saturating_sub(added + removed);
        format!("{changed} changed, {added} added, {removed} removed")
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum DebugLayoutMovementKind {
    Added,
    Removed,
    Moved,
    Resized,
    Reparented,
    Reordered,
    ClipChanged,
    StyleChanged,
    ContentChanged,
    VisibilityChanged,
    ScrollChanged,
    ParentMoved,
    SiblingChanged,
    ConstraintWarning,
}

impl DebugLayoutMovementKind {
    pub const fn label(self) -> &'static str {
        match self {
            Self::Added => "added",
            Self::Removed => "removed",
            Self::Moved => "moved",
            Self::Resized => "resized",
            Self::Reparented => "reparented",
            Self::Reordered => "reordered",
            Self::ClipChanged => "clip",
            Self::StyleChanged => "style",
            Self::ContentChanged => "content",
            Self::VisibilityChanged => "visibility",
            Self::ScrollChanged => "scroll",
            Self::ParentMoved => "parent",
            Self::SiblingChanged => "sibling",
            Self::ConstraintWarning => "constraint",
        }
    }
}

