#[derive(Debug, Clone, PartialEq)]
pub struct DebugRenderLayerTrace {
    pub status: DebugFrameTraceStatus,
    pub item_count: usize,
    pub layer_count: usize,
    pub shader_item_count: usize,
    pub transparent_item_count: usize,
    pub clipped_item_count: usize,
    pub offscreen_item_count: usize,
    pub layers: Vec<DebugRenderLayerRecord>,
    pub featured_items: Vec<DebugRenderLayerItemRecord>,
    pub summary: String,
}

impl DebugRenderLayerTrace {
    pub fn from_document(document: &UiDocument) -> Self {
        Self::from_dump(&DebugPaintDump::from_document(document))
    }

    pub fn from_parts(layout: &LayoutSnapshot, paint: &PaintList) -> Self {
        Self::from_dump(&DebugPaintDump::from_parts(layout, paint))
    }

    pub fn from_dump(dump: &DebugPaintDump) -> Self {
        let mut accumulators = BTreeMap::<UiLayer, DebugRenderLayerAccumulator>::new();
        let mut featured_items = Vec::new();
        for (index, item) in dump.items.iter().enumerate() {
            accumulators
                .entry(item.layer)
                .or_insert_with(|| DebugRenderLayerAccumulator::new(item.layer))
                .record(item);
            if let Some(record) = debug_render_layer_item_record(index, item) {
                featured_items.push(record);
            }
        }

        let layers = accumulators
            .into_values()
            .map(DebugRenderLayerAccumulator::finish)
            .collect::<Vec<_>>();
        featured_items.sort_by(|left, right| {
            debug_render_layer_status_rank(left.status)
                .cmp(&debug_render_layer_status_rank(right.status))
                .then_with(|| right.resolved_z.total_cmp(&left.resolved_z))
                .then_with(|| left.index.cmp(&right.index))
        });

        let shader_item_count = layers.iter().map(|layer| layer.shader_count).sum();
        let transparent_item_count = layers.iter().map(|layer| layer.transparent_count).sum();
        let clipped_item_count = layers.iter().map(|layer| layer.clipped_count).sum();
        let offscreen_item_count = layers.iter().map(|layer| layer.offscreen_count).sum();
        let status = debug_render_layer_trace_status(&layers, &featured_items);
        let summary = debug_render_layer_trace_summary(
            status,
            dump.item_count,
            layers.len(),
            shader_item_count,
            transparent_item_count,
            clipped_item_count,
            offscreen_item_count,
        );

        Self {
            status,
            item_count: dump.item_count,
            layer_count: layers.len(),
            shader_item_count,
            transparent_item_count,
            clipped_item_count,
            offscreen_item_count,
            layers,
            featured_items,
            summary,
        }
    }

    pub fn layer(&self, layer: UiLayer) -> Option<&DebugRenderLayerRecord> {
        self.layers.iter().find(|record| record.layer == layer)
    }
}

