#[derive(Debug, Clone, PartialEq)]
pub struct DebugPaintOverdrawTimelineTrace {
    pub status: DebugFrameTraceStatus,
    pub frame_count: usize,
    pub overdraw_frame_count: usize,
    pub warning_frame_count: usize,
    pub changed_frame_count: usize,
    pub item_count: usize,
    pub covered_item_count: usize,
    pub new_overdraw_count: usize,
    pub resolved_overdraw_count: usize,
    pub persistent_overdraw_count: usize,
    pub total_covered_area: f32,
    pub max_covered_ratio: f32,
    pub top_key: Option<String>,
    pub top_name: Option<String>,
    pub records: Vec<DebugPaintOverdrawTimelineRecord>,
    pub frames: Vec<DebugPaintOverdrawTimelineFrameRecord>,
    pub summary: String,
}

impl DebugPaintOverdrawTrace {
    pub fn from_document(document: &UiDocument) -> Self {
        Self::from_dump(&DebugPaintDump::from_document(document))
    }

    pub fn from_parts(layout: &LayoutSnapshot, paint: &PaintList) -> Self {
        Self::from_dump(&DebugPaintDump::from_parts(layout, paint))
    }

    pub fn from_dump(dump: &DebugPaintDump) -> Self {
        let ordered = debug_paint_items_bottom_to_top(dump);
        let mut records = Vec::new();
        for position in 0..ordered.len() {
            if let Some(record) = debug_paint_overdraw_record(position, &ordered) {
                records.push(record);
            }
        }
        records.sort_by(|left, right| {
            debug_paint_overdraw_status_rank(left.status)
                .cmp(&debug_paint_overdraw_status_rank(right.status))
                .then_with(|| right.covered_ratio.total_cmp(&left.covered_ratio))
                .then_with(|| right.covered_area.total_cmp(&left.covered_area))
                .then_with(|| left.item_index.cmp(&right.item_index))
        });
        let covered_item_count = records.len();
        let total_covered_area = records.iter().map(|record| record.covered_area).sum();
        let max_covered_ratio = records
            .iter()
            .map(|record| record.covered_ratio)
            .fold(0.0_f32, f32::max);
        let status = debug_paint_overdraw_trace_status(&records);
        let summary = debug_paint_overdraw_trace_summary(
            status,
            dump.item_count,
            covered_item_count,
            total_covered_area,
            max_covered_ratio,
        );

        Self {
            status,
            item_count: dump.item_count,
            covered_item_count,
            total_covered_area,
            max_covered_ratio,
            records,
            summary,
        }
    }

    pub fn record(&self, name: &str) -> Option<&DebugPaintOverdrawRecord> {
        self.records
            .iter()
            .find(|record| record.node_name.as_deref() == Some(name))
    }
}

impl DebugPaintOverdrawTimelineTrace {
    pub fn from_traces<'a>(traces: impl IntoIterator<Item = &'a DebugFrameTrace>) -> Self {
        debug_paint_overdraw_timeline_trace(traces)
    }

    pub fn record(&self, key: &str) -> Option<&DebugPaintOverdrawTimelineRecord> {
        self.records.iter().find(|record| record.key == key)
    }

    pub fn record_name(&self, name: &str) -> Option<&DebugPaintOverdrawTimelineRecord> {
        self.records
            .iter()
            .find(|record| record.node_name.as_deref() == Some(name))
    }

    pub fn frame(&self, label: &str) -> Option<&DebugPaintOverdrawTimelineFrameRecord> {
        self.frames.iter().find(|frame| frame.label == label)
    }
}

