#[derive(Debug, Clone, PartialEq)]
pub struct DebugPaintBatchTrace {
    pub status: DebugFrameTraceStatus,
    pub item_count: usize,
    pub batch_count: usize,
    pub singleton_batch_count: usize,
    pub largest_batch_len: usize,
    pub average_items_per_batch: f32,
    pub break_count: usize,
    pub records: Vec<DebugPaintBatchRecord>,
    pub breaks: Vec<DebugPaintBatchBreakRecord>,
    pub summary: String,
}

impl DebugPaintBatchTrace {
    pub fn from_document(document: &UiDocument) -> Self {
        let layout = document.layout_snapshot();
        let paint = document.paint_list();
        Self::from_parts(&layout, &paint)
    }

    pub fn from_parts(layout: &LayoutSnapshot, paint: &PaintList) -> Self {
        let names = layout_names_by_node(layout);
        let batches = PaintBatcher::default().batch(paint);
        let mut records = batches
            .iter()
            .enumerate()
            .map(|(index, batch)| debug_paint_batch_record(index, batch, paint, &names))
            .collect::<Vec<_>>();
        records.sort_by(|left, right| {
            debug_paint_batch_status_rank(left.status)
                .cmp(&debug_paint_batch_status_rank(right.status))
                .then_with(|| left.batch_index.cmp(&right.batch_index))
        });

        let mut breaks = batches
            .windows(2)
            .enumerate()
            .map(|(index, pair)| debug_paint_batch_break_record(index, &pair[0], &pair[1]))
            .collect::<Vec<_>>();
        breaks.sort_by(|left, right| {
            debug_paint_batch_status_rank(left.status)
                .cmp(&debug_paint_batch_status_rank(right.status))
                .then_with(|| left.from_batch.cmp(&right.from_batch))
        });

        let batch_count = batches.len();
        let item_count = paint.items.len();
        let singleton_batch_count = batches.iter().filter(|batch| batch.len() == 1).count();
        let largest_batch_len = batches.iter().map(|batch| batch.len()).max().unwrap_or(0);
        let average_items_per_batch = if batch_count == 0 {
            0.0
        } else {
            item_count as f32 / batch_count as f32
        };
        let status = debug_paint_batch_trace_status(
            item_count,
            batch_count,
            singleton_batch_count,
            &records,
            &breaks,
        );
        let summary = debug_paint_batch_trace_summary(
            status,
            item_count,
            batch_count,
            singleton_batch_count,
            largest_batch_len,
            average_items_per_batch,
        );

        Self {
            status,
            item_count,
            batch_count,
            singleton_batch_count,
            largest_batch_len,
            average_items_per_batch,
            break_count: breaks.len(),
            records,
            breaks,
            summary,
        }
    }

    pub fn batch(&self, index: usize) -> Option<&DebugPaintBatchRecord> {
        self.records
            .iter()
            .find(|record| record.batch_index == index)
    }
}

