#[derive(Debug)]
struct DebugRenderLayerAccumulator {
    layer: UiLayer,
    item_count: usize,
    nodes: HashSet<UiNodeId>,
    min_z_index: f32,
    max_z_index: f32,
    min_resolved_z: f32,
    max_resolved_z: f32,
    shader_count: usize,
    transparent_count: usize,
    clipped_count: usize,
    offscreen_count: usize,
    kind_counts: BTreeMap<String, usize>,
}

impl DebugRenderLayerAccumulator {
    fn new(layer: UiLayer) -> Self {
        Self {
            layer,
            item_count: 0,
            nodes: HashSet::new(),
            min_z_index: f32::MAX,
            max_z_index: f32::MIN,
            min_resolved_z: f32::MAX,
            max_resolved_z: f32::MIN,
            shader_count: 0,
            transparent_count: 0,
            clipped_count: 0,
            offscreen_count: 0,
            kind_counts: BTreeMap::new(),
        }
    }

    fn record(&mut self, item: &DebugPaintItem) {
        self.item_count += 1;
        self.nodes.insert(item.node);
        self.min_z_index = self.min_z_index.min(item.z_index);
        self.max_z_index = self.max_z_index.max(item.z_index);
        self.min_resolved_z = self.min_resolved_z.min(item.resolved_z);
        self.max_resolved_z = self.max_resolved_z.max(item.resolved_z);
        if item.shader_key.is_some() {
            self.shader_count += 1;
        }
        if debug_paint_item_transparent(item) {
            self.transparent_count += 1;
        }
        if debug_paint_item_clipped(item) {
            self.clipped_count += 1;
        }
        if debug_paint_item_offscreen(item) {
            self.offscreen_count += 1;
        }
        *self.kind_counts.entry(item.kind.clone()).or_default() += 1;
    }

    fn finish(self) -> DebugRenderLayerRecord {
        let status = debug_render_layer_record_status(
            self.item_count,
            self.shader_count,
            self.transparent_count,
            self.clipped_count,
            self.offscreen_count,
        );
        let kind_counts = self
            .kind_counts
            .into_iter()
            .map(|(kind, count)| DebugPaintKindCount { kind, count })
            .collect::<Vec<_>>();
        let summary = debug_render_layer_record_summary(
            self.layer,
            self.item_count,
            self.nodes.len(),
            self.min_resolved_z,
            self.max_resolved_z,
            self.shader_count,
            self.transparent_count,
            self.clipped_count,
            self.offscreen_count,
        );
        let cause = debug_render_layer_record_cause(
            self.item_count,
            self.shader_count,
            self.transparent_count,
            self.clipped_count,
            self.offscreen_count,
            self.min_resolved_z,
            self.max_resolved_z,
        );
        let fix = debug_render_layer_record_fix(
            self.item_count,
            self.shader_count,
            self.transparent_count,
            self.clipped_count,
            self.offscreen_count,
        );

        DebugRenderLayerRecord {
            layer: self.layer,
            item_count: self.item_count,
            node_count: self.nodes.len(),
            min_z_index: self.min_z_index,
            max_z_index: self.max_z_index,
            min_resolved_z: self.min_resolved_z,
            max_resolved_z: self.max_resolved_z,
            shader_count: self.shader_count,
            transparent_count: self.transparent_count,
            clipped_count: self.clipped_count,
            offscreen_count: self.offscreen_count,
            kind_counts,
            status,
            summary,
            cause,
            fix,
        }
    }
}

