#[derive(Debug, Clone, PartialEq)]
pub struct DebugPaintOrderTrace {
    pub point: UiPoint,
    pub status: DebugNodeExplanationStatus,
    pub item_count: usize,
    pub stack: Vec<DebugPaintStackItem>,
    pub top_visible_index: Option<usize>,
    pub top_visible_node: Option<UiNodeId>,
    pub top_visible_name: Option<String>,
    pub summary: String,
}

impl DebugPaintOrderTrace {
    pub fn from_document(document: &UiDocument, point: UiPoint) -> Self {
        let layout = document.layout_snapshot();
        let paint = document.paint_list();
        Self::from_parts(&layout, &paint, point)
    }

    pub fn from_parts(layout: &LayoutSnapshot, paint: &PaintList, point: UiPoint) -> Self {
        let names = layout_names_by_node(layout);
        let mut stack = paint
            .items
            .iter()
            .enumerate()
            .filter_map(|(index, item)| debug_paint_stack_item(index, item, &names, point))
            .collect::<Vec<_>>();
        stack.sort_by(|left, right| {
            right
                .resolved_z
                .total_cmp(&left.resolved_z)
                .then_with(|| right.z_index.total_cmp(&left.z_index))
                .then_with(|| right.index.cmp(&left.index))
        });
        let top_visible = stack.iter().find(|item| item.visible_at_point);
        let top_visible_index = top_visible.map(|item| item.index);
        let top_visible_node = top_visible.map(|item| item.node);
        let top_visible_name = top_visible.and_then(|item| item.node_name.clone());
        let status = debug_paint_order_status(&stack, top_visible_index);
        let summary = debug_paint_order_summary(point, status, &stack, top_visible);

        Self {
            point,
            status,
            item_count: paint.items.len(),
            stack,
            top_visible_index,
            top_visible_node,
            top_visible_name,
            summary,
        }
    }
}

