#[derive(Debug, Clone, PartialEq)]
pub struct DebugHitboxSnapshot {
    pub nodes: Vec<DebugHitboxNode>,
}

impl DebugHitboxSnapshot {
    pub fn from_document(document: &UiDocument) -> Self {
        let paint = document.paint_list();
        let paint_bounds = paint_visible_bounds_by_node(&paint);
        let nodes = document
            .effective_geometries()
            .into_iter()
            .map(|geometry| {
                let record = geometry.diagnostic_record();
                let transform = geometry.transform;
                let node = document.node(record.node);
                let input = node.input();
                DebugHitboxNode {
                    id: record.node,
                    name: node.name().to_owned(),
                    parent: node.parent(),
                    rect: record.original_rect,
                    transformed_rect: record.transformed_rect,
                    transform,
                    clip_rect: node.layout.clip_rect,
                    visible_rect: record.visible_rect,
                    hit_rect: record
                        .hit_eligibility
                        .eligible
                        .then_some(record.visible_rect)
                        .flatten(),
                    paint_rect: paint_bounds.get(&record.node).copied(),
                    pointer: input.pointer,
                    focusable: input.focusable,
                    visible: record.visible,
                    hit_testable: record.hit_testable,
                    hit_shape: record.hit_shape,
                    hit_eligibility: record.hit_eligibility,
                    clip_chain: record.clip_chain,
                    layer_order: record.layer_order,
                    layer: record.layer,
                    local_z: record.local_z,
                    resolved_z: record.resolved_z,
                    order: record.order,
                }
            })
            .collect();
        Self { nodes }
    }

    pub fn node(&self, name: &str) -> Option<&DebugHitboxNode> {
        self.nodes.iter().find(|node| node.name == name)
    }

    pub fn topmost_at(&self, point: UiPoint) -> Option<&DebugHitboxNode> {
        self.nodes
            .iter()
            .filter(|node| debug_hitbox_contains_point(node, point))
            .max_by_key(|node| (node.layer_order, node.order, node.id.0))
    }
}

