impl DebugStackingOrderTrace {
    pub fn from_document(document: &UiDocument) -> Self {
        let hitbox_snapshot = DebugHitboxSnapshot::from_document(document);
        Self::from_hitboxes(&hitbox_snapshot.nodes)
    }

    pub fn from_snapshot(snapshot: &DebugInspectorSnapshot) -> Self {
        Self::from_hitboxes(&snapshot.hitboxes)
    }

    pub fn from_hitboxes(hitboxes: &[DebugHitboxNode]) -> Self {
        let mut ordered = hitboxes
            .iter()
            .filter(|hitbox| debug_stacking_order_relevant(hitbox))
            .cloned()
            .collect::<Vec<_>>();
        ordered.sort_by(|left, right| debug_node_sort_key(right).cmp(&debug_node_sort_key(left)));

        let mut overlaps_in_front = vec![0_usize; ordered.len()];
        let mut overlaps_behind = vec![0_usize; ordered.len()];
        let mut front_neighbor = vec![None::<String>; ordered.len()];
        let mut back_neighbor = vec![None::<String>; ordered.len()];
        let mut overlap_pair_count = 0_usize;

        for front_index in 0..ordered.len() {
            let Some(front_rect) = debug_stacking_order_rect(&ordered[front_index]) else {
                continue;
            };
            for back_index in (front_index + 1)..ordered.len() {
                let Some(back_rect) = debug_stacking_order_rect(&ordered[back_index]) else {
                    continue;
                };
                if rect_overlap_at_least(front_rect, back_rect, 1.0).is_none() {
                    continue;
                }
                overlap_pair_count += 1;
                overlaps_behind[front_index] += 1;
                overlaps_in_front[back_index] += 1;
                if back_neighbor[front_index].is_none() {
                    back_neighbor[front_index] = Some(ordered[back_index].name.clone());
                }
                if front_neighbor[back_index].is_none() {
                    front_neighbor[back_index] = Some(ordered[front_index].name.clone());
                }
            }
        }

        let records = ordered
            .iter()
            .enumerate()
            .map(|(front_index, hitbox)| {
                debug_stacking_order_record(
                    hitbox,
                    front_index,
                    overlaps_in_front[front_index],
                    overlaps_behind[front_index],
                    front_neighbor[front_index].clone(),
                    back_neighbor[front_index].clone(),
                )
            })
            .collect::<Vec<_>>();
        let node_count = records.len();
        let interactive_count = records
            .iter()
            .filter(|record| record.pointer || record.focusable)
            .count();
        let paint_count = records.iter().filter(|record| record.has_paint).count();
        let layer_count = records
            .iter()
            .map(|record| record.layer)
            .collect::<BTreeSet<_>>()
            .len();
        let min_resolved_z = records
            .iter()
            .map(|record| record.resolved_z)
            .min_by(|left, right| left.total_cmp(right));
        let max_resolved_z = records
            .iter()
            .map(|record| record.resolved_z)
            .max_by(|left, right| left.total_cmp(right));
        let covered_interactive_count = records
            .iter()
            .filter(|record| {
                (record.pointer || record.focusable)
                    && record.effective_hit
                    && record.overlaps_in_front > 0
            })
            .count();
        let status = debug_stacking_order_trace_status(&records);
        let summary = debug_stacking_order_trace_summary(
            status,
            node_count,
            interactive_count,
            paint_count,
            layer_count,
            min_resolved_z,
            max_resolved_z,
            overlap_pair_count,
            covered_interactive_count,
        );

        Self {
            status,
            node_count,
            interactive_count,
            paint_count,
            layer_count,
            min_resolved_z,
            max_resolved_z,
            overlap_pair_count,
            covered_interactive_count,
            records,
            summary,
        }
    }

    pub fn record(&self, name: &str) -> Option<&DebugStackingOrderRecord> {
        self.records.iter().find(|record| record.name == name)
    }
}

