impl DebugHitboxMapTrace {
    pub fn from_document(document: &UiDocument) -> Self {
        let hitbox_snapshot = DebugHitboxSnapshot::from_document(document);
        let actions = hitbox_snapshot
            .nodes
            .iter()
            .map(|hitbox| {
                let node = document.node(hitbox.id);
                (
                    hitbox.id,
                    (
                        node.action().map(debug_action_binding_label),
                        Some(node.action_mode()),
                    ),
                )
            })
            .collect::<HashMap<_, _>>();
        Self::from_hitboxes_with_actions(&hitbox_snapshot.nodes, &actions)
    }

    pub fn from_snapshot(snapshot: &DebugInspectorSnapshot) -> Self {
        Self::from_hitboxes(&snapshot.hitboxes)
    }

    pub fn from_hitboxes(hitboxes: &[DebugHitboxNode]) -> Self {
        Self::from_hitboxes_with_actions(hitboxes, &HashMap::new())
    }

    fn from_hitboxes_with_actions(
        hitboxes: &[DebugHitboxNode],
        actions: &HashMap<UiNodeId, (Option<String>, Option<WidgetActionMode>)>,
    ) -> Self {
        let mut records = hitboxes
            .iter()
            .map(|hitbox| {
                let (action, action_mode) = actions.get(&hitbox.id).cloned().unwrap_or_default();
                debug_hitbox_map_record(hitbox, action, action_mode)
            })
            .collect::<Vec<_>>();
        records.sort_by(|left, right| {
            debug_hitbox_map_status_rank(left.status)
                .cmp(&debug_hitbox_map_status_rank(right.status))
                .then_with(|| {
                    debug_bool_rank(right.pointer || right.focusable)
                        .cmp(&debug_bool_rank(left.pointer || left.focusable))
                })
                .then_with(|| right.layer.cmp(&left.layer))
                .then_with(|| right.resolved_z.total_cmp(&left.resolved_z))
                .then_with(|| right.order.cmp(&left.order))
                .then_with(|| left.name.cmp(&right.name))
        });
        let node_count = records.len();
        let interactive_count = records
            .iter()
            .filter(|record| record.pointer || record.focusable)
            .count();
        let action_count = records
            .iter()
            .filter(|record| record.action.is_some())
            .count();
        let visible_count = records.iter().filter(|record| record.visible).count();
        let effective_hit_count = records.iter().filter(|record| record.effective_hit).count();
        let missing_hit_count = records
            .iter()
            .filter(|record| (record.pointer || record.focusable) && record.hit_rect.is_none())
            .count();
        let clipped_count = records
            .iter()
            .filter(|record| (record.pointer || record.focusable) && record.clipped)
            .count();
        let paint_only_count = records
            .iter()
            .filter(|record| record.has_paint && record.hit_rect.is_none())
            .count();
        let issue_count = records
            .iter()
            .filter(|record| {
                matches!(
                    record.status,
                    DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
                )
            })
            .count();
        let status = debug_hitbox_map_trace_status(&records);
        let summary = debug_hitbox_map_trace_summary(
            status,
            node_count,
            interactive_count,
            action_count,
            effective_hit_count,
            missing_hit_count,
            clipped_count,
            paint_only_count,
            issue_count,
        );
        Self {
            status,
            node_count,
            interactive_count,
            action_count,
            visible_count,
            effective_hit_count,
            missing_hit_count,
            clipped_count,
            paint_only_count,
            issue_count,
            records,
            summary,
        }
    }

    pub fn record(&self, name: &str) -> Option<&DebugHitboxMapRecord> {
        self.records.iter().find(|record| record.name == name)
    }
}

impl DebugHitTargetTrace {
    pub fn from_document(document: &UiDocument, text_measurer: &mut impl TextMeasurer) -> Self {
        let snapshot = DebugInspectorSnapshot::from_document(document, text_measurer);
        Self::from_snapshot(&snapshot)
    }

    pub fn from_snapshot(snapshot: &DebugInspectorSnapshot) -> Self {
        Self::from_hitboxes(&snapshot.hitboxes)
    }

    pub fn from_hitboxes(hitboxes: &[DebugHitboxNode]) -> Self {
        let mut records = hitboxes
            .iter()
            .filter(|hitbox| hitbox.pointer || hitbox.focusable)
            .map(debug_hit_target_record)
            .collect::<Vec<_>>();
        records.sort_by(|left, right| {
            debug_hit_target_status_rank(left.status)
                .cmp(&debug_hit_target_status_rank(right.status))
                .then_with(|| left.min_dimension.total_cmp(&right.min_dimension))
                .then_with(|| left.name.cmp(&right.name))
        });

        let interactive_count = records.len();
        let issue_count = records
            .iter()
            .filter(|record| {
                matches!(
                    record.status,
                    DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
                )
            })
            .count();
        let missing_hit_count = records
            .iter()
            .filter(|record| record.hit_rect.is_none())
            .count();
        let small_target_count = records
            .iter()
            .filter(|record| {
                record.hit_rect.is_some() && record.min_dimension < DEBUG_HIT_TARGET_MIN_SIZE
            })
            .count();
        let clipped_count = records.iter().filter(|record| record.clipped).count();
        let status = debug_hit_target_trace_status(&records);
        let summary = debug_hit_target_trace_summary(
            status,
            interactive_count,
            issue_count,
            missing_hit_count,
            small_target_count,
            clipped_count,
        );

        Self {
            status,
            node_count: hitboxes.len(),
            interactive_count,
            issue_count,
            missing_hit_count,
            small_target_count,
            clipped_count,
            records,
            summary,
        }
    }

    pub fn record(&self, name: &str) -> Option<&DebugHitTargetRecord> {
        self.records.iter().find(|record| record.name == name)
    }
}

