#[derive(Debug, Clone, PartialEq)]
pub struct DebugResponsiveLayoutTrace {
    pub status: DebugFrameTraceStatus,
    pub viewport_count: usize,
    pub issue_viewport_count: usize,
    pub worst_viewport: Option<UiSize>,
    pub max_warning_count: usize,
    pub records: Vec<DebugResponsiveViewportRecord>,
    pub summary: String,
}

impl DebugResponsiveLayoutTrace {
    pub fn from_snapshots<'a>(
        snapshots: impl IntoIterator<Item = (UiSize, &'a DebugInspectorSnapshot)>,
    ) -> Self {
        let mut records = snapshots
            .into_iter()
            .map(|(viewport, snapshot)| debug_responsive_viewport_record(viewport, snapshot))
            .collect::<Vec<_>>();
        records.sort_by(|left, right| {
            debug_responsive_status_rank(left.status)
                .cmp(&debug_responsive_status_rank(right.status))
                .then_with(|| right.warning_count.cmp(&left.warning_count))
                .then_with(|| left.viewport.width.total_cmp(&right.viewport.width))
                .then_with(|| left.viewport.height.total_cmp(&right.viewport.height))
        });
        let viewport_count = records.len();
        let issue_viewport_count = records
            .iter()
            .filter(|record| record.status != DebugFrameTraceStatus::Ok)
            .count();
        let worst_viewport = records
            .iter()
            .find(|record| record.status != DebugFrameTraceStatus::Ok)
            .map(|record| record.viewport);
        let max_warning_count = records
            .iter()
            .map(|record| record.warning_count)
            .max()
            .unwrap_or(0);
        let status = debug_responsive_trace_status(&records);
        let summary =
            debug_responsive_trace_summary(status, viewport_count, issue_viewport_count, &records);

        Self {
            status,
            viewport_count,
            issue_viewport_count,
            worst_viewport,
            max_warning_count,
            records,
            summary,
        }
    }

    pub fn record_for_viewport(&self, viewport: UiSize) -> Option<&DebugResponsiveViewportRecord> {
        self.records.iter().find(|record| {
            float_close(record.viewport.width, viewport.width)
                && float_close(record.viewport.height, viewport.height)
        })
    }
}

