#[derive(Debug, Clone, PartialEq)]
pub struct DebugPointAutopsyTrace {
    pub event: DebugPointerRouteKind,
    pub point: UiPoint,
    pub status: DebugFrameTraceStatus,
    pub target: Option<UiNodeId>,
    pub target_name: Option<String>,
    pub overlap_count: usize,
    pub warning_count: usize,
    pub pointer: DebugPointerAutopsyTrace,
    pub resolution: Option<DebugPointResolutionTrace>,
    pub visibility: Option<DebugVisibilityRecord>,
    pub paint: Option<DebugPaintOrderTrace>,
    pub bounds: Option<DebugBoundsAutopsyTrace>,
    pub overlap: Option<DebugOverlapAutopsyTrace>,
    pub records: Vec<DebugPointAutopsyRecord>,
    pub summary: String,
}

impl DebugPointAutopsyTrace {
    pub fn pointer_down(
        document: &UiDocument,
        text_measurer: &mut impl TextMeasurer,
        point: UiPoint,
    ) -> Self {
        Self::from_pointer_event(document, text_measurer, DebugPointerRouteKind::Down, point)
    }

    pub fn pointer_move(
        document: &UiDocument,
        text_measurer: &mut impl TextMeasurer,
        point: UiPoint,
    ) -> Self {
        Self::from_pointer_event(document, text_measurer, DebugPointerRouteKind::Move, point)
    }

    pub fn pointer_up(
        document: &UiDocument,
        text_measurer: &mut impl TextMeasurer,
        point: UiPoint,
    ) -> Self {
        Self::from_pointer_event(document, text_measurer, DebugPointerRouteKind::Up, point)
    }

    pub fn from_pointer_event(
        document: &UiDocument,
        text_measurer: &mut impl TextMeasurer,
        event: DebugPointerRouteKind,
        point: UiPoint,
    ) -> Self {
        let probe = DebugPointerProbe::from_pointer_event(document, event, point);
        let pointer = DebugPointerAutopsyTrace::from_probe(&probe);
        let snapshot = DebugInspectorSnapshot::from_document(document, text_measurer);
        let visibility = debug_point_autopsy_visibility(&snapshot, &probe);
        let paint = DebugPaintOrderTrace::from_document(document, point);
        let resolution = DebugPointResolutionTrace::from_probe_and_paint(&probe, Some(&paint));
        let bounds = debug_point_autopsy_bounds(&snapshot, &probe);
        let overlap_count = debug_point_autopsy_overlap_count(&snapshot, point);
        let overlap = debug_point_autopsy_overlap(&snapshot, &probe)
            .map(DebugOverlapAutopsyTrace::from_overlap);
        Self::from_traces_with_visibility_and_paint(
            pointer,
            Some(resolution),
            visibility,
            Some(paint),
            bounds,
            overlap,
            overlap_count,
        )
    }

    pub fn from_traces(
        pointer: DebugPointerAutopsyTrace,
        bounds: Option<DebugBoundsAutopsyTrace>,
        overlap: Option<DebugOverlapAutopsyTrace>,
        overlap_count: usize,
    ) -> Self {
        Self::from_traces_with_visibility_and_paint(
            pointer,
            None,
            None,
            None,
            bounds,
            overlap,
            overlap_count,
        )
    }

    pub fn from_traces_with_paint(
        pointer: DebugPointerAutopsyTrace,
        paint: DebugPaintOrderTrace,
        bounds: Option<DebugBoundsAutopsyTrace>,
        overlap: Option<DebugOverlapAutopsyTrace>,
        overlap_count: usize,
    ) -> Self {
        Self::from_traces_with_visibility_and_paint(
            pointer,
            None,
            None,
            Some(paint),
            bounds,
            overlap,
            overlap_count,
        )
    }

    fn from_traces_with_visibility_and_paint(
        pointer: DebugPointerAutopsyTrace,
        resolution: Option<DebugPointResolutionTrace>,
        visibility: Option<DebugVisibilityRecord>,
        paint: Option<DebugPaintOrderTrace>,
        bounds: Option<DebugBoundsAutopsyTrace>,
        overlap: Option<DebugOverlapAutopsyTrace>,
        overlap_count: usize,
    ) -> Self {
        let mut records = vec![
            debug_point_autopsy_resolution_record(resolution.as_ref(), &pointer),
            debug_point_autopsy_pointer_record(&pointer),
            debug_point_autopsy_visibility_record(&pointer, visibility.as_ref()),
            debug_point_autopsy_paint_record(paint.as_ref()),
            debug_point_autopsy_bounds_record(bounds.as_ref()),
            debug_point_autopsy_overlap_record(overlap.as_ref(), overlap_count),
            debug_point_autopsy_action_record(&pointer),
        ];
        records.push(debug_point_autopsy_next_step_record(&records));
        finish_debug_point_autopsy_trace(
            pointer,
            resolution,
            visibility,
            paint,
            bounds,
            overlap,
            overlap_count,
            records,
        )
    }

    pub fn record(&self, source: DebugPointAutopsySource) -> Option<&DebugPointAutopsyRecord> {
        self.records.iter().find(|record| record.source == source)
    }
}

