#[derive(Debug, Clone, PartialEq)]
pub struct DebugInspectNodeTrace {
    pub selected: UiNodeId,
    pub selected_name: String,
    pub status: DebugFrameTraceStatus,
    pub warning_count: usize,
    pub explanation: DebugNodeExplanation,
    pub visibility: Option<DebugVisibilityRecord>,
    pub bounds: Option<DebugBoundsAutopsyTrace>,
    pub layout: Option<DebugLayoutCauseTrace>,
    pub clip: Option<DebugClipChainRecord>,
    pub hitbox: Option<DebugHitboxMapRecord>,
    pub paint_hit_mismatches: Vec<DebugPaintHitMismatchRecord>,
    pub overlaps: Vec<DebugOverlapRecord>,
    pub text_fit: Option<DebugTextFitRecord>,
    pub provenance: Option<DebugNodeProvenanceTrace>,
    pub slow_node: Option<DebugSlowNodeRecord>,
    pub records: Vec<DebugInspectNodeRecord>,
    pub summary: String,
}

impl DebugInspectNodeTrace {
    pub fn from_document(
        document: &UiDocument,
        text_measurer: &mut impl TextMeasurer,
        selected_name: Option<&str>,
    ) -> Option<Self> {
        let snapshot = DebugInspectorSnapshot::from_document(document, text_measurer);
        let slow_nodes = DebugSlowNodeTrace::from_document(document, text_measurer);
        let text_fit = DebugTextFitTrace::from_document(document, text_measurer);
        Self::from_context_with_traces(
            &snapshot,
            selected_name,
            None,
            None,
            Some(&slow_nodes),
            Some(&text_fit),
        )
    }

    pub fn from_snapshot(
        snapshot: &DebugInspectorSnapshot,
        selected_name: Option<&str>,
    ) -> Option<Self> {
        Self::from_context(snapshot, selected_name, None, None, None)
    }

    pub fn from_context(
        snapshot: &DebugInspectorSnapshot,
        selected_name: Option<&str>,
        route: Option<&DebugEventRouteTrace>,
        resources: Option<&DebugResourceReport>,
        slow_nodes: Option<&DebugSlowNodeTrace>,
    ) -> Option<Self> {
        Self::from_context_with_traces(snapshot, selected_name, route, resources, slow_nodes, None)
    }

    pub fn from_context_with_traces(
        snapshot: &DebugInspectorSnapshot,
        selected_name: Option<&str>,
        route: Option<&DebugEventRouteTrace>,
        resources: Option<&DebugResourceReport>,
        slow_nodes: Option<&DebugSlowNodeTrace>,
        text_fit: Option<&DebugTextFitTrace>,
    ) -> Option<Self> {
        let explanation =
            DebugNodeExplanation::from_context(snapshot, selected_name, route, resources)?;
        let selected_name = explanation.name.clone();
        let visibility = DebugVisibilityTrace::from_snapshot(snapshot)
            .record(&selected_name)
            .cloned();
        let bounds = DebugBoundsAutopsyTrace::from_snapshot(snapshot, Some(&selected_name));
        let layout = DebugLayoutCauseTrace::from_snapshot(snapshot, Some(&selected_name));
        let clip = DebugClipChainTrace::from_snapshot(snapshot)
            .record(&selected_name)
            .cloned();
        let hitbox = DebugHitboxMapTrace::from_snapshot(snapshot)
            .record(&selected_name)
            .cloned();
        let paint_hit_mismatches = DebugPaintHitMismatchTrace::from_snapshot(snapshot)
            .records_for(&selected_name)
            .cloned()
            .collect::<Vec<_>>();
        let overlaps = snapshot
            .overlaps_for(explanation.node)
            .cloned()
            .collect::<Vec<_>>();
        let text_fit = text_fit
            .and_then(|trace| trace.record(&selected_name))
            .cloned();
        let provenance =
            DebugNodeProvenanceTrace::from_context(snapshot, Some(&selected_name), resources);
        let slow_node = slow_nodes
            .and_then(|trace| trace.record(&selected_name))
            .cloned();
        Some(Self::from_parts(
            explanation,
            visibility,
            bounds,
            layout,
            clip,
            hitbox,
            paint_hit_mismatches,
            overlaps,
            text_fit,
            provenance,
            slow_node,
        ))
    }

    pub fn from_parts(
        explanation: DebugNodeExplanation,
        visibility: Option<DebugVisibilityRecord>,
        bounds: Option<DebugBoundsAutopsyTrace>,
        layout: Option<DebugLayoutCauseTrace>,
        clip: Option<DebugClipChainRecord>,
        hitbox: Option<DebugHitboxMapRecord>,
        paint_hit_mismatches: Vec<DebugPaintHitMismatchRecord>,
        overlaps: Vec<DebugOverlapRecord>,
        text_fit: Option<DebugTextFitRecord>,
        provenance: Option<DebugNodeProvenanceTrace>,
        slow_node: Option<DebugSlowNodeRecord>,
    ) -> Self {
        let mut records = vec![
            debug_inspect_node_explanation_record(&explanation),
            debug_inspect_node_visibility_record(&explanation, visibility.as_ref()),
            debug_inspect_node_bounds_record(bounds.as_ref()),
            debug_inspect_node_layout_record(layout.as_ref()),
            debug_inspect_node_clip_record(&explanation, clip.as_ref()),
            debug_inspect_node_hitbox_record(&explanation, hitbox.as_ref()),
            debug_inspect_node_paint_hit_record(&explanation, &paint_hit_mismatches),
            debug_inspect_node_overlap_record(&explanation, &overlaps),
            debug_inspect_node_text_fit_record(&explanation, text_fit.as_ref()),
            debug_inspect_node_provenance_record(provenance.as_ref()),
            debug_inspect_node_performance_record(&explanation, slow_node.as_ref()),
        ];
        records.push(debug_inspect_node_next_step_record(&records));
        finish_debug_inspect_node_trace(
            explanation,
            visibility,
            bounds,
            layout,
            clip,
            hitbox,
            paint_hit_mismatches,
            overlaps,
            text_fit,
            provenance,
            slow_node,
            records,
        )
    }

    pub fn record(&self, source: DebugInspectNodeSource) -> Option<&DebugInspectNodeRecord> {
        self.records.iter().find(|record| record.source == source)
    }
}

pub fn layout_snapshot_dump(snapshot: &LayoutSnapshot) -> String {
    let mut lines = Vec::new();
    push_layout_dump_line(snapshot, 0, &mut lines);
    lines.join("\n")
}

fn collect_debug_nodes(
    snapshot: &LayoutSnapshot,
    paint_stats: &HashMap<UiNodeId, DebugPaintStats>,
    host: &HostInteractionState,
    include_invisible: bool,
    out: &mut Vec<DebugOverlayNode>,
) {
    if include_invisible || snapshot.visible {
        out.push(DebugOverlayNode {
            id: snapshot.id,
            name: snapshot.name.clone(),
            rect: snapshot.rect,
            clip_rect: snapshot.clip_rect,
            visible: snapshot.visible,
            pointer: snapshot.pointer,
            focusable: snapshot.focusable,
            interaction: host.node_state(snapshot.id),
            paint: paint_stats.get(&snapshot.id).copied().unwrap_or_default(),
        });
    }

    for child in &snapshot.children {
        collect_debug_nodes(child, paint_stats, host, include_invisible, out);
    }
}

fn debug_interaction_role_target(
    snapshot: &DebugOverlaySnapshot,
    role: impl Fn(HostNodeInteraction) -> bool,
) -> (Option<UiNodeId>, Option<String>) {
    snapshot
        .nodes
        .iter()
        .find(|node| role(node.interaction))
        .map(|node| (Some(node.id), Some(node.name.clone())))
        .unwrap_or((None, None))
}

fn debug_interaction_node_label(snapshot: &DebugOverlaySnapshot, node: UiNodeId) -> String {
    snapshot
        .nodes
        .iter()
        .find(|candidate| candidate.id == node)
        .map(|candidate| candidate.name.clone())
        .unwrap_or_else(|| format!("#{}", node.0))
}

fn debug_interaction_gesture_summary(
    snapshot: &DebugOverlaySnapshot,
    gesture: &DebugGestureState,
) -> String {
    let kind = match &gesture.kind {
        DebugGestureKind::Hover => "hover".to_owned(),
        DebugGestureKind::Press => "press".to_owned(),
        DebugGestureKind::Drag(phase) => format!("drag {phase:?}"),
        DebugGestureKind::Click { count } => format!("click x{count}"),
        DebugGestureKind::Wheel => "wheel".to_owned(),
        DebugGestureKind::Cancel => "cancel".to_owned(),
    };
    let target = gesture
        .target
        .map(|node| debug_interaction_node_label(snapshot, node))
        .unwrap_or_else(|| "none".to_owned());
    format!(
        "{kind} on {target} at {}",
        format_debug_point(gesture.position)
    )
}

fn debug_interaction_state_record(node: &DebugOverlayNode) -> DebugInteractionStateRecord {
    let roles = debug_interaction_roles(node.interaction);
    let status = debug_interaction_record_status(node);
    let summary = debug_interaction_record_summary(node, status, &roles);
    let cause = debug_interaction_record_cause(node, &roles);
    let fix = debug_interaction_record_fix(node, &roles);
    DebugInteractionStateRecord {
        node: node.id,
        name: node.name.clone(),
        status,
        roles,
        hovered: node.interaction.hovered,
        pressed: node.interaction.pressed,
        focused: node.interaction.focused,
        drag_captured: node.interaction.drag_captured,
        text_editing: node.interaction.text_editing,
        wheel_targeted: node.interaction.wheel_targeted,
        shortcut_targeted: node.interaction.shortcut_targeted,
        input_consumed: node.interaction.input_consumed,
        visible: node.visible,
        pointer: node.pointer,
        focusable: node.focusable,
        paint_count: node.paint.count,
        summary,
        cause,
        fix,
    }
}

fn debug_interaction_roles(interaction: HostNodeInteraction) -> Vec<String> {
    let mut roles = Vec::new();
    if interaction.hovered {
        roles.push("hovered".to_owned());
    }
    if interaction.pressed {
        roles.push("pressed".to_owned());
    }
    if interaction.focused {
        roles.push("focused".to_owned());
    }
    if interaction.drag_captured {
        roles.push("drag captured".to_owned());
    }
    if interaction.text_editing {
        roles.push("text editing".to_owned());
    }
    if interaction.wheel_targeted {
        roles.push("wheel target".to_owned());
    }
    if interaction.shortcut_targeted {
        roles.push("shortcut target".to_owned());
    }
    if interaction.input_consumed {
        roles.push("input consumed".to_owned());
    }
    roles
}

fn debug_interaction_record_status(node: &DebugOverlayNode) -> DebugFrameTraceStatus {
    if !node.visible {
        return DebugFrameTraceStatus::Warning;
    }
    if (node.interaction.pressed || node.interaction.hovered || node.interaction.drag_captured)
        && !node.pointer
    {
        return DebugFrameTraceStatus::Warning;
    }
    if (node.interaction.focused || node.interaction.shortcut_targeted) && !node.focusable {
        return DebugFrameTraceStatus::Warning;
    }
    DebugFrameTraceStatus::Info
}

fn debug_interaction_record_summary(
    node: &DebugOverlayNode,
    status: DebugFrameTraceStatus,
    roles: &[String],
) -> String {
    let role_label = if roles.is_empty() {
        "inactive".to_owned()
    } else {
        roles.join(", ")
    };
    format!(
        "{} interaction {}: {}",
        node.name,
        status.label(),
        role_label
    )
}

fn debug_interaction_record_cause(node: &DebugOverlayNode, roles: &[String]) -> String {
    if !node.visible {
        return "host interaction targets a hidden node".to_owned();
    }
    if (node.interaction.pressed || node.interaction.hovered || node.interaction.drag_captured)
        && !node.pointer
    {
        return "pointer interaction targets a node that is not pointer-interactive".to_owned();
    }
    if (node.interaction.focused || node.interaction.shortcut_targeted) && !node.focusable {
        return "keyboard interaction targets a node that is not focusable".to_owned();
    }
    if roles.is_empty() {
        "node has no active host interaction roles".to_owned()
    } else {
        format!("active host roles: {}", roles.join(", "))
    }
}

fn debug_interaction_record_fix(node: &DebugOverlayNode, roles: &[String]) -> String {
    if !node.visible {
        "clear stale host state or keep hidden targets from receiving interaction".to_owned()
    } else if (node.interaction.pressed
        || node.interaction.hovered
        || node.interaction.drag_captured)
        && !node.pointer
    {
        "verify hit testing and InputBehavior for the target node".to_owned()
    } else if (node.interaction.focused || node.interaction.shortcut_targeted) && !node.focusable {
        "make the node focusable or clear focus/shortcut routing to it".to_owned()
    } else if roles.iter().any(|role| role == "drag captured") {
        "check drag lifecycle; commit/cancel should release capture when the gesture ends"
            .to_owned()
    } else if roles.iter().any(|role| role == "input consumed") {
        "inspect event-route diagnostics to see which input event was consumed".to_owned()
    } else {
        "interaction state is consistent; inspect event route if the role is unexpected".to_owned()
    }
}

fn debug_interaction_trace_status(
    records: &[DebugInteractionStateRecord],
) -> DebugFrameTraceStatus {
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Error)
    {
        return DebugFrameTraceStatus::Error;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Info)
    {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

fn debug_interaction_trace_summary(
    status: DebugFrameTraceStatus,
    active_count: usize,
    warning_count: usize,
    active_gesture: Option<&DebugGestureState>,
    active_shortcut_scope_count: usize,
    shortcut_label: Option<&str>,
    routed_command: Option<&CommandId>,
) -> String {
    let mut parts = vec![format!("{} interaction state", status.label())];
    parts.push(format!("{active_count} active nodes"));
    if warning_count > 0 {
        parts.push(format!("{warning_count} warnings"));
    }
    if let Some(gesture) = active_gesture {
        parts.push(format!("gesture {:?}", gesture.kind));
    }
    if active_shortcut_scope_count > 0 {
        parts.push(format!("{active_shortcut_scope_count} shortcut scopes"));
    }
    if let Some(shortcut) = shortcut_label {
        parts.push(format!("shortcut {shortcut}"));
    }
    if let Some(command) = routed_command {
        parts.push(format!("command {}", command.as_str()));
    }
    parts.join("; ")
}

fn debug_interaction_status_rank(status: DebugFrameTraceStatus) -> u8 {
    match status {
        DebugFrameTraceStatus::Error => 0,
        DebugFrameTraceStatus::Warning => 1,
        DebugFrameTraceStatus::Info => 2,
        DebugFrameTraceStatus::Ok => 3,
    }
}

fn debug_widget_state_retention_trace(
    store: &RetainedWidgetStateStore,
) -> DebugWidgetStateRetentionTrace {
    let lifecycle = store
        .last_lifecycle_report()
        .items()
        .into_iter()
        .map(|item| (item.key, item.outcome))
        .collect::<HashMap<_, _>>();
    let mut records = store
        .entries()
        .map(|entry| {
            debug_widget_state_retention_entry_record(
                store.generation(),
                store.retention(),
                entry,
                lifecycle.get(&entry.key).copied(),
            )
        })
        .collect::<Vec<_>>();

    for key in store.last_lifecycle_report().expired.iter() {
        if store.get(key).is_none() {
            records.push(debug_widget_state_retention_expired_record(
                store.generation(),
                key,
            ));
        }
    }

    records.sort_by(|left, right| {
        debug_widget_state_retention_status_rank(left.status)
            .cmp(&debug_widget_state_retention_status_rank(right.status))
            .then_with(|| {
                debug_widget_state_retention_lifecycle_rank(left.lifecycle.as_deref()).cmp(
                    &debug_widget_state_retention_lifecycle_rank(right.lifecycle.as_deref()),
                )
            })
            .then_with(|| right.stale_generations.cmp(&left.stale_generations))
            .then_with(|| left.key.cmp(&right.key))
    });

    let entry_count = store.len();
    let stale_count = records
        .iter()
        .filter(|record| record.stale_since_generation.is_some())
        .count();
    let keepalive_count = records.iter().filter(|record| record.keepalive).count();
    let report = store.last_lifecycle_report();
    let active_count = entry_count.saturating_sub(stale_count);
    let created_count = report.created.len();
    let reused_count = report.reused.len();
    let orphaned_count = report.orphaned.len();
    let expired_count = report.expired.len();
    let status = debug_widget_state_retention_trace_status(
        entry_count,
        stale_count,
        orphaned_count,
        expired_count,
        created_count,
    );
    let summary = debug_widget_state_retention_trace_summary(
        status,
        store.generation(),
        entry_count,
        active_count,
        stale_count,
        keepalive_count,
        created_count,
        reused_count,
        orphaned_count,
        expired_count,
    );

    DebugWidgetStateRetentionTrace {
        status,
        generation: store.generation(),
        retention: store.retention(),
        entry_count,
        active_count,
        stale_count,
        keepalive_count,
        created_count,
        reused_count,
        orphaned_count,
        expired_count,
        records,
        summary,
    }
}

fn debug_widget_state_retention_entry_record(
    generation: u64,
    retention: WidgetStateRetention,
    entry: &RetainedWidgetStateEntry,
    lifecycle: Option<WidgetStateLifecycleOutcome>,
) -> DebugWidgetStateRetentionRecord {
    let status = debug_widget_state_retention_record_status(entry, lifecycle);
    let lifecycle_label = lifecycle.map(debug_widget_state_lifecycle_label);
    let key = debug_widget_state_key_label(&entry.key);
    let scope = debug_widget_state_scope_label(&entry.key.widget.scope);
    let widget = entry.key.widget.id.as_str().to_owned();
    let slot = entry.key.slot.as_str().to_owned();
    let kind = debug_widget_state_slot_kind_label(&entry.descriptor.kind);
    let age_generations = generation.saturating_sub(entry.created_generation);
    let stale_generations = entry
        .stale_since_generation
        .map(|stale_since| generation.saturating_sub(stale_since).saturating_add(1));
    let value = debug_widget_state_value_label(&entry.value);
    let dirty_flags = debug_widget_state_dirty_flags_label(entry.descriptor.dirty_flags);
    let invalidation = format!("{:?}", entry.descriptor.invalidation_reason);
    let summary = debug_widget_state_retention_record_summary(
        &widget,
        &slot,
        status,
        lifecycle_label,
        stale_generations,
        entry.keepalive,
        entry.revision,
    );
    let cause = debug_widget_state_retention_record_cause(
        lifecycle,
        stale_generations,
        entry.keepalive,
        entry.revision,
    );
    let fix = debug_widget_state_retention_record_fix(
        lifecycle,
        stale_generations,
        entry.keepalive,
        retention,
    );

    DebugWidgetStateRetentionRecord {
        key,
        scope,
        widget,
        slot,
        kind,
        status,
        lifecycle: lifecycle_label.map(ToOwned::to_owned),
        created_generation: Some(entry.created_generation),
        updated_generation: Some(entry.updated_generation),
        last_seen_generation: Some(entry.last_seen_generation),
        stale_since_generation: entry.stale_since_generation,
        age_generations: Some(age_generations),
        stale_generations,
        keepalive: entry.keepalive,
        revision: Some(entry.revision),
        value: Some(value),
        dirty_flags: Some(dirty_flags),
        invalidation: Some(invalidation),
        summary,
        cause,
        fix,
    }
}

fn debug_widget_state_retention_expired_record(
    generation: u64,
    key: &WidgetStateKey,
) -> DebugWidgetStateRetentionRecord {
    let scope = debug_widget_state_scope_label(&key.widget.scope);
    let widget = key.widget.id.as_str().to_owned();
    let slot = key.slot.as_str().to_owned();
    let key_label = debug_widget_state_key_label(key);
    DebugWidgetStateRetentionRecord {
        key: key_label,
        scope,
        widget: widget.clone(),
        slot: slot.clone(),
        kind: "unknown".to_owned(),
        status: DebugFrameTraceStatus::Warning,
        lifecycle: Some("expired".to_owned()),
        created_generation: None,
        updated_generation: None,
        last_seen_generation: None,
        stale_since_generation: None,
        age_generations: None,
        stale_generations: None,
        keepalive: false,
        revision: None,
        value: None,
        dirty_flags: None,
        invalidation: None,
        summary: format!("{widget}.{slot} state warning; expired at generation {generation}"),
        cause: "retained widget state was evicted because the widget was not seen within the retention window"
            .to_owned(),
        fix: "verify the widget id and scope are stable across rebuilds, or increase retention/keepalive when unmounting is intentional"
            .to_owned(),
    }
}

fn debug_widget_state_retention_record_status(
    entry: &RetainedWidgetStateEntry,
    lifecycle: Option<WidgetStateLifecycleOutcome>,
) -> DebugFrameTraceStatus {
    if matches!(
        lifecycle,
        Some(WidgetStateLifecycleOutcome::Expired | WidgetStateLifecycleOutcome::Orphaned)
    ) || entry.is_stale()
    {
        DebugFrameTraceStatus::Warning
    } else if lifecycle.is_some() || entry.revision > 0 || entry.keepalive {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    }
}

fn debug_widget_state_retention_record_summary(
    widget: &str,
    slot: &str,
    status: DebugFrameTraceStatus,
    lifecycle: Option<&str>,
    stale_generations: Option<u64>,
    keepalive: bool,
    revision: u64,
) -> String {
    let mut parts = vec![format!("{widget}.{slot} state {}", status.label())];
    if let Some(lifecycle) = lifecycle {
        parts.push(lifecycle.to_owned());
    }
    if let Some(stale) = stale_generations {
        parts.push(format!("stale {stale} generations"));
    }
    if keepalive {
        parts.push("keepalive".to_owned());
    }
    if revision > 0 {
        parts.push(format!("revision {revision}"));
    }
    parts.join("; ")
}

fn debug_widget_state_retention_record_cause(
    lifecycle: Option<WidgetStateLifecycleOutcome>,
    stale_generations: Option<u64>,
    keepalive: bool,
    revision: u64,
) -> String {
    match lifecycle {
        Some(WidgetStateLifecycleOutcome::Created) => {
            "state slot was created this frame because no retained entry matched the widget key"
                .to_owned()
        }
        Some(WidgetStateLifecycleOutcome::Reused) => {
            "state slot matched a widget seen this frame and was reused".to_owned()
        }
        Some(WidgetStateLifecycleOutcome::Orphaned) => {
            "state slot is retained but its widget key was not seen this frame".to_owned()
        }
        Some(WidgetStateLifecycleOutcome::Expired) => {
            "state slot exceeded retention while its widget key was missing".to_owned()
        }
        None if stale_generations.is_some() && keepalive => {
            "state slot is stale but keepalive prevents eviction".to_owned()
        }
        None if stale_generations.is_some() => {
            "state slot remains stale from an earlier frame".to_owned()
        }
        None if revision > 0 => {
            "state slot has been updated since creation and is currently retained".to_owned()
        }
        None => "state slot is retained and has no lifecycle churn in the latest frame".to_owned(),
    }
}

fn debug_widget_state_retention_record_fix(
    lifecycle: Option<WidgetStateLifecycleOutcome>,
    stale_generations: Option<u64>,
    keepalive: bool,
    retention: WidgetStateRetention,
) -> String {
    match lifecycle {
        Some(WidgetStateLifecycleOutcome::Created) => {
            "if this was unexpected, check for changed widget ids, changed scopes, or conditional slot creation"
                .to_owned()
        }
        Some(WidgetStateLifecycleOutcome::Reused) => {
            "no retention action needed; inspect value/revision if the state content is unexpected"
                .to_owned()
        }
        Some(WidgetStateLifecycleOutcome::Orphaned) => {
            "inspect the widget tree for missing ids or a branch that stopped mounting this widget"
                .to_owned()
        }
        Some(WidgetStateLifecycleOutcome::Expired) => {
            "restore a stable widget key, mark intentional state keepalive, or increase retention"
                .to_owned()
        }
        None if stale_generations.is_some() && keepalive => {
            "clear keepalive when this state should be evicted after unmounting".to_owned()
        }
        None if stale_generations.is_some() => format!(
            "state will expire after more than {} stale generations unless the widget key reappears",
            retention.max_stale_generations
        ),
        None => "no retained-state action needed".to_owned(),
    }
}

fn debug_widget_state_retention_trace_status(
    entry_count: usize,
    stale_count: usize,
    orphaned_count: usize,
    expired_count: usize,
    created_count: usize,
) -> DebugFrameTraceStatus {
    if expired_count > 0 || orphaned_count > 0 || stale_count > 0 {
        DebugFrameTraceStatus::Warning
    } else if created_count > 0 || entry_count > 0 {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    }
}

#[allow(clippy::too_many_arguments)]
fn debug_widget_state_retention_trace_summary(
    status: DebugFrameTraceStatus,
    generation: u64,
    entry_count: usize,
    active_count: usize,
    stale_count: usize,
    keepalive_count: usize,
    created_count: usize,
    reused_count: usize,
    orphaned_count: usize,
    expired_count: usize,
) -> String {
    let mut parts = vec![format!(
        "widget state retention {} at generation {generation}",
        status.label()
    )];
    parts.push(format!("{entry_count} entries"));
    if active_count > 0 {
        parts.push(format!("{active_count} active"));
    }
    if stale_count > 0 {
        parts.push(format!("{stale_count} stale"));
    }
    if keepalive_count > 0 {
        parts.push(format!("{keepalive_count} keepalive"));
    }
    if created_count > 0 {
        parts.push(format!("{created_count} created"));
    }
    if reused_count > 0 {
        parts.push(format!("{reused_count} reused"));
    }
    if orphaned_count > 0 {
        parts.push(format!("{orphaned_count} orphaned"));
    }
    if expired_count > 0 {
        parts.push(format!("{expired_count} expired"));
    }
    parts.join("; ")
}

fn debug_widget_state_lifecycle_label(outcome: WidgetStateLifecycleOutcome) -> &'static str {
    match outcome {
        WidgetStateLifecycleOutcome::Created => "created",
        WidgetStateLifecycleOutcome::Reused => "reused",
        WidgetStateLifecycleOutcome::Expired => "expired",
        WidgetStateLifecycleOutcome::Orphaned => "orphaned",
    }
}

fn debug_widget_state_scope_label(scope: &WidgetStateScope) -> String {
    match scope {
        WidgetStateScope::Document(document) => format!("document:{document}"),
        WidgetStateScope::Window(window) => format!("window:{}", window.as_str()),
        WidgetStateScope::Custom(scope) => format!("custom:{scope}"),
    }
}

fn debug_widget_state_key_label(key: &WidgetStateKey) -> String {
    format!(
        "{}::{}.{}",
        debug_widget_state_scope_label(&key.widget.scope),
        key.widget.id.as_str(),
        key.slot.as_str()
    )
}

fn debug_widget_state_slot_kind_label(kind: &WidgetStateSlotKind) -> String {
    match kind {
        WidgetStateSlotKind::Focus => "Focus".to_owned(),
        WidgetStateSlotKind::Hover => "Hover".to_owned(),
        WidgetStateSlotKind::Pressed => "Pressed".to_owned(),
        WidgetStateSlotKind::Overlay => "Overlay".to_owned(),
        WidgetStateSlotKind::Scroll => "Scroll".to_owned(),
        WidgetStateSlotKind::Animation => "Animation".to_owned(),
        WidgetStateSlotKind::Edit => "Edit".to_owned(),
        WidgetStateSlotKind::Custom(kind) => format!("Custom({kind})"),
    }
}

fn debug_widget_state_value_label(value: &WidgetStateValue) -> String {
    match value {
        WidgetStateValue::Focus(state) => format!("focused={}", state.focused),
        WidgetStateValue::Hover(state) => format!("hovered={}", state.hovered),
        WidgetStateValue::Pressed(state) => format!("pressed={}", state.pressed),
        WidgetStateValue::Overlay(state) => format!("open={}", state.open),
        WidgetStateValue::Scroll(state) => format!(
            "offset {}; viewport {}; content {}",
            format_debug_point(state.offset()),
            debug_size_label(state.viewport_size()),
            debug_size_label(state.content_size())
        ),
        WidgetStateValue::Animation(state) => {
            format!(
                "animation {}; opacity {:.2}; scale {:.2}; translate {}",
                state.name,
                state.values.opacity,
                state.values.scale,
                format_debug_point(state.values.translate)
            )
        }
        WidgetStateValue::Edit(state) => format!(
            "text {} chars; cursor {}; selection {}; composing={}",
            state.text.chars().count(),
            state.cursor_byte_index,
            state
                .selection_anchor_byte_index
                .map(|selection| selection.to_string())
                .unwrap_or_else(|| "none".to_owned()),
            state.composing
        ),
        WidgetStateValue::Custom { kind, revision } => {
            format!("custom {kind}; revision {revision}")
        }
    }
}

fn debug_widget_state_dirty_flags_label(flags: DirtyFlags) -> String {
    let mut parts = Vec::new();
    if flags.layout {
        parts.push("layout");
    }
    if flags.paint {
        parts.push("paint");
    }
    if flags.input {
        parts.push("input");
    }
    if flags.theme {
        parts.push("theme");
    }
    if flags.text_measurement {
        parts.push("text_measurement");
    }
    if parts.is_empty() {
        "none".to_owned()
    } else {
        parts.join(", ")
    }
}

fn debug_widget_state_retention_status_rank(status: DebugFrameTraceStatus) -> u8 {
    match status {
        DebugFrameTraceStatus::Error => 0,
        DebugFrameTraceStatus::Warning => 1,
        DebugFrameTraceStatus::Info => 2,
        DebugFrameTraceStatus::Ok => 3,
    }
}

fn debug_widget_state_retention_lifecycle_rank(lifecycle: Option<&str>) -> u8 {
    match lifecycle {
        Some("expired") => 0,
        Some("orphaned") => 1,
        Some("created") => 2,
        Some("reused") => 3,
        _ => 4,
    }
}

#[derive(Debug)]
struct DebugInteractionStateTimelineAccumulator {
    name: String,
    status: DebugFrameTraceStatus,
    frame_count: usize,
    warning_frame_count: usize,
    first_frame_label: Option<String>,
    latest_frame_label: Option<String>,
    hovered_frame_count: usize,
    pressed_frame_count: usize,
    focused_frame_count: usize,
    drag_captured_frame_count: usize,
    text_editing_frame_count: usize,
    wheel_targeted_frame_count: usize,
    shortcut_targeted_frame_count: usize,
    input_consumed_frame_count: usize,
    latest_roles: Vec<String>,
    latest_visible: bool,
    latest_pointer: bool,
    latest_focusable: bool,
    latest_summary: String,
    latest_cause: String,
    latest_fix: String,
}

fn debug_interaction_state_timeline_trace<'a>(
    traces: impl IntoIterator<Item = &'a DebugFrameTrace>,
) -> DebugInteractionStateTimelineTrace {
    let traces = traces.into_iter().collect::<Vec<_>>();
    let mut records = Vec::<DebugInteractionStateTimelineAccumulator>::new();
    let mut frames = Vec::new();
    let mut previous_active = HashSet::<String>::new();
    let mut has_previous_capture = false;
    let mut latest_hovered_name = None;
    let mut latest_pressed_name = None;
    let mut latest_focused_name = None;

    for (index, trace) in traces.iter().enumerate() {
        let label = debug_frame_timeline_label(trace, index);
        if let Some(interaction) = trace.interaction_state.as_ref() {
            let current_active = debug_interaction_state_timeline_keys(&interaction.records);
            let new_active_count = if has_previous_capture {
                current_active.difference(&previous_active).count()
            } else {
                0
            };
            let resolved_active_count = if has_previous_capture {
                previous_active.difference(&current_active).count()
            } else {
                0
            };
            let persistent_active_count = if has_previous_capture {
                current_active.intersection(&previous_active).count()
            } else {
                0
            };
            for record in &interaction.records {
                debug_interaction_state_timeline_merge_record(&mut records, &label, record);
            }
            latest_hovered_name = interaction.hovered_name.clone();
            latest_pressed_name = interaction.pressed_name.clone();
            latest_focused_name = interaction.focused_name.clone();
            frames.push(debug_interaction_state_timeline_frame_record(
                index,
                label,
                trace.frame_index,
                Some(interaction),
                new_active_count,
                resolved_active_count,
                persistent_active_count,
            ));
            previous_active = current_active;
            has_previous_capture = true;
        } else {
            frames.push(debug_interaction_state_timeline_frame_record(
                index,
                label,
                trace.frame_index,
                None,
                0,
                0,
                0,
            ));
        }
    }

    let frame_count = frames.len();
    let captured_frame_count = frames.iter().filter(|frame| frame.captured).count();
    let missing_frame_count = frame_count.saturating_sub(captured_frame_count);
    let active_frame_count = frames
        .iter()
        .filter(|frame| frame.active_node_count > 0)
        .count();
    let warning_frame_count = frames
        .iter()
        .filter(|frame| {
            matches!(
                frame.status,
                DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
            )
        })
        .count();
    let changed_frame_count = frames
        .iter()
        .filter(|frame| frame.new_active_count > 0 || frame.resolved_active_count > 0)
        .count();
    let node_count = frames.iter().map(|frame| frame.node_count).sum();
    let active_node_count = frames.iter().map(|frame| frame.active_node_count).sum();
    let warning_count = frames.iter().map(|frame| frame.warning_count).sum();
    let gesture_frame_count = frames
        .iter()
        .filter(|frame| frame.gesture_summary.is_some())
        .count();
    let new_active_count = frames.iter().map(|frame| frame.new_active_count).sum();
    let resolved_active_count = frames.iter().map(|frame| frame.resolved_active_count).sum();
    let persistent_active_count = frames
        .iter()
        .map(|frame| frame.persistent_active_count)
        .sum();

    let drag_capture_frame_count = records
        .iter()
        .map(|record| record.drag_captured_frame_count)
        .sum();
    let text_editing_frame_count = records
        .iter()
        .map(|record| record.text_editing_frame_count)
        .sum();
    let wheel_target_frame_count = records
        .iter()
        .map(|record| record.wheel_targeted_frame_count)
        .sum();
    let shortcut_frame_count = records
        .iter()
        .map(|record| record.shortcut_targeted_frame_count)
        .sum();
    let input_consumed_frame_count = records
        .iter()
        .map(|record| record.input_consumed_frame_count)
        .sum();

    let mut records = records
        .into_iter()
        .map(|record| debug_interaction_state_timeline_record(record, frame_count))
        .collect::<Vec<_>>();
    records.sort_by(|left, right| {
        debug_interaction_status_rank(left.status)
            .cmp(&debug_interaction_status_rank(right.status))
            .then_with(|| {
                right
                    .drag_captured_frame_count
                    .cmp(&left.drag_captured_frame_count)
            })
            .then_with(|| right.frame_count.cmp(&left.frame_count))
            .then_with(|| left.name.cmp(&right.name))
    });

    let status = debug_interaction_state_timeline_status(&frames);
    let summary = debug_interaction_state_timeline_summary(
        status,
        frame_count,
        captured_frame_count,
        missing_frame_count,
        active_frame_count,
        warning_frame_count,
        changed_frame_count,
        active_node_count,
        warning_count,
        gesture_frame_count,
        drag_capture_frame_count,
        new_active_count,
        resolved_active_count,
        latest_hovered_name.as_deref(),
        latest_focused_name.as_deref(),
    );

    DebugInteractionStateTimelineTrace {
        status,
        frame_count,
        captured_frame_count,
        missing_frame_count,
        active_frame_count,
        warning_frame_count,
        changed_frame_count,
        node_count,
        active_node_count,
        warning_count,
        gesture_frame_count,
        drag_capture_frame_count,
        text_editing_frame_count,
        wheel_target_frame_count,
        shortcut_frame_count,
        input_consumed_frame_count,
        new_active_count,
        resolved_active_count,
        persistent_active_count,
        latest_hovered_name,
        latest_pressed_name,
        latest_focused_name,
        records,
        frames,
        summary,
    }
}

fn debug_interaction_state_timeline_keys(
    records: &[DebugInteractionStateRecord],
) -> HashSet<String> {
    records.iter().map(|record| record.name.clone()).collect()
}

fn debug_interaction_state_timeline_merge_record(
    records: &mut Vec<DebugInteractionStateTimelineAccumulator>,
    frame_label: &str,
    record: &DebugInteractionStateRecord,
) {
    let warning = matches!(
        record.status,
        DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
    );
    let Some(accumulator) = records
        .iter_mut()
        .find(|accumulator| accumulator.name == record.name)
    else {
        records.push(DebugInteractionStateTimelineAccumulator {
            name: record.name.clone(),
            status: record.status,
            frame_count: 1,
            warning_frame_count: usize::from(warning),
            first_frame_label: Some(frame_label.to_owned()),
            latest_frame_label: Some(frame_label.to_owned()),
            hovered_frame_count: usize::from(record.hovered),
            pressed_frame_count: usize::from(record.pressed),
            focused_frame_count: usize::from(record.focused),
            drag_captured_frame_count: usize::from(record.drag_captured),
            text_editing_frame_count: usize::from(record.text_editing),
            wheel_targeted_frame_count: usize::from(record.wheel_targeted),
            shortcut_targeted_frame_count: usize::from(record.shortcut_targeted),
            input_consumed_frame_count: usize::from(record.input_consumed),
            latest_roles: record.roles.clone(),
            latest_visible: record.visible,
            latest_pointer: record.pointer,
            latest_focusable: record.focusable,
            latest_summary: record.summary.clone(),
            latest_cause: record.cause.clone(),
            latest_fix: record.fix.clone(),
        });
        return;
    };

    accumulator.status = accumulator.status.max(record.status);
    accumulator.frame_count += 1;
    accumulator.warning_frame_count += usize::from(warning);
    accumulator.latest_frame_label = Some(frame_label.to_owned());
    accumulator.hovered_frame_count += usize::from(record.hovered);
    accumulator.pressed_frame_count += usize::from(record.pressed);
    accumulator.focused_frame_count += usize::from(record.focused);
    accumulator.drag_captured_frame_count += usize::from(record.drag_captured);
    accumulator.text_editing_frame_count += usize::from(record.text_editing);
    accumulator.wheel_targeted_frame_count += usize::from(record.wheel_targeted);
    accumulator.shortcut_targeted_frame_count += usize::from(record.shortcut_targeted);
    accumulator.input_consumed_frame_count += usize::from(record.input_consumed);
    accumulator.latest_roles = record.roles.clone();
    accumulator.latest_visible = record.visible;
    accumulator.latest_pointer = record.pointer;
    accumulator.latest_focusable = record.focusable;
    accumulator.latest_summary = record.summary.clone();
    accumulator.latest_cause = record.cause.clone();
    accumulator.latest_fix = record.fix.clone();
}

fn debug_interaction_state_timeline_record(
    record: DebugInteractionStateTimelineAccumulator,
    retained_frame_count: usize,
) -> DebugInteractionStateTimelineRecord {
    let summary = debug_interaction_state_timeline_record_summary(
        &record.name,
        record.status,
        record.frame_count,
        retained_frame_count,
        record.warning_frame_count,
        record.hovered_frame_count,
        record.pressed_frame_count,
        record.focused_frame_count,
        record.drag_captured_frame_count,
        &record.latest_roles,
    );
    let cause = debug_interaction_state_timeline_record_cause(
        &record.name,
        record.frame_count,
        retained_frame_count,
        record.warning_frame_count,
        record.drag_captured_frame_count,
        &record.latest_cause,
    );
    let fix = format!(
        "open interaction_state_panel for {}; {}",
        record.name, record.latest_fix
    );
    DebugInteractionStateTimelineRecord {
        name: record.name,
        status: record.status,
        frame_count: record.frame_count,
        warning_frame_count: record.warning_frame_count,
        first_frame_label: record.first_frame_label,
        latest_frame_label: record.latest_frame_label,
        hovered_frame_count: record.hovered_frame_count,
        pressed_frame_count: record.pressed_frame_count,
        focused_frame_count: record.focused_frame_count,
        drag_captured_frame_count: record.drag_captured_frame_count,
        text_editing_frame_count: record.text_editing_frame_count,
        wheel_targeted_frame_count: record.wheel_targeted_frame_count,
        shortcut_targeted_frame_count: record.shortcut_targeted_frame_count,
        input_consumed_frame_count: record.input_consumed_frame_count,
        latest_roles: record.latest_roles,
        latest_visible: record.latest_visible,
        latest_pointer: record.latest_pointer,
        latest_focusable: record.latest_focusable,
        latest_summary: record.latest_summary,
        summary,
        cause,
        fix,
    }
}

fn debug_interaction_state_timeline_frame_record(
    index: usize,
    label: String,
    frame_index: Option<u64>,
    trace: Option<&DebugInteractionStateTrace>,
    new_active_count: usize,
    resolved_active_count: usize,
    persistent_active_count: usize,
) -> DebugInteractionStateTimelineFrameRecord {
    let captured = trace.is_some();
    let status = debug_interaction_state_timeline_frame_status(trace);
    let top_node_name =
        trace.and_then(|trace| trace.records.first().map(|record| record.name.clone()));
    let node_count = trace.map(|trace| trace.node_count).unwrap_or_default();
    let active_node_count = trace
        .map(|trace| trace.active_node_count)
        .unwrap_or_default();
    let warning_count = trace.map(|trace| trace.warning_count).unwrap_or_default();
    let gesture_summary = trace.and_then(|trace| trace.gesture_summary.clone());
    let hovered_name = trace.and_then(|trace| trace.hovered_name.clone());
    let pressed_name = trace.and_then(|trace| trace.pressed_name.clone());
    let focused_name = trace.and_then(|trace| trace.focused_name.clone());
    let shortcut_label = trace.and_then(|trace| trace.shortcut_label.clone());
    let summary = debug_interaction_state_timeline_frame_summary(
        &label,
        captured,
        status,
        active_node_count,
        warning_count,
        new_active_count,
        resolved_active_count,
        persistent_active_count,
        gesture_summary.as_deref(),
        top_node_name.as_deref(),
    );
    let cause = debug_interaction_state_timeline_frame_cause(
        captured,
        active_node_count,
        warning_count,
        new_active_count,
        resolved_active_count,
        top_node_name.as_deref(),
    );
    let fix = debug_interaction_state_timeline_frame_fix(
        captured,
        active_node_count,
        warning_count,
        new_active_count,
        resolved_active_count,
        top_node_name.as_deref(),
    );
    DebugInteractionStateTimelineFrameRecord {
        index,
        label,
        frame_index,
        captured,
        status,
        node_count,
        active_node_count,
        warning_count,
        new_active_count,
        resolved_active_count,
        persistent_active_count,
        gesture_summary,
        hovered_name,
        pressed_name,
        focused_name,
        shortcut_label,
        top_node_name,
        summary,
        cause,
        fix,
    }
}

fn debug_interaction_state_timeline_frame_status(
    trace: Option<&DebugInteractionStateTrace>,
) -> DebugFrameTraceStatus {
    let Some(trace) = trace else {
        return DebugFrameTraceStatus::Info;
    };
    trace.status
}

fn debug_interaction_state_timeline_status(
    frames: &[DebugInteractionStateTimelineFrameRecord],
) -> DebugFrameTraceStatus {
    if frames
        .iter()
        .any(|frame| frame.status == DebugFrameTraceStatus::Error)
    {
        return DebugFrameTraceStatus::Error;
    }
    if frames
        .iter()
        .any(|frame| frame.status == DebugFrameTraceStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if frames.iter().any(|frame| {
        frame.status == DebugFrameTraceStatus::Info
            || !frame.captured
            || frame.new_active_count > 0
            || frame.resolved_active_count > 0
    }) {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

#[allow(clippy::too_many_arguments)]
fn debug_interaction_state_timeline_summary(
    status: DebugFrameTraceStatus,
    frame_count: usize,
    captured_frame_count: usize,
    missing_frame_count: usize,
    active_frame_count: usize,
    warning_frame_count: usize,
    changed_frame_count: usize,
    active_node_count: usize,
    warning_count: usize,
    gesture_frame_count: usize,
    drag_capture_frame_count: usize,
    new_active_count: usize,
    resolved_active_count: usize,
    latest_hovered_name: Option<&str>,
    latest_focused_name: Option<&str>,
) -> String {
    let mut parts = vec![format!("{} interaction state timeline", status.label())];
    parts.push(format!(
        "{frame_count} frame{}",
        debug_plural_s(frame_count)
    ));
    parts.push(format!("{captured_frame_count} captured"));
    if missing_frame_count > 0 {
        parts.push(format!("{missing_frame_count} missing"));
    }
    if active_frame_count > 0 {
        parts.push(format!("{active_frame_count} active frames"));
    }
    if warning_frame_count > 0 {
        parts.push(format!("{warning_frame_count} warning frames"));
    }
    if changed_frame_count > 0 {
        parts.push(format!("{changed_frame_count} changed frames"));
    }
    if active_node_count > 0 {
        parts.push(format!("{active_node_count} active nodes"));
    }
    if warning_count > 0 {
        parts.push(format!("{warning_count} warnings"));
    }
    if gesture_frame_count > 0 {
        parts.push(format!("{gesture_frame_count} gestures"));
    }
    if drag_capture_frame_count > 0 {
        parts.push(format!("{drag_capture_frame_count} drag captures"));
    }
    if new_active_count > 0 {
        parts.push(format!("{new_active_count} new"));
    }
    if resolved_active_count > 0 {
        parts.push(format!("{resolved_active_count} resolved"));
    }
    if let Some(name) = latest_hovered_name {
        parts.push(format!("hover {name}"));
    }
    if let Some(name) = latest_focused_name {
        parts.push(format!("focus {name}"));
    }
    parts.join("; ")
}

#[allow(clippy::too_many_arguments)]
fn debug_interaction_state_timeline_record_summary(
    name: &str,
    status: DebugFrameTraceStatus,
    frame_count: usize,
    retained_frame_count: usize,
    warning_frame_count: usize,
    hovered_frame_count: usize,
    pressed_frame_count: usize,
    focused_frame_count: usize,
    drag_captured_frame_count: usize,
    latest_roles: &[String],
) -> String {
    let mut parts = vec![format!("{} interaction {name}", status.label())];
    parts.push(format!("{frame_count}/{retained_frame_count} frames"));
    if warning_frame_count > 0 {
        parts.push(format!("{warning_frame_count} warnings"));
    }
    if hovered_frame_count > 0 {
        parts.push(format!("hovered {hovered_frame_count}"));
    }
    if pressed_frame_count > 0 {
        parts.push(format!("pressed {pressed_frame_count}"));
    }
    if focused_frame_count > 0 {
        parts.push(format!("focused {focused_frame_count}"));
    }
    if drag_captured_frame_count > 0 {
        parts.push(format!("drag captured {drag_captured_frame_count}"));
    }
    if !latest_roles.is_empty() {
        parts.push(format!("latest {}", latest_roles.join(", ")));
    }
    parts.join("; ")
}

fn debug_interaction_state_timeline_record_cause(
    name: &str,
    frame_count: usize,
    retained_frame_count: usize,
    warning_frame_count: usize,
    drag_captured_frame_count: usize,
    latest_cause: &str,
) -> String {
    if warning_frame_count > 0 {
        return format!(
            "{name} had stale or inconsistent host interaction state in {warning_frame_count} retained frame{}; latest cause {latest_cause}",
            debug_plural_s(warning_frame_count)
        );
    }
    if drag_captured_frame_count > 0 {
        return format!(
            "{name} held drag capture in {drag_captured_frame_count}/{retained_frame_count} retained frame{}",
            debug_plural_s(retained_frame_count)
        );
    }
    format!(
        "{name} was an active interaction target in {frame_count}/{retained_frame_count} retained frame{}; latest cause {latest_cause}",
        debug_plural_s(retained_frame_count)
    )
}

#[allow(clippy::too_many_arguments)]
fn debug_interaction_state_timeline_frame_summary(
    label: &str,
    captured: bool,
    status: DebugFrameTraceStatus,
    active_node_count: usize,
    warning_count: usize,
    new_active_count: usize,
    resolved_active_count: usize,
    persistent_active_count: usize,
    gesture_summary: Option<&str>,
    top_node_name: Option<&str>,
) -> String {
    if !captured {
        return format!("info interaction state for {label}; not captured");
    }
    let mut parts = vec![format!("{} interaction state for {label}", status.label())];
    parts.push(format!("{active_node_count} active"));
    if warning_count > 0 {
        parts.push(format!("{warning_count} warnings"));
    }
    if new_active_count > 0 {
        parts.push(format!("{new_active_count} new"));
    }
    if resolved_active_count > 0 {
        parts.push(format!("{resolved_active_count} resolved"));
    }
    if persistent_active_count > 0 {
        parts.push(format!("{persistent_active_count} persistent"));
    }
    if let Some(gesture) = gesture_summary {
        parts.push(format!("gesture {gesture}"));
    }
    if let Some(top) = top_node_name {
        parts.push(format!("top {top}"));
    }
    parts.join("; ")
}

fn debug_interaction_state_timeline_frame_cause(
    captured: bool,
    active_node_count: usize,
    warning_count: usize,
    new_active_count: usize,
    resolved_active_count: usize,
    top_node_name: Option<&str>,
) -> String {
    if !captured {
        return "this frame did not attach DebugInteractionStateTrace to the frame capture"
            .to_owned();
    }
    if warning_count > 0 {
        return format!(
            "{warning_count} active host interaction target{} need review; top {}",
            debug_plural_s(warning_count),
            top_node_name.unwrap_or("unknown")
        );
    }
    if new_active_count > 0 || resolved_active_count > 0 {
        return format!(
            "active interaction target set changed: {new_active_count} new, {resolved_active_count} resolved"
        );
    }
    if active_node_count > 0 {
        return format!(
            "{active_node_count} node{} held hover, press, focus, drag, text, wheel, shortcut, or consumed-input state",
            debug_plural_s(active_node_count)
        );
    }
    "captured interaction state had no active host roles".to_owned()
}

fn debug_interaction_state_timeline_frame_fix(
    captured: bool,
    active_node_count: usize,
    warning_count: usize,
    new_active_count: usize,
    resolved_active_count: usize,
    top_node_name: Option<&str>,
) -> String {
    if !captured {
        return "attach DebugInteractionStateTrace with DebugFrameTraceContext::interaction_state or interaction_state_from_overlay"
            .to_owned();
    }
    if warning_count > 0 || active_node_count > 0 || new_active_count > 0 {
        return format!(
            "open interaction_state_panel for {} and compare pointer_session_panel, event_route_panel, and focus_navigation_panel",
            top_node_name.unwrap_or("the active target")
        );
    }
    if resolved_active_count > 0 {
        return "compare adjacent frame_timeline_panel captures to confirm interaction state resolved"
            .to_owned();
    }
    "no interaction-state timeline action needed".to_owned()
}

fn debug_shortcut_route_trace(
    registry: &CommandRegistry,
    shortcut: Shortcut,
    active_scopes: &[CommandScope],
) -> DebugShortcutRouteTrace {
    let shortcut_label = ShortcutFormatter::default().format(shortcut);
    let ordered_scopes = debug_shortcut_route_ordered_scopes(active_scopes);
    let mut records = Vec::new();
    let mut selected_scope = None;
    let mut selected_scope_label = None;
    let mut command = None;
    let mut command_label = None;
    let mut resolved = false;

    for (index, scope) in ordered_scopes.iter().rev().enumerate() {
        let matching = registry
            .bindings()
            .iter()
            .filter(|binding| binding.scope == *scope && binding.shortcut == shortcut)
            .collect::<Vec<_>>();
        let selected_binding = (!resolved).then(|| {
            matching.iter().find(|binding| {
                registry
                    .command(&binding.command)
                    .is_some_and(|command| command.is_enabled())
            })
        });
        let selected_binding = selected_binding.flatten();
        let selected = selected_binding.is_some();
        if let Some(binding) = selected_binding {
            resolved = true;
            selected_scope = Some(scope.clone());
            selected_scope_label = Some(debug_shortcut_scope_label(scope));
            command = Some(binding.command.clone());
            command_label = registry
                .command(&binding.command)
                .map(|command| command.meta.label.clone());
        }
        records.push(debug_shortcut_route_record(
            index,
            scope,
            active_scopes,
            registry,
            &matching,
            selected,
            resolved && !selected,
        ));
    }

    let binding_count = records.iter().map(|record| record.binding_count).sum();
    let disabled_binding_count = records
        .iter()
        .filter(|record| record.binding_count > 0 && !record.command_enabled)
        .count();
    let status =
        debug_shortcut_route_status(command.is_some(), binding_count, disabled_binding_count);
    let summary = debug_shortcut_route_summary(
        status,
        &shortcut_label,
        records.len(),
        binding_count,
        disabled_binding_count,
        selected_scope_label.as_deref(),
        command.as_ref(),
    );

    DebugShortcutRouteTrace {
        status,
        shortcut,
        shortcut_label,
        active_scopes: active_scopes.to_vec(),
        checked_scope_count: records.len(),
        binding_count,
        disabled_binding_count,
        selected_scope,
        selected_scope_label,
        command,
        command_label,
        records,
        summary,
    }
}

fn debug_shortcut_route_ordered_scopes(active_scopes: &[CommandScope]) -> Vec<CommandScope> {
    let mut scopes = Vec::<(CommandScope, usize)>::new();
    debug_shortcut_route_upsert_scope(&mut scopes, CommandScope::Global, 0);
    for (index, scope) in active_scopes.iter().enumerate() {
        debug_shortcut_route_upsert_scope(&mut scopes, scope.clone(), index + 1);
    }
    scopes.sort_by(|(left_scope, left_index), (right_scope, right_index)| {
        left_scope
            .hierarchy_rank()
            .cmp(&right_scope.hierarchy_rank())
            .then_with(|| left_index.cmp(right_index))
    });
    scopes.into_iter().map(|(scope, _)| scope).collect()
}

fn debug_shortcut_route_upsert_scope(
    scopes: &mut Vec<(CommandScope, usize)>,
    scope: CommandScope,
    index: usize,
) {
    if let Some((_, existing_index)) = scopes
        .iter_mut()
        .find(|(existing_scope, _)| *existing_scope == scope)
    {
        *existing_index = index;
    } else {
        scopes.push((scope, index));
    }
}

fn debug_shortcut_route_record(
    index: usize,
    scope: &CommandScope,
    active_scopes: &[CommandScope],
    registry: &CommandRegistry,
    matching: &[&crate::commands::ShortcutBinding],
    selected: bool,
    shadowed: bool,
) -> DebugShortcutRouteRecord {
    let scope_label = debug_shortcut_scope_label(scope);
    let active =
        *scope == CommandScope::Global || active_scopes.iter().any(|active| active == scope);
    let binding = matching.first().copied();
    let command = binding.map(|binding| binding.command.clone());
    let registered = command
        .as_ref()
        .and_then(|command| registry.command(command));
    let command_label = registered.map(|command| command.meta.label.clone());
    let command_enabled = registered.is_some_and(|command| command.is_enabled());
    let disabled_reason = registered.and_then(|command| command.disabled_reason.clone());
    let status =
        debug_shortcut_route_record_status(selected, shadowed, matching.len(), command_enabled);
    let summary = debug_shortcut_route_record_summary(
        status,
        &scope_label,
        selected,
        shadowed,
        matching.len(),
        command.as_ref(),
        command_enabled,
    );
    let cause = debug_shortcut_route_record_cause(
        &scope_label,
        selected,
        shadowed,
        matching.len(),
        command.as_ref(),
        command_enabled,
        disabled_reason.as_deref(),
    );
    let fix = debug_shortcut_route_record_fix(
        selected,
        shadowed,
        matching.len(),
        command.as_ref(),
        command_enabled,
    );

    DebugShortcutRouteRecord {
        index,
        scope: scope.clone(),
        scope_label,
        active,
        selected,
        shadowed,
        binding_count: matching.len(),
        command,
        command_label,
        command_enabled,
        disabled_reason,
        status,
        summary,
        cause,
        fix,
    }
}

fn debug_shortcut_scope_label(scope: &CommandScope) -> String {
    match scope {
        CommandScope::Global => "Global".to_owned(),
        CommandScope::Workspace => "Workspace".to_owned(),
        CommandScope::Panel => "Panel".to_owned(),
        CommandScope::Editor => "Editor".to_owned(),
        CommandScope::Text => "Text".to_owned(),
        CommandScope::Modal => "Modal".to_owned(),
        CommandScope::Custom(id) => format!("Custom({id})"),
    }
}

fn debug_shortcut_route_record_status(
    selected: bool,
    shadowed: bool,
    binding_count: usize,
    command_enabled: bool,
) -> DebugFrameTraceStatus {
    if binding_count > 0 && !command_enabled {
        DebugFrameTraceStatus::Warning
    } else if selected || shadowed || binding_count > 0 {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    }
}

fn debug_shortcut_route_status(
    resolved: bool,
    binding_count: usize,
    disabled_binding_count: usize,
) -> DebugFrameTraceStatus {
    if disabled_binding_count > 0 {
        DebugFrameTraceStatus::Warning
    } else if resolved || binding_count > 0 {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    }
}

fn debug_shortcut_route_summary(
    status: DebugFrameTraceStatus,
    shortcut_label: &str,
    checked_scope_count: usize,
    binding_count: usize,
    disabled_binding_count: usize,
    selected_scope: Option<&str>,
    command: Option<&CommandId>,
) -> String {
    let mut parts = vec![format!(
        "{} shortcut route {shortcut_label}",
        status.label()
    )];
    parts.push(format!("{checked_scope_count} scopes checked"));
    if binding_count > 0 {
        parts.push(format!("{binding_count} bindings"));
    }
    if disabled_binding_count > 0 {
        parts.push(format!("{disabled_binding_count} disabled"));
    }
    if let Some(scope) = selected_scope {
        parts.push(format!("selected {scope}"));
    }
    if let Some(command) = command {
        parts.push(format!("command {}", command.as_str()));
    } else {
        parts.push("no command".to_owned());
    }
    parts.join("; ")
}

fn debug_shortcut_route_record_summary(
    status: DebugFrameTraceStatus,
    scope_label: &str,
    selected: bool,
    shadowed: bool,
    binding_count: usize,
    command: Option<&CommandId>,
    command_enabled: bool,
) -> String {
    let mut parts = vec![format!("{} {scope_label}", status.label())];
    if selected {
        parts.push("selected".to_owned());
    } else if shadowed {
        parts.push("shadowed".to_owned());
    }
    if binding_count > 0 {
        parts.push(format!("{binding_count} binding"));
    } else {
        parts.push("no binding".to_owned());
    }
    if let Some(command) = command {
        parts.push(format!("command {}", command.as_str()));
        if !command_enabled {
            parts.push("disabled".to_owned());
        }
    }
    parts.join("; ")
}

fn debug_shortcut_route_record_cause(
    scope_label: &str,
    selected: bool,
    shadowed: bool,
    binding_count: usize,
    command: Option<&CommandId>,
    command_enabled: bool,
    disabled_reason: Option<&str>,
) -> String {
    if selected {
        return format!(
            "{scope_label} is the most specific checked scope with an enabled binding for {}",
            command.map(CommandId::as_str).unwrap_or("unknown")
        );
    }
    if binding_count > 0 && !command_enabled {
        return format!(
            "{scope_label} has a matching binding for {}, but the command is disabled{}",
            command.map(CommandId::as_str).unwrap_or("unknown"),
            disabled_reason
                .map(|reason| format!(": {reason}"))
                .unwrap_or_default()
        );
    }
    if shadowed {
        return format!("{scope_label} was not reached because a more specific enabled scope won");
    }
    if binding_count > 0 {
        return format!(
            "{scope_label} has a matching binding for {}",
            command.map(CommandId::as_str).unwrap_or("unknown")
        );
    }
    format!("{scope_label} has no matching binding for this shortcut")
}

fn debug_shortcut_route_record_fix(
    selected: bool,
    shadowed: bool,
    binding_count: usize,
    command: Option<&CommandId>,
    command_enabled: bool,
) -> String {
    if selected {
        return "shortcut routing is working; inspect command effects if execution still fails"
            .to_owned();
    }
    if binding_count > 0 && !command_enabled {
        return format!(
            "enable {} or bind this shortcut to an enabled command in a checked scope",
            command
                .map(CommandId::as_str)
                .unwrap_or("the disabled command")
        );
    }
    if shadowed {
        return "remove or change the more-specific binding if this lower scope should win"
            .to_owned();
    }
    "bind the shortcut in this scope or add the expected scope to active shortcut scopes".to_owned()
}

fn collect_layout_inspector_nodes(
    document: &UiDocument,
    snapshot: &LayoutSnapshot,
    paint_stats: &HashMap<UiNodeId, DebugPaintStats>,
    accessibility_by_node: &HashMap<UiNodeId, AccessibilityNode>,
    audits_by_node: &HashMap<UiNodeId, Vec<AuditWarning>>,
    text_measurer: &mut impl TextMeasurer,
    out: &mut Vec<DebugLayoutInspectorNode>,
) {
    let node = document.node(snapshot.id);
    out.push(DebugLayoutInspectorNode {
        id: snapshot.id,
        name: node.name.clone(),
        parent: node.parent,
        children: node.children.clone(),
        content_kind: debug_content_kind(node),
        text: debug_node_text(node),
        rect: snapshot.rect,
        clip_rect: snapshot.clip_rect,
        final_size: UiSize::new(snapshot.rect.width, snapshot.rect.height),
        intrinsic_size: document.intrinsic_size(snapshot.id, text_measurer).ok(),
        layout_content_size: node.layout.content_size,
        visible: snapshot.visible,
        input: node.input,
        action: node.action().map(debug_action_binding_label),
        action_kind: node.action().map(debug_action_binding_kind),
        action_mode: node.action_mode(),
        scroll: snapshot.scroll,
        scrollbar: snapshot.scrollbar,
        style: debug_layout_style_summary(node),
        visual: debug_node_visual_summary(node, snapshot.rect),
        paint: paint_stats.get(&snapshot.id).copied().unwrap_or_default(),
        accessibility: accessibility_by_node.get(&snapshot.id).cloned(),
        audit_warnings: audits_by_node
            .get(&snapshot.id)
            .cloned()
            .unwrap_or_default(),
    });

    for child in &snapshot.children {
        collect_layout_inspector_nodes(
            document,
            child,
            paint_stats,
            accessibility_by_node,
            audits_by_node,
            text_measurer,
            out,
        );
    }
}

fn debug_node_visual_summary(node: &UiNode, rect: UiRect) -> DebugNodeVisualSummary {
    let material = node.material();
    let shader = node.shader();
    let material_visual_outset = material
        .map(|material| material.visual_outset_for_rect(rect))
        .unwrap_or(0.0);
    let shader_visual_outset = shader.map(shader_debug_outset).unwrap_or(0.0);
    DebugNodeVisualSummary {
        shader_key: shader.map(|shader| shader.key.clone()),
        material: material.map(debug_material_label),
        paint_outset: material
            .map(|material| material.paint_outset)
            .unwrap_or(LayoutInsets::ZERO),
        material_visual_outset,
        shader_visual_outset,
        geometry_effect: material
            .map(|material| material.geometry_effect.clone())
            .unwrap_or(GeometryEffect::None),
        clip_shape: material
            .map(|material| material.clip_shape.clone())
            .unwrap_or(ElementShape::Rect),
        hit_shape: material
            .map(|material| material.hit_shape.clone())
            .unwrap_or(ElementShape::Rect),
    }
}

fn debug_content_kind(node: &UiNode) -> DebugNodeContentKind {
    match &node.content {
        UiContent::Empty => DebugNodeContentKind::Empty,
        UiContent::Text(_) => DebugNodeContentKind::Text,
        UiContent::Canvas(_) => DebugNodeContentKind::Canvas,
        UiContent::Image(_) => DebugNodeContentKind::Image,
        UiContent::PaintRect(_) => DebugNodeContentKind::PaintRect,
        UiContent::Scene(_) => DebugNodeContentKind::Scene,
    }
}

fn debug_node_text(node: &UiNode) -> Option<String> {
    match &node.content {
        UiContent::Text(text) => Some(text.text.clone()),
        _ => None,
    }
}

fn debug_layout_style_summary(node: &UiNode) -> DebugLayoutStyleSummary {
    let style = &node.style.layout;
    DebugLayoutStyleSummary {
        display: format!("{:?}", style.display),
        flex_direction: format!("{:?}", style.flex_direction),
        flex_wrap: format!("{:?}", style.flex_wrap),
        size: format!("{:?}", style.size),
        min_size: format!("{:?}", style.min_size),
        max_size: format!("{:?}", style.max_size),
        margin: format!("{:?}", style.margin),
        padding: format!("{:?}", style.padding),
        gap: format!("{:?}", style.gap),
        position: format!("{:?}", style.position),
        inset: format!("{:?}", style.inset),
        align_items: format!("{:?}", style.align_items),
        justify_content: format!("{:?}", style.justify_content),
        clip: format!("{:?}", node.style.clip),
        clip_scope: format!("{:?}", node.clip_scope),
        layer: node.layer.map(|layer| format!("{layer:?}")),
        z_index: node.style.z_index,
        opacity: format!("{:.3}", node.style.opacity),
        layout_constraint: node
            .layout_constraint
            .as_ref()
            .map(|constraint| format!("{constraint:?}")),
    }
}

