fn debug_scroll_timeline_frame_cause(
    ranges: &DebugScrollRangeTrace,
    new_overflow_count: usize,
    resolved_overflow_count: usize,
    changed_offset_count: usize,
    top_summary: Option<&str>,
) -> String {
    let mut parts = vec![ranges.summary.clone()];
    if new_overflow_count > 0 {
        parts.push(format!(
            "{new_overflow_count} overflow node{} appeared since previous frame",
            debug_plural_s(new_overflow_count)
        ));
    }
    if resolved_overflow_count > 0 {
        parts.push(format!(
            "{resolved_overflow_count} overflow node{} resolved since previous frame",
            debug_plural_s(resolved_overflow_count)
        ));
    }
    if changed_offset_count > 0 {
        parts.push(format!(
            "{changed_offset_count} scroll offset or range{} changed",
            debug_plural_s(changed_offset_count)
        ));
    }
    if let Some(top_summary) = top_summary {
        parts.push(format!("top {top_summary}"));
    }
    parts.join("; ")
}

fn debug_scroll_timeline_frame_fix(
    status: DebugFrameTraceStatus,
    overflow_node_count: usize,
    out_of_range_count: usize,
    new_overflow_count: usize,
    resolved_overflow_count: usize,
    changed_offset_count: usize,
    top_name: Option<&str>,
) -> String {
    if let Some(top_name) = top_name {
        return format!("open scroll_range_panel filtered to {top_name}");
    }
    if out_of_range_count > 0 {
        return "clamp scroll offsets after layout changes content or viewport sizes".to_owned();
    }
    if new_overflow_count > 0 || resolved_overflow_count > 0 || changed_offset_count > 0 {
        return "compare frame_timeline_panel with scroll_range_panel to inspect size and range changes"
            .to_owned();
    }
    if overflow_node_count > 0 {
        return "open scroll_range_panel and clip_scroll_panel for overflowing scroll nodes"
            .to_owned();
    }
    if matches!(status, DebugFrameTraceStatus::Warning) {
        return "open scroll_range_panel for the highest severity row".to_owned();
    }
    "no scroll action needed".to_owned()
}

