fn debug_text_fit_timeline_frame_fix(
    issue_count: usize,
    new_issue_count: usize,
    resolved_issue_count: usize,
    persistent_issue_count: usize,
    top_node_name: Option<&str>,
) -> String {
    if let Some(top_node_name) = top_node_name {
        return format!("open text_fit_panel or text_layout_panel for {top_node_name}");
    }
    if new_issue_count > 0 || resolved_issue_count > 0 {
        return "compare frame_timeline_panel with text_fit_panel to inspect changed text pressure"
            .to_owned();
    }
    if persistent_issue_count > 0 || issue_count > 0 {
        return "open text_fit_panel and inspect retained overflow or clipping".to_owned();
    }
    "no text-fit action needed".to_owned()
}

fn debug_text_fit_timeline_node_summary(
    node: &DebugLayoutInspectorNode,
    status: DebugFrameTraceStatus,
    horizontal_overflow_by: f32,
    vertical_overflow_by: f32,
    clipped: bool,
    missing_paint: bool,
) -> String {
    let mut parts = vec![format!("{} {}", node.name, status.label())];
    if horizontal_overflow_by > 0.0 {
        parts.push(format!("x +{horizontal_overflow_by:.0}px"));
    }
    if vertical_overflow_by > 0.0 {
        parts.push(format!("y +{vertical_overflow_by:.0}px"));
    }
    if clipped {
        parts.push("clipped".to_owned());
    }
    if missing_paint {
        parts.push("missing paint".to_owned());
    }
    if node.intrinsic_size.is_some() {
        parts.push("intrinsic".to_owned());
    }
    parts.join("; ")
}

fn debug_text_fit_timeline_node_cause(
    node: &DebugLayoutInspectorNode,
    horizontal_overflow_by: f32,
    vertical_overflow_by: f32,
    clipped: bool,
    missing_paint: bool,
) -> String {
    if missing_paint {
        return "text node produced no paint in this retained frame".to_owned();
    }
    if !node.visible {
        return "text node is hidden before paint".to_owned();
    }
    if horizontal_overflow_by > 0.0 && vertical_overflow_by > 0.0 {
        return "recorded text content exceeds both resolved width and height".to_owned();
    }
    if horizontal_overflow_by > 0.0 {
        return "recorded text content width exceeds the resolved text box".to_owned();
    }
    if vertical_overflow_by > 0.0 {
        return "recorded text content height exceeds the resolved text box".to_owned();
    }
    if clipped {
        return "ancestor clipping reduces the text node rect".to_owned();
    }
    if node.intrinsic_size.is_some() {
        return "retained frame includes intrinsic text measurement for this node".to_owned();
    }
    "text appears to fit its retained layout and clip".to_owned()
}

fn debug_text_fit_timeline_node_fix(
    node: &DebugLayoutInspectorNode,
    horizontal_overflow_by: f32,
    vertical_overflow_by: f32,
    clipped: bool,
    missing_paint: bool,
) -> String {
    if missing_paint {
        return "verify the text node is visible and produces text paint after layout".to_owned();
    }
    if !node.visible {
        return "inspect visibility, parent clipping, and conditional render state".to_owned();
    }
    if horizontal_overflow_by > 0.0 || vertical_overflow_by > 0.0 {
        return "increase the text box, enable wrapping, reduce font/line height, or intentionally truncate"
            .to_owned();
    }
    if clipped {
        return "relax the clipping ancestor or keep the clipped text intentional".to_owned();
    }
    if node.intrinsic_size.is_some() {
        return "check intrinsic text against localized and dynamic labels".to_owned();
    }
    "no text-fit action needed".to_owned()
}

fn debug_text_fit_timeline_overflow_amount(record: &DebugTextFitTimelineRecord) -> f32 {
    record.max_horizontal_overflow_by + record.max_vertical_overflow_by
}

fn debug_text_fit_timeline_estimated_text_width(text: &str, rect_height: f32) -> f32 {
    let average_glyph_width = rect_height.clamp(10.0, 32.0) * 0.5;
    text.chars().count() as f32 * average_glyph_width
}

fn debug_text_fit_timeline_excerpt(value: &str, max_chars: usize) -> String {
    if value.chars().count() <= max_chars {
        return value.to_owned();
    }
    let mut excerpt = value
        .chars()
        .take(max_chars.saturating_sub(3))
        .collect::<String>();
    excerpt.push_str("...");
    excerpt
}

fn debug_text_layout_status(
    visible: bool,
    text_paint_count: usize,
    horizontal_overflow: bool,
    vertical_overflow: bool,
    clip_reduces_text: bool,
) -> DebugNodeExplanationStatus {
    if !visible || text_paint_count == 0 {
        return DebugNodeExplanationStatus::Warning;
    }
    if horizontal_overflow || vertical_overflow || clip_reduces_text {
        return DebugNodeExplanationStatus::Warning;
    }
    DebugNodeExplanationStatus::Info
}

fn debug_text_layout_cause(
    text: &crate::TextContent,
    uses_intrinsic_text: bool,
    estimated_line_count: usize,
    horizontal_overflow: bool,
    vertical_overflow: bool,
    clip_reduces_text: bool,
) -> String {
    if horizontal_overflow || vertical_overflow {
        return format!(
            "measured text with {:?} wrap needs more space than the resolved layout rect",
            text.style.wrap
        );
    }
    if clip_reduces_text {
        return "the resolved clip is smaller than the text layout rect".to_owned();
    }
    if uses_intrinsic_text {
        return "intrinsic_text is used for measurement while visible text is rendered".to_owned();
    }
    if estimated_line_count > 1 {
        return format!(
            "{estimated_line_count} estimated lines from {:?} wrapping at the final width",
            text.style.wrap
        );
    }
    format!(
        "single-line text measured with {:?} family, size {:.1}, line {:.1}, {:?} wrap",
        text.style.family, text.style.font_size, text.style.line_height, text.style.wrap
    )
}

fn debug_text_layout_fix(
    text: &crate::TextContent,
    text_paint_count: usize,
    horizontal_overflow: bool,
    vertical_overflow: bool,
    clip_reduces_text: bool,
) -> String {
    if text_paint_count == 0 {
        return "compute layout and paint before collecting the text trace".to_owned();
    }
    if horizontal_overflow && text.style.wrap == TextWrap::None {
        return "increase width, enable wrapping, reduce font size, or intentionally clip/truncate"
            .to_owned();
    }
    if horizontal_overflow || vertical_overflow {
        return "increase the text box, reduce font/line height, adjust wrapping, or allow scrolling"
            .to_owned();
    }
    if clip_reduces_text {
        return "relax the clipping ancestor or keep the clipped text intentional".to_owned();
    }
    "no text layout action needed".to_owned()
}

fn debug_text_layout_summary(
    name: &str,
    status: DebugNodeExplanationStatus,
    estimated_line_count: usize,
    horizontal_overflow: bool,
    vertical_overflow: bool,
    uses_intrinsic_text: bool,
) -> String {
    let mut parts = vec![format!("{name} text {}", status.label())];
    parts.push(format!("{estimated_line_count} estimated lines"));
    if horizontal_overflow {
        parts.push("horizontal overflow".to_owned());
    }
    if vertical_overflow {
        parts.push("vertical overflow".to_owned());
    }
    if uses_intrinsic_text {
        parts.push("intrinsic text".to_owned());
    }
    parts.join("; ")
}

fn debug_frame_trace_summary(
    snapshot: &DebugInspectorSnapshot,
    timing: &FrameTimingExplanation,
    routes: &[DebugEventRouteTrace],
    resources: &DebugResourceReport,
    selected_node: Option<&DebugNodeExplanation>,
) -> DebugFrameTraceSummary {
    let paint_item_count = snapshot.nodes.iter().map(|node| node.paint.count).sum();
    let status = debug_frame_trace_status(snapshot, timing, resources, selected_node);
    let slowest_stage = timing
        .slowest_stage
        .as_ref()
        .map(|stage| stage.label().to_owned());
    let selected_name = selected_node.map(|node| node.name.clone());
    let mut parts = vec![format!("{} frame", status.label())];
    if let Some(selected) = selected_node {
        parts.push(format!("selected {}", selected.name));
    }
    if let Some(stage) = &slowest_stage {
        parts.push(format!("slowest {stage}"));
    }
    if timing.over_budget == Some(true) {
        parts.push("over budget".to_owned());
    }
    if !snapshot.constraints.is_empty() {
        parts.push(format!("{} constraints", snapshot.constraints.len()));
    }
    if !snapshot.overlaps.is_empty() {
        parts.push(format!("{} overlaps", snapshot.overlaps.len()));
    }
    if !resources.records.is_empty() {
        parts.push(format!(
            "{} resources ({} missing)",
            resources.records.len(),
            resources.missing_count()
        ));
    }
    if !routes.is_empty() {
        parts.push(format!("{} routes", routes.len()));
    }

    DebugFrameTraceSummary {
        status,
        node_count: snapshot.nodes.len(),
        paint_item_count,
        animation_count: snapshot.animations.len(),
        overlap_count: snapshot.overlaps.len(),
        constraint_issue_count: snapshot.constraints.len(),
        resource_count: resources.records.len(),
        route_count: routes.len(),
        selected_node: selected_name,
        slowest_stage,
        over_budget: timing.over_budget,
        summary: parts.join("; "),
    }
}

fn debug_frame_trace_status(
    snapshot: &DebugInspectorSnapshot,
    timing: &FrameTimingExplanation,
    resources: &DebugResourceReport,
    selected_node: Option<&DebugNodeExplanation>,
) -> DebugFrameTraceStatus {
    if snapshot
        .constraints
        .iter()
        .any(|issue| issue.severity == DebugConstraintSeverity::Error)
        || resources.invalid_count() > 0
        || selected_node.is_some_and(|node| node.status == DebugNodeExplanationStatus::Error)
    {
        return DebugFrameTraceStatus::Error;
    }
    if timing.over_budget == Some(true)
        || snapshot
            .constraints
            .iter()
            .any(|issue| issue.severity == DebugConstraintSeverity::Warning)
        || resources.missing_count() > 0
        || resources.unused_update_count() > 0
        || snapshot
            .overlaps
            .iter()
            .any(|overlap| overlap.kind == DebugOverlapKind::InteractiveHitbox)
        || selected_node.is_some_and(|node| node.status == DebugNodeExplanationStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if !snapshot.constraints.is_empty()
        || !snapshot.overlaps.is_empty()
        || !resources.records.is_empty()
        || selected_node.is_some_and(|node| node.status == DebugNodeExplanationStatus::Info)
    {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

fn debug_frame_bottleneck_timing_stage_record(
    stage: &DebugFrameBudgetStage,
    budget: &DebugFrameBudgetTrace,
) -> DebugFrameBottleneckRecord {
    let mut score = debug_frame_bottleneck_duration_score(stage.duration);
    if stage.dominant {
        score = score.saturating_add(80);
    }
    if stage.over_budget {
        score = score.saturating_add(180);
    }
    if budget.over_budget_by.is_some() && stage.dominant {
        score = score.saturating_add(120);
    }
    let status = if stage.over_budget || (budget.over_budget_by.is_some() && stage.dominant) {
        DebugFrameTraceStatus::Warning
    } else if stage.dominant || stage.duration > Duration::default() {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    };
    DebugFrameBottleneckRecord {
        source: DebugFrameBottleneckSource::TimingStage,
        label: stage.label.clone(),
        status,
        score,
        duration: Some(stage.duration),
        percent_of_budget: stage.percent_of_budget,
        node: None,
        node_name: None,
        inspect: "frame_budget_panel".to_owned(),
        summary: format!(
            "{} timing stage; {}; {:.0}% of total",
            stage.label,
            format_debug_duration_ms(stage.duration),
            stage.percent_of_total
        ),
        cause: stage.cause.clone(),
        fix: stage.action.clone(),
    }
}

fn debug_frame_bottleneck_dirty_record(
    budget: &DebugFrameBudgetTrace,
    blame: &DebugInvalidationBlameTrace,
) -> Option<DebugFrameBottleneckRecord> {
    if blame.clean && budget.over_budget_by.is_none() {
        return None;
    }
    let primary = blame.primary();
    let status = if budget.over_budget_by.is_some() && blame.dirty_subsystem_count > 0 {
        DebugFrameTraceStatus::Warning
    } else {
        blame.status
    };
    let score = (blame.dirty_subsystem_count as u32)
        .saturating_mul(30)
        .saturating_add((blame.invalidation_count as u32).saturating_mul(18))
        .saturating_add(
            primary
                .map(|record| record.blast_radius as u32 * 10)
                .unwrap_or(0),
        )
        .saturating_add(if budget.over_budget_by.is_some() {
            90
        } else {
            0
        });
    let recompute = if blame.recompute_order.is_empty() {
        "none".to_owned()
    } else {
        blame
            .recompute_order
            .iter()
            .map(|subsystem| subsystem.display_label())
            .collect::<Vec<_>>()
            .join(", ")
    };
    Some(DebugFrameBottleneckRecord {
        source: DebugFrameBottleneckSource::DirtyState,
        label: "dirty state".to_owned(),
        status,
        score,
        duration: None,
        percent_of_budget: None,
        node: None,
        node_name: None,
        inspect: "invalidation_blame_panel".to_owned(),
        summary: format!("dirty state; recompute {recompute}; {}", blame.summary),
        cause: primary
            .map(|record| record.cause.clone())
            .unwrap_or_else(|| {
                "dirty subsystems were present without a specific invalidation cause".to_owned()
            }),
        fix: primary.map(|record| record.fix.clone()).unwrap_or_else(|| {
            "attach runtime invalidation details and inspect dirty_state_panel".to_owned()
        }),
    })
}

fn debug_frame_bottleneck_layout_cost_record(
    budget: &DebugFrameBudgetTrace,
    trace: &DebugLayoutCostTrace,
) -> Option<DebugFrameBottleneckRecord> {
    let top = trace.records.first()?;
    if top.score == 0 && trace.status == DebugFrameTraceStatus::Ok {
        return None;
    }
    let status = if budget
        .slowest_stage
        .as_deref()
        .is_some_and(|stage| stage == "layout")
        || (budget.over_budget_by.is_some() && top.score > 0)
    {
        DebugFrameTraceStatus::Warning
    } else {
        top.status
    };
    Some(DebugFrameBottleneckRecord {
        source: DebugFrameBottleneckSource::LayoutCost,
        label: format!("layout {}", top.name),
        status,
        score: top
            .score
            .saturating_add(if status == DebugFrameTraceStatus::Warning {
                70
            } else {
                0
            }),
        duration: None,
        percent_of_budget: None,
        node: Some(top.node),
        node_name: Some(top.name.clone()),
        inspect: "layout_cost_panel".to_owned(),
        summary: format!("layout cost score {}; {}", top.score, top.summary),
        cause: top.cause.clone(),
        fix: top.fix.clone(),
    })
}

fn debug_frame_bottleneck_slow_node_record(
    record: &DebugSlowNodeRecord,
    budget: &DebugFrameBudgetTrace,
) -> DebugFrameBottleneckRecord {
    let status = if budget.over_budget_by.is_some()
        && record.score > 0
        && matches!(
            record.status,
            DebugFrameTraceStatus::Info | DebugFrameTraceStatus::Ok
        ) {
        DebugFrameTraceStatus::Warning
    } else {
        record.status
    };
    DebugFrameBottleneckRecord {
        source: DebugFrameBottleneckSource::SlowNode,
        label: format!("slow node {}", record.name),
        status,
        score: record
            .score
            .saturating_add(if status == DebugFrameTraceStatus::Warning {
                80
            } else {
                0
            }),
        duration: None,
        percent_of_budget: None,
        node: Some(record.node),
        node_name: Some(record.name.clone()),
        inspect: "slow_nodes_panel".to_owned(),
        summary: format!("slow node score {}; {}", record.score, record.summary),
        cause: record.cause.clone(),
        fix: record.fix.clone(),
    }
}

fn debug_frame_bottleneck_paint_record(
    trace: &DebugFrameTrace,
) -> Option<DebugFrameBottleneckRecord> {
    let record = debug_frame_autopsy_paint_record(trace);
    if record.status == DebugFrameTraceStatus::Ok
        && trace.summary.paint_item_count <= trace.summary.node_count
    {
        return None;
    }
    let score = (trace.summary.paint_item_count as u32)
        .saturating_mul(4)
        .saturating_add(if record.status == DebugFrameTraceStatus::Warning {
            100
        } else {
            0
        });
    Some(DebugFrameBottleneckRecord {
        source: DebugFrameBottleneckSource::Paint,
        label: "paint".to_owned(),
        status: record.status,
        score,
        duration: None,
        percent_of_budget: None,
        node: None,
        node_name: None,
        inspect: "paint_order_panel".to_owned(),
        summary: record.summary,
        cause: record.cause,
        fix: record.fix,
    })
}

fn debug_frame_bottleneck_resource_record(
    resources: &DebugResourceReport,
) -> Option<DebugFrameBottleneckRecord> {
    let record = debug_frame_autopsy_resource_record(resources);
    if record.status == DebugFrameTraceStatus::Ok {
        return None;
    }
    let score = (resources.missing_count() as u32)
        .saturating_mul(120)
        .saturating_add((resources.invalid_count() as u32).saturating_mul(100))
        .saturating_add((resources.unused_update_count() as u32).saturating_mul(30))
        .saturating_add(resources.records.len() as u32);
    Some(DebugFrameBottleneckRecord {
        source: DebugFrameBottleneckSource::Resources,
        label: "resources".to_owned(),
        status: record.status,
        score,
        duration: None,
        percent_of_budget: None,
        node: None,
        node_name: None,
        inspect: "resource_diagnostics_panel".to_owned(),
        summary: record.summary,
        cause: record.cause,
        fix: record.fix,
    })
}

fn debug_frame_bottleneck_cache_record(
    cache: &DebugCacheReuseTrace,
) -> Option<DebugFrameBottleneckRecord> {
    if cache.status == DebugFrameTraceStatus::Ok
        && cache.total_misses == 0
        && cache.total_evictions == 0
        && cache.missing_required_count == 0
    {
        return None;
    }
    let slow = debug_slow_frame_cache_record(cache);
    Some(DebugFrameBottleneckRecord {
        source: DebugFrameBottleneckSource::CacheReuse,
        label: "cache reuse".to_owned(),
        status: slow.status,
        score: slow.score,
        duration: None,
        percent_of_budget: None,
        node: None,
        node_name: None,
        inspect: "cache_reuse_panel".to_owned(),
        summary: slow.summary,
        cause: slow.cause,
        fix: slow.fix,
    })
}

fn debug_frame_bottleneck_route_record(
    routes: &[DebugEventRouteTrace],
) -> Option<DebugFrameBottleneckRecord> {
    let record = debug_frame_autopsy_route_record(routes);
    if record.status == DebugFrameTraceStatus::Ok {
        return None;
    }
    let rejected = routes
        .iter()
        .flat_map(|route| route.candidates.iter())
        .filter(|candidate| !candidate.rejections.is_empty())
        .count();
    Some(DebugFrameBottleneckRecord {
        source: DebugFrameBottleneckSource::EventRoutes,
        label: "event routes".to_owned(),
        status: record.status,
        score: (routes.len() as u32)
            .saturating_mul(20)
            .saturating_add((rejected as u32).saturating_mul(12)),
        duration: None,
        percent_of_budget: None,
        node: None,
        node_name: None,
        inspect: "event_route_panel".to_owned(),
        summary: record.summary,
        cause: record.cause,
        fix: record.fix,
    })
}

fn debug_frame_bottleneck_constraint_record(
    constraints: &[DebugConstraintIssue],
) -> Option<DebugFrameBottleneckRecord> {
    let record = debug_frame_autopsy_constraint_record(constraints);
    if record.status == DebugFrameTraceStatus::Ok {
        return None;
    }
    Some(DebugFrameBottleneckRecord {
        source: DebugFrameBottleneckSource::Constraints,
        label: "constraints".to_owned(),
        status: record.status,
        score: (constraints.len() as u32).saturating_mul(45),
        duration: None,
        percent_of_budget: None,
        node: None,
        node_name: None,
        inspect: "constraint_issues_panel".to_owned(),
        summary: record.summary,
        cause: record.cause,
        fix: record.fix,
    })
}

fn debug_frame_bottleneck_overlap_record(
    overlaps: &[DebugOverlapRecord],
) -> Option<DebugFrameBottleneckRecord> {
    let record = debug_frame_autopsy_overlap_record(overlaps);
    if record.status == DebugFrameTraceStatus::Ok {
        return None;
    }
    let interactive = overlaps
        .iter()
        .filter(|overlap| overlap.kind == DebugOverlapKind::InteractiveHitbox)
        .count();
    Some(DebugFrameBottleneckRecord {
        source: DebugFrameBottleneckSource::Overlaps,
        label: "overlaps".to_owned(),
        status: record.status,
        score: (overlaps.len() as u32)
            .saturating_mul(18)
            .saturating_add((interactive as u32).saturating_mul(70)),
        duration: None,
        percent_of_budget: None,
        node: None,
        node_name: None,
        inspect: "overlap_report_panel".to_owned(),
        summary: record.summary,
        cause: record.cause,
        fix: record.fix,
    })
}

fn debug_frame_bottleneck_duration_score(duration: Duration) -> u32 {
    (duration.as_secs_f64() * 1_000.0 * 8.0)
        .round()
        .clamp(0.0, 30_000.0) as u32
}

fn debug_frame_bottleneck_trace_status(
    records: &[DebugFrameBottleneckRecord],
    budget_status: DebugFrameTraceStatus,
) -> DebugFrameTraceStatus {
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Error)
    {
        return DebugFrameTraceStatus::Error;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Warning)
        || budget_status == DebugFrameTraceStatus::Warning
    {
        return DebugFrameTraceStatus::Warning;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Info)
        || budget_status == DebugFrameTraceStatus::Info
    {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

#[allow(clippy::too_many_arguments)]
fn debug_frame_bottleneck_trace_summary(
    status: DebugFrameTraceStatus,
    label: &str,
    total: Duration,
    budget: Option<Duration>,
    over_budget_by: Option<Duration>,
    top_label: Option<&str>,
    record_count: usize,
    warning_count: usize,
) -> String {
    let mut parts = vec![format!("{} frame bottlenecks", status.label())];
    parts.push(label.to_owned());
    parts.push(format!("total {}", format_debug_duration_ms(total)));
    if let Some(budget) = budget {
        parts.push(format!("budget {}", format_debug_duration_ms(budget)));
    }
    if let Some(over_by) = over_budget_by {
        parts.push(format!("over by {}", format_debug_duration_ms(over_by)));
    }
    if let Some(top) = top_label {
        parts.push(format!("top {top}"));
    }
    parts.push(format!("{record_count} records"));
    if warning_count > 0 {
        parts.push(format!(
            "{warning_count} warning{}",
            debug_plural_s(warning_count)
        ));
    }
    parts.join("; ")
}

fn debug_frame_bottleneck_status_rank(status: DebugFrameTraceStatus) -> u8 {
    match status {
        DebugFrameTraceStatus::Error => 0,
        DebugFrameTraceStatus::Warning => 1,
        DebugFrameTraceStatus::Info => 2,
        DebugFrameTraceStatus::Ok => 3,
    }
}

fn debug_frame_bottleneck_source_rank(source: DebugFrameBottleneckSource) -> u8 {
    match source {
        DebugFrameBottleneckSource::TimingStage => 0,
        DebugFrameBottleneckSource::SlowNode => 1,
        DebugFrameBottleneckSource::DirtyState => 2,
        DebugFrameBottleneckSource::LayoutCost => 3,
        DebugFrameBottleneckSource::Paint => 4,
        DebugFrameBottleneckSource::Resources => 5,
        DebugFrameBottleneckSource::CacheReuse => 6,
        DebugFrameBottleneckSource::EventRoutes => 7,
        DebugFrameBottleneckSource::Constraints => 8,
        DebugFrameBottleneckSource::Overlaps => 9,
    }
}

fn debug_frame_autopsy_timing_record(budget: &DebugFrameBudgetTrace) -> DebugFrameAutopsyRecord {
    let source = DebugFrameAutopsySource::Timing;
    let status = budget.status;
    let mut parts = vec![format!(
        "timing: {}",
        format_debug_duration_ms(budget.timing.total)
    )];
    if let Some(over) = budget.over_budget_by {
        parts.push(format!("over by {}", format_debug_duration_ms(over)));
    }
    if let Some(stage) = &budget.slowest_stage {
        parts.push(format!("slowest {stage}"));
    }
    let cause = if let Some(stage) = budget.stages.first() {
        stage.cause.clone()
    } else if budget.timing.stages.is_empty() {
        "no frame timing sections were captured".to_owned()
    } else {
        "frame timing sections were captured but no dominant stage was identified".to_owned()
    };
    let fix = if let Some(stage) = budget.stages.first() {
        stage.action.clone()
    } else {
        "record frame timing sections around tree build, layout, text, paint, batching, and renderer work".to_owned()
    };
    DebugFrameAutopsyRecord {
        source,
        status,
        summary: parts.join("; "),
        cause,
        fix,
    }
}

fn debug_frame_autopsy_dirty_record(
    blame: &DebugInvalidationBlameTrace,
) -> DebugFrameAutopsyRecord {
    let source = DebugFrameAutopsySource::DirtyState;
    let cause = blame
        .primary()
        .map(|record| record.cause.clone())
        .unwrap_or_else(|| {
            if blame.clean {
                "frame did not report dirty subsystems".to_owned()
            } else {
                "dirty flags were present without runtime invalidation details".to_owned()
            }
        });
    let fix = blame
        .primary()
        .map(|record| record.fix.clone())
        .unwrap_or_else(|| {
            if blame.clean {
                "no dirty-state action needed".to_owned()
            } else {
                "attach runtime invalidation details to explain why subsystems recomputed"
                    .to_owned()
            }
        });
    DebugFrameAutopsyRecord {
        source,
        status: blame.status,
        summary: format!("dirty: {}", blame.summary),
        cause,
        fix,
    }
}

fn debug_frame_autopsy_layout_cost_record(trace: &DebugLayoutCostTrace) -> DebugFrameAutopsyRecord {
    let source = DebugFrameAutopsySource::LayoutCost;
    let top = trace.records.first();
    DebugFrameAutopsyRecord {
        source,
        status: trace.status,
        summary: top
            .map(|record| format!("layout cost: {} score {}", record.name, record.score))
            .unwrap_or_else(|| "layout cost: no layout nodes".to_owned()),
        cause: top
            .map(|record| record.cause.clone())
            .unwrap_or_else(|| "no layout-cost pressure was detected".to_owned()),
        fix: top
            .map(|record| record.fix.clone())
            .unwrap_or_else(|| "no layout-cost action needed".to_owned()),
    }
}

fn debug_frame_autopsy_paint_record(trace: &DebugFrameTrace) -> DebugFrameAutopsyRecord {
    let source = DebugFrameAutopsySource::Paint;
    let effects = DebugVisualEffectTrace::from_snapshot(&trace.snapshot, None);
    let shader_count = trace
        .snapshot
        .nodes
        .iter()
        .filter(|node| node.visual.shader_key.is_some())
        .count();
    let material_outset_count = trace
        .snapshot
        .nodes
        .iter()
        .filter(|node| {
            node.visual.material_visual_outset > 0.0 || node.visual.shader_visual_outset > 0.0
        })
        .count();
    let status = if effects.issue_count > 0 {
        DebugFrameTraceStatus::Warning
    } else if trace.summary.paint_item_count > trace.summary.node_count
        || shader_count > 0
        || material_outset_count > 0
    {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    };
    let mut parts = vec![format!("paint: {} items", trace.summary.paint_item_count)];
    if shader_count > 0 {
        parts.push(format!("{shader_count} shaders"));
    }
    if material_outset_count > 0 {
        parts.push(format!("{material_outset_count} outsets"));
    }
    if effects.issue_count > 0 {
        parts.push(format!("{} effect issues", effects.issue_count));
    }
    let issue = effects
        .records
        .iter()
        .find(|record| {
            matches!(
                record.status,
                DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
            )
        })
        .or_else(|| effects.records.first());
    DebugFrameAutopsyRecord {
        source,
        status,
        summary: parts.join("; "),
        cause: issue
            .map(|record| record.cause.clone())
            .unwrap_or_else(|| "paint item count, shaders, and visual outsets are within expected debug bounds".to_owned()),
        fix: issue
            .map(|record| record.fix.clone())
            .unwrap_or_else(|| "inspect paint_order_panel, visual_effects_panel, and paint_batches_panel when paint cost or stacking is unexpected".to_owned()),
    }
}

fn debug_frame_autopsy_resource_record(resources: &DebugResourceReport) -> DebugFrameAutopsyRecord {
    let source = DebugFrameAutopsySource::Resources;
    let status = resources
        .records
        .iter()
        .filter_map(|record| debug_resource_issue_status(record.status))
        .min_by_key(|status| debug_frame_autopsy_status_rank(*status))
        .unwrap_or_else(|| {
            if resources.records.is_empty() {
                DebugFrameTraceStatus::Ok
            } else {
                DebugFrameTraceStatus::Info
            }
        });
    let issue = resources
        .records
        .iter()
        .find(|record| debug_resource_issue_status(record.status).is_some());
    let summary = if resources.missing_count() > 0 {
        format!(
            "resources: {} missing of {}",
            resources.missing_count(),
            resources.records.len()
        )
    } else if resources.invalid_count() > 0 {
        format!(
            "resources: {} invalid of {}",
            resources.invalid_count(),
            resources.records.len()
        )
    } else if resources.unused_update_count() > 0 {
        format!(
            "resources: {} unused of {}",
            resources.unused_update_count(),
            resources.records.len()
        )
    } else {
        format!("resources: {}", resources.summary())
    };
    DebugFrameAutopsyRecord {
        source,
        status,
        summary,
        cause: issue.map(|record| record.cause.clone()).unwrap_or_else(|| {
            "resource references and updates resolved without frame-level issues".to_owned()
        }),
        fix: issue
            .map(|record| record.fix.clone())
            .unwrap_or_else(|| "no resource action needed".to_owned()),
    }
}

fn debug_frame_autopsy_route_record(routes: &[DebugEventRouteTrace]) -> DebugFrameAutopsyRecord {
    let source = DebugFrameAutopsySource::EventRoutes;
    let missing_target_count = routes
        .iter()
        .filter(|route| route.target.is_none() && !route.candidates.is_empty())
        .count();
    let rejected_candidate_count = routes
        .iter()
        .flat_map(|route| route.candidates.iter())
        .filter(|candidate| !candidate.rejections.is_empty())
        .count();
    let status = if missing_target_count > 0 {
        DebugFrameTraceStatus::Warning
    } else if !routes.is_empty() || rejected_candidate_count > 0 {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    };
    let cause = if missing_target_count > 0 {
        "one or more routed pointer events had candidates but no final target".to_owned()
    } else if rejected_candidate_count > 0 {
        "some route candidates were rejected by geometry, z-order, or scrollbar capture".to_owned()
    } else if routes.is_empty() {
        "no event route traces were attached to this frame".to_owned()
    } else {
        "attached route traces resolved final targets".to_owned()
    };
    let fix = if status == DebugFrameTraceStatus::Warning {
        "inspect event_route_panel and pointer_probe_panel for the missing target".to_owned()
    } else if rejected_candidate_count > 0 {
        "inspect event_route_panel when rejected candidates explain surprising input behavior"
            .to_owned()
    } else {
        "no event-route action needed".to_owned()
    };
    DebugFrameAutopsyRecord {
        source,
        status,
        summary: format!(
            "routes: {} traces; {} rejected candidates",
            routes.len(),
            rejected_candidate_count
        ),
        cause,
        fix,
    }
}

fn debug_frame_autopsy_constraint_record(
    constraints: &[DebugConstraintIssue],
) -> DebugFrameAutopsyRecord {
    let source = DebugFrameAutopsySource::Constraints;
    let status = constraints
        .iter()
        .map(|issue| debug_constraint_status(issue.severity))
        .min_by_key(|status| debug_frame_autopsy_status_rank(*status))
        .unwrap_or(DebugFrameTraceStatus::Ok);
    let issue = constraints.first();
    DebugFrameAutopsyRecord {
        source,
        status,
        summary: format!("constraints: {} issues", constraints.len()),
        cause: issue
            .map(|issue| issue.summary.clone())
            .unwrap_or_else(|| "no constraint/audit issue was recorded for this frame".to_owned()),
        fix: issue
            .map(|issue| issue.fix.clone())
            .unwrap_or_else(|| "no constraint action needed".to_owned()),
    }
}

fn debug_frame_autopsy_overlap_record(overlaps: &[DebugOverlapRecord]) -> DebugFrameAutopsyRecord {
    let source = DebugFrameAutopsySource::Overlaps;
    let interactive = overlaps
        .iter()
        .filter(|overlap| overlap.kind == DebugOverlapKind::InteractiveHitbox)
        .count();
    let status = if interactive > 0 {
        DebugFrameTraceStatus::Warning
    } else if !overlaps.is_empty() {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    };
    let issue = overlaps.first();
    DebugFrameAutopsyRecord {
        source,
        status,
        summary: if interactive > 0 {
            format!("overlaps: {interactive} interactive")
        } else {
            format!("overlaps: {}", overlaps.len())
        },
        cause: issue
            .map(|overlap| {
                format!(
                    "{} overlap between {} and {}",
                    debug_overlap_kind_label(overlap.kind),
                    overlap.back.name,
                    overlap.front.name
                )
            })
            .unwrap_or_else(|| "no overlap report entry was recorded for this frame".to_owned()),
        fix: if interactive > 0 {
            "open overlap_report_panel and separate, clip, disable, or reorder interactive regions"
                .to_owned()
        } else if !overlaps.is_empty() {
            "inspect paint_order_panel and layout_cause_panel if visual/layout overlap is unexpected"
                .to_owned()
        } else {
            "no overlap action needed".to_owned()
        },
    }
}

fn debug_frame_autopsy_selected_record(
    selected: Option<&DebugNodeExplanation>,
) -> DebugFrameAutopsyRecord {
    let source = DebugFrameAutopsySource::SelectedNode;
    let Some(selected) = selected else {
        return DebugFrameAutopsyRecord {
            source,
            status: DebugFrameTraceStatus::Ok,
            summary: "selected node: none".to_owned(),
            cause: "frame trace did not include selected-node context".to_owned(),
            fix: "attach selected_node to DebugFrameTraceContext when debugging a specific node"
                .to_owned(),
        };
    };
    DebugFrameAutopsyRecord {
        source,
        status: DebugFrameTraceStatus::from(selected.status),
        summary: format!("selected node: {}", selected.summary),
        cause: selected
            .constraints
            .first()
            .map(|issue| issue.summary.clone())
            .or_else(|| {
                selected
                    .resources
                    .first()
                    .map(|resource| resource.summary.clone())
            })
            .or_else(|| {
                selected
                    .overlaps
                    .first()
                    .map(|overlap| overlap.cause.clone())
            })
            .unwrap_or_else(|| selected.input.cause.clone()),
        fix: selected
            .constraints
            .first()
            .map(|issue| issue.fix.clone())
            .or_else(|| {
                selected
                    .resources
                    .first()
                    .map(|resource| resource.fix.clone())
            })
            .or_else(|| selected.overlaps.first().map(|overlap| overlap.fix.clone()))
            .unwrap_or_else(|| selected.input.fix.clone()),
    }
}

fn debug_frame_autopsy_cache_record(
    cache: Option<&DebugCacheReuseTrace>,
) -> DebugFrameAutopsyRecord {
    let source = DebugFrameAutopsySource::CacheReuse;
    let Some(cache) = cache else {
        return DebugFrameAutopsyRecord {
            source,
            status: DebugFrameTraceStatus::Ok,
            summary: "cache reuse: no report supplied".to_owned(),
            cause: "cache provenance requires a DebugCacheReuseTrace for the same frame".to_owned(),
            fix: "pass DebugCacheReuseTrace into DebugFrameAutopsyTrace::from_trace_with_cache"
                .to_owned(),
        };
    };
    let issue = cache
        .records
        .iter()
        .find(|record| record.status != DebugFrameTraceStatus::Ok)
        .map(|record| (record.cause.clone(), record.fix.clone()))
        .or_else(|| {
            cache
                .display_lists
                .iter()
                .find(|record| record.status != DebugFrameTraceStatus::Ok)
                .map(|record| (record.cause.clone(), record.fix.clone()))
        });
    DebugFrameAutopsyRecord {
        source,
        status: cache.status,
        summary: format!("cache reuse: {}", cache.summary),
        cause: issue
            .as_ref()
            .map(|(cause, _)| cause.clone())
            .unwrap_or_else(|| {
                "cache and display-list reuse did not report frame-level issues".to_owned()
            }),
        fix: issue
            .map(|(_, fix)| fix)
            .unwrap_or_else(|| "no cache action needed".to_owned()),
    }
}

fn debug_frame_autopsy_trace_status(records: &[DebugFrameAutopsyRecord]) -> DebugFrameTraceStatus {
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Error)
    {
        return DebugFrameTraceStatus::Error;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Info)
    {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

fn debug_frame_autopsy_summary(
    trace: &DebugFrameTrace,
    issues: &DebugIssueReport,
    status: DebugFrameTraceStatus,
    record_count: usize,
    warning_count: usize,
) -> String {
    let mut parts = vec![format!("{} frame autopsy", status.label())];
    parts.push(trace.label.clone());
    parts.push(format!("{record_count} sources"));
    if warning_count > 0 {
        parts.push(format!("{warning_count} need review"));
    }
    if issues.issue_count > 0 {
        parts.push(format!("{} issues", issues.issue_count));
    }
    parts.join("; ")
}

fn debug_frame_autopsy_source_rank(source: DebugFrameAutopsySource) -> u8 {
    match source {
        DebugFrameAutopsySource::Timing => 0,
        DebugFrameAutopsySource::DirtyState => 1,
        DebugFrameAutopsySource::LayoutCost => 2,
        DebugFrameAutopsySource::Paint => 3,
        DebugFrameAutopsySource::Resources => 4,
        DebugFrameAutopsySource::EventRoutes => 5,
        DebugFrameAutopsySource::Constraints => 6,
        DebugFrameAutopsySource::Overlaps => 7,
        DebugFrameAutopsySource::SelectedNode => 8,
        DebugFrameAutopsySource::CacheReuse => 9,
    }
}

fn debug_frame_autopsy_status_rank(status: DebugFrameTraceStatus) -> u8 {
    match status {
        DebugFrameTraceStatus::Error => 0,
        DebugFrameTraceStatus::Warning => 1,
        DebugFrameTraceStatus::Info => 2,
        DebugFrameTraceStatus::Ok => 3,
    }
}

fn debug_question_clickability_record(trace: &DebugFrameTrace) -> DebugQuestionGuideRecord {
    let hit_targets = DebugHitTargetTrace::from_snapshot(&trace.snapshot);
    let occlusion = DebugHitboxOcclusionTrace::from_snapshot(&trace.snapshot);
    let rejected_candidates = trace
        .routes
        .iter()
        .flat_map(|route| route.candidates.iter())
        .filter(|candidate| !candidate.rejections.is_empty())
        .count();
    let first_hit_issue = hit_targets.records.iter().find(|record| {
        matches!(
            record.status,
            DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
        )
    });
    let first_occlusion = occlusion.records.iter().find(|record| {
        matches!(
            record.status,
            DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
        )
    });
    let status = if occlusion.blocked_count > 0 || hit_targets.missing_hit_count > 0 {
        DebugFrameTraceStatus::Error
    } else if hit_targets.issue_count > 0 || occlusion.warning_count > 0 || rejected_candidates > 0
    {
        DebugFrameTraceStatus::Warning
    } else if hit_targets.interactive_count > 0 || !trace.routes.is_empty() {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    };
    let mut evidence = vec![hit_targets.summary, occlusion.summary];
    if !trace.routes.is_empty() {
        evidence.push(format!(
            "{} route{}; {rejected_candidates} rejected candidate{}",
            trace.routes.len(),
            debug_plural_s(trace.routes.len()),
            debug_plural_s(rejected_candidates)
        ));
    }
    DebugQuestionGuideRecord {
        kind: DebugQuestionGuideKind::Clickability,
        status,
        question: DebugQuestionGuideKind::Clickability.title().to_owned(),
        summary: match (first_occlusion, first_hit_issue) {
            (Some(record), _) => record.summary.clone(),
            (None, Some(record)) => record.summary.clone(),
            (None, None) => "clickability has no blocking hitbox issue".to_owned(),
        },
        evidence: evidence.join("; "),
        inspect: "hitbox_occlusion_panel, hit_target_panel, pointer_probe_panel".to_owned(),
        fix: first_occlusion
            .map(|record| record.fix.clone())
            .or_else(|| first_hit_issue.map(|record| record.fix.clone()))
            .unwrap_or_else(|| {
                "use pointer_probe_panel when a specific point misroutes".to_owned()
            }),
    }
}

fn debug_question_overlap_record(trace: &DebugFrameTrace) -> DebugQuestionGuideRecord {
    let report = DebugOverlapReport {
        nodes: trace.snapshot.hitboxes.clone(),
        overlaps: trace.snapshot.overlaps.clone(),
    };
    let interactive = report.interactive_overlap_count();
    let status = report.status();
    let issue = report.overlaps.first();
    DebugQuestionGuideRecord {
        kind: DebugQuestionGuideKind::Overlap,
        status,
        question: DebugQuestionGuideKind::Overlap.title().to_owned(),
        summary: if let Some(overlap) = issue {
            format!(
                "{} overlap between {} and {}",
                debug_overlap_kind_label(overlap.kind),
                overlap.back.name,
                overlap.front.name
            )
        } else {
            "no overlaps in this frame".to_owned()
        },
        evidence: report.summary(),
        inspect: "overlap_report_panel, overlap_autopsy_panel, hitbox_debug_overlay".to_owned(),
        fix: if interactive > 0 {
            "separate, reorder, disable input, or make decorative regions passive".to_owned()
        } else if issue.is_some() {
            "inspect paint order, effect outsets, clipping, and layout cause".to_owned()
        } else {
            "no overlap action needed".to_owned()
        },
    }
}

fn debug_question_performance_record(trace: &DebugFrameTrace) -> DebugQuestionGuideRecord {
    let budget = DebugFrameBudgetTrace::from_trace(trace);
    let layout_cost = DebugLayoutCostTrace::from_snapshot(&trace.snapshot);
    let top_layout = layout_cost.records.first();
    let dominant_stage = budget
        .stages
        .iter()
        .find(|stage| stage.over_budget)
        .or_else(|| budget.stages.iter().find(|stage| stage.dominant));
    let status = if budget.status == DebugFrameTraceStatus::Warning {
        DebugFrameTraceStatus::Warning
    } else if layout_cost.status == DebugFrameTraceStatus::Warning {
        DebugFrameTraceStatus::Warning
    } else if !budget.stages.is_empty() || layout_cost.record_count > 0 {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    };
    DebugQuestionGuideRecord {
        kind: DebugQuestionGuideKind::Performance,
        status,
        question: DebugQuestionGuideKind::Performance.title().to_owned(),
        summary: dominant_stage
            .map(|stage| {
                format!(
                    "{} stage {:.2}ms",
                    stage.label,
                    stage.duration.as_secs_f64() * 1000.0
                )
            })
            .or_else(|| top_layout.map(|record| record.summary.clone()))
            .unwrap_or_else(|| "no timing or layout pressure recorded".to_owned()),
        evidence: format!("{}; {}", budget.summary, layout_cost.summary),
        inspect: "frame_bottleneck_panel, slow_frame_panel, frame_budget_panel, frame_autopsy_panel, layout_cost_panel, slow_nodes_panel"
            .to_owned(),
        fix: dominant_stage
            .map(|stage| stage.action.clone())
            .or_else(|| top_layout.map(|record| record.fix.clone()))
            .unwrap_or_else(|| "capture frame timing and layout-cost diagnostics".to_owned()),
    }
}

fn debug_question_paint_hit_record(trace: &DebugFrameTrace) -> DebugQuestionGuideRecord {
    let mismatch = DebugPaintHitMismatchTrace::from_snapshot(&trace.snapshot);
    let first = mismatch.records.first();
    DebugQuestionGuideRecord {
        kind: DebugQuestionGuideKind::PaintHit,
        status: mismatch.status,
        question: DebugQuestionGuideKind::PaintHit.title().to_owned(),
        summary: first
            .map(|record| record.summary.clone())
            .unwrap_or_else(|| "paint and hit regions agree in this frame".to_owned()),
        evidence: mismatch.summary,
        inspect:
            "paint_hit_mismatch_panel, bounds_autopsy_panel, hitbox_map_panel, visual_effects_panel"
                .to_owned(),
        fix: first
            .map(|record| record.fix.clone())
            .unwrap_or_else(|| "no paint/hit action needed".to_owned()),
    }
}

fn debug_question_text_fit_record(trace: &DebugFrameTrace) -> DebugQuestionGuideRecord {
    let text_nodes = trace
        .snapshot
        .nodes
        .iter()
        .filter(|node| node.text.is_some())
        .count();
    let text_issues = trace
        .snapshot
        .constraints
        .iter()
        .filter(|issue| {
            matches!(
                issue.kind,
                DebugConstraintIssueKind::TextClipped
                    | DebugConstraintIssueKind::TextContrastTooLow
            )
        })
        .collect::<Vec<_>>();
    let clipped = text_issues
        .iter()
        .filter(|issue| issue.kind == DebugConstraintIssueKind::TextClipped)
        .count();
    let contrast = text_issues
        .iter()
        .filter(|issue| issue.kind == DebugConstraintIssueKind::TextContrastTooLow)
        .count();
    let status = if text_issues
        .iter()
        .any(|issue| issue.severity == DebugConstraintSeverity::Error)
    {
        DebugFrameTraceStatus::Error
    } else if !text_issues.is_empty() {
        DebugFrameTraceStatus::Warning
    } else if text_nodes > 0 {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    };
    let first = text_issues.first();
    let mut evidence = vec![format!(
        "{text_nodes} text node{}",
        debug_plural_s(text_nodes)
    )];
    if clipped > 0 {
        evidence.push(format!("{clipped} clipped"));
    }
    if contrast > 0 {
        evidence.push(format!("{contrast} contrast"));
    }
    DebugQuestionGuideRecord {
        kind: DebugQuestionGuideKind::TextFit,
        status,
        question: DebugQuestionGuideKind::TextFit.title().to_owned(),
        summary: first.map(|issue| issue.summary.clone()).unwrap_or_else(|| {
            if text_nodes > 0 {
                "text has no clipped or contrast warning in this frame".to_owned()
            } else {
                "no text nodes in this frame".to_owned()
            }
        }),
        evidence: evidence.join("; "),
        inspect:
            "text_fit_panel, text_layout_panel, text_contrast_panel, layout_pressure_panel, visibility_panel"
                .to_owned(),
        fix: first
            .map(|issue| issue.fix.clone())
            .unwrap_or_else(|| "no text-fit action needed".to_owned()),
    }
}

fn debug_question_clipping_record(trace: &DebugFrameTrace) -> DebugQuestionGuideRecord {
    let Some(selected) = trace.selected_node.as_ref() else {
        return DebugQuestionGuideRecord {
            kind: DebugQuestionGuideKind::Clipping,
            status: DebugFrameTraceStatus::Ok,
            question: DebugQuestionGuideKind::Clipping.title().to_owned(),
            summary: "no selected node to inspect for clipping".to_owned(),
            evidence: "DebugFrameTraceContext did not include selected_node".to_owned(),
            inspect: "clip_scroll_panel, bounds_autopsy_panel".to_owned(),
            fix: "select a node before asking clipping questions".to_owned(),
        };
    };
    let visible_rect = selected.geometry.visible_rect;
    let clipped = visible_rect
        .is_some_and(|visible| !debug_rect_contains_rect(visible, selected.layout.rect));
    let status = if !selected.layout.visible || visible_rect.is_none() {
        DebugFrameTraceStatus::Error
    } else if clipped {
        DebugFrameTraceStatus::Warning
    } else if selected.geometry.clip_chain_len > 0 {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    };
    DebugQuestionGuideRecord {
        kind: DebugQuestionGuideKind::Clipping,
        status,
        question: DebugQuestionGuideKind::Clipping.title().to_owned(),
        summary: if clipped {
            format!("{} is clipped by its visible rect", selected.name)
        } else if selected.geometry.clip_chain_len > 0 {
            format!(
                "{} has {} clip ancestor{}",
                selected.name,
                selected.geometry.clip_chain_len,
                debug_plural_s(selected.geometry.clip_chain_len)
            )
        } else {
            format!("{} is not clipped", selected.name)
        },
        evidence: format!(
            "visible={}; clip chain {}; geometry: {}",
            selected.layout.visible, selected.geometry.clip_chain_len, selected.geometry.cause
        ),
        inspect: "clip_scroll_panel, bounds_autopsy_panel, visual_effects_panel".to_owned(),
        fix: if clipped || visible_rect.is_none() {
            selected.geometry.fix.clone()
        } else {
            "no clipping action needed".to_owned()
        },
    }
}

fn debug_question_resources_record(trace: &DebugFrameTrace) -> DebugQuestionGuideRecord {
    let issue = trace.resources.records.iter().find(|record| {
        matches!(
            record.status,
            DebugResourceStatus::Missing
                | DebugResourceStatus::Invalid
                | DebugResourceStatus::UnusedUpdate
                | DebugResourceStatus::Unresolved
        )
    });
    let status = if trace.resources.invalid_count() > 0 {
        DebugFrameTraceStatus::Error
    } else if trace.resources.missing_count() > 0
        || trace.resources.unused_update_count() > 0
        || trace
            .resources
            .count_by_status(DebugResourceStatus::Unresolved)
            > 0
    {
        DebugFrameTraceStatus::Warning
    } else if !trace.resources.records.is_empty() {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    };
    DebugQuestionGuideRecord {
        kind: DebugQuestionGuideKind::Resources,
        status,
        question: DebugQuestionGuideKind::Resources.title().to_owned(),
        summary: issue
            .map(|record| record.summary.clone())
            .unwrap_or_else(|| trace.resources.summary()),
        evidence: trace.resources.summary(),
        inspect: "resource_diagnostics_panel, node_explanation_panel".to_owned(),
        fix: issue
            .map(|record| record.fix.clone())
            .unwrap_or_else(|| "no resource action needed".to_owned()),
    }
}

fn debug_question_selected_node_record(trace: &DebugFrameTrace) -> DebugQuestionGuideRecord {
    let Some(selected) = trace.selected_node.as_ref() else {
        return DebugQuestionGuideRecord {
            kind: DebugQuestionGuideKind::SelectedNode,
            status: DebugFrameTraceStatus::Ok,
            question: DebugQuestionGuideKind::SelectedNode.title().to_owned(),
            summary: "no selected node captured".to_owned(),
            evidence: "DebugFrameTraceContext did not include selected_node".to_owned(),
            inspect: "node_explanation_panel, node_provenance_panel".to_owned(),
            fix: "attach selected_node to DebugFrameTraceContext".to_owned(),
        };
    };
    let status = DebugFrameTraceStatus::from(selected.status);
    DebugQuestionGuideRecord {
        kind: DebugQuestionGuideKind::SelectedNode,
        status,
        question: DebugQuestionGuideKind::SelectedNode.title().to_owned(),
        summary: selected.summary.clone(),
        evidence: format!(
            "{} constraints; {} resources; {} overlaps; route {}",
            selected.constraints.len(),
            selected.resources.len(),
            selected.overlaps.len(),
            selected
                .route
                .as_ref()
                .map(|route| route.summary.as_str())
                .unwrap_or("not captured")
        ),
        inspect: "node_explanation_panel, node_provenance_panel, layout_cause_panel".to_owned(),
        fix: selected
            .constraints
            .first()
            .map(|issue| issue.fix.clone())
            .or_else(|| {
                selected
                    .resources
                    .first()
                    .map(|resource| resource.fix.clone())
            })
            .or_else(|| selected.overlaps.first().map(|overlap| overlap.fix.clone()))
            .unwrap_or_else(|| selected.input.fix.clone()),
    }
}

