fn debug_unique_strings<'a>(values: impl Iterator<Item = &'a str>) -> Vec<String> {
    let mut out = Vec::new();
    for value in values {
        if !out.iter().any(|existing| existing == value) {
            out.push(value.to_owned());
        }
    }
    out
}

fn debug_unique_sources(values: impl Iterator<Item = DebugWhySource>) -> Vec<DebugWhySource> {
    let mut out = Vec::new();
    for value in values {
        if !out.contains(&value) {
            out.push(value);
        }
    }
    out
}

fn debug_why_timeline_record(index: usize, trace: &DebugFrameTrace) -> DebugWhyTimelineRecord {
    let why = DebugWhyTrace::from_frame_trace(trace);
    let top_step = why.first_step();
    let overlay_plan = why.overlay_plan();
    let primary_overlay_record = overlay_plan.primary();
    let label = debug_frame_timeline_label(trace, index);
    let primary_overlay = top_step
        .as_ref()
        .and_then(DebugWhyTrailStep::primary_overlay)
        .or_else(|| primary_overlay_record.map(|record| record.layer));
    let primary_surface = primary_overlay_record.map(|record| record.surface.clone());
    let overlay_layers = why.overlay_layers();
    let warning_count = why.warning_count;
    let status = why.status.max(trace.summary.status);
    let top_title = top_step.as_ref().map(|step| step.title.clone());
    let top_panel = top_step.as_ref().map(|step| step.panel.clone());
    let top_action = top_step.as_ref().map(|step| step.action.clone());
    let top_subject = top_step.as_ref().map(|step| step.subject.clone());
    let summary = debug_why_timeline_record_summary(
        &label,
        status,
        top_title.as_deref(),
        top_panel.as_deref(),
        primary_overlay,
        warning_count,
    );
    let cause = debug_why_timeline_record_cause(
        why.record_count,
        warning_count,
        top_panel.as_deref(),
        primary_overlay,
    );
    let fix = debug_why_timeline_record_fix(top_panel.as_deref(), primary_surface.as_deref());
    DebugWhyTimelineRecord {
        index,
        label,
        frame_index: trace.frame_index,
        status,
        why_status: why.status,
        why_record_count: why.record_count,
        warning_count,
        top_title,
        top_panel,
        top_action,
        top_subject,
        primary_overlay,
        overlay_layers,
        primary_surface,
        summary,
        cause,
        fix,
    }
}

