fn debug_diagnostics_coverage_record(
    area: DebugDiagnosticsCoverageArea,
    status: DebugFrameTraceStatus,
    captured: bool,
    required: bool,
    evidence_count: usize,
    panels: &[&str],
    summary: String,
    cause: String,
    fix: String,
) -> DebugDiagnosticsCoverageRecord {
    DebugDiagnosticsCoverageRecord {
        area,
        status,
        captured,
        required,
        evidence_count,
        panels: panels.iter().map(|panel| (*panel).to_owned()).collect(),
        summary,
        cause,
        fix,
    }
}

fn debug_diagnostics_coverage_summary(
    status: DebugFrameTraceStatus,
    frame_label: &str,
    record_count: usize,
    captured_count: usize,
    missing_count: usize,
    warning_count: usize,
    first_missing: Option<DebugDiagnosticsCoverageArea>,
) -> String {
    let mut parts = vec![format!(
        "{} diagnostics coverage for {frame_label}",
        status.label()
    )];
    parts.push(format!("{captured_count}/{record_count} areas captured"));
    if missing_count > 0 {
        parts.push(format!("{missing_count} missing"));
    }
    if warning_count > 0 {
        parts.push(format!("{warning_count} need instrumentation"));
    }
    if let Some(first_missing) = first_missing {
        parts.push(format!("first missing {}", first_missing.label()));
    }
    parts.join("; ")
}

fn debug_investigation_plan_push_coverage(
    records: &mut Vec<DebugInvestigationStepRecord>,
    record: &DebugDiagnosticsCoverageRecord,
) {
    let panel = record.panels.first().cloned();
    debug_investigation_plan_push(
        records,
        DebugInvestigationStepKind::CaptureEvidence,
        record.status,
        format!("coverage.{}", record.area.label()),
        panel,
        None,
        Some(record.area.title().to_owned()),
        format!("capture {}", record.area.title()),
        record.cause.clone(),
        record.fix.clone(),
    );
}

fn debug_investigation_plan_push_overlay(
    records: &mut Vec<DebugInvestigationStepRecord>,
    record: &DebugOverlayRecommendationRecord,
) {
    debug_investigation_plan_push(
        records,
        DebugInvestigationStepKind::EnableOverlay,
        record.status,
        format!("overlay.{}", record.layer.label()),
        Some(record.surface.clone()),
        Some(record.layer),
        record.subjects.first().cloned(),
        format!("show {} overlay", record.layer.label()),
        record.cause.clone(),
        record.fix.clone(),
    );
}

fn debug_investigation_plan_push_panel(
    records: &mut Vec<DebugInvestigationStepRecord>,
    record: &DebugPanelRecommendationRecord,
) {
    debug_investigation_plan_push(
        records,
        DebugInvestigationStepKind::OpenPanel,
        record.status,
        record.action.clone(),
        Some(record.panel.clone()),
        record.overlays.first().copied(),
        record.subjects.first().cloned(),
        format!("open {}", record.panel),
        record.cause.clone(),
        record.fix.clone(),
    );
}

fn debug_investigation_plan_push_why(
    records: &mut Vec<DebugInvestigationStepRecord>,
    step: &DebugWhyTrailStep,
) {
    debug_investigation_plan_push(
        records,
        DebugInvestigationStepKind::InspectSubject,
        step.status,
        step.action.clone(),
        Some(step.panel.clone()),
        step.primary_overlay(),
        Some(step.subject.clone()),
        step.summary.clone(),
        step.evidence.clone(),
        step.fix.clone(),
    );
}

fn debug_investigation_plan_push_verify(
    records: &mut Vec<DebugInvestigationStepRecord>,
    trace: &DebugFrameTrace,
    panels: &DebugPanelRecommendationTrace,
    overlays: &DebugOverlayRecommendationTrace,
) {
    let panel = panels.top_panel.clone();
    let overlay = overlays.primary_overlay;
    let mut summary = format!("rerun diagnostics for {}", trace.label);
    if let Some(panel) = &panel {
        summary.push_str(&format!(" after inspecting {panel}"));
    }
    if let Some(overlay) = overlay {
        summary.push_str(&format!(" with {} visible", overlay.label()));
    }
    debug_investigation_plan_push(
        records,
        DebugInvestigationStepKind::VerifyFix,
        DebugFrameTraceStatus::Info,
        "verify.rerun-frame-trace".to_owned(),
        panel,
        overlay,
        trace.selected_node.as_ref().map(|node| node.name.clone()),
        summary,
        "the investigation plan should end by checking whether the frame summary, issue report, and overlay recommendation changed"
            .to_owned(),
        "capture a new DebugFrameTrace and compare frame_regression_panel, issue_timeline_panel, and overlay_recommendation_panel"
            .to_owned(),
    );
}

#[allow(clippy::too_many_arguments)]
fn debug_investigation_plan_push(
    records: &mut Vec<DebugInvestigationStepRecord>,
    kind: DebugInvestigationStepKind,
    status: DebugFrameTraceStatus,
    action: String,
    panel: Option<String>,
    overlay: Option<DebugWhyOverlayLayer>,
    subject: Option<String>,
    summary: String,
    cause: String,
    fix: String,
) {
    if records
        .iter()
        .any(|record| record.kind == kind && record.action == action)
    {
        return;
    }
    let index = records.len();
    records.push(DebugInvestigationStepRecord {
        index,
        kind,
        status,
        action,
        panel,
        overlay,
        subject,
        summary,
        cause,
        fix,
    });
}

fn finish_debug_investigation_plan(
    trace: &DebugFrameTrace,
    coverage: &DebugDiagnosticsCoverageTrace,
    panels: &DebugPanelRecommendationTrace,
    overlays: &DebugOverlayRecommendationTrace,
    mut records: Vec<DebugInvestigationStepRecord>,
) -> DebugInvestigationPlanTrace {
    for (index, record) in records.iter_mut().enumerate() {
        record.index = index;
    }
    let step_count = records.len();
    let warning_count = records
        .iter()
        .filter(|record| debug_contract_status_fails(record.status))
        .count();
    let coverage_gap_count = coverage.missing_count;
    let panel_count = panels.recommendation_count;
    let overlay_count = overlays.recommendation_count;
    let status = records
        .iter()
        .map(|record| record.status)
        .max()
        .unwrap_or(DebugFrameTraceStatus::Ok);
    let summary = debug_investigation_plan_summary(
        status,
        &trace.label,
        step_count,
        warning_count,
        coverage_gap_count,
        panels.top_panel.as_deref(),
        overlays.primary_overlay,
    );
    DebugInvestigationPlanTrace {
        frame_label: trace.label.clone(),
        frame_index: trace.frame_index,
        status,
        step_count,
        warning_count,
        coverage_gap_count,
        panel_count,
        overlay_count,
        records,
        summary,
    }
}

fn debug_investigation_plan_summary(
    status: DebugFrameTraceStatus,
    frame_label: &str,
    step_count: usize,
    warning_count: usize,
    coverage_gap_count: usize,
    top_panel: Option<&str>,
    primary_overlay: Option<DebugWhyOverlayLayer>,
) -> String {
    let mut parts = vec![format!(
        "{} investigation plan for {frame_label}",
        status.label()
    )];
    parts.push(format!("{step_count} steps"));
    if warning_count > 0 {
        parts.push(format!("{warning_count} need review"));
    }
    if coverage_gap_count > 0 {
        parts.push(format!("{coverage_gap_count} coverage gaps"));
    }
    if let Some(primary_overlay) = primary_overlay {
        parts.push(format!("show {}", primary_overlay.label()));
    }
    if let Some(top_panel) = top_panel {
        parts.push(format!("open {top_panel}"));
    }
    parts.join("; ")
}

#[allow(clippy::too_many_arguments)]
fn debug_node_recommendation_push(
    records: &mut Vec<DebugNodeRecommendationRecord>,
    source: DebugNodeRecommendationSource,
    node: Option<UiNodeId>,
    name: String,
    status: DebugFrameTraceStatus,
    score: u32,
    panels: Vec<String>,
    overlays: Vec<DebugWhyOverlayLayer>,
    summary: String,
    cause: String,
    fix: String,
) {
    if let Some(existing) = records.iter_mut().find(|record| record.name == name) {
        let previous_score = existing.score;
        existing.score = existing.score.saturating_add(score);
        existing.occurrence_count += 1;
        existing.status = existing.status.max(status);
        existing.node = existing.node.or(node);
        if !existing.sources.contains(&source) {
            existing.sources.push(source);
            existing.sources.sort();
        }
        for panel in panels {
            let panel = debug_why_primary_panel(&panel);
            if !existing.panels.contains(&panel) {
                existing.panels.push(panel);
            }
        }
        for overlay in overlays {
            if !existing.overlays.contains(&overlay) {
                existing.overlays.push(overlay);
            }
        }
        if debug_frame_timeline_status_rank(status)
            <= debug_frame_timeline_status_rank(existing.status)
            && score >= previous_score / existing.occurrence_count.max(1) as u32
        {
            existing.summary = summary;
            existing.cause = cause;
            existing.fix = fix;
        }
        existing.action = debug_node_recommendation_action(&existing.name, existing.panels.first());
        return;
    }

    let panels = panels
        .into_iter()
        .map(|panel| debug_why_primary_panel(&panel))
        .collect::<Vec<_>>();
    let action = debug_node_recommendation_action(&name, panels.first());
    records.push(DebugNodeRecommendationRecord {
        node,
        name,
        status,
        score,
        occurrence_count: 1,
        sources: vec![source],
        panels,
        overlays,
        action,
        summary,
        cause,
        fix,
    });
}

fn finish_debug_node_recommendations(
    trace: &DebugFrameTrace,
    mut records: Vec<DebugNodeRecommendationRecord>,
) -> DebugNodeRecommendationTrace {
    records.sort_by(|left, right| {
        debug_frame_timeline_status_rank(left.status)
            .cmp(&debug_frame_timeline_status_rank(right.status))
            .then_with(|| right.score.cmp(&left.score))
            .then_with(|| right.occurrence_count.cmp(&left.occurrence_count))
            .then_with(|| left.name.cmp(&right.name))
    });
    let recommendation_count = records.len();
    let warning_count = records
        .iter()
        .filter(|record| debug_contract_status_fails(record.status))
        .count();
    let status = records
        .iter()
        .map(|record| record.status)
        .max()
        .unwrap_or(DebugFrameTraceStatus::Ok);
    let top_node = records.first().map(|record| record.name.clone());
    let summary = debug_node_recommendation_summary(
        status,
        &trace.label,
        recommendation_count,
        warning_count,
        top_node.as_deref(),
    );
    DebugNodeRecommendationTrace {
        frame_label: trace.label.clone(),
        frame_index: trace.frame_index,
        status,
        recommendation_count,
        warning_count,
        top_node,
        records,
        summary,
    }
}

fn debug_node_recommendation_score(status: DebugFrameTraceStatus, score: u32) -> u32 {
    debug_panel_recommendation_score(status, score).saturating_add(score.min(500))
}

fn debug_node_recommendation_action(name: &str, panel: Option<&String>) -> String {
    let panel = panel.map(String::as_str).unwrap_or("inspect_node_panel");
    format!(
        "node.{}.{}",
        debug_action_id_part(name),
        debug_action_id_part(panel)
    )
}

fn debug_node_recommendation_issue_overlays(issue: &DebugIssueRecord) -> Vec<DebugWhyOverlayLayer> {
    let panel = debug_issue_source_inspect(issue.source);
    let mut overlays = debug_panel_recommendation_overlays(
        panel,
        issue.source.title(),
        &issue.summary,
        &issue.cause,
        &issue.fix,
    );
    debug_overlay_recommendation_extend_unique(
        &mut overlays,
        debug_overlay_recommendation_issue_layers(issue.source),
    );
    overlays
}

fn debug_node_recommendation_hotspot_overlays(
    hotspot: &DebugNodeHotspotRecord,
) -> Vec<DebugWhyOverlayLayer> {
    let mut overlays = Vec::new();
    if hotspot.interactive_overlap_count > 0 || hotspot.overlap_count > 0 {
        overlays.push(DebugWhyOverlayLayer::Overlaps);
        overlays.push(DebugWhyOverlayLayer::Hitboxes);
    }
    if hotspot.constraint_count > 0 || hotspot.clipped {
        overlays.push(DebugWhyOverlayLayer::LayoutBounds);
        overlays.push(DebugWhyOverlayLayer::ClipBounds);
    }
    if hotspot.paint_count > 0 || hotspot.effect_count > 0 {
        overlays.push(DebugWhyOverlayLayer::PaintBounds);
    }
    if hotspot.score > 0 {
        overlays.push(DebugWhyOverlayLayer::Performance);
    }
    if overlays.is_empty() {
        overlays.push(DebugWhyOverlayLayer::LayoutBounds);
    }
    overlays
}

fn debug_node_recommendation_summary(
    status: DebugFrameTraceStatus,
    frame_label: &str,
    recommendation_count: usize,
    warning_count: usize,
    top_node: Option<&str>,
) -> String {
    let mut parts = vec![format!(
        "{} node recommendations for {frame_label}",
        status.label()
    )];
    parts.push(format!(
        "{recommendation_count} node{}",
        debug_plural_s(recommendation_count)
    ));
    if warning_count > 0 {
        parts.push(format!("{warning_count} need review"));
    }
    if let Some(top_node) = top_node {
        parts.push(format!("inspect {top_node} first"));
    }
    parts.join("; ")
}

#[allow(clippy::too_many_arguments)]
fn debug_finding_inbox_push(
    records: &mut Vec<DebugFindingRecord>,
    source: DebugFindingSource,
    key: String,
    title: String,
    status: DebugFrameTraceStatus,
    score: u32,
    node: Option<UiNodeId>,
    node_name: Option<String>,
    panel: Option<String>,
    overlay: Option<DebugWhyOverlayLayer>,
    action: String,
    summary: String,
    cause: String,
    fix: String,
) {
    if let Some(existing) = records.iter_mut().find(|record| record.key == key) {
        let previous_score = existing.score;
        existing.score = existing.score.saturating_add(score);
        existing.occurrence_count += 1;
        existing.status = existing.status.max(status);
        existing.node = existing.node.or(node);
        existing.node_name = existing.node_name.clone().or(node_name);
        existing.panel = existing.panel.clone().or_else(|| panel.clone());
        existing.overlay = existing.overlay.or(overlay);
        if !existing.sources.contains(&source) {
            existing.sources.push(source);
            existing.sources.sort();
        }
        if debug_frame_timeline_status_rank(status)
            <= debug_frame_timeline_status_rank(existing.status)
            && score >= previous_score / existing.occurrence_count.max(1) as u32
        {
            existing.title = title;
            existing.panel = panel.or_else(|| existing.panel.clone());
            existing.overlay = overlay.or(existing.overlay);
            existing.action = action;
            existing.summary = summary;
            existing.cause = cause;
            existing.fix = fix;
        }
        return;
    }

    records.push(DebugFindingRecord {
        key,
        title,
        status,
        score,
        occurrence_count: 1,
        sources: vec![source],
        node,
        node_name,
        panel: panel.map(|panel| debug_why_primary_panel(&panel)),
        overlay,
        action,
        summary,
        cause,
        fix,
    });
}

fn finish_debug_finding_inbox(
    trace: &DebugFrameTrace,
    coverage_gap_count: usize,
    mut records: Vec<DebugFindingRecord>,
) -> DebugFindingInboxTrace {
    if records.is_empty() {
        records.push(DebugFindingRecord {
            key: "frame.ok".to_owned(),
            title: "No findings".to_owned(),
            status: DebugFrameTraceStatus::Ok,
            score: debug_finding_inbox_score(DebugFrameTraceStatus::Ok, 0),
            occurrence_count: 1,
            sources: vec![DebugFindingSource::PanelRecommendation],
            node: None,
            node_name: None,
            panel: Some("frame_trace_panel".to_owned()),
            overlay: None,
            action: "panel.frame_trace_panel".to_owned(),
            summary: "no actionable findings were produced for this frame".to_owned(),
            cause:
                "issues, coverage gaps, recommendations, and node triage did not produce warnings"
                    .to_owned(),
            fix: "keep the frame trace available for baseline comparison".to_owned(),
        });
    }
    records.sort_by(|left, right| {
        debug_frame_timeline_status_rank(left.status)
            .cmp(&debug_frame_timeline_status_rank(right.status))
            .then_with(|| right.score.cmp(&left.score))
            .then_with(|| right.occurrence_count.cmp(&left.occurrence_count))
            .then_with(|| left.key.cmp(&right.key))
    });
    let finding_count = records.len();
    let warning_count = records
        .iter()
        .filter(|record| debug_contract_status_fails(record.status))
        .count();
    let status = records
        .iter()
        .map(|record| record.status)
        .max()
        .unwrap_or(DebugFrameTraceStatus::Ok);
    let top_action = records.first().map(|record| record.action.clone());
    let top_panel = records.first().and_then(|record| record.panel.clone());
    let top_node = records.first().and_then(|record| record.node_name.clone());
    let summary = debug_finding_inbox_summary(
        status,
        &trace.label,
        finding_count,
        warning_count,
        coverage_gap_count,
        top_action.as_deref(),
        top_panel.as_deref(),
        top_node.as_deref(),
    );
    DebugFindingInboxTrace {
        frame_label: trace.label.clone(),
        frame_index: trace.frame_index,
        status,
        finding_count,
        warning_count,
        coverage_gap_count,
        top_action,
        top_panel,
        top_node,
        records,
        summary,
    }
}

fn debug_finding_inbox_score(status: DebugFrameTraceStatus, score: u32) -> u32 {
    debug_panel_recommendation_score(status, score).saturating_add(score.min(500))
}

#[allow(clippy::too_many_arguments)]
fn debug_finding_inbox_summary(
    status: DebugFrameTraceStatus,
    frame_label: &str,
    finding_count: usize,
    warning_count: usize,
    coverage_gap_count: usize,
    top_action: Option<&str>,
    top_panel: Option<&str>,
    top_node: Option<&str>,
) -> String {
    let mut parts = vec![format!(
        "{} finding inbox for {frame_label}",
        status.label()
    )];
    parts.push(format!(
        "{finding_count} finding{}",
        debug_plural_s(finding_count)
    ));
    if warning_count > 0 {
        parts.push(format!("{warning_count} need review"));
    }
    if coverage_gap_count > 0 {
        parts.push(format!("{coverage_gap_count} coverage gaps"));
    }
    if let Some(top_action) = top_action {
        parts.push(format!("first action {top_action}"));
    } else if let Some(top_panel) = top_panel {
        parts.push(format!("open {top_panel} first"));
    }
    if let Some(top_node) = top_node {
        parts.push(format!("node {top_node}"));
    }
    parts.join("; ")
}

fn debug_health_score_record(
    area: DebugHealthArea,
    contract: &DebugContractReport,
    coverage: &DebugDiagnosticsCoverageTrace,
    issues: &DebugIssueReport,
) -> DebugHealthScoreRecord {
    let contract_kinds = debug_health_area_contracts(area);
    let coverage_areas = debug_health_area_coverage(area);
    let issue_sources = debug_health_area_issue_sources(area);
    let mut status = DebugFrameTraceStatus::Ok;
    let mut issue_count = 0usize;
    let mut missing_evidence_count = 0usize;
    let mut panels = Vec::<String>::new();
    let mut overlays = Vec::<DebugWhyOverlayLayer>::new();
    let mut causes = Vec::<String>::new();
    let mut fixes = Vec::<String>::new();

    for &kind in contract_kinds {
        if let Some(check) = contract.check(kind) {
            status = status.max(check.status);
            if !check.checked || !check.passed {
                issue_count = issue_count.saturating_add(check.issue_count.max(1));
                causes.push(check.cause.clone());
                fixes.push(check.fix.clone());
            }
            debug_health_push_panel(&mut panels, debug_panel_recommendation_contract_panel(kind));
            debug_health_push_overlays(
                &mut overlays,
                debug_overlay_recommendation_contract_layers(kind),
            );
        }
    }

    for &area in coverage_areas {
        if let Some(record) = coverage.record(area) {
            status = status.max(record.status);
            if !record.captured {
                missing_evidence_count += 1;
                causes.push(record.cause.clone());
                fixes.push(record.fix.clone());
            }
            for panel in &record.panels {
                debug_health_push_panel(&mut panels, panel);
            }
        }
    }

    for issue in issues
        .issues
        .iter()
        .filter(|issue| issue_sources.contains(&issue.source))
    {
        status = status.max(issue.status);
        issue_count += 1;
        causes.push(issue.cause.clone());
        fixes.push(issue.fix.clone());
        debug_health_push_panel(&mut panels, debug_issue_source_inspect(issue.source));
        debug_health_push_overlays(
            &mut overlays,
            debug_overlay_recommendation_issue_layers(issue.source),
        );
    }

    if area == DebugHealthArea::Instrumentation && missing_evidence_count > 0 {
        status = status.max(DebugFrameTraceStatus::Info);
    }

    let score = debug_health_score_value(status, issue_count, missing_evidence_count);
    let action_panel = panels
        .first()
        .cloned()
        .unwrap_or_else(|| debug_health_area_default_panel(area).to_owned());
    let action = format!(
        "health.{}.{}",
        area.label(),
        debug_action_id_part(&action_panel)
    );
    let summary =
        debug_health_score_record_summary(area, status, score, issue_count, missing_evidence_count);
    let cause = debug_health_first_nonempty(causes).unwrap_or_else(|| {
        format!(
            "{} diagnostics are within captured expectations",
            area.title()
        )
    });
    let fix = debug_health_first_nonempty(fixes)
        .unwrap_or_else(|| format!("keep {} diagnostics in the frame capture", area.title()));

    DebugHealthScoreRecord {
        area,
        status,
        score,
        issue_count,
        missing_evidence_count,
        panels,
        overlays,
        action,
        summary,
        cause,
        fix,
    }
}

fn finish_debug_health_score(
    trace: &DebugFrameTrace,
    records: Vec<DebugHealthScoreRecord>,
) -> DebugHealthScoreTrace {
    let area_count = records.len();
    let healthy_count = records
        .iter()
        .filter(|record| record.status == DebugFrameTraceStatus::Ok)
        .count();
    let review_count = records
        .iter()
        .filter(|record| debug_contract_status_fails(record.status))
        .count();
    let missing_evidence_count = records
        .iter()
        .map(|record| record.missing_evidence_count)
        .sum();
    let average_score = if records.is_empty() {
        100
    } else {
        (records
            .iter()
            .map(|record| record.score as usize)
            .sum::<usize>()
            / records.len()) as u8
    };
    let status = records
        .iter()
        .map(|record| record.status)
        .max()
        .unwrap_or(DebugFrameTraceStatus::Ok);
    let top_area = records.first().map(|record| record.area);
    let top_action = records.first().map(|record| record.action.clone());
    let summary = debug_health_score_summary(
        status,
        &trace.label,
        average_score,
        healthy_count,
        review_count,
        missing_evidence_count,
        top_area,
    );
    DebugHealthScoreTrace {
        frame_label: trace.label.clone(),
        frame_index: trace.frame_index,
        status,
        area_count,
        healthy_count,
        review_count,
        missing_evidence_count,
        average_score,
        top_area,
        top_action,
        records,
        summary,
    }
}

fn debug_health_area_contracts(area: DebugHealthArea) -> &'static [DebugContractCheckKind] {
    match area {
        DebugHealthArea::Performance => &[
            DebugContractCheckKind::FrameBudget,
            DebugContractCheckKind::CacheReuse,
        ],
        DebugHealthArea::Layout => &[
            DebugContractCheckKind::Constraints,
            DebugContractCheckKind::Overlaps,
            DebugContractCheckKind::SelectedNode,
        ],
        DebugHealthArea::Input => &[
            DebugContractCheckKind::HitTargets,
            DebugContractCheckKind::EventRoutes,
        ],
        DebugHealthArea::Paint => &[DebugContractCheckKind::HitTargets],
        DebugHealthArea::Text => &[DebugContractCheckKind::TextFit],
        DebugHealthArea::Resources => &[DebugContractCheckKind::Resources],
        DebugHealthArea::Accessibility => &[DebugContractCheckKind::Accessibility],
        DebugHealthArea::Instrumentation => &[],
    }
}

fn debug_health_area_coverage(area: DebugHealthArea) -> &'static [DebugDiagnosticsCoverageArea] {
    match area {
        DebugHealthArea::Performance => &[
            DebugDiagnosticsCoverageArea::TimingSections,
            DebugDiagnosticsCoverageArea::TimingBudget,
            DebugDiagnosticsCoverageArea::DirtyState,
            DebugDiagnosticsCoverageArea::CacheReuse,
        ],
        DebugHealthArea::Layout => &[
            DebugDiagnosticsCoverageArea::FrameSnapshot,
            DebugDiagnosticsCoverageArea::SelectedNode,
        ],
        DebugHealthArea::Input => &[
            DebugDiagnosticsCoverageArea::EventRoutes,
            DebugDiagnosticsCoverageArea::ActionMap,
        ],
        DebugHealthArea::Paint => &[DebugDiagnosticsCoverageArea::FrameSnapshot],
        DebugHealthArea::Text => &[DebugDiagnosticsCoverageArea::TextFit],
        DebugHealthArea::Resources => &[DebugDiagnosticsCoverageArea::Resources],
        DebugHealthArea::Accessibility => &[DebugDiagnosticsCoverageArea::FrameSnapshot],
        DebugHealthArea::Instrumentation => &[
            DebugDiagnosticsCoverageArea::TimingSections,
            DebugDiagnosticsCoverageArea::TimingBudget,
            DebugDiagnosticsCoverageArea::DirtyState,
            DebugDiagnosticsCoverageArea::EventRoutes,
            DebugDiagnosticsCoverageArea::Resources,
            DebugDiagnosticsCoverageArea::SelectedNode,
            DebugDiagnosticsCoverageArea::TextFit,
            DebugDiagnosticsCoverageArea::ActionMap,
            DebugDiagnosticsCoverageArea::CacheReuse,
        ],
    }
}

fn debug_health_area_issue_sources(area: DebugHealthArea) -> &'static [DebugIssueSource] {
    match area {
        DebugHealthArea::Performance => &[DebugIssueSource::Performance],
        DebugHealthArea::Layout => &[
            DebugIssueSource::Constraint,
            DebugIssueSource::Overlap,
            DebugIssueSource::SelectedNode,
        ],
        DebugHealthArea::Input => &[DebugIssueSource::EventRoute],
        DebugHealthArea::Paint => &[DebugIssueSource::PaintHit],
        DebugHealthArea::Text => &[DebugIssueSource::TextFit],
        DebugHealthArea::Resources => &[DebugIssueSource::Resource],
        DebugHealthArea::Accessibility => &[],
        DebugHealthArea::Instrumentation => &[],
    }
}

fn debug_health_area_default_panel(area: DebugHealthArea) -> &'static str {
    match area {
        DebugHealthArea::Performance => "frame_budget_panel",
        DebugHealthArea::Layout => "layout_pressure_panel",
        DebugHealthArea::Input => "hit_target_panel",
        DebugHealthArea::Paint => "paint_hit_mismatch_panel",
        DebugHealthArea::Text => "text_fit_panel",
        DebugHealthArea::Resources => "resource_diagnostics_panel",
        DebugHealthArea::Accessibility => "accessibility_tree_panel",
        DebugHealthArea::Instrumentation => "diagnostics_coverage_panel",
    }
}

fn debug_health_score_value(
    status: DebugFrameTraceStatus,
    issue_count: usize,
    missing_evidence_count: usize,
) -> u8 {
    let base = match status {
        DebugFrameTraceStatus::Ok => 100usize,
        DebugFrameTraceStatus::Info => 84,
        DebugFrameTraceStatus::Warning => 62,
        DebugFrameTraceStatus::Error => 35,
    };
    base.saturating_sub(issue_count.saturating_mul(7))
        .saturating_sub(missing_evidence_count.saturating_mul(5))
        .max(1) as u8
}

fn debug_health_score_record_summary(
    area: DebugHealthArea,
    status: DebugFrameTraceStatus,
    score: u8,
    issue_count: usize,
    missing_evidence_count: usize,
) -> String {
    let mut parts = vec![format!(
        "{} {} health score {score}",
        status.label(),
        area.title()
    )];
    if issue_count > 0 {
        parts.push(format!(
            "{issue_count} issue{}",
            debug_plural_s(issue_count)
        ));
    }
    if missing_evidence_count > 0 {
        parts.push(format!("{missing_evidence_count} missing evidence"));
    }
    parts.join("; ")
}

fn debug_health_score_summary(
    status: DebugFrameTraceStatus,
    frame_label: &str,
    average_score: u8,
    healthy_count: usize,
    review_count: usize,
    missing_evidence_count: usize,
    top_area: Option<DebugHealthArea>,
) -> String {
    let mut parts = vec![format!(
        "{} health score for {frame_label}: {average_score}",
        status.label()
    )];
    parts.push(format!("{healthy_count} healthy"));
    if review_count > 0 {
        parts.push(format!("{review_count} need review"));
    }
    if missing_evidence_count > 0 {
        parts.push(format!("{missing_evidence_count} missing evidence"));
    }
    if let Some(top_area) = top_area {
        parts.push(format!("start with {}", top_area.label()));
    }
    parts.join("; ")
}

fn debug_health_area_rank(area: DebugHealthArea) -> u8 {
    match area {
        DebugHealthArea::Performance => 0,
        DebugHealthArea::Layout => 1,
        DebugHealthArea::Input => 2,
        DebugHealthArea::Paint => 3,
        DebugHealthArea::Text => 4,
        DebugHealthArea::Resources => 5,
        DebugHealthArea::Accessibility => 6,
        DebugHealthArea::Instrumentation => 7,
    }
}

