fn debug_hitbox_timeline_record_cause(
    hitboxes: &DebugHitboxMapTrace,
    occlusion: &DebugHitboxOcclusionTrace,
    added_hitbox_count: usize,
    removed_hitbox_count: usize,
    changed_hitbox_count: usize,
    previous_change: Option<&DebugFrameTimelineChangeSummary>,
) -> String {
    let mut parts = vec![format!(
        "{} hitbox nodes; {} interactive; {} effective hits",
        hitboxes.node_count, hitboxes.interactive_count, hitboxes.effective_hit_count
    )];
    if hitboxes.missing_hit_count > 0 {
        parts.push(format!(
            "{} missing effective hit",
            hitboxes.missing_hit_count
        ));
    }
    if hitboxes.clipped_count > 0 {
        parts.push(format!("{} clipped interactive", hitboxes.clipped_count));
    }
    if occlusion.occluded_count > 0 {
        parts.push(format!("{} occluded interactive", occlusion.occluded_count));
    }
    if added_hitbox_count > 0 {
        parts.push(format!(
            "{added_hitbox_count} appeared since previous frame"
        ));
    }
    if removed_hitbox_count > 0 {
        parts.push(format!(
            "{removed_hitbox_count} disappeared since previous frame"
        ));
    }
    if changed_hitbox_count > 0 {
        parts.push(format!("{changed_hitbox_count} hitbox changes"));
    }
    if let Some(change) = previous_change {
        if change.changed_node_count > 0 {
            parts.push(format!("after {}", change.summary));
        }
    }
    parts.join("; ")
}

fn debug_hitbox_timeline_record_fix(
    status: DebugFrameTraceStatus,
    missing_hit_count: usize,
    clipped_count: usize,
    occluded_count: usize,
    added_hitbox_count: usize,
    removed_hitbox_count: usize,
    changed_hitbox_count: usize,
) -> String {
    if missing_hit_count > 0 {
        return "open hitbox_map_panel, hit_target_panel, and visibility_panel".to_owned();
    }
    if clipped_count > 0 {
        return "open hitbox_map_panel and clip_chain_panel to inspect clipping ancestors"
            .to_owned();
    }
    if occluded_count > 0 {
        return "open hitbox_occlusion_panel, overlap_report_panel, and hitbox_debug_overlay"
            .to_owned();
    }
    if added_hitbox_count > 0 || removed_hitbox_count > 0 || changed_hitbox_count > 0 {
        return "compare with frame_timeline_panel and inspect changed hitbox nodes".to_owned();
    }
    if matches!(
        status,
        DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
    ) {
        return "open hitbox_map_panel for the highest severity hitbox row".to_owned();
    }
    "no hitbox action needed".to_owned()
}

fn debug_hitbox_timeline_status(records: &[DebugHitboxTimelineRecord]) -> DebugFrameTraceStatus {
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Error)
    {
        return DebugFrameTraceStatus::Error;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Info)
    {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

