fn debug_frame_timeline_status_rank(status: DebugFrameTraceStatus) -> u8 {
    match status {
        DebugFrameTraceStatus::Error => 0,
        DebugFrameTraceStatus::Warning => 1,
        DebugFrameTraceStatus::Info => 2,
        DebugFrameTraceStatus::Ok => 3,
    }
}

fn debug_capture_report_title(trace: &DebugFrameTrace) -> String {
    trace
        .frame_index
        .map(|frame| format!("Operad Debug Capture {} #{frame}", trace.label))
        .unwrap_or_else(|| format!("Operad Debug Capture {}", trace.label))
}

fn debug_capture_report_summary(report: &DebugCaptureReport) -> String {
    let mut parts = vec![format!("{} capture", report.status.label())];
    parts.push(report.frame_summary.clone());
    if !report.top_issues.is_empty() {
        parts.push(format!("{} top issues", report.top_issues.len()));
    }
    if !report.timeline_records.is_empty() {
        parts.push(format!("{} timeline rows", report.timeline_records.len()));
    }
    parts.join("; ")
}

fn debug_capture_report_sections(
    trace: &DebugFrameTrace,
    timeline: Option<&DebugFrameTimelineTrace>,
    issues: &DebugIssueReport,
    report: &DebugCaptureReport,
) -> Vec<DebugCaptureReportSection> {
    let mut sections = Vec::new();
    sections.push(DebugCaptureReportSection {
        title: "Frame".to_owned(),
        lines: debug_capture_frame_lines(trace),
    });
    if let Some(timeline) = timeline {
        sections.push(DebugCaptureReportSection {
            title: "Frame timeline".to_owned(),
            lines: debug_capture_timeline_lines(timeline),
        });
    }
    sections.push(DebugCaptureReportSection {
        title: "Issue triage".to_owned(),
        lines: debug_capture_issue_lines(issues),
    });
    let questions = DebugQuestionGuideTrace::from_frame_trace(trace);
    sections.push(DebugCaptureReportSection {
        title: "Question guide".to_owned(),
        lines: debug_capture_question_lines(&questions),
    });
    let bottlenecks = DebugFrameBottleneckTrace::from_trace(trace);
    sections.push(DebugCaptureReportSection {
        title: "Bottleneck triage".to_owned(),
        lines: debug_capture_bottleneck_lines(&bottlenecks),
    });
    sections.push(DebugCaptureReportSection {
        title: "Next actions".to_owned(),
        lines: debug_capture_next_action_lines(report),
    });
    sections
}

fn debug_capture_frame_lines(trace: &DebugFrameTrace) -> Vec<String> {
    let mut lines = vec![
        format!("summary: {}", trace.summary.summary),
        format!(
            "viewport: {:.0} x {:.0}",
            trace.viewport.width, trace.viewport.height
        ),
        format!("nodes: {}", trace.summary.node_count),
        format!("paint items: {}", trace.summary.paint_item_count),
        format!("dirty: {}", trace.dirty.summary),
    ];
    if let Some(stage) = trace.timing.slowest_stage_explanation() {
        lines.push(format!(
            "slowest stage: {} at {}",
            stage.label,
            format_debug_duration_ms(stage.duration)
        ));
    }
    if let Some(selected) = &trace.selected_node {
        lines.push(format!("selected: {}", selected.summary));
    }
    if trace.summary.overlap_count > 0 {
        lines.push(format!("overlaps: {}", trace.summary.overlap_count));
    }
    if trace.summary.constraint_issue_count > 0 {
        lines.push(format!(
            "constraints: {}",
            trace.summary.constraint_issue_count
        ));
    }
    if trace.summary.resource_count > 0 {
        lines.push(format!("resources: {}", trace.summary.resource_count));
    }
    lines
}

fn debug_capture_timeline_lines(timeline: &DebugFrameTimelineTrace) -> Vec<String> {
    let mut lines = vec![timeline.summary.clone()];
    for record in timeline.records.iter().take(5) {
        let mut parts = vec![
            record.label.clone(),
            record.status.label().to_owned(),
            format_debug_duration_ms(record.total),
        ];
        if let Some(over_by) = record.over_budget_by {
            parts.push(format!("over by {}", format_debug_duration_ms(over_by)));
        }
        if let Some(stage) = &record.slowest_stage {
            parts.push(format!("slowest {stage}"));
        }
        if let Some(change) = &record.previous_change {
            if change.changed_node_count > 0 {
                parts.push(format!("after {}", change.summary));
            }
        }
        lines.push(parts.join("; "));
    }
    lines
}

fn debug_capture_issue_lines(issues: &DebugIssueReport) -> Vec<String> {
    let mut lines = vec![issues.summary.clone()];
    if issues.issues.is_empty() {
        lines.push("no ranked issues".to_owned());
        return lines;
    }
    for issue in issues.issues.iter().take(5) {
        lines.push(format!(
            "{} {}: {}; fix: {}",
            issue.status.label(),
            issue.source.label(),
            issue.cause,
            issue.fix
        ));
    }
    lines
}

fn debug_capture_question_lines(questions: &DebugQuestionGuideTrace) -> Vec<String> {
    let mut lines = vec![questions.summary.clone()];
    for record in &questions.records {
        lines.push(format!(
            "{}: {}; inspect {}; fix: {}",
            record.question, record.summary, record.inspect, record.fix
        ));
    }
    lines
}

fn debug_capture_bottleneck_lines(bottlenecks: &DebugFrameBottleneckTrace) -> Vec<String> {
    let mut lines = vec![bottlenecks.summary.clone()];
    if bottlenecks.records.is_empty() {
        lines.push("no bottleneck records".to_owned());
        return lines;
    }
    for record in bottlenecks.records.iter().take(5) {
        lines.push(format!(
            "{} {}: {}; inspect {}; fix: {}",
            record.status.label(),
            record.source.title(),
            record.summary,
            record.inspect,
            record.fix
        ));
    }
    lines
}

fn debug_capture_next_action_lines(report: &DebugCaptureReport) -> Vec<String> {
    let mut lines = report
        .top_issues
        .iter()
        .take(3)
        .map(|issue| format!("{}: {}", issue.source.title(), issue.fix))
        .collect::<Vec<_>>();
    if lines.is_empty() {
        lines.extend(
            report
                .timeline_records
                .iter()
                .filter(|record| record.over_budget_by.is_some())
                .take(3)
                .map(|record| format!("{}: {}", record.label, record.fix)),
        );
    }
    if lines.is_empty() {
        lines.push(
            "no blocking action captured; keep the report for baseline comparison".to_owned(),
        );
    }
    lines
}

fn debug_frame_budget_summary(
    status: DebugFrameTraceStatus,
    timing: &FrameTimingExplanation,
    over_budget_by: Option<Duration>,
    slowest_stage: Option<&str>,
) -> String {
    let mut parts = vec![format!("{} frame budget", status.label())];
    parts.push(format!("total {}", format_debug_duration_ms(timing.total)));
    if let Some(budget) = timing.budget {
        parts.push(format!("budget {}", format_debug_duration_ms(budget)));
    }
    if let Some(over_by) = over_budget_by {
        parts.push(format!("over by {}", format_debug_duration_ms(over_by)));
    }
    if let Some(stage) = slowest_stage {
        parts.push(format!("slowest {stage}"));
    }
    parts.join("; ")
}

fn debug_frame_timing_waterfall_record_summary(
    section: &FrameTimingSectionExplanation,
    timing: &FrameTimingExplanation,
    after_budget: bool,
) -> String {
    let mut parts = vec![format!(
        "{} {}-{}",
        format_debug_duration_ms(section.duration),
        format_debug_duration_ms(section.start),
        format_debug_duration_ms(section.end)
    )];
    parts.push(format!("{:.0}% total", section.percent_of_total));
    if let Some(percent) = section.percent_of_budget {
        parts.push(format!("{percent:.0}% budget"));
    }
    if let Some(percent) = timing.budget.and_then(|budget| {
        (!budget.is_zero())
            .then(|| (section.end.as_secs_f64() / budget.as_secs_f64() * 100.0) as f32)
    }) {
        parts.push(format!("{percent:.0}% cumulative"));
    }
    if section.crosses_budget {
        parts.push("crosses budget".to_owned());
    } else if after_budget {
        parts.push("after budget".to_owned());
    }
    parts.join("; ")
}

#[allow(clippy::too_many_arguments)]
fn debug_frame_timing_waterfall_summary(
    status: DebugFrameTraceStatus,
    label: &str,
    total: Duration,
    budget: Option<Duration>,
    over_budget_by: Option<Duration>,
    section_count: usize,
    missing_required_stage_count: usize,
    budget_crossed_at: Option<&str>,
) -> String {
    let mut parts = vec![format!("{} frame timing waterfall", status.label())];
    parts.push(label.to_owned());
    parts.push(format!("total {}", format_debug_duration_ms(total)));
    if let Some(budget) = budget {
        parts.push(format!("budget {}", format_debug_duration_ms(budget)));
    }
    if let Some(over_by) = over_budget_by {
        parts.push(format!("over by {}", format_debug_duration_ms(over_by)));
    }
    parts.push(format!(
        "{section_count} section{}",
        debug_plural_s(section_count)
    ));
    if let Some(stage) = budget_crossed_at {
        parts.push(format!("crossed at {stage}"));
    }
    if missing_required_stage_count > 0 {
        parts.push(format!("{missing_required_stage_count} missing stages"));
    }
    parts.join("; ")
}

fn debug_frame_timing_waterfall_status(
    timing: &FrameTimingExplanation,
    over_budget_by: Option<Duration>,
    records: &[DebugFrameTimingWaterfallRecord],
) -> DebugFrameTraceStatus {
    if over_budget_by.is_some() {
        return DebugFrameTraceStatus::Warning;
    }
    if timing.sections.is_empty() || !timing.missing_required_stages.is_empty() {
        return DebugFrameTraceStatus::Info;
    }
    records
        .iter()
        .map(|record| record.status)
        .max()
        .unwrap_or(DebugFrameTraceStatus::Ok)
}

fn debug_frame_timing_waterfall_stage_inspect(stage: &FramePipelineStage) -> &'static str {
    match stage {
        FramePipelineStage::TreeBuild | FramePipelineStage::Diff => "invalidation_blame_panel",
        FramePipelineStage::Layout => "layout_cause_panel",
        FramePipelineStage::TextShaping => "text_layout_panel",
        FramePipelineStage::HitTesting => "hitbox_map_panel",
        FramePipelineStage::PaintList => "paint_order_panel",
        FramePipelineStage::Batching => "paint_batches_panel",
        FramePipelineStage::Uploads => "resource_diagnostics_panel",
        FramePipelineStage::BackendDraw => "paint_overdraw_panel",
        FramePipelineStage::Canvas => "frame_budget_panel",
        FramePipelineStage::Accessibility => "accessibility_tree_panel",
        FramePipelineStage::Custom(_) => "frame_budget_panel",
    }
}

fn debug_frame_budget_stage_cause(
    stage: &FramePipelineStage,
    dirty: &DirtyStateExplanation,
) -> String {
    match stage {
        FramePipelineStage::TreeBuild => {
            "document tree work ran before diff, so check high-churn view construction".to_owned()
        }
        FramePipelineStage::Diff => {
            "document changes required diffing before layout and paint could reuse caches".to_owned()
        }
        FramePipelineStage::Layout => {
            if debug_dirty_contains(dirty, DirtyStateSubsystem::Layout) {
                "layout was dirty, so constraints, intrinsic sizes, clips, and hitboxes recomputed"
                    .to_owned()
            } else {
                "layout dominated even though layout was not marked dirty in the captured state"
                    .to_owned()
            }
        }
        FramePipelineStage::TextShaping => {
            if debug_dirty_contains(dirty, DirtyStateSubsystem::TextMeasurement) {
                "text measurement was dirty, so shaped text and intrinsic text sizes recomputed"
                    .to_owned()
            } else {
                "text shaping work ran without a captured text dirty flag".to_owned()
            }
        }
        FramePipelineStage::HitTesting => {
            if debug_dirty_contains(dirty, DirtyStateSubsystem::Input) {
                "input state was dirty, so focus, hover, pressed, and hit routing refreshed".to_owned()
            } else {
                "hit testing dominated without a captured input dirty flag".to_owned()
            }
        }
        FramePipelineStage::PaintList => {
            if debug_dirty_contains(dirty, DirtyStateSubsystem::Paint) {
                "paint was dirty, so visual commands and renderer batches had to be rebuilt"
                    .to_owned()
            } else {
                "paint-list work ran without a captured paint dirty flag".to_owned()
            }
        }
        FramePipelineStage::Batching => {
            "paint commands were grouped for the backend; many layers or state changes raise this cost"
                .to_owned()
        }
        FramePipelineStage::Uploads => {
            "renderer resources were uploaded or refreshed before draw submission".to_owned()
        }
        FramePipelineStage::BackendDraw => {
            "backend draw work dominated after layout and paint prepared the frame".to_owned()
        }
        FramePipelineStage::Canvas => {
            "canvas work ran inside the frame budget and may include custom app drawing".to_owned()
        }
        FramePipelineStage::Accessibility => {
            "accessibility output was refreshed for changed focus, labels, or geometry".to_owned()
        }
        FramePipelineStage::Custom(label) => {
            format!("custom timing section {label} contributed to this frame")
        }
    }
}

fn debug_frame_budget_stage_action(
    stage: &FramePipelineStage,
    dirty: &DirtyStateExplanation,
) -> String {
    match stage {
        FramePipelineStage::TreeBuild => {
            "reuse stable node names and avoid rebuilding unchanged subtrees".to_owned()
        }
        FramePipelineStage::Diff => {
            "reduce state churn or split frequently changing nodes from stable containers"
                .to_owned()
        }
        FramePipelineStage::Layout => {
            if debug_dirty_contains(dirty, DirtyStateSubsystem::TextMeasurement) {
                "inspect text/layout invalidations first, then reduce intrinsic size dependencies"
                    .to_owned()
            } else {
                "inspect layout cause traces for constraint pressure, clipping, and absolute placement"
                    .to_owned()
            }
        }
        FramePipelineStage::TextShaping => {
            "reuse fonts/styles and avoid changing text content every frame where possible"
                .to_owned()
        }
        FramePipelineStage::HitTesting => {
            "inspect pointer probes and simplify overlapping interactive regions".to_owned()
        }
        FramePipelineStage::PaintList => {
            "inspect paint order and reduce visual/state changes that rebuild paint commands"
                .to_owned()
        }
        FramePipelineStage::Batching => {
            "merge compatible visuals and reduce layer, clip, shader, or texture switches"
                .to_owned()
        }
        FramePipelineStage::Uploads => {
            "check resource diagnostics for missing, stale, or repeatedly uploaded resources"
                .to_owned()
        }
        FramePipelineStage::BackendDraw => {
            "inspect paint stack, shader outsets, overdraw, and GPU resource churn".to_owned()
        }
        FramePipelineStage::Canvas => {
            "move expensive canvas updates behind dirty checks or cache rendered content".to_owned()
        }
        FramePipelineStage::Accessibility => {
            "limit unnecessary accessibility label, focus, and geometry invalidations".to_owned()
        }
        FramePipelineStage::Custom(_) => {
            "instrument the custom stage with narrower timing sections to isolate the owner"
                .to_owned()
        }
    }
}

fn debug_invalidation_blame_record(
    index: usize,
    invalidation: &DirtyInvalidationExplanation,
) -> DebugInvalidationBlameRecord {
    let subsystem_labels = invalidation
        .subsystems
        .iter()
        .map(|subsystem| subsystem.display_label().to_owned())
        .collect::<Vec<_>>();
    let recompute_steps = debug_invalidation_unique_strings(
        invalidation
            .subsystems
            .iter()
            .flat_map(|subsystem| subsystem.recomputes()),
    );
    let downstream = debug_invalidation_unique_strings(
        invalidation
            .subsystems
            .iter()
            .flat_map(|subsystem| subsystem.downstream()),
    );
    let blast_radius = invalidation.subsystems.len();
    let broad = blast_radius >= 3;
    let status = debug_invalidation_record_status(invalidation, broad);
    let summary = debug_invalidation_record_summary(invalidation, blast_radius, broad);
    let cause = debug_invalidation_record_cause(invalidation, blast_radius);
    let fix = debug_invalidation_record_fix(invalidation.reason, broad);

    DebugInvalidationBlameRecord {
        index,
        reason: invalidation.reason,
        label: invalidation.label.clone(),
        detail: invalidation.detail.clone(),
        flags: invalidation.flags,
        subsystems: invalidation.subsystems.clone(),
        subsystem_labels,
        recompute_steps,
        downstream,
        blast_radius,
        broad,
        status,
        summary,
        cause,
        fix,
    }
}

fn debug_invalidation_unique_strings(values: impl IntoIterator<Item = String>) -> Vec<String> {
    let mut unique = Vec::new();
    for value in values {
        if !unique.contains(&value) {
            unique.push(value);
        }
    }
    unique
}

fn debug_invalidation_record_status(
    invalidation: &DirtyInvalidationExplanation,
    broad: bool,
) -> DebugFrameTraceStatus {
    if broad
        || invalidation
            .subsystems
            .contains(&DirtyStateSubsystem::TextMeasurement)
        || invalidation
            .subsystems
            .contains(&DirtyStateSubsystem::Layout)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if invalidation.subsystems.is_empty() {
        return DebugFrameTraceStatus::Ok;
    }
    DebugFrameTraceStatus::Info
}

fn debug_invalidation_record_summary(
    invalidation: &DirtyInvalidationExplanation,
    blast_radius: usize,
    broad: bool,
) -> String {
    let mut parts = Vec::new();
    parts.push(invalidation.summary.clone());
    parts.push(format!("{blast_radius} subsystems"));
    if broad {
        parts.push("broad".to_owned());
    }
    if !invalidation.subsystems.is_empty() {
        parts.push(
            invalidation
                .subsystems
                .iter()
                .map(|subsystem| subsystem.display_label())
                .collect::<Vec<_>>()
                .join(", "),
        );
    }
    parts.join("; ")
}

fn debug_invalidation_record_cause(
    invalidation: &DirtyInvalidationExplanation,
    blast_radius: usize,
) -> String {
    let detail = invalidation
        .detail
        .as_deref()
        .map(|detail| format!(" ({detail})"))
        .unwrap_or_default();
    match invalidation.reason {
        RuntimeInvalidationReason::Input => {
            format!("input event{detail} dirtied interaction state and visual feedback")
        }
        RuntimeInvalidationReason::Resize => {
            format!("window resize{detail} invalidated text measurement, layout, and paint")
        }
        RuntimeInvalidationReason::ScaleFactor => {
            format!("scale factor change{detail} invalidated text metrics, layout, and paint")
        }
        RuntimeInvalidationReason::Animation => {
            format!("animation tick{detail} dirtied paint for changing visual values")
        }
        RuntimeInvalidationReason::AsyncTask => {
            format!("async task{detail} requested {blast_radius} dirty subsystems")
        }
        RuntimeInvalidationReason::PlatformResponse => {
            format!("platform response{detail} requested {blast_radius} dirty subsystems")
        }
        RuntimeInvalidationReason::Accessibility => {
            format!("accessibility change{detail} refreshed input/focus routing")
        }
        RuntimeInvalidationReason::Resource => {
            format!("resource update{detail} dirtied paint and renderer resources")
        }
        RuntimeInvalidationReason::Explicit => {
            format!("explicit invalidation{detail} requested {blast_radius} dirty subsystems")
        }
    }
}

fn debug_invalidation_record_fix(reason: RuntimeInvalidationReason, broad: bool) -> String {
    let broad_prefix = if broad {
        "narrow the invalidation scope where possible; "
    } else {
        ""
    };
    match reason {
        RuntimeInvalidationReason::Input => {
            "keep pointer-only changes paint/input-only and avoid layout-affecting hover state"
                .to_owned()
        }
        RuntimeInvalidationReason::Resize => {
            format!("{broad_prefix}debounce resize-sensitive work and avoid changing text metrics unnecessarily")
        }
        RuntimeInvalidationReason::ScaleFactor => {
            format!("{broad_prefix}rebuild font and layout caches once per scale change, then reuse them")
        }
        RuntimeInvalidationReason::Animation => {
            "keep animations paint-only unless geometry genuinely changes; pause offscreen animation"
                .to_owned()
        }
        RuntimeInvalidationReason::AsyncTask => {
            format!("{broad_prefix}batch async results and attach details that identify the state owner")
        }
        RuntimeInvalidationReason::PlatformResponse => {
            format!("{broad_prefix}coalesce platform responses and update only affected resources or state")
        }
        RuntimeInvalidationReason::Accessibility => {
            "limit accessibility invalidation to focus, label, state, or geometry changes".to_owned()
        }
        RuntimeInvalidationReason::Resource => {
            "batch resource updates and use resource diagnostics to catch repeated uploads"
                .to_owned()
        }
        RuntimeInvalidationReason::Explicit => {
            format!("{broad_prefix}replace broad explicit invalidation with a specific dirty reason")
        }
    }
}

fn debug_invalidation_trace_status(
    dirty: &DirtyStateExplanation,
    records: &[DebugInvalidationBlameRecord],
) -> DebugFrameTraceStatus {
    if dirty.clean {
        return DebugFrameTraceStatus::Ok;
    }
    if dirty.invalidations.is_empty() {
        return DebugFrameTraceStatus::Warning;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    DebugFrameTraceStatus::Info
}

fn debug_invalidation_trace_summary(
    clean: bool,
    invalidation_count: usize,
    dirty_subsystem_count: usize,
    status: DebugFrameTraceStatus,
) -> String {
    if clean {
        return "clean frame; no invalidation blame".to_owned();
    }
    if invalidation_count == 0 {
        return format!(
            "{} dirty subsystems; no runtime invalidation captured",
            dirty_subsystem_count
        );
    }
    format!(
        "{} invalidations; {} dirty subsystems; {}",
        invalidation_count,
        dirty_subsystem_count,
        status.label()
    )
}

struct DebugInvalidationTimelineReasonBuilder {
    reason: RuntimeInvalidationReason,
    label: String,
    frame_count: usize,
    invalidation_count: usize,
    broad_count: usize,
    first_frame_label: Option<String>,
    latest_frame_label: Option<String>,
    details: Vec<String>,
    subsystems: Vec<DirtyStateSubsystem>,
}

fn debug_invalidation_timeline_trace<'a, L>(
    states: impl IntoIterator<Item = (L, Option<u64>, &'a DirtyStateExplanation)>,
) -> DebugInvalidationTimelineTrace
where
    L: Into<String>,
{
    let mut reasons = Vec::<DebugInvalidationTimelineReasonBuilder>::new();
    let mut frames = Vec::new();
    let mut dirty_subsystems = Vec::<DirtyStateSubsystem>::new();

    for (index, (label, frame_index, dirty)) in states.into_iter().enumerate() {
        let label = label.into();
        let blame = DebugInvalidationBlameTrace::from_dirty_state(dirty);
        for subsystem in &dirty.recompute_order {
            debug_invalidation_push_unique_subsystem(&mut dirty_subsystems, *subsystem);
        }
        for record in &blame.records {
            debug_invalidation_timeline_merge_reason(&mut reasons, &label, record);
        }
        frames.push(debug_invalidation_timeline_frame_record(
            index,
            label,
            frame_index,
            &blame,
        ));
    }

    let frame_count = frames.len();
    let dirty_frame_count = frames
        .iter()
        .filter(|frame| frame.dirty_subsystem_count > 0)
        .count();
    let invalidation_frame_count = frames
        .iter()
        .filter(|frame| frame.invalidation_count > 0)
        .count();
    let broad_frame_count = frames.iter().filter(|frame| frame.broad_count > 0).count();
    let invalidation_count = frames
        .iter()
        .map(|frame| frame.invalidation_count)
        .sum::<usize>();

    let mut records = reasons
        .into_iter()
        .map(|reason| debug_invalidation_timeline_reason_record(reason, frame_count))
        .collect::<Vec<_>>();
    records.sort_by(|left, right| {
        debug_invalidation_status_rank(left.status)
            .cmp(&debug_invalidation_status_rank(right.status))
            .then_with(|| right.frame_count.cmp(&left.frame_count))
            .then_with(|| right.broad_count.cmp(&left.broad_count))
            .then_with(|| right.invalidation_count.cmp(&left.invalidation_count))
            .then_with(|| left.label.cmp(&right.label))
    });

    let status = debug_invalidation_timeline_status(&frames);
    let broad_count = records.iter().map(|record| record.broad_count).sum();
    let reason_count = records.len();
    let top_reason = records.first().map(|record| record.reason);
    let top_reason_label = records.first().map(|record| record.label.clone());
    let summary = debug_invalidation_timeline_summary(
        status,
        frame_count,
        dirty_frame_count,
        invalidation_frame_count,
        invalidation_count,
        broad_count,
        top_reason_label.as_deref(),
    );

    DebugInvalidationTimelineTrace {
        status,
        frame_count,
        dirty_frame_count,
        invalidation_frame_count,
        broad_frame_count,
        invalidation_count,
        broad_count,
        dirty_subsystem_count: dirty_subsystems.len(),
        reason_count,
        top_reason,
        top_reason_label,
        records,
        frames,
        summary,
    }
}

fn debug_invalidation_timeline_merge_reason(
    reasons: &mut Vec<DebugInvalidationTimelineReasonBuilder>,
    frame_label: &str,
    record: &DebugInvalidationBlameRecord,
) {
    let Some(reason) = reasons
        .iter_mut()
        .find(|reason| reason.reason == record.reason)
    else {
        let mut reason = DebugInvalidationTimelineReasonBuilder {
            reason: record.reason,
            label: record.label.clone(),
            frame_count: 1,
            invalidation_count: 1,
            broad_count: usize::from(record.broad),
            first_frame_label: Some(frame_label.to_owned()),
            latest_frame_label: Some(frame_label.to_owned()),
            details: Vec::new(),
            subsystems: Vec::new(),
        };
        debug_invalidation_timeline_merge_reason_details(&mut reason, record);
        reasons.push(reason);
        return;
    };

    if reason.latest_frame_label.as_deref() != Some(frame_label) {
        reason.frame_count += 1;
        reason.latest_frame_label = Some(frame_label.to_owned());
    }
    reason.invalidation_count += 1;
    reason.broad_count += usize::from(record.broad);
    debug_invalidation_timeline_merge_reason_details(reason, record);
}

fn debug_invalidation_timeline_merge_reason_details(
    reason: &mut DebugInvalidationTimelineReasonBuilder,
    record: &DebugInvalidationBlameRecord,
) {
    if let Some(detail) = &record.detail {
        debug_invalidation_push_unique_string(&mut reason.details, detail.clone());
    }
    for subsystem in &record.subsystems {
        debug_invalidation_push_unique_subsystem(&mut reason.subsystems, *subsystem);
    }
}

fn debug_invalidation_timeline_frame_record(
    index: usize,
    label: String,
    frame_index: Option<u64>,
    blame: &DebugInvalidationBlameTrace,
) -> DebugInvalidationTimelineFrameRecord {
    let broad_count = blame.records.iter().filter(|record| record.broad).count();
    let top = blame.primary();
    let top_reason = top.map(|record| record.reason);
    let top_reason_label = top.map(|record| record.label.clone());
    let summary = debug_invalidation_timeline_frame_summary(
        &label,
        blame.status,
        blame.invalidation_count,
        broad_count,
        blame.dirty_subsystem_count,
        top_reason_label.as_deref(),
    );
    DebugInvalidationTimelineFrameRecord {
        index,
        label,
        frame_index,
        status: blame.status,
        invalidation_count: blame.invalidation_count,
        broad_count,
        dirty_subsystem_count: blame.dirty_subsystem_count,
        top_reason,
        top_reason_label,
        summary,
    }
}

fn debug_invalidation_timeline_reason_record(
    reason: DebugInvalidationTimelineReasonBuilder,
    retained_frame_count: usize,
) -> DebugInvalidationTimelineReasonRecord {
    let status = debug_invalidation_timeline_reason_status(
        reason.invalidation_count,
        reason.broad_count,
        &reason.subsystems,
    );
    let summary = debug_invalidation_timeline_reason_summary(
        &reason.label,
        status,
        reason.frame_count,
        retained_frame_count,
        reason.invalidation_count,
        reason.broad_count,
        &reason.subsystems,
    );
    let cause = debug_invalidation_timeline_reason_cause(
        &reason.label,
        reason.frame_count,
        retained_frame_count,
        reason.invalidation_count,
        reason.broad_count,
        &reason.subsystems,
        &reason.details,
    );
    let fix = debug_invalidation_record_fix(reason.reason, reason.broad_count > 0);
    DebugInvalidationTimelineReasonRecord {
        reason: reason.reason,
        label: reason.label,
        status,
        frame_count: reason.frame_count,
        invalidation_count: reason.invalidation_count,
        broad_count: reason.broad_count,
        dirty_subsystem_count: reason.subsystems.len(),
        first_frame_label: reason.first_frame_label,
        latest_frame_label: reason.latest_frame_label,
        details: reason.details,
        subsystems: reason.subsystems,
        summary,
        cause,
        fix,
    }
}

fn debug_invalidation_timeline_reason_status(
    invalidation_count: usize,
    broad_count: usize,
    subsystems: &[DirtyStateSubsystem],
) -> DebugFrameTraceStatus {
    if broad_count > 0
        || subsystems.contains(&DirtyStateSubsystem::TextMeasurement)
        || subsystems.contains(&DirtyStateSubsystem::Layout)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if invalidation_count > 0 {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

fn debug_invalidation_timeline_status(
    frames: &[DebugInvalidationTimelineFrameRecord],
) -> DebugFrameTraceStatus {
    if frames
        .iter()
        .any(|frame| frame.status == DebugFrameTraceStatus::Error)
    {
        return DebugFrameTraceStatus::Error;
    }
    if frames
        .iter()
        .any(|frame| frame.status == DebugFrameTraceStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if frames
        .iter()
        .any(|frame| frame.status == DebugFrameTraceStatus::Info)
    {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

#[allow(clippy::too_many_arguments)]
fn debug_invalidation_timeline_summary(
    status: DebugFrameTraceStatus,
    frame_count: usize,
    dirty_frame_count: usize,
    invalidation_frame_count: usize,
    invalidation_count: usize,
    broad_count: usize,
    top_reason_label: Option<&str>,
) -> String {
    let mut parts = vec![format!("{} invalidation timeline", status.label())];
    parts.push(format!(
        "{frame_count} frame{}",
        debug_plural_s(frame_count)
    ));
    if dirty_frame_count > 0 {
        parts.push(format!(
            "{dirty_frame_count} dirty frame{}",
            debug_plural_s(dirty_frame_count)
        ));
    }
    if invalidation_frame_count > 0 {
        parts.push(format!(
            "{invalidation_frame_count} with runtime cause{}",
            debug_plural_s(invalidation_frame_count)
        ));
    }
    if invalidation_count > 0 {
        parts.push(format!(
            "{invalidation_count} invalidation{}",
            debug_plural_s(invalidation_count)
        ));
    }
    if broad_count > 0 {
        parts.push(format!("{broad_count} broad"));
    }
    if let Some(top_reason_label) = top_reason_label {
        parts.push(format!("top {top_reason_label}"));
    }
    parts.join("; ")
}

#[allow(clippy::too_many_arguments)]
fn debug_invalidation_timeline_reason_summary(
    label: &str,
    status: DebugFrameTraceStatus,
    frame_count: usize,
    retained_frame_count: usize,
    invalidation_count: usize,
    broad_count: usize,
    subsystems: &[DirtyStateSubsystem],
) -> String {
    let mut parts = vec![format!("{} {label}", status.label())];
    parts.push(format!(
        "{frame_count}/{retained_frame_count} frame{}",
        debug_plural_s(retained_frame_count)
    ));
    if invalidation_count != frame_count {
        parts.push(format!(
            "{invalidation_count} invalidation{}",
            debug_plural_s(invalidation_count)
        ));
    }
    if broad_count > 0 {
        parts.push(format!(
            "{broad_count} broad trigger{}",
            debug_plural_s(broad_count)
        ));
    }
    if !subsystems.is_empty() {
        parts.push(debug_invalidation_subsystem_display_labels(subsystems).join(", "));
    }
    parts.join("; ")
}

fn debug_invalidation_timeline_reason_cause(
    label: &str,
    frame_count: usize,
    retained_frame_count: usize,
    invalidation_count: usize,
    broad_count: usize,
    subsystems: &[DirtyStateSubsystem],
    details: &[String],
) -> String {
    let mut parts = vec![format!(
        "{label} appeared in {frame_count}/{retained_frame_count} retained frame{}",
        debug_plural_s(retained_frame_count)
    )];
    if invalidation_count > frame_count {
        parts.push(format!(
            "{invalidation_count} total invalidation{}",
            debug_plural_s(invalidation_count)
        ));
    }
    if broad_count > 0 {
        parts.push(format!(
            "{broad_count} broad trigger{}",
            debug_plural_s(broad_count)
        ));
    }
    if !subsystems.is_empty() {
        parts.push(format!(
            "dirtied {}",
            debug_invalidation_subsystem_display_labels(subsystems).join(", ")
        ));
    }
    if !details.is_empty() {
        parts.push(format!(
            "details {}",
            details
                .iter()
                .take(3)
                .cloned()
                .collect::<Vec<_>>()
                .join(", ")
        ));
    }
    parts.join("; ")
}

fn debug_invalidation_timeline_frame_summary(
    label: &str,
    status: DebugFrameTraceStatus,
    invalidation_count: usize,
    broad_count: usize,
    dirty_subsystem_count: usize,
    top_reason_label: Option<&str>,
) -> String {
    let mut parts = vec![format!("{} invalidation for {label}", status.label())];
    if dirty_subsystem_count == 0 {
        parts.push("clean".to_owned());
    } else {
        parts.push(format!(
            "{dirty_subsystem_count} dirty subsystem{}",
            debug_plural_s(dirty_subsystem_count)
        ));
    }
    if invalidation_count > 0 {
        parts.push(format!(
            "{invalidation_count} invalidation{}",
            debug_plural_s(invalidation_count)
        ));
    } else if dirty_subsystem_count > 0 {
        parts.push("no runtime cause captured".to_owned());
    }
    if broad_count > 0 {
        parts.push(format!("{broad_count} broad"));
    }
    if let Some(top_reason_label) = top_reason_label {
        parts.push(format!("top {top_reason_label}"));
    }
    parts.join("; ")
}

fn debug_invalidation_subsystem_display_labels(subsystems: &[DirtyStateSubsystem]) -> Vec<String> {
    subsystems
        .iter()
        .map(|subsystem| subsystem.display_label().to_owned())
        .collect()
}

fn debug_invalidation_push_unique_subsystem(
    subsystems: &mut Vec<DirtyStateSubsystem>,
    subsystem: DirtyStateSubsystem,
) {
    if !subsystems.contains(&subsystem) {
        subsystems.push(subsystem);
    }
}

fn debug_invalidation_push_unique_string(values: &mut Vec<String>, value: String) {
    if !values.contains(&value) {
        values.push(value);
    }
}

fn debug_invalidation_status_rank(status: DebugFrameTraceStatus) -> u8 {
    match status {
        DebugFrameTraceStatus::Error => 0,
        DebugFrameTraceStatus::Warning => 1,
        DebugFrameTraceStatus::Info => 2,
        DebugFrameTraceStatus::Ok => 3,
    }
}

fn debug_invalidation_blast_trace(dirty: &DirtyStateExplanation) -> DebugInvalidationBlastTrace {
    let mut records = dirty
        .subsystems
        .iter()
        .filter(|subsystem| subsystem.active)
        .map(|subsystem| debug_invalidation_blast_record(dirty, subsystem))
        .collect::<Vec<_>>();
    records.sort_by(|left, right| {
        debug_invalidation_status_rank(left.status)
            .cmp(&debug_invalidation_status_rank(right.status))
            .then_with(|| right.score.cmp(&left.score))
            .then_with(|| left.label.cmp(&right.label))
    });
    let active_subsystem_count = records.len();
    let broad_trigger_count = records
        .iter()
        .map(|record| record.broad_trigger_count)
        .max()
        .unwrap_or(0);
    let max_score = records.iter().map(|record| record.score).max().unwrap_or(0);
    let status = debug_invalidation_blast_trace_status(dirty, &records);
    let summary = debug_invalidation_blast_trace_summary(
        dirty.clean,
        dirty.invalidations.len(),
        active_subsystem_count,
        broad_trigger_count,
        max_score,
        status,
    );
    DebugInvalidationBlastTrace {
        flags: dirty.flags,
        clean: dirty.clean,
        status,
        invalidation_count: dirty.invalidations.len(),
        active_subsystem_count,
        broad_trigger_count,
        max_score,
        records,
        summary,
    }
}

fn debug_invalidation_blast_record(
    dirty: &DirtyStateExplanation,
    subsystem: &DirtySubsystemExplanation,
) -> DebugInvalidationBlastRecord {
    let triggers = dirty
        .invalidations
        .iter()
        .filter(|invalidation| invalidation.subsystems.contains(&subsystem.subsystem))
        .collect::<Vec<_>>();
    let trigger_count = triggers.len();
    let broad_trigger_count = triggers
        .iter()
        .filter(|invalidation| invalidation.subsystems.len() >= 3)
        .count();
    let trigger_labels = triggers
        .iter()
        .map(|invalidation| invalidation.summary.clone())
        .collect::<Vec<_>>();
    let score = debug_invalidation_blast_score(
        subsystem.subsystem,
        trigger_count,
        broad_trigger_count,
        subsystem.recomputes.len(),
        subsystem.downstream.len(),
        dirty.invalidations.is_empty(),
    );
    let status = debug_invalidation_blast_record_status(
        subsystem.subsystem,
        trigger_count,
        broad_trigger_count,
        dirty.invalidations.is_empty(),
    );
    let summary = debug_invalidation_blast_record_summary(
        subsystem,
        trigger_count,
        broad_trigger_count,
        score,
        &trigger_labels,
    );
    let cause = debug_invalidation_blast_record_cause(
        subsystem,
        trigger_count,
        broad_trigger_count,
        &trigger_labels,
        dirty.invalidations.is_empty(),
    );
    let fix = debug_invalidation_blast_record_fix(
        subsystem.subsystem,
        trigger_count,
        broad_trigger_count,
        dirty.invalidations.is_empty(),
    );
    DebugInvalidationBlastRecord {
        subsystem: subsystem.subsystem,
        label: subsystem.label.clone(),
        status,
        score,
        trigger_count,
        broad_trigger_count,
        trigger_labels,
        recompute_steps: subsystem.recomputes.clone(),
        downstream: subsystem.downstream.clone(),
        summary,
        cause,
        fix,
    }
}

fn debug_invalidation_blast_score(
    subsystem: DirtyStateSubsystem,
    trigger_count: usize,
    broad_trigger_count: usize,
    recompute_count: usize,
    downstream_count: usize,
    uncaptured: bool,
) -> u32 {
    let mut score = trigger_count as u32 * 12
        + broad_trigger_count as u32 * 14
        + recompute_count as u32 * 4
        + downstream_count as u32 * 4;
    score += match subsystem {
        DirtyStateSubsystem::TextMeasurement => 18,
        DirtyStateSubsystem::Layout => 20,
        DirtyStateSubsystem::Paint => 12,
        DirtyStateSubsystem::Input => 8,
        DirtyStateSubsystem::Theme => 10,
    };
    if uncaptured {
        score += 20;
    }
    score
}

fn debug_invalidation_blast_record_status(
    subsystem: DirtyStateSubsystem,
    trigger_count: usize,
    broad_trigger_count: usize,
    uncaptured: bool,
) -> DebugFrameTraceStatus {
    if uncaptured {
        return DebugFrameTraceStatus::Warning;
    }
    if broad_trigger_count > 0
        || matches!(
            subsystem,
            DirtyStateSubsystem::TextMeasurement | DirtyStateSubsystem::Layout
        )
        || trigger_count > 2
    {
        return DebugFrameTraceStatus::Warning;
    }
    if trigger_count > 0 {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

fn debug_invalidation_blast_record_summary(
    subsystem: &DirtySubsystemExplanation,
    trigger_count: usize,
    broad_trigger_count: usize,
    score: u32,
    trigger_labels: &[String],
) -> String {
    let mut parts = vec![format!("{} blast score {score}", subsystem.label)];
    parts.push(format!("{trigger_count} triggers"));
    if broad_trigger_count > 0 {
        parts.push(format!("{broad_trigger_count} broad"));
    }
    if let Some(trigger) = trigger_labels.first() {
        parts.push(format!("top trigger {trigger}"));
    }
    parts.push(format!("recomputes {}", subsystem.recomputes.join(", ")));
    if !subsystem.downstream.is_empty() {
        parts.push(format!("downstream {}", subsystem.downstream.join(", ")));
    }
    parts.join("; ")
}

fn debug_invalidation_blast_record_cause(
    subsystem: &DirtySubsystemExplanation,
    trigger_count: usize,
    broad_trigger_count: usize,
    trigger_labels: &[String],
    uncaptured: bool,
) -> String {
    if uncaptured {
        return format!(
            "{} was dirty, but no runtime invalidation trigger was captured",
            subsystem.label
        );
    }
    if trigger_count == 0 {
        return format!(
            "{} was marked dirty without a matching trigger",
            subsystem.label
        );
    }
    let trigger_summary = trigger_labels.join("; ");
    if broad_trigger_count > 0 {
        return format!(
            "{} was reached by broad invalidation trigger(s): {trigger_summary}",
            subsystem.label
        );
    }
    format!(
        "{} was dirtied by {trigger_count} trigger{}: {trigger_summary}",
        subsystem.label,
        debug_plural_s(trigger_count)
    )
}

fn debug_invalidation_blast_record_fix(
    subsystem: DirtyStateSubsystem,
    trigger_count: usize,
    broad_trigger_count: usize,
    uncaptured: bool,
) -> String {
    if uncaptured {
        return "capture runtime invalidation reasons so dirty work can be tied to a state owner"
            .to_owned();
    }
    if broad_trigger_count > 0 {
        return "split broad invalidations into the smallest affected subsystem and owner"
            .to_owned();
    }
    match subsystem {
        DirtyStateSubsystem::TextMeasurement => {
            "avoid changing text/font inputs unless measured text actually changed".to_owned()
        }
        DirtyStateSubsystem::Layout => {
            "keep visual-only state out of layout inputs and inspect layout cause diagnostics"
                .to_owned()
        }
        DirtyStateSubsystem::Paint => {
            if trigger_count > 2 {
                "coalesce paint invalidations and avoid repainting unrelated visual scopes"
                    .to_owned()
            } else {
                "confirm paint-only work stays out of layout and text measurement".to_owned()
            }
        }
        DirtyStateSubsystem::Input => {
            "keep pointer/focus invalidations scoped to hit routing and interactive visuals"
                .to_owned()
        }
        DirtyStateSubsystem::Theme => {
            "avoid broad theme invalidation unless tokens or typography actually changed".to_owned()
        }
    }
}

fn debug_invalidation_blast_trace_status(
    dirty: &DirtyStateExplanation,
    records: &[DebugInvalidationBlastRecord],
) -> DebugFrameTraceStatus {
    if dirty.clean {
        return DebugFrameTraceStatus::Ok;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if !records.is_empty() {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

fn debug_invalidation_blast_trace_summary(
    clean: bool,
    invalidation_count: usize,
    active_subsystem_count: usize,
    broad_trigger_count: usize,
    max_score: u32,
    status: DebugFrameTraceStatus,
) -> String {
    if clean {
        return "clean frame; no invalidation blast radius".to_owned();
    }
    let mut parts = vec![format!("{} invalidation blast radius", status.label())];
    parts.push(format!("{active_subsystem_count} dirty subsystems"));
    parts.push(format!("{invalidation_count} triggers"));
    if broad_trigger_count > 0 {
        parts.push(format!("{broad_trigger_count} broad triggers"));
    }
    parts.push(format!("max score {max_score}"));
    parts.join("; ")
}

fn debug_cache_reuse_record(cache: &CacheDiagnostic) -> DebugCacheReuseRecord {
    let hit_rate = cache.hit_rate();
    let status = debug_cache_reuse_record_status(cache, false);
    let summary = debug_cache_reuse_record_summary(cache, hit_rate, false);
    let cause = debug_cache_reuse_record_cause(cache, hit_rate, false);
    let fix = debug_cache_reuse_record_fix(cache, false);
    DebugCacheReuseRecord {
        kind: cache.kind.clone(),
        name: cache.name.clone(),
        lookups: cache.lookups,
        hits: cache.hits,
        misses: cache.misses,
        evictions: cache.evictions,
        retained_bytes: cache.retained_bytes,
        hit_rate,
        missing_required: false,
        status,
        summary,
        cause,
        fix,
    }
}

fn debug_missing_cache_reuse_record(kind: CacheDiagnosticKind) -> DebugCacheReuseRecord {
    let name = kind.label().to_owned();
    let cache = CacheDiagnostic::new(name.clone()).with_kind(kind.clone());
    DebugCacheReuseRecord {
        kind,
        name,
        lookups: 0,
        hits: 0,
        misses: 0,
        evictions: 0,
        retained_bytes: None,
        hit_rate: None,
        missing_required: true,
        status: DebugFrameTraceStatus::Warning,
        summary: debug_cache_reuse_record_summary(&cache, None, true),
        cause: debug_cache_reuse_record_cause(&cache, None, true),
        fix: debug_cache_reuse_record_fix(&cache, true),
    }
}

fn debug_cache_reuse_record_status(
    cache: &CacheDiagnostic,
    missing_required: bool,
) -> DebugFrameTraceStatus {
    if missing_required || cache.evictions > 0 {
        return DebugFrameTraceStatus::Warning;
    }
    if cache.lookups == 0 {
        return DebugFrameTraceStatus::Info;
    }
    if cache.misses > cache.hits {
        return DebugFrameTraceStatus::Warning;
    }
    if cache.misses > 0 {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

fn debug_cache_reuse_record_summary(
    cache: &CacheDiagnostic,
    hit_rate: Option<f32>,
    missing_required: bool,
) -> String {
    if missing_required {
        return format!("missing {} cache diagnostic", cache.kind.label());
    }
    let mut parts = vec![format!("{} cache", cache.kind.label())];
    if let Some(hit_rate) = hit_rate {
        parts.push(format!("hit {:.0}%", hit_rate * 100.0));
    } else {
        parts.push("not queried".to_owned());
    }
    parts.push(format!(
        "{} lookups; {} hits; {} misses",
        cache.lookups, cache.hits, cache.misses
    ));
    if cache.evictions > 0 {
        parts.push(format!("{} evictions", cache.evictions));
    }
    if let Some(bytes) = cache.retained_bytes {
        parts.push(format!("{} retained bytes", bytes));
    }
    parts.join("; ")
}

fn debug_cache_reuse_record_cause(
    cache: &CacheDiagnostic,
    hit_rate: Option<f32>,
    missing_required: bool,
) -> String {
    if missing_required {
        return format!(
            "no {} cache diagnostic was captured for this frame",
            cache.kind.label()
        );
    }
    if cache.evictions > 0 {
        return "cache entries were evicted before later lookups could reuse them".to_owned();
    }
    if cache.lookups == 0 {
        return "cache instrumentation was present, but no lookup happened this frame".to_owned();
    }
    if cache.misses > cache.hits {
        return "more cache lookups missed than hit, so work rebuilt instead of reusing previous data"
            .to_owned();
    }
    if cache.misses > 0 {
        return "some lookups missed because entries were absent, stale, dirty, or not retained"
            .to_owned();
    }
    if hit_rate == Some(1.0) {
        return "all cache lookups reused retained work".to_owned();
    }
    "cache reused retained work for this frame".to_owned()
}

fn debug_cache_reuse_record_fix(cache: &CacheDiagnostic, missing_required: bool) -> String {
    if missing_required {
        return format!(
            "emit a {} CacheDiagnostic so devtools can explain reuse for this cache",
            cache.kind.label()
        );
    }
    if cache.evictions > 0 {
        return "raise capacity, reduce retained entry churn, or inspect the evicted keys"
            .to_owned();
    }
    if cache.misses > cache.hits {
        return "inspect dirty inputs and cache keys; stabilize revisions and avoid broad invalidation"
            .to_owned();
    }
    if cache.misses > 0 {
        return "check absent/stale entries and keep cache keys stable across frames".to_owned();
    }
    if cache.lookups == 0 {
        return "verify the cache is expected to participate in this frame".to_owned();
    }
    "no cache action needed".to_owned()
}

fn debug_display_list_reuse_record(report: &DisplayListReuseReport) -> DebugDisplayListReuseRecord {
    let status = debug_display_list_reuse_status(report.outcome);
    let key = debug_display_list_key_label(report);
    let scope = debug_display_list_scope_label(&report.key.scope);
    let invalidation_flags = report
        .invalidation
        .map(|invalidation| invalidation.dirty_flags);
    let age_frames = report
        .last_used_frame
        .map(|last_used| report.frame.saturating_sub(last_used));
    let summary = debug_display_list_reuse_summary(report);
    let cause = debug_display_list_reuse_cause(report);
    let fix = debug_display_list_reuse_fix(report);

    DebugDisplayListReuseRecord {
        key,
        scope,
        revision: report.key.revision,
        outcome: report.outcome,
        frame: report.frame,
        dirty_flags: report.dirty_flags,
        kind: report.kind.map(|kind| format!("{kind:?}")),
        invalidation_flags,
        item_count: report.item_count,
        age_frames,
        status,
        summary,
        cause,
        fix,
    }
}

fn debug_display_list_reuse_status(outcome: DisplayListReuseOutcome) -> DebugFrameTraceStatus {
    match outcome {
        DisplayListReuseOutcome::Reused => DebugFrameTraceStatus::Ok,
        DisplayListReuseOutcome::MissAbsent => DebugFrameTraceStatus::Info,
        DisplayListReuseOutcome::MissDirty | DisplayListReuseOutcome::MissEvicted => {
            DebugFrameTraceStatus::Warning
        }
    }
}

fn debug_display_list_reuse_summary(report: &DisplayListReuseReport) -> String {
    let mut parts = vec![format!("{:?}", report.outcome)];
    parts.push(debug_display_list_key_label(report));
    if let Some(kind) = report.kind {
        parts.push(format!("{kind:?}"));
    }
    if let Some(count) = report.item_count {
        parts.push(format!("{count} paint items"));
    }
    if let Some(last_used) = report.last_used_frame {
        parts.push(format!(
            "last used {} frame{} ago",
            report.frame.saturating_sub(last_used),
            debug_plural_s(report.frame.saturating_sub(last_used) as usize)
        ));
    }
    parts.join("; ")
}

fn debug_display_list_reuse_cause(report: &DisplayListReuseReport) -> String {
    match report.outcome {
        DisplayListReuseOutcome::Reused => {
            "retained display list matched the key and dirty flags allowed reuse".to_owned()
        }
        DisplayListReuseOutcome::MissAbsent => {
            "no retained display list existed for this key; it may be first use, a new revision, or previously invalidated".to_owned()
        }
        DisplayListReuseOutcome::MissDirty => {
            let invalidation = report
                .invalidation
                .map(|invalidation| debug_dirty_flags_label(invalidation.dirty_flags))
                .unwrap_or_else(|| "unknown invalidation contract".to_owned());
            format!(
                "dirty flags {} overlap the display-list invalidation contract {invalidation}",
                debug_dirty_flags_label(report.dirty_flags)
            )
        }
        DisplayListReuseOutcome::MissEvicted => {
            "the retained display list existed previously but was evicted before this lookup"
                .to_owned()
        }
    }
}

fn debug_display_list_reuse_fix(report: &DisplayListReuseReport) -> String {
    match report.outcome {
        DisplayListReuseOutcome::Reused => "no display-list reuse action needed".to_owned(),
        DisplayListReuseOutcome::MissAbsent => {
            "warm the display list before the frame or keep its key/revision stable".to_owned()
        }
        DisplayListReuseOutcome::MissDirty => {
            "narrow dirty flags or split static paint from regions invalidated by this change"
                .to_owned()
        }
        DisplayListReuseOutcome::MissEvicted => {
            "increase display-list capacity or reduce retained surface churn".to_owned()
        }
    }
}

fn debug_display_list_key_label(report: &DisplayListReuseReport) -> String {
    format!(
        "{}:{}@{}",
        debug_display_list_scope_label(&report.key.scope),
        report.key.id.as_str(),
        report.key.revision
    )
}

fn debug_display_list_scope_label(scope: &DisplayListScope) -> String {
    match scope {
        DisplayListScope::Document => "document".to_owned(),
        DisplayListScope::Node(node) => format!("node#{}", node.0),
        DisplayListScope::EditorSurface(surface) => format!("editor:{surface}"),
        DisplayListScope::Custom(label) => format!("custom:{label}"),
    }
}

fn debug_cache_reuse_trace_status(
    records: &[DebugCacheReuseRecord],
    display_lists: &[DebugDisplayListReuseRecord],
) -> DebugFrameTraceStatus {
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Warning)
        || display_lists
            .iter()
            .any(|record| record.status == DebugFrameTraceStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Info)
        || display_lists
            .iter()
            .any(|record| record.status == DebugFrameTraceStatus::Info)
    {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

#[allow(clippy::too_many_arguments)]
fn debug_cache_reuse_trace_summary(
    cache_count: usize,
    missing_required_count: usize,
    total_lookups: usize,
    total_hits: usize,
    total_misses: usize,
    total_evictions: usize,
    display_list_count: usize,
    status: DebugFrameTraceStatus,
) -> String {
    let mut parts = vec![format!("{} cache reuse", status.label())];
    parts.push(format!("{cache_count} caches"));
    if total_lookups > 0 {
        let hit_rate = total_hits as f32 / total_lookups as f32 * 100.0;
        parts.push(format!("{hit_rate:.0}% hit rate"));
        parts.push(format!("{total_misses} misses"));
    } else {
        parts.push("no lookups".to_owned());
    }
    if total_evictions > 0 {
        parts.push(format!("{total_evictions} evictions"));
    }
    if missing_required_count > 0 {
        parts.push(format!("{missing_required_count} missing diagnostics"));
    }
    if display_list_count > 0 {
        parts.push(format!("{display_list_count} display-list reports"));
    }
    parts.join("; ")
}

fn debug_dirty_flags_label(flags: DirtyFlags) -> String {
    let mut labels = Vec::new();
    if flags.layout {
        labels.push("layout");
    }
    if flags.paint {
        labels.push("paint");
    }
    if flags.input {
        labels.push("input");
    }
    if flags.theme {
        labels.push("theme");
    }
    if flags.text_measurement {
        labels.push("text_measurement");
    }
    if labels.is_empty() {
        "clean".to_owned()
    } else {
        labels.join(", ")
    }
}

fn debug_plural_s(count: usize) -> &'static str {
    if count == 1 {
        ""
    } else {
        "s"
    }
}

fn debug_cache_reuse_status_rank(status: DebugFrameTraceStatus) -> u8 {
    match status {
        DebugFrameTraceStatus::Error => 0,
        DebugFrameTraceStatus::Warning => 1,
        DebugFrameTraceStatus::Info => 2,
        DebugFrameTraceStatus::Ok => 3,
    }
}

fn debug_dirty_contains(dirty: &DirtyStateExplanation, subsystem: DirtyStateSubsystem) -> bool {
    dirty
        .recompute_order
        .iter()
        .any(|candidate| *candidate == subsystem)
}

fn collect_debug_budget_issues(budget: &DebugFrameBudgetTrace, issues: &mut Vec<DebugIssueRecord>) {
    if matches!(budget.status, DebugFrameTraceStatus::Ok) {
        return;
    }
    let dominant = budget.stages.iter().find(|stage| stage.dominant);
    let cause = if let Some(over_by) = budget.over_budget_by {
        format!(
            "frame exceeded the supplied budget by {}",
            format_debug_duration_ms(over_by)
        )
    } else if budget.timing.stages.is_empty() {
        "no timing stages were captured for this frame".to_owned()
    } else {
        "frame is close to the supplied budget".to_owned()
    };
    let fix = dominant
        .map(|stage| stage.action.clone())
        .unwrap_or_else(|| "capture pipeline timing sections and inspect dirty state".to_owned());
    issues.push(DebugIssueRecord {
        status: budget.status,
        source: DebugIssueSource::Performance,
        label: "frame-budget".to_owned(),
        node: None,
        node_name: None,
        summary: budget.summary.clone(),
        cause,
        fix,
    });
}

fn collect_debug_constraint_issues(
    constraints: &[DebugConstraintIssue],
    issues: &mut Vec<DebugIssueRecord>,
) {
    for constraint in constraints {
        issues.push(DebugIssueRecord {
            status: debug_constraint_status(constraint.severity),
            source: debug_issue_source_for_constraint(constraint.kind),
            label: constraint.kind.label().to_owned(),
            node: constraint.node,
            node_name: constraint.name.clone(),
            summary: constraint.summary.clone(),
            cause: constraint.cause.clone(),
            fix: constraint.fix.clone(),
        });
    }
}

fn debug_issue_source_for_constraint(kind: DebugConstraintIssueKind) -> DebugIssueSource {
    match kind {
        DebugConstraintIssueKind::PaintOutsideHitbox
        | DebugConstraintIssueKind::HitboxOutsidePaint => DebugIssueSource::PaintHit,
        DebugConstraintIssueKind::TextClipped | DebugConstraintIssueKind::TextContrastTooLow => {
            DebugIssueSource::TextFit
        }
        _ => DebugIssueSource::Constraint,
    }
}

fn collect_debug_overlap_issues(
    overlaps: &[DebugOverlapRecord],
    issues: &mut Vec<DebugIssueRecord>,
) {
    for overlap in overlaps {
        let status = match overlap.kind {
            DebugOverlapKind::InteractiveHitbox => DebugFrameTraceStatus::Warning,
            DebugOverlapKind::Paint | DebugOverlapKind::Layout => DebugFrameTraceStatus::Info,
        };
        let label = match overlap.kind {
            DebugOverlapKind::InteractiveHitbox => "interactive-overlap",
            DebugOverlapKind::Paint => "paint-overlap",
            DebugOverlapKind::Layout => "layout-overlap",
        };
        issues.push(DebugIssueRecord {
            status,
            source: DebugIssueSource::Overlap,
            label: label.to_owned(),
            node: Some(overlap.front.id),
            node_name: Some(overlap.front.name.clone()),
            summary: format!(
                "{} overlaps {} ({:.0} x {:.0})",
                overlap.front.name,
                overlap.back.name,
                overlap.overlap_rect.width,
                overlap.overlap_rect.height
            ),
            cause: debug_overlap_issue_cause(overlap),
            fix: debug_overlap_issue_fix(overlap),
        });
    }
}

fn collect_debug_resource_issues(
    resources: &[DebugResourceRecord],
    issues: &mut Vec<DebugIssueRecord>,
) {
    for record in resources {
        let Some(status) = debug_resource_issue_status(record.status) else {
            continue;
        };
        let reference = record.references.first();
        issues.push(DebugIssueRecord {
            status,
            source: DebugIssueSource::Resource,
            label: record
                .issue
                .map(|issue| issue.label().to_owned())
                .unwrap_or_else(|| record.status.label().to_owned()),
            node: reference.map(|reference| reference.node),
            node_name: reference.map(|reference| reference.name.clone()),
            summary: record.summary.clone(),
            cause: record.cause.clone(),
            fix: record.fix.clone(),
        });
    }
}

fn collect_debug_route_issues(routes: &[DebugEventRouteTrace], issues: &mut Vec<DebugIssueRecord>) {
    for route in routes {
        if route.target.is_none() {
            issues.push(DebugIssueRecord {
                status: DebugFrameTraceStatus::Info,
                source: DebugIssueSource::EventRoute,
                label: "no-route-target".to_owned(),
                node: None,
                node_name: None,
                summary: format!(
                    "{:?} at {} had no target",
                    route.event,
                    format_debug_point(route.point)
                ),
                cause: "no hit-test candidate accepted the pointer event".to_owned(),
                fix: "inspect hitboxes, clips, pointer behavior, and disabled nodes at this point"
                    .to_owned(),
            });
            continue;
        }
        for candidate in route
            .candidates
            .iter()
            .filter(|candidate| candidate.point_hit && !candidate.selected)
            .take(2)
        {
            issues.push(DebugIssueRecord {
                status: DebugFrameTraceStatus::Info,
                source: DebugIssueSource::EventRoute,
                label: "route-candidate-rejected".to_owned(),
                node: Some(candidate.id),
                node_name: Some(candidate.name.clone()),
                summary: format!("{} hit the point but did not receive {:?}", candidate.name, route.event),
                cause: debug_route_candidate_issue_cause(candidate),
                fix: "use pointer_probe_panel or event_route_panel to compare z order, clips, and input behavior"
                    .to_owned(),
            });
        }
    }
}

fn collect_debug_selected_node_issue(
    selected: &DebugNodeExplanation,
    issues: &mut Vec<DebugIssueRecord>,
) {
    let status = DebugFrameTraceStatus::from(selected.status);
    if matches!(status, DebugFrameTraceStatus::Ok) {
        return;
    }
    issues.push(DebugIssueRecord {
        status,
        source: DebugIssueSource::SelectedNode,
        label: "selected-node".to_owned(),
        node: Some(selected.node),
        node_name: Some(selected.name.clone()),
        summary: selected.summary.clone(),
        cause: selected.layout.cause.clone(),
        fix: debug_selected_node_issue_fix(selected),
    });
}

fn finish_debug_issue_report(
    frame_label: String,
    mut issues: Vec<DebugIssueRecord>,
) -> DebugIssueReport {
    issues.sort_by(|left, right| {
        right
            .status
            .cmp(&left.status)
            .then_with(|| left.source.cmp(&right.source))
            .then_with(|| left.label.cmp(&right.label))
            .then_with(|| left.node_name.cmp(&right.node_name))
            .then_with(|| left.summary.cmp(&right.summary))
    });
    let error_count = issues
        .iter()
        .filter(|issue| issue.status == DebugFrameTraceStatus::Error)
        .count();
    let warning_count = issues
        .iter()
        .filter(|issue| issue.status == DebugFrameTraceStatus::Warning)
        .count();
    let info_count = issues
        .iter()
        .filter(|issue| issue.status == DebugFrameTraceStatus::Info)
        .count();
    let issue_count = issues.len();
    let status = issues
        .iter()
        .map(|issue| issue.status)
        .max()
        .unwrap_or(DebugFrameTraceStatus::Ok);
    let summary =
        debug_issue_report_summary(status, issue_count, error_count, warning_count, info_count);
    DebugIssueReport {
        frame_label,
        status,
        issue_count,
        error_count,
        warning_count,
        info_count,
        issues,
        summary,
    }
}

fn debug_issue_timeline_frame_record(
    index: usize,
    trace: &DebugFrameTrace,
    report: &DebugIssueReport,
) -> DebugIssueTimelineFrameRecord {
    let top = report.issues.first();
    let source_counts = debug_issue_source_counts(&report.issues);
    let label = debug_frame_timeline_label(trace, index);
    let summary = debug_issue_timeline_frame_summary(
        &label,
        report.status,
        report.issue_count,
        top.map(|issue| issue.source),
        top.map(|issue| issue.label.as_str()),
    );
    DebugIssueTimelineFrameRecord {
        index,
        label,
        frame_index: trace.frame_index,
        status: report.status,
        issue_count: report.issue_count,
        error_count: report.error_count,
        warning_count: report.warning_count,
        info_count: report.info_count,
        top_source: top.map(|issue| issue.source),
        top_issue_label: top.map(|issue| issue.label.clone()),
        source_counts,
        summary,
    }
}

fn debug_issue_timeline_source_records(
    traces: &[&DebugFrameTrace],
    reports: &[DebugIssueReport],
) -> Vec<DebugIssueTimelineSourceRecord> {
    debug_issue_sources()
        .into_iter()
        .map(|source| debug_issue_timeline_source_record(source, traces, reports))
        .collect()
}

fn debug_issue_timeline_source_record(
    source: DebugIssueSource,
    traces: &[&DebugFrameTrace],
    reports: &[DebugIssueReport],
) -> DebugIssueTimelineSourceRecord {
    let mut issue_count = 0;
    let mut error_count = 0;
    let mut warning_count = 0;
    let mut info_count = 0;
    let mut frame_count = 0;
    let mut new_issue_count = 0;
    let mut resolved_issue_count = 0;
    let mut persistent_issue_count = 0;
    let mut top_issue = None::<&DebugIssueRecord>;
    let mut top_frame_label = None::<String>;
    let mut previous_keys = BTreeSet::<String>::new();
    let mut previous_seen = false;

    for (index, report) in reports.iter().enumerate() {
        let issues = report
            .issues
            .iter()
            .filter(|issue| issue.source == source)
            .collect::<Vec<_>>();
        if !issues.is_empty() {
            frame_count += 1;
            if top_issue.is_none() {
                top_issue = issues.first().copied();
                top_frame_label = traces
                    .get(index)
                    .map(|trace| debug_frame_timeline_label(trace, index));
            }
        }
        issue_count += issues.len();
        error_count += issues
            .iter()
            .filter(|issue| issue.status == DebugFrameTraceStatus::Error)
            .count();
        warning_count += issues
            .iter()
            .filter(|issue| issue.status == DebugFrameTraceStatus::Warning)
            .count();
        info_count += issues
            .iter()
            .filter(|issue| issue.status == DebugFrameTraceStatus::Info)
            .count();

        let current_keys = issues
            .iter()
            .map(|issue| debug_issue_timeline_fingerprint(issue))
            .collect::<BTreeSet<_>>();
        if previous_seen {
            new_issue_count += current_keys.difference(&previous_keys).count();
            resolved_issue_count += previous_keys.difference(&current_keys).count();
            persistent_issue_count += current_keys.intersection(&previous_keys).count();
        }
        previous_keys = current_keys;
        previous_seen = true;
    }

    let status = if error_count > 0 {
        DebugFrameTraceStatus::Error
    } else if warning_count > 0 {
        DebugFrameTraceStatus::Warning
    } else if info_count > 0 || new_issue_count > 0 || resolved_issue_count > 0 {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    };
    let top_issue_label = top_issue.map(|issue| issue.label.clone());
    let summary = debug_issue_timeline_source_summary(
        source,
        status,
        frame_count,
        issue_count,
        new_issue_count,
        resolved_issue_count,
        top_issue_label.as_deref(),
    );
    DebugIssueTimelineSourceRecord {
        source,
        status,
        frame_count,
        issue_count,
        error_count,
        warning_count,
        info_count,
        new_issue_count,
        resolved_issue_count,
        persistent_issue_count,
        top_frame_label,
        top_issue_label,
        inspect: debug_issue_source_inspect(source).to_owned(),
        summary,
        cause: top_issue
            .map(|issue| issue.cause.clone())
            .unwrap_or_else(|| {
                "no issue from this source was captured across retained frames".to_owned()
            }),
        fix: top_issue
            .map(|issue| issue.fix.clone())
            .unwrap_or_else(|| "no action needed for this issue source".to_owned()),
    }
}

fn debug_issue_source_counts(issues: &[DebugIssueRecord]) -> Vec<(DebugIssueSource, usize)> {
    let mut counts = debug_issue_sources()
        .into_iter()
        .filter_map(|source| {
            let count = issues.iter().filter(|issue| issue.source == source).count();
            (count > 0).then_some((source, count))
        })
        .collect::<Vec<_>>();
    counts.sort_by(|left, right| left.0.cmp(&right.0));
    counts
}

fn debug_issue_timeline_fingerprint(issue: &DebugIssueRecord) -> String {
    format!(
        "{}:{}:{}:{}",
        issue.source.label(),
        issue.label,
        issue.node_name.as_deref().unwrap_or("none"),
        issue.summary
    )
}

fn debug_issue_sources() -> Vec<DebugIssueSource> {
    vec![
        DebugIssueSource::Performance,
        DebugIssueSource::Constraint,
        DebugIssueSource::PaintHit,
        DebugIssueSource::TextFit,
        DebugIssueSource::Overlap,
        DebugIssueSource::Resource,
        DebugIssueSource::EventRoute,
        DebugIssueSource::SelectedNode,
    ]
}

fn debug_issue_source_inspect(source: DebugIssueSource) -> &'static str {
    match source {
        DebugIssueSource::Performance => "frame_budget_panel",
        DebugIssueSource::Constraint => "constraint_issues_panel",
        DebugIssueSource::PaintHit => "paint_hit_mismatch_panel",
        DebugIssueSource::TextFit => "text_fit_panel",
        DebugIssueSource::Overlap => "overlap_report_panel",
        DebugIssueSource::Resource => "resource_diagnostics_panel",
        DebugIssueSource::EventRoute => "event_route_panel",
        DebugIssueSource::SelectedNode => "inspect_node_panel",
    }
}

fn debug_issue_timeline_summary(
    status: DebugFrameTraceStatus,
    frame_count: usize,
    issue_frame_count: usize,
    changed_frame_count: usize,
    issue_count: usize,
    new_issue_count: usize,
    resolved_issue_count: usize,
    top_source: Option<DebugIssueSource>,
) -> String {
    let mut parts = vec![format!("{} issue timeline", status.label())];
    parts.push(format!(
        "{frame_count} frame{}",
        debug_plural_s(frame_count)
    ));
    if issue_frame_count > 0 {
        parts.push(format!("{issue_frame_count} issue frames"));
    }
    if changed_frame_count > 0 {
        parts.push(format!("{changed_frame_count} changed"));
    }
    if issue_count > 0 {
        parts.push(format!("{issue_count} issues"));
    }
    if new_issue_count > 0 {
        parts.push(format!("{new_issue_count} new"));
    }
    if resolved_issue_count > 0 {
        parts.push(format!("{resolved_issue_count} resolved"));
    }
    if let Some(source) = top_source {
        parts.push(format!("top {}", source.title()));
    }
    parts.join("; ")
}

fn debug_issue_timeline_frame_summary(
    label: &str,
    status: DebugFrameTraceStatus,
    issue_count: usize,
    top_source: Option<DebugIssueSource>,
    top_issue_label: Option<&str>,
) -> String {
    let mut parts = vec![format!("{label} issues {}", status.label())];
    parts.push(format!(
        "{issue_count} issue{}",
        debug_plural_s(issue_count)
    ));
    if let Some(source) = top_source {
        parts.push(format!("top {}", source.title()));
    }
    if let Some(label) = top_issue_label {
        parts.push(label.to_owned());
    }
    parts.join("; ")
}

fn debug_issue_timeline_source_summary(
    source: DebugIssueSource,
    status: DebugFrameTraceStatus,
    frame_count: usize,
    issue_count: usize,
    new_issue_count: usize,
    resolved_issue_count: usize,
    top_issue_label: Option<&str>,
) -> String {
    let mut parts = vec![format!("{} {}", status.label(), source.title())];
    parts.push(format!(
        "{frame_count} frame{}",
        debug_plural_s(frame_count)
    ));
    parts.push(format!(
        "{issue_count} issue{}",
        debug_plural_s(issue_count)
    ));
    if new_issue_count > 0 {
        parts.push(format!("{new_issue_count} new"));
    }
    if resolved_issue_count > 0 {
        parts.push(format!("{resolved_issue_count} resolved"));
    }
    if let Some(label) = top_issue_label {
        parts.push(format!("top {label}"));
    }
    parts.join("; ")
}

fn debug_issue_report_summary(
    status: DebugFrameTraceStatus,
    issue_count: usize,
    error_count: usize,
    warning_count: usize,
    info_count: usize,
) -> String {
    if issue_count == 0 {
        return "ok debug triage; no issues".to_owned();
    }
    let mut parts = vec![format!("{} debug triage", status.label())];
    parts.push(format!("{issue_count} issues"));
    if error_count > 0 {
        parts.push(format!("{error_count} errors"));
    }
    if warning_count > 0 {
        parts.push(format!("{warning_count} warnings"));
    }
    if info_count > 0 {
        parts.push(format!("{info_count} info"));
    }
    parts.join("; ")
}

fn debug_contract_budget_check(budget: &DebugFrameBudgetTrace) -> DebugContractCheckRecord {
    let issue_count = usize::from(debug_contract_status_fails(budget.status));
    let cause = budget
        .slowest_stage
        .as_ref()
        .map(|stage| {
            format!(
                "{stage} was the slowest stage; {}",
                budget
                    .primary_dirty_cause
                    .as_deref()
                    .unwrap_or("dirty-state context was not captured")
            )
        })
        .unwrap_or_else(|| "frame timing had no captured pipeline stages".to_owned());
    let fix = if budget.over_budget_by.is_some() {
        "open frame_budget_panel and frame_autopsy_panel; reduce the dominant stage or narrow dirty invalidation"
            .to_owned()
    } else if budget.status == DebugFrameTraceStatus::Info {
        "watch the dominant stage; this frame is close to its supplied budget".to_owned()
    } else {
        "no frame-budget action needed".to_owned()
    };
    debug_contract_record(
        DebugContractCheckKind::FrameBudget,
        budget.status,
        true,
        issue_count,
        budget.summary.clone(),
        cause,
        fix,
    )
}

fn debug_contract_constraint_check(issues: &[DebugConstraintIssue]) -> DebugContractCheckRecord {
    let status = debug_contract_status_from_iter(
        issues
            .iter()
            .map(|issue| debug_constraint_status(issue.severity)),
    );
    let issue_count = issues
        .iter()
        .filter(|issue| debug_contract_status_fails(debug_constraint_status(issue.severity)))
        .count();
    let summary = if issues.is_empty() {
        "no constraint issues".to_owned()
    } else {
        format!("{} constraint issues", issues.len())
    };
    let cause = issues
        .first()
        .map(|issue| issue.summary.clone())
        .unwrap_or_else(|| "layout audit and geometry constraints passed".to_owned());
    let fix = issues
        .first()
        .map(|issue| issue.fix.clone())
        .unwrap_or_else(|| "no constraint action needed".to_owned());
    debug_contract_record(
        DebugContractCheckKind::Constraints,
        status,
        true,
        issue_count,
        summary,
        cause,
        fix,
    )
}

fn debug_contract_overlap_check(overlaps: &[DebugOverlapRecord]) -> DebugContractCheckRecord {
    let interactive_count = overlaps
        .iter()
        .filter(|overlap| overlap.kind == DebugOverlapKind::InteractiveHitbox)
        .count();
    let paint_count = overlaps
        .iter()
        .filter(|overlap| overlap.kind == DebugOverlapKind::Paint)
        .count();
    let layout_count = overlaps
        .iter()
        .filter(|overlap| overlap.kind == DebugOverlapKind::Layout)
        .count();
    let status = if interactive_count > 0 {
        DebugFrameTraceStatus::Warning
    } else if !overlaps.is_empty() {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    };
    let mut summary_parts = vec![format!("{} overlaps", overlaps.len())];
    if interactive_count > 0 {
        summary_parts.push(format!("{interactive_count} interactive"));
    }
    if paint_count > 0 {
        summary_parts.push(format!("{paint_count} paint"));
    }
    if layout_count > 0 {
        summary_parts.push(format!("{layout_count} layout"));
    }
    let cause = overlaps
        .first()
        .map(|overlap| {
            format!(
                "{} overlap between {} and {}",
                debug_overlap_kind_label(overlap.kind),
                overlap.back.name,
                overlap.front.name
            )
        })
        .unwrap_or_else(|| "no hitbox, paint, or layout overlaps were recorded".to_owned());
    let fix = if interactive_count > 0 {
        "open overlap_report_panel or pointer_probe_panel; separate, clip, disable, or reorder competing hit regions"
            .to_owned()
    } else if !overlaps.is_empty() {
        "verify visual/layout overlaps in paint_order_panel, visual_effects_panel, or layout_cause_panel"
            .to_owned()
    } else {
        "no overlap action needed".to_owned()
    };
    debug_contract_record(
        DebugContractCheckKind::Overlaps,
        status,
        true,
        interactive_count,
        summary_parts.join("; "),
        cause,
        fix,
    )
}

fn debug_contract_hit_target_check(trace: &DebugHitTargetTrace) -> DebugContractCheckRecord {
    let issue = trace
        .records
        .iter()
        .find(|record| debug_contract_status_fails(record.status));
    debug_contract_record(
        DebugContractCheckKind::HitTargets,
        trace.status,
        true,
        trace.issue_count,
        trace.summary.clone(),
        issue
            .map(|record| record.cause.clone())
            .unwrap_or_else(|| "interactive nodes have effective hit targets".to_owned()),
        issue
            .map(|record| record.fix.clone())
            .unwrap_or_else(|| "no hit-target action needed".to_owned()),
    )
}

fn debug_contract_text_fit_check(trace: Option<&DebugTextFitTrace>) -> DebugContractCheckRecord {
    let Some(trace) = trace else {
        return debug_contract_record(
            DebugContractCheckKind::TextFit,
            DebugFrameTraceStatus::Info,
            false,
            0,
            "text fit not captured".to_owned(),
            "the contract report was built without DebugTextFitTrace for this document".to_owned(),
            "build DebugTextFitTrace from the same document when localization, wrapping, or clipping matters"
                .to_owned(),
        );
    };
    let issue = trace
        .records
        .iter()
        .find(|record| debug_contract_status_fails(record.status));
    debug_contract_record(
        DebugContractCheckKind::TextFit,
        trace.status,
        true,
        trace.issue_count,
        trace.summary.clone(),
        issue
            .map(|record| record.cause.clone())
            .unwrap_or_else(|| "text nodes fit within measured layout and clips".to_owned()),
        issue
            .map(|record| record.fix.clone())
            .unwrap_or_else(|| "no text-fit action needed".to_owned()),
    )
}

fn debug_contract_resource_check(report: &DebugResourceReport) -> DebugContractCheckRecord {
    let status = debug_contract_status_from_iter(
        report
            .records
            .iter()
            .filter_map(|record| debug_resource_issue_status(record.status)),
    );
    let issue_count = report
        .records
        .iter()
        .filter(|record| debug_resource_issue_status(record.status).is_some())
        .count();
    let issue = report
        .records
        .iter()
        .find(|record| debug_resource_issue_status(record.status).is_some());
    debug_contract_record(
        DebugContractCheckKind::Resources,
        status,
        true,
        issue_count,
        report.summary(),
        issue
            .map(|record| record.cause.clone())
            .unwrap_or_else(|| "resource references and updates resolved cleanly".to_owned()),
        issue
            .map(|record| record.fix.clone())
            .unwrap_or_else(|| "no resource action needed".to_owned()),
    )
}

fn debug_contract_route_check(routes: &[DebugEventRouteTrace]) -> DebugContractCheckRecord {
    if routes.is_empty() {
        return debug_contract_record(
            DebugContractCheckKind::EventRoutes,
            DebugFrameTraceStatus::Info,
            false,
            0,
            "event routes not captured".to_owned(),
            "no pointer or input routes were attached to this frame trace".to_owned(),
            "attach DebugEventRouteTrace samples for the points or controls being debugged"
                .to_owned(),
        );
    }
    let missing_target_count = routes.iter().filter(|route| route.target.is_none()).count();
    let rejected_hit_count = routes
        .iter()
        .flat_map(|route| route.candidates.iter())
        .filter(|candidate| candidate.point_hit && !candidate.selected)
        .count();
    let status = if missing_target_count > 0 {
        DebugFrameTraceStatus::Warning
    } else if rejected_hit_count > 0 {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    };
    let mut summary_parts = vec![format!("{} event routes", routes.len())];
    if missing_target_count > 0 {
        summary_parts.push(format!("{missing_target_count} without targets"));
    }
    if rejected_hit_count > 0 {
        summary_parts.push(format!("{rejected_hit_count} rejected hit candidates"));
    }
    let cause = routes
        .iter()
        .find(|route| route.target.is_none())
        .map(|route| {
            format!(
                "{:?} at {} had no accepted target",
                route.event,
                format_debug_point(route.point)
            )
        })
        .or_else(|| {
            routes
                .iter()
                .flat_map(|route| route.candidates.iter())
                .find(|candidate| candidate.point_hit && !candidate.selected)
                .map(|candidate| {
                    format!(
                        "{} hit the point but another node received the event",
                        candidate.name
                    )
                })
        })
        .unwrap_or_else(|| "captured event routes selected an effective target".to_owned());
    let fix = if missing_target_count > 0 {
        "open event_route_panel and pointer_probe_panel to inspect hit-test rejection, clips, z order, and input behavior"
            .to_owned()
    } else if rejected_hit_count > 0 {
        "use pointer_probe_panel to compare candidate ordering and occlusion at the routed point"
            .to_owned()
    } else {
        "no event-route action needed".to_owned()
    };
    debug_contract_record(
        DebugContractCheckKind::EventRoutes,
        status,
        true,
        missing_target_count + rejected_hit_count,
        summary_parts.join("; "),
        cause,
        fix,
    )
}

fn debug_contract_selected_node_check(
    selected: Option<&DebugNodeExplanation>,
) -> DebugContractCheckRecord {
    let Some(selected) = selected else {
        return debug_contract_record(
            DebugContractCheckKind::SelectedNode,
            DebugFrameTraceStatus::Info,
            false,
            0,
            "selected node not captured".to_owned(),
            "the frame trace did not include selected-node context".to_owned(),
            "set DebugFrameTraceContext::selected_node when debugging one control, panel, or hitbox"
                .to_owned(),
        );
    };
    let status = DebugFrameTraceStatus::from(selected.status);
    debug_contract_record(
        DebugContractCheckKind::SelectedNode,
        status,
        true,
        usize::from(status != DebugFrameTraceStatus::Ok),
        selected.summary.clone(),
        selected.layout.cause.clone(),
        debug_selected_node_issue_fix(selected),
    )
}

fn debug_contract_accessibility_check(
    trace: &DebugAccessibilityTreeTrace,
) -> DebugContractCheckRecord {
    let status = if trace.warning_count > 0 {
        DebugFrameTraceStatus::Warning
    } else {
        DebugFrameTraceStatus::Ok
    };
    let issue = trace.nodes.iter().find(|node| node.warning_count > 0);
    debug_contract_record(
        DebugContractCheckKind::Accessibility,
        status,
        true,
        trace.warning_count,
        trace.summary.clone(),
        issue
            .map(|node| node.cause.clone())
            .unwrap_or_else(|| "accessibility metadata has no recorded warnings".to_owned()),
        issue
            .map(|node| node.fix.clone())
            .unwrap_or_else(|| "no accessibility action needed".to_owned()),
    )
}

fn debug_contract_cache_check(trace: Option<&DebugCacheReuseTrace>) -> DebugContractCheckRecord {
    let Some(trace) = trace else {
        return debug_contract_record(
            DebugContractCheckKind::CacheReuse,
            DebugFrameTraceStatus::Info,
            false,
            0,
            "cache reuse not captured".to_owned(),
            "the contract report was built without DebugCacheReuseTrace for this frame".to_owned(),
            "pass DebugCacheReuseTrace from the same frame to explain cache misses and display-list reuse"
                .to_owned(),
        );
    };
    let issue_count = trace
        .records
        .iter()
        .filter(|record| record.status != DebugFrameTraceStatus::Ok)
        .count()
        + trace
            .display_lists
            .iter()
            .filter(|record| record.status != DebugFrameTraceStatus::Ok)
            .count();
    let issue = trace
        .records
        .iter()
        .find(|record| record.status != DebugFrameTraceStatus::Ok)
        .map(|record| (record.cause.clone(), record.fix.clone()))
        .or_else(|| {
            trace
                .display_lists
                .iter()
                .find(|record| record.status != DebugFrameTraceStatus::Ok)
                .map(|record| (record.cause.clone(), record.fix.clone()))
        });
    debug_contract_record(
        DebugContractCheckKind::CacheReuse,
        trace.status,
        true,
        issue_count,
        trace.summary.clone(),
        issue
            .as_ref()
            .map(|(cause, _)| cause.clone())
            .unwrap_or_else(|| "captured caches reused retained frame work".to_owned()),
        issue
            .map(|(_, fix)| fix)
            .unwrap_or_else(|| "no cache action needed".to_owned()),
    )
}

fn debug_contract_record(
    kind: DebugContractCheckKind,
    status: DebugFrameTraceStatus,
    checked: bool,
    issue_count: usize,
    summary: String,
    cause: String,
    fix: String,
) -> DebugContractCheckRecord {
    DebugContractCheckRecord {
        kind,
        status,
        checked,
        passed: checked && !debug_contract_status_fails(status),
        issue_count,
        summary,
        cause,
        fix,
    }
}

fn finish_debug_contract_report(
    frame_label: String,
    mut checks: Vec<DebugContractCheckRecord>,
) -> DebugContractReport {
    checks.sort_by(|left, right| {
        debug_contract_check_rank(left)
            .cmp(&debug_contract_check_rank(right))
            .then_with(|| {
                debug_contract_kind_rank(left.kind).cmp(&debug_contract_kind_rank(right.kind))
            })
    });
    let check_count = checks.len();
    let pass_count = checks
        .iter()
        .filter(|check| check.checked && check.passed)
        .count();
    let fail_count = checks
        .iter()
        .filter(|check| check.checked && !check.passed)
        .count();
    let error_count = checks
        .iter()
        .filter(|check| check.checked && check.status == DebugFrameTraceStatus::Error)
        .count();
    let warning_count = checks
        .iter()
        .filter(|check| check.checked && check.status == DebugFrameTraceStatus::Warning)
        .count();
    let info_count = checks
        .iter()
        .filter(|check| check.checked && check.status == DebugFrameTraceStatus::Info)
        .count();
    let skipped_count = checks.iter().filter(|check| !check.checked).count();
    let status =
        debug_contract_report_status(error_count, warning_count, info_count, skipped_count);
    let summary = debug_contract_report_summary(
        status,
        check_count,
        pass_count,
        fail_count,
        skipped_count,
        error_count,
        warning_count,
        info_count,
    );
    DebugContractReport {
        frame_label,
        status,
        check_count,
        pass_count,
        fail_count,
        error_count,
        warning_count,
        info_count,
        skipped_count,
        checks,
        summary,
    }
}

fn debug_contract_report_status(
    error_count: usize,
    warning_count: usize,
    info_count: usize,
    skipped_count: usize,
) -> DebugFrameTraceStatus {
    if error_count > 0 {
        DebugFrameTraceStatus::Error
    } else if warning_count > 0 {
        DebugFrameTraceStatus::Warning
    } else if info_count > 0 || skipped_count > 0 {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    }
}

#[allow(clippy::too_many_arguments)]
fn debug_contract_report_summary(
    status: DebugFrameTraceStatus,
    check_count: usize,
    pass_count: usize,
    fail_count: usize,
    skipped_count: usize,
    error_count: usize,
    warning_count: usize,
    info_count: usize,
) -> String {
    let mut parts = vec![format!("{} debug contract", status.label())];
    parts.push(format!("{check_count} checks"));
    parts.push(format!("{pass_count} passed"));
    if fail_count > 0 {
        parts.push(format!("{fail_count} failed"));
    }
    if skipped_count > 0 {
        parts.push(format!("{skipped_count} skipped"));
    }
    if error_count > 0 {
        parts.push(format!("{error_count} errors"));
    }
    if warning_count > 0 {
        parts.push(format!("{warning_count} warnings"));
    }
    if info_count > 0 {
        parts.push(format!("{info_count} info"));
    }
    parts.join("; ")
}

fn debug_contract_status_from_iter(
    statuses: impl IntoIterator<Item = DebugFrameTraceStatus>,
) -> DebugFrameTraceStatus {
    let mut result = DebugFrameTraceStatus::Ok;
    for status in statuses {
        match status {
            DebugFrameTraceStatus::Error => return DebugFrameTraceStatus::Error,
            DebugFrameTraceStatus::Warning => result = DebugFrameTraceStatus::Warning,
            DebugFrameTraceStatus::Info if result == DebugFrameTraceStatus::Ok => {
                result = DebugFrameTraceStatus::Info;
            }
            DebugFrameTraceStatus::Ok | DebugFrameTraceStatus::Info => {}
        }
    }
    result
}

fn debug_contract_status_fails(status: DebugFrameTraceStatus) -> bool {
    matches!(
        status,
        DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
    )
}

fn debug_contract_check_rank(check: &DebugContractCheckRecord) -> u8 {
    if !check.checked {
        return 3;
    }
    match check.status {
        DebugFrameTraceStatus::Error => 0,
        DebugFrameTraceStatus::Warning => 1,
        DebugFrameTraceStatus::Info => 2,
        DebugFrameTraceStatus::Ok => 4,
    }
}

fn debug_contract_kind_rank(kind: DebugContractCheckKind) -> u8 {
    match kind {
        DebugContractCheckKind::FrameBudget => 0,
        DebugContractCheckKind::Constraints => 1,
        DebugContractCheckKind::Overlaps => 2,
        DebugContractCheckKind::HitTargets => 3,
        DebugContractCheckKind::TextFit => 4,
        DebugContractCheckKind::Resources => 5,
        DebugContractCheckKind::EventRoutes => 6,
        DebugContractCheckKind::SelectedNode => 7,
        DebugContractCheckKind::Accessibility => 8,
        DebugContractCheckKind::CacheReuse => 9,
    }
}

fn debug_invariant_interactive_overlap_record(
    snapshot: &DebugInspectorSnapshot,
) -> DebugInvariantRecord {
    let overlaps = snapshot
        .overlaps
        .iter()
        .filter(|overlap| overlap.kind == DebugOverlapKind::InteractiveHitbox)
        .collect::<Vec<_>>();
    let issue_count = overlaps.len();
    let status = if issue_count > 0 {
        DebugFrameTraceStatus::Warning
    } else {
        DebugFrameTraceStatus::Ok
    };
    let subjects = overlaps
        .iter()
        .take(5)
        .map(|overlap| format!("{} / {}", overlap.back.name, overlap.front.name))
        .collect::<Vec<_>>();
    let summary = if issue_count == 0 {
        "no interactive overlaps".to_owned()
    } else {
        format!(
            "{issue_count} interactive overlap{}",
            debug_plural_s(issue_count)
        )
    };
    let cause = overlaps
        .first()
        .map(|overlap| {
            format!(
                "{} overlaps {} at {}",
                overlap.front.name,
                overlap.back.name,
                debug_rect_label(overlap.overlap_rect)
            )
        })
        .unwrap_or_else(|| "interactive hitboxes do not overlap".to_owned());
    let fix = if issue_count > 0 {
        "open overlap_report_panel and hitbox_debug_overlay; separate hitboxes, change z/order, or make one passive"
            .to_owned()
    } else {
        "no overlap action needed".to_owned()
    };
    debug_invariant_record(
        DebugInvariantKind::NoInteractiveOverlap,
        status,
        true,
        issue_count,
        subjects,
        "overlap_report_panel",
        summary,
        cause,
        fix,
    )
}

fn debug_invariant_clipped_text_record(trace: Option<&DebugTextFitTrace>) -> DebugInvariantRecord {
    let Some(trace) = trace else {
        return debug_invariant_record(
            DebugInvariantKind::NoClippedText,
            DebugFrameTraceStatus::Info,
            false,
            0,
            Vec::new(),
            "text_fit_panel",
            "text clipping not checked",
            "DebugTextFitTrace was not supplied with the snapshot",
            "build DebugTextFitTrace from the same document or use DebugInvariantTrace::from_document",
        );
    };
    let issues = trace
        .records
        .iter()
        .filter(|record| {
            record.clip_reduces_text || record.horizontal_overflow || record.vertical_overflow
        })
        .collect::<Vec<_>>();
    let issue_count = issues.len();
    let status = debug_contract_status_from_iter(issues.iter().map(|record| record.status));
    let subjects = issues
        .iter()
        .take(5)
        .map(|record| record.name.clone())
        .collect::<Vec<_>>();
    let summary = if issue_count == 0 {
        "no clipped or overflowing text".to_owned()
    } else {
        format!(
            "{issue_count} clipped/overflowing text node{}",
            debug_plural_s(issue_count)
        )
    };
    let cause = issues
        .first()
        .map(|record| record.cause.clone())
        .unwrap_or_else(|| "measured text fits within layout and clip bounds".to_owned());
    let fix = issues
        .first()
        .map(|record| record.fix.clone())
        .unwrap_or_else(|| "no text-fit action needed".to_owned());
    debug_invariant_record(
        DebugInvariantKind::NoClippedText,
        status,
        true,
        issue_count,
        subjects,
        "text_fit_panel",
        summary,
        cause,
        fix,
    )
}

fn debug_invariant_zero_size_interactive_record(
    snapshot: &DebugInspectorSnapshot,
) -> DebugInvariantRecord {
    let mut seen = HashSet::new();
    let mut issues = Vec::new();
    for node in snapshot.nodes.iter().filter(|node| {
        (node.input.pointer || node.input.focusable) && debug_invariant_zero_size_rect(node.rect)
    }) {
        seen.insert(node.id);
        issues.push((
            node.name.clone(),
            format!(
                "{} has resolved layout {}",
                node.name,
                debug_rect_label(node.rect)
            ),
        ));
    }
    for hitbox in snapshot.hitboxes.iter().filter(|hitbox| {
        (hitbox.pointer || hitbox.focusable)
            && (debug_invariant_zero_size_rect(hitbox.rect)
                || hitbox.hit_rect.is_some_and(debug_invariant_zero_size_rect))
    }) {
        if seen.insert(hitbox.id) {
            let cause = if hitbox.hit_rect.is_some_and(debug_invariant_zero_size_rect) {
                format!(
                    "{} has effective hit region {}",
                    hitbox.name,
                    debug_optional_rect_label(hitbox.hit_rect)
                )
            } else {
                format!(
                    "{} has resolved layout {}",
                    hitbox.name,
                    debug_rect_label(hitbox.rect)
                )
            };
            issues.push((hitbox.name.clone(), cause));
        }
    }
    let issue_count = issues.len();
    let status = if issue_count > 0 {
        DebugFrameTraceStatus::Warning
    } else {
        DebugFrameTraceStatus::Ok
    };
    let subjects = issues
        .iter()
        .take(5)
        .map(|(name, _)| name.clone())
        .collect::<Vec<_>>();
    let summary = if issue_count == 0 {
        "no zero-size interactive controls".to_owned()
    } else {
        format!(
            "{issue_count} zero-size interactive control{}",
            debug_plural_s(issue_count)
        )
    };
    let cause = issues
        .first()
        .map(|(_, cause)| cause.clone())
        .unwrap_or_else(|| "interactive controls have non-empty layout and hit regions".to_owned());
    let fix = if issue_count > 0 {
        "open hit_target_panel and layout_autopsy_panel; give the control explicit size, content, padding, or a valid hit shape"
            .to_owned()
    } else {
        "no zero-size control action needed".to_owned()
    };
    debug_invariant_record(
        DebugInvariantKind::NoZeroSizeInteractive,
        status,
        true,
        issue_count,
        subjects,
        "hit_target_panel",
        summary,
        cause,
        fix,
    )
}

