#[allow(clippy::too_many_arguments)]
fn debug_invariant_record(
    kind: DebugInvariantKind,
    status: DebugFrameTraceStatus,
    checked: bool,
    issue_count: usize,
    subjects: Vec<String>,
    panel: impl Into<String>,
    summary: impl Into<String>,
    cause: impl Into<String>,
    fix: impl Into<String>,
) -> DebugInvariantRecord {
    DebugInvariantRecord {
        kind,
        status,
        checked,
        passed: checked && issue_count == 0 && !debug_contract_status_fails(status),
        issue_count,
        subjects,
        panel: panel.into(),
        summary: summary.into(),
        cause: cause.into(),
        fix: fix.into(),
    }
}

fn finish_debug_invariant_trace(mut records: Vec<DebugInvariantRecord>) -> DebugInvariantTrace {
    records.sort_by(|left, right| {
        debug_invariant_record_rank(left)
            .cmp(&debug_invariant_record_rank(right))
            .then_with(|| {
                debug_invariant_kind_rank(left.kind).cmp(&debug_invariant_kind_rank(right.kind))
            })
    });
    let invariant_count = records.len();
    let passed_count = records
        .iter()
        .filter(|record| record.checked && record.passed)
        .count();
    let failed_count = records
        .iter()
        .filter(|record| record.checked && !record.passed)
        .count();
    let skipped_count = records.iter().filter(|record| !record.checked).count();
    let error_count = records
        .iter()
        .filter(|record| record.checked && record.status == DebugFrameTraceStatus::Error)
        .count();
    let warning_count = records
        .iter()
        .filter(|record| record.checked && record.status == DebugFrameTraceStatus::Warning)
        .count();
    let status = debug_invariant_trace_status(error_count, warning_count, skipped_count);
    let summary = debug_invariant_trace_summary(
        status,
        invariant_count,
        passed_count,
        failed_count,
        skipped_count,
        error_count,
        warning_count,
    );
    DebugInvariantTrace {
        status,
        invariant_count,
        passed_count,
        failed_count,
        skipped_count,
        error_count,
        warning_count,
        records,
        summary,
    }
}

fn debug_invariant_trace_status(
    error_count: usize,
    warning_count: usize,
    skipped_count: usize,
) -> DebugFrameTraceStatus {
    if error_count > 0 {
        DebugFrameTraceStatus::Error
    } else if warning_count > 0 {
        DebugFrameTraceStatus::Warning
    } else if skipped_count > 0 {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    }
}

fn debug_invariant_trace_summary(
    status: DebugFrameTraceStatus,
    invariant_count: usize,
    passed_count: usize,
    failed_count: usize,
    skipped_count: usize,
    error_count: usize,
    warning_count: usize,
) -> String {
    let mut parts = vec![format!("{} debug invariants", status.label())];
    parts.push(format!("{invariant_count} checks"));
    parts.push(format!("{passed_count} passed"));
    if failed_count > 0 {
        parts.push(format!("{failed_count} failed"));
    }
    if skipped_count > 0 {
        parts.push(format!("{skipped_count} skipped"));
    }
    if error_count > 0 {
        parts.push(format!("{error_count} errors"));
    }
    if warning_count > 0 {
        parts.push(format!("{warning_count} warnings"));
    }
    parts.join("; ")
}

fn debug_invariant_record_rank(record: &DebugInvariantRecord) -> u8 {
    if !record.checked {
        return 3;
    }
    match record.status {
        DebugFrameTraceStatus::Error => 0,
        DebugFrameTraceStatus::Warning => 1,
        DebugFrameTraceStatus::Info => 2,
        DebugFrameTraceStatus::Ok => 4,
    }
}

fn debug_invariant_kind_rank(kind: DebugInvariantKind) -> u8 {
    match kind {
        DebugInvariantKind::NoInteractiveOverlap => 0,
        DebugInvariantKind::NoClippedText => 1,
        DebugInvariantKind::NoZeroSizeInteractive => 2,
        DebugInvariantKind::NoUnreachableActions => 3,
        DebugInvariantKind::NoPaintHitMismatch => 4,
    }
}

fn debug_invariant_zero_size_rect(rect: UiRect) -> bool {
    rect.width <= 0.5 || rect.height <= 0.5
}

fn debug_constraint_status(severity: DebugConstraintSeverity) -> DebugFrameTraceStatus {
    match severity {
        DebugConstraintSeverity::Error => DebugFrameTraceStatus::Error,
        DebugConstraintSeverity::Warning => DebugFrameTraceStatus::Warning,
        DebugConstraintSeverity::Info => DebugFrameTraceStatus::Info,
    }
}

fn debug_resource_issue_status(status: DebugResourceStatus) -> Option<DebugFrameTraceStatus> {
    match status {
        DebugResourceStatus::Invalid => Some(DebugFrameTraceStatus::Error),
        DebugResourceStatus::Missing
        | DebugResourceStatus::UnusedUpdate
        | DebugResourceStatus::Unresolved => Some(DebugFrameTraceStatus::Warning),
        DebugResourceStatus::Updated | DebugResourceStatus::Resolved => None,
    }
}

fn debug_overlap_issue_cause(overlap: &DebugOverlapRecord) -> String {
    if overlap.reasons.is_empty() {
        return "overlap source was not classified".to_owned();
    }
    overlap
        .reasons
        .iter()
        .map(debug_overlap_reason_label)
        .collect::<Vec<_>>()
        .join(", ")
}

fn debug_overlap_issue_fix(overlap: &DebugOverlapRecord) -> String {
    match overlap.kind {
        DebugOverlapKind::InteractiveHitbox => {
            "inspect hitboxes and z/layer order, then separate the interactive regions or disable one target"
                .to_owned()
        }
        DebugOverlapKind::Paint => {
            "inspect paint outsets, shader/material bounds, and clipping for intentional visual overlap"
                .to_owned()
        }
        DebugOverlapKind::Layout => {
            "inspect parent layout, absolute placement, margins, and sibling pressure".to_owned()
        }
    }
}

fn debug_overlap_autopsy_kind_record(overlap: &DebugOverlapRecord) -> DebugOverlapAutopsyRecord {
    let source = DebugOverlapAutopsySource::Kind;
    let status = match overlap.kind {
        DebugOverlapKind::InteractiveHitbox => DebugFrameTraceStatus::Warning,
        DebugOverlapKind::Paint | DebugOverlapKind::Layout => DebugFrameTraceStatus::Info,
    };
    let summary = format!(
        "{} overlap; {:.0}px2",
        debug_overlap_kind_label(overlap.kind),
        rect_area(overlap.overlap_rect)
    );
    let cause = match overlap.kind {
        DebugOverlapKind::InteractiveHitbox => {
            "both effective hit regions include the same point range, so pointer routing can surprise users"
                .to_owned()
        }
        DebugOverlapKind::Paint => {
            "paint bounds intersect even though effective hitboxes do not collide".to_owned()
        }
        DebugOverlapKind::Layout => {
            "layout rectangles intersect, but no paint or hitbox collision was recorded".to_owned()
        }
    };
    let fix = match overlap.kind {
        DebugOverlapKind::InteractiveHitbox => {
            "separate hit regions, disable one pointer target, or make the intended front target explicit"
                .to_owned()
        }
        DebugOverlapKind::Paint => {
            "verify visual overlap is intentional, or adjust paint outsets, clips, z order, or effects"
                .to_owned()
        }
        DebugOverlapKind::Layout => {
            "inspect parent sizing, absolute placement, margins, and sibling flow".to_owned()
        }
    };
    DebugOverlapAutopsyRecord {
        source,
        status,
        summary,
        cause,
        fix,
    }
}

fn debug_overlap_autopsy_hierarchy_record(
    overlap: &DebugOverlapRecord,
) -> DebugOverlapAutopsyRecord {
    let source = DebugOverlapAutopsySource::Hierarchy;
    let reason = overlap.reasons.iter().find(|reason| {
        matches!(
            reason,
            DebugOverlapReason::SharedParent { .. }
                | DebugOverlapReason::DifferentParents { .. }
                | DebugOverlapReason::AncestorDescendant { .. }
        )
    });
    let status = match reason {
        Some(DebugOverlapReason::SharedParent { .. })
            if overlap.kind == DebugOverlapKind::InteractiveHitbox =>
        {
            DebugFrameTraceStatus::Warning
        }
        Some(_) => DebugFrameTraceStatus::Info,
        None => DebugFrameTraceStatus::Ok,
    };
    let summary = reason
        .map(debug_overlap_reason_label)
        .unwrap_or_else(|| "no hierarchy reason recorded".to_owned());
    let cause = match reason {
        Some(DebugOverlapReason::SharedParent { .. }) => {
            "both nodes are siblings under the same parent, so normal flow, absolute placement, or sibling sizing produced the collision"
                .to_owned()
        }
        Some(DebugOverlapReason::DifferentParents { .. }) => {
            "the nodes come from different parent branches, so parent geometry, layer stacking, or portals likely contribute"
                .to_owned()
        }
        Some(DebugOverlapReason::AncestorDescendant { .. }) => {
            "one node is inside the other; ancestor/descendant intersections can be intentional but may still hide input"
                .to_owned()
        }
        _ => "overlap report did not classify parentage for this pair".to_owned(),
    };
    let fix = match reason {
        Some(DebugOverlapReason::SharedParent { .. }) => {
            "inspect sibling layout pressure, flex/grid sizing, margins, and absolute offsets in layout_cause_panel"
                .to_owned()
        }
        Some(DebugOverlapReason::DifferentParents { .. }) => {
            "inspect both parent chains and render layer ownership before changing child geometry"
                .to_owned()
        }
        Some(DebugOverlapReason::AncestorDescendant { .. }) => {
            "verify whether the descendant should remain inside the ancestor hit/paint region".to_owned()
        }
        _ => "no hierarchy action needed".to_owned(),
    };
    DebugOverlapAutopsyRecord {
        source,
        status,
        summary,
        cause,
        fix,
    }
}

fn debug_overlap_autopsy_positioning_record(
    overlap: &DebugOverlapRecord,
) -> DebugOverlapAutopsyRecord {
    let source = DebugOverlapAutopsySource::Positioning;
    let absolute = overlap
        .reasons
        .iter()
        .filter_map(|reason| match reason {
            DebugOverlapReason::AbsolutePositioning { node } => Some(*node),
            _ => None,
        })
        .collect::<Vec<_>>();
    let status = if absolute.is_empty() {
        DebugFrameTraceStatus::Ok
    } else if overlap.kind == DebugOverlapKind::InteractiveHitbox {
        DebugFrameTraceStatus::Warning
    } else {
        DebugFrameTraceStatus::Info
    };
    let summary = if absolute.is_empty() {
        "no absolute positioning".to_owned()
    } else {
        format!(
            "{} absolute node{}: {}",
            absolute.len(),
            debug_plural_s(absolute.len()),
            absolute
                .iter()
                .map(|node| debug_overlap_node_name(overlap, *node))
                .collect::<Vec<_>>()
                .join(", ")
        )
    };
    let cause = if absolute.is_empty() {
        "no absolute-positioning reason was recorded for this overlap".to_owned()
    } else {
        "absolute placement removes a node from normal sibling flow, so it can cover nearby layout"
            .to_owned()
    };
    let fix = if absolute.is_empty() {
        "no positioning action needed".to_owned()
    } else {
        "inspect absolute offsets, anchor parent size, and whether the target should reserve layout space"
            .to_owned()
    };
    DebugOverlapAutopsyRecord {
        source,
        status,
        summary,
        cause,
        fix,
    }
}

fn debug_overlap_autopsy_ordering_record(
    overlap: &DebugOverlapRecord,
) -> DebugOverlapAutopsyRecord {
    let source = DebugOverlapAutopsySource::Ordering;
    let layer = overlap
        .reasons
        .iter()
        .find(|reason| matches!(reason, DebugOverlapReason::LayerOrdering { .. }));
    let z = overlap
        .reasons
        .iter()
        .find(|reason| matches!(reason, DebugOverlapReason::ZOrdering { .. }));
    let status = if layer.is_some() || z.is_some() {
        if overlap.kind == DebugOverlapKind::InteractiveHitbox {
            DebugFrameTraceStatus::Warning
        } else {
            DebugFrameTraceStatus::Info
        }
    } else {
        DebugFrameTraceStatus::Ok
    };
    let mut parts = Vec::new();
    if let Some(layer) = layer {
        parts.push(debug_overlap_reason_label(layer));
    }
    if let Some(z) = z {
        parts.push(debug_overlap_reason_label(z));
    }
    let summary = if parts.is_empty() {
        "same layer and z order".to_owned()
    } else {
        parts.join("; ")
    };
    let cause = if layer.is_some() || z.is_some() {
        format!(
            "{} paints behind {}; ordering decides which overlapping pixels and hit regions win",
            overlap.back.name, overlap.front.name
        )
    } else {
        "the pair shares layer and resolved z ordering; document order decides the front node"
            .to_owned()
    };
    let fix = if layer.is_some() || z.is_some() {
        "inspect paint_order_panel and render_layers_panel before changing z or layer ownership"
            .to_owned()
    } else {
        "adjust sibling order or z index only if the front/back relationship is wrong".to_owned()
    };
    DebugOverlapAutopsyRecord {
        source,
        status,
        summary,
        cause,
        fix,
    }
}

fn debug_overlap_autopsy_interactivity_record(
    overlap: &DebugOverlapRecord,
) -> DebugOverlapAutopsyRecord {
    let source = DebugOverlapAutopsySource::Interactivity;
    let both_pointer = overlap
        .reasons
        .iter()
        .any(|reason| *reason == DebugOverlapReason::BothPointerInteractive);
    let status = if both_pointer || overlap.kind == DebugOverlapKind::InteractiveHitbox {
        DebugFrameTraceStatus::Warning
    } else if overlap.back.pointer || overlap.front.pointer {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    };
    let summary = if both_pointer {
        "both nodes receive pointer input".to_owned()
    } else if overlap.back.pointer || overlap.front.pointer {
        "one node receives pointer input".to_owned()
    } else {
        "neither node receives pointer input".to_owned()
    };
    let cause = if both_pointer {
        "two pointer-enabled nodes share effective hit area, so the front node can steal clicks from the back node"
            .to_owned()
    } else if overlap.kind == DebugOverlapKind::InteractiveHitbox {
        "effective hitboxes overlap even though both-pointer metadata was not recorded".to_owned()
    } else {
        "this overlap is not primarily an input collision".to_owned()
    };
    let fix = if both_pointer || overlap.kind == DebugOverlapKind::InteractiveHitbox {
        "make one region passive, shrink/outset hit rects deliberately, or separate the controls"
            .to_owned()
    } else {
        "no interactivity action needed unless visual overlap suggests an input affordance"
            .to_owned()
    };
    DebugOverlapAutopsyRecord {
        source,
        status,
        summary,
        cause,
        fix,
    }
}

fn debug_overlap_autopsy_paint_record(overlap: &DebugOverlapRecord) -> DebugOverlapAutopsyRecord {
    let source = DebugOverlapAutopsySource::PaintBounds;
    let paint_outside = overlap
        .reasons
        .iter()
        .filter_map(|reason| match reason {
            DebugOverlapReason::PaintExtendsOutsideLayout { node } => Some(*node),
            _ => None,
        })
        .collect::<Vec<_>>();
    let status = if !paint_outside.is_empty() || overlap.kind == DebugOverlapKind::Paint {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    };
    let summary = if !paint_outside.is_empty() {
        format!(
            "paint outside layout: {}",
            paint_outside
                .iter()
                .map(|node| debug_overlap_node_name(overlap, *node))
                .collect::<Vec<_>>()
                .join(", ")
        )
    } else if overlap.paint_overlap.is_some() {
        "paint bounds overlap".to_owned()
    } else {
        "paint bounds did not drive this overlap".to_owned()
    };
    let cause = if !paint_outside.is_empty() {
        "paint, shader, material, shadow, or effect bounds extend past layout, creating visual collision"
            .to_owned()
    } else if overlap.kind == DebugOverlapKind::Paint {
        "paint rectangles intersect even without a hitbox collision".to_owned()
    } else {
        "paint bounds were not the first classified overlap source".to_owned()
    };
    let fix = if !paint_outside.is_empty() || overlap.kind == DebugOverlapKind::Paint {
        "inspect visual_effects_panel and paint_order_panel; adjust declared outsets, clips, or effect bounds"
            .to_owned()
    } else {
        "no paint-bound action needed".to_owned()
    };
    DebugOverlapAutopsyRecord {
        source,
        status,
        summary,
        cause,
        fix,
    }
}

fn debug_overlap_autopsy_clipping_record(
    overlap: &DebugOverlapRecord,
) -> DebugOverlapAutopsyRecord {
    let source = DebugOverlapAutopsySource::Clipping;
    let clipped = overlap
        .reasons
        .iter()
        .filter_map(|reason| match reason {
            DebugOverlapReason::ClipReducesVisibleHitbox { node } => Some(*node),
            _ => None,
        })
        .collect::<Vec<_>>();
    let status = if clipped.is_empty() {
        DebugFrameTraceStatus::Ok
    } else if overlap.kind == DebugOverlapKind::InteractiveHitbox {
        DebugFrameTraceStatus::Warning
    } else {
        DebugFrameTraceStatus::Info
    };
    let summary = if clipped.is_empty() {
        "no clipping reduction recorded".to_owned()
    } else {
        format!(
            "clip reduces: {}",
            clipped
                .iter()
                .map(|node| debug_overlap_node_name(overlap, *node))
                .collect::<Vec<_>>()
                .join(", ")
        )
    };
    let cause = if clipped.is_empty() {
        "visible rects match layout rects closely for this pair".to_owned()
    } else {
        "an ancestor clip reduced a visible or hit region, which can make the remaining overlap less obvious"
            .to_owned()
    };
    let fix = if clipped.is_empty() {
        "no clipping action needed".to_owned()
    } else {
        "open clip_scroll_panel for the clipped node and inspect the ancestor viewport".to_owned()
    };
    DebugOverlapAutopsyRecord {
        source,
        status,
        summary,
        cause,
        fix,
    }
}

fn debug_overlap_autopsy_geometry_record(
    overlap: &DebugOverlapRecord,
) -> DebugOverlapAutopsyRecord {
    let source = DebugOverlapAutopsySource::Geometry;
    let mut parts = vec![format!("rect {}", debug_rect_label(overlap.overlap_rect))];
    if overlap.layout_overlap.is_some() {
        parts.push("layout".to_owned());
    }
    if overlap.hitbox_overlap.is_some() {
        parts.push("hitbox".to_owned());
    }
    if overlap.paint_overlap.is_some() {
        parts.push("paint".to_owned());
    }
    let status = if overlap.kind == DebugOverlapKind::InteractiveHitbox {
        DebugFrameTraceStatus::Warning
    } else {
        DebugFrameTraceStatus::Info
    };
    let cause = format!(
        "{} and {} intersect over {:.0}px2",
        overlap.back.name,
        overlap.front.name,
        rect_area(overlap.overlap_rect)
    );
    let fix = match overlap.kind {
        DebugOverlapKind::InteractiveHitbox => {
            "inspect hit_target_panel and pointer_autopsy_panel for the shared hit region"
                .to_owned()
        }
        DebugOverlapKind::Paint => {
            "inspect visual_effects_panel and paint_order_panel for the intersecting paint bounds"
                .to_owned()
        }
        DebugOverlapKind::Layout => {
            "inspect layout_cause_panel for parent constraints and sibling geometry".to_owned()
        }
    };
    DebugOverlapAutopsyRecord {
        source,
        status,
        summary: parts.join("; "),
        cause,
        fix,
    }
}

fn finish_debug_overlap_autopsy_trace(
    overlap: &DebugOverlapRecord,
    mut records: Vec<DebugOverlapAutopsyRecord>,
) -> DebugOverlapAutopsyTrace {
    records.sort_by(|left, right| {
        debug_overlap_autopsy_status_rank(left.status)
            .cmp(&debug_overlap_autopsy_status_rank(right.status))
            .then_with(|| {
                debug_overlap_autopsy_source_rank(left.source)
                    .cmp(&debug_overlap_autopsy_source_rank(right.source))
            })
    });
    let status = debug_overlap_autopsy_trace_status(&records);
    let warning_count = records
        .iter()
        .filter(|record| {
            matches!(
                record.status,
                DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
            )
        })
        .count();
    let summary = debug_overlap_autopsy_summary(overlap, status, warning_count);
    DebugOverlapAutopsyTrace {
        kind: overlap.kind,
        back: overlap.back.id,
        back_name: overlap.back.name.clone(),
        front: overlap.front.id,
        front_name: overlap.front.name.clone(),
        overlap_rect: overlap.overlap_rect,
        overlap_area: rect_area(overlap.overlap_rect),
        status,
        warning_count,
        records,
        summary,
    }
}

fn debug_overlap_autopsy_trace_status(
    records: &[DebugOverlapAutopsyRecord],
) -> DebugFrameTraceStatus {
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Error)
    {
        return DebugFrameTraceStatus::Error;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Info)
    {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

fn debug_overlap_autopsy_summary(
    overlap: &DebugOverlapRecord,
    status: DebugFrameTraceStatus,
    warning_count: usize,
) -> String {
    let mut parts = vec![format!(
        "{} overlap autopsy: {} -> {}",
        status.label(),
        overlap.back.name,
        overlap.front.name
    )];
    parts.push(debug_overlap_kind_label(overlap.kind).to_owned());
    parts.push(format!("{:.0}px2", rect_area(overlap.overlap_rect)));
    if warning_count > 0 {
        parts.push(format!(
            "{warning_count} warning{}",
            debug_plural_s(warning_count)
        ));
    }
    parts.join("; ")
}

fn debug_overlap_autopsy_status_rank(status: DebugFrameTraceStatus) -> u8 {
    match status {
        DebugFrameTraceStatus::Error => 0,
        DebugFrameTraceStatus::Warning => 1,
        DebugFrameTraceStatus::Info => 2,
        DebugFrameTraceStatus::Ok => 3,
    }
}

fn debug_overlap_autopsy_source_rank(source: DebugOverlapAutopsySource) -> u8 {
    match source {
        DebugOverlapAutopsySource::Kind => 0,
        DebugOverlapAutopsySource::Interactivity => 1,
        DebugOverlapAutopsySource::Ordering => 2,
        DebugOverlapAutopsySource::Positioning => 3,
        DebugOverlapAutopsySource::Hierarchy => 4,
        DebugOverlapAutopsySource::PaintBounds => 5,
        DebugOverlapAutopsySource::Clipping => 6,
        DebugOverlapAutopsySource::Geometry => 7,
    }
}

fn debug_point_autopsy_bounds(
    snapshot: &DebugInspectorSnapshot,
    probe: &DebugPointerProbe,
) -> Option<DebugBoundsAutopsyTrace> {
    probe
        .target_name
        .as_deref()
        .or(probe.hit_name.as_deref())
        .or_else(|| {
            probe
                .candidates
                .first()
                .map(|candidate| candidate.name.as_str())
        })
        .and_then(|name| DebugBoundsAutopsyTrace::from_snapshot(snapshot, Some(name)))
}

fn debug_point_autopsy_overlap_count(snapshot: &DebugInspectorSnapshot, point: UiPoint) -> usize {
    snapshot
        .overlaps
        .iter()
        .filter(|overlap| overlap.overlap_rect.contains_point(point))
        .count()
}

fn debug_point_autopsy_overlap<'a>(
    snapshot: &'a DebugInspectorSnapshot,
    probe: &DebugPointerProbe,
) -> Option<&'a DebugOverlapRecord> {
    let target = probe
        .target
        .or(probe.hit)
        .or_else(|| probe.candidates.first().map(|candidate| candidate.id));
    snapshot
        .overlaps
        .iter()
        .filter(|overlap| overlap.overlap_rect.contains_point(probe.point))
        .min_by_key(|overlap| {
            (
                !target
                    .is_some_and(|target| overlap.back.id == target || overlap.front.id == target),
                debug_point_autopsy_overlap_kind_rank(overlap.kind),
            )
        })
}

fn debug_point_autopsy_overlap_kind_rank(kind: DebugOverlapKind) -> u8 {
    match kind {
        DebugOverlapKind::InteractiveHitbox => 0,
        DebugOverlapKind::Paint => 1,
        DebugOverlapKind::Layout => 2,
    }
}

fn debug_point_autopsy_target_name(probe: &DebugPointerProbe) -> Option<&str> {
    probe
        .target_name
        .as_deref()
        .or(probe.hit_name.as_deref())
        .or_else(|| {
            probe
                .candidates
                .first()
                .map(|candidate| candidate.name.as_str())
        })
}

fn debug_point_autopsy_visibility(
    snapshot: &DebugInspectorSnapshot,
    probe: &DebugPointerProbe,
) -> Option<DebugVisibilityRecord> {
    let target_name = debug_point_autopsy_target_name(probe)?;
    DebugVisibilityTrace::from_snapshot(snapshot)
        .record(target_name)
        .cloned()
}

fn debug_point_resolution_trace(
    probe: &DebugPointerProbe,
    paint: Option<&DebugPaintOrderTrace>,
) -> DebugPointResolutionTrace {
    let top_effective_hit = probe
        .candidates
        .iter()
        .filter(|candidate| candidate.effective_hit)
        .max_by(|left, right| {
            cmp_optional_z(left.resolved_z, right.resolved_z)
                .then_with(|| left.order.unwrap_or(0).cmp(&right.order.unwrap_or(0)))
                .then_with(|| left.id.0.cmp(&right.id.0))
        });
    let target_candidate = probe.target_candidate();
    let effective_hit_count = probe
        .candidates
        .iter()
        .filter(|candidate| candidate.effective_hit)
        .count();
    let rejected_count = probe
        .candidates
        .iter()
        .filter(|candidate| !candidate.rejections.is_empty())
        .count();
    let geometry_rejection_count = probe
        .candidates
        .iter()
        .filter(|candidate| {
            candidate
                .rejections
                .iter()
                .any(|rejection| matches!(rejection, DebugEventRouteRejection::Geometry(_)))
        })
        .count();
    let occluded_hit_count = probe
        .candidates
        .iter()
        .filter(|candidate| candidate.effective_hit && !candidate.target)
        .count();
    let passive_layout_count = probe
        .candidates
        .iter()
        .filter(|candidate| candidate.layout_contains_point && !candidate.pointer)
        .count();
    let top_paint_node = paint.and_then(|paint| paint.top_visible_node);
    let top_paint_name = paint.and_then(|paint| paint.top_visible_name.clone());
    let top_effective_hit =
        top_effective_hit.map(|candidate| (candidate.id, candidate.name.clone()));
    let action = target_candidate.and_then(|candidate| candidate.action.clone());
    let status = debug_point_resolution_status(
        probe,
        top_effective_hit.as_ref().map(|candidate| candidate.0),
        top_paint_node,
        effective_hit_count,
        rejected_count,
        occluded_hit_count,
        passive_layout_count,
    );
    let summary = debug_point_resolution_summary(
        probe,
        status,
        top_effective_hit
            .as_ref()
            .map(|candidate| candidate.1.as_str()),
        top_paint_name.as_deref(),
        action.as_deref(),
        effective_hit_count,
        rejected_count,
        occluded_hit_count,
    );
    let cause = debug_point_resolution_cause(
        probe,
        top_effective_hit
            .as_ref()
            .map(|candidate| candidate.1.as_str()),
        top_paint_name.as_deref(),
        top_paint_node,
        effective_hit_count,
        rejected_count,
        geometry_rejection_count,
        occluded_hit_count,
        passive_layout_count,
    );
    let fix = debug_point_resolution_fix(
        probe,
        top_effective_hit.as_ref().map(|candidate| candidate.0),
        top_paint_node,
        rejected_count,
        geometry_rejection_count,
        occluded_hit_count,
        passive_layout_count,
    );

    DebugPointResolutionTrace {
        event: probe.event,
        point: probe.point,
        status,
        target: probe.target,
        target_name: probe.target_name.clone(),
        raw_hit: probe.hit,
        raw_hit_name: probe.hit_name.clone(),
        top_effective_hit: top_effective_hit.as_ref().map(|candidate| candidate.0),
        top_effective_hit_name: top_effective_hit.map(|candidate| candidate.1),
        top_paint_node,
        top_paint_name,
        consumed_by: probe.consumed_by,
        consumed_by_name: probe.consumed_by_name.clone(),
        clicked: probe.clicked,
        clicked_name: probe.clicked_name.clone(),
        auto_scrollbar_target: probe.auto_scrollbar_target,
        auto_scrollbar_target_name: probe.auto_scrollbar_target_name.clone(),
        action,
        candidate_count: probe.candidates.len(),
        effective_hit_count,
        rejected_count,
        geometry_rejection_count,
        occluded_hit_count,
        passive_layout_count,
        summary,
        cause,
        fix,
    }
}

fn debug_point_resolution_status(
    probe: &DebugPointerProbe,
    top_effective_hit: Option<UiNodeId>,
    top_paint_node: Option<UiNodeId>,
    effective_hit_count: usize,
    rejected_count: usize,
    occluded_hit_count: usize,
    passive_layout_count: usize,
) -> DebugFrameTraceStatus {
    if probe.target.is_none() {
        return DebugFrameTraceStatus::Warning;
    }
    if probe.auto_scrollbar_target.is_none()
        && top_effective_hit.is_some()
        && top_effective_hit != probe.target
    {
        return DebugFrameTraceStatus::Warning;
    }
    if rejected_count > 0
        || occluded_hit_count > 0
        || passive_layout_count > 0
        || probe.auto_scrollbar_target.is_some()
        || (top_paint_node.is_some() && top_paint_node != probe.target)
        || effective_hit_count > 1
    {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

fn debug_point_resolution_summary(
    probe: &DebugPointerProbe,
    status: DebugFrameTraceStatus,
    top_effective_hit_name: Option<&str>,
    top_paint_name: Option<&str>,
    action: Option<&str>,
    effective_hit_count: usize,
    rejected_count: usize,
    occluded_hit_count: usize,
) -> String {
    let mut parts = vec![format!(
        "{} point resolution {} at {}",
        status.label(),
        probe.event.label(),
        debug_point_label(probe.point)
    )];
    parts.push(format!(
        "target {}",
        probe.target_name.as_deref().unwrap_or("none")
    ));
    if let Some(raw_hit) = probe.hit_name.as_deref() {
        parts.push(format!("raw hit {raw_hit}"));
    }
    if let Some(top_effective_hit_name) = top_effective_hit_name {
        parts.push(format!("effective top {top_effective_hit_name}"));
    }
    if let Some(top_paint_name) = top_paint_name {
        parts.push(format!("paint top {top_paint_name}"));
    }
    if effective_hit_count > 0 {
        parts.push(format!(
            "{effective_hit_count} effective hit{}",
            debug_plural_s(effective_hit_count)
        ));
    }
    if occluded_hit_count > 0 {
        parts.push(format!("{occluded_hit_count} behind target",));
    }
    if rejected_count > 0 {
        parts.push(format!(
            "{rejected_count} rejected candidate{}",
            debug_plural_s(rejected_count)
        ));
    }
    if let Some(auto_scrollbar) = probe.auto_scrollbar_target_name.as_deref() {
        parts.push(format!("scrollbar {auto_scrollbar}"));
    }
    if let Some(action) = action {
        parts.push(format!("action {action}"));
    }
    parts.join("; ")
}

fn debug_point_resolution_cause(
    probe: &DebugPointerProbe,
    top_effective_hit_name: Option<&str>,
    top_paint_name: Option<&str>,
    top_paint_node: Option<UiNodeId>,
    effective_hit_count: usize,
    rejected_count: usize,
    geometry_rejection_count: usize,
    occluded_hit_count: usize,
    passive_layout_count: usize,
) -> String {
    if probe.target.is_none() {
        if passive_layout_count > 0 {
            return format!(
                "{passive_layout_count} layout candidate{} contained the point but did not accept pointer input",
                debug_plural_s(passive_layout_count)
            );
        }
        if effective_hit_count == 0 {
            return "no effective hitbox accepted the inspected point".to_owned();
        }
        return "effective hitboxes were present, but no route target was selected".to_owned();
    }
    if let Some(scrollbar) = probe.auto_scrollbar_target_name.as_deref() {
        return format!(
            "auto-scrollbar hit testing selected {scrollbar} before normal document routing"
        );
    }
    if top_effective_hit_name.is_some() && probe.target_name.as_deref() != top_effective_hit_name {
        let target = probe.target_name.as_deref().unwrap_or("target");
        let top = top_effective_hit_name.unwrap_or("another node");
        return format!("{target} won routing even though {top} is the top effective hitbox");
    }
    if top_paint_node.is_some() && top_paint_node != probe.target {
        let target = probe.target_name.as_deref().unwrap_or("target");
        let top = top_paint_name.unwrap_or("another node");
        return format!("{target} won routing while {top} is the top visible paint at the point");
    }
    if geometry_rejection_count > 0 {
        return format!(
            "{geometry_rejection_count} candidate{} failed hit geometry before routing chose the target",
            debug_plural_s(geometry_rejection_count)
        );
    }
    if rejected_count > 0 {
        return format!(
            "{rejected_count} candidate{} lost routing after the target was chosen",
            debug_plural_s(rejected_count)
        );
    }
    if occluded_hit_count > 0 {
        return format!(
            "{occluded_hit_count} effective hit{} sit behind the routed target",
            debug_plural_s(occluded_hit_count)
        );
    }
    if let Some(action) = probe
        .target_candidate()
        .and_then(|candidate| candidate.action.as_ref())
    {
        let target = probe.target_name.as_deref().unwrap_or("target");
        return format!("{target} won routing and will dispatch {action}");
    }
    "raw hit, route target, effective hitbox, and visible paint agree at this point".to_owned()
}

fn debug_point_resolution_fix(
    probe: &DebugPointerProbe,
    top_effective_hit: Option<UiNodeId>,
    top_paint_node: Option<UiNodeId>,
    rejected_count: usize,
    geometry_rejection_count: usize,
    occluded_hit_count: usize,
    passive_layout_count: usize,
) -> String {
    if probe.target.is_none() {
        return "open pointer_probe_panel and compare hit shape, clips, pointer input, and z order"
            .to_owned();
    }
    if probe.auto_scrollbar_target.is_some() {
        return "inspect scrollbar geometry or move interactive content out of the scrollbar gutter"
            .to_owned();
    }
    if probe.auto_scrollbar_target.is_none()
        && top_effective_hit.is_some()
        && top_effective_hit != probe.target
    {
        return "inspect z/layer order and effective hitboxes before changing routing".to_owned();
    }
    if top_paint_node.is_some() && top_paint_node != probe.target {
        return "compare paint_order_panel with hitbox_debug_overlay for paint/hit disagreement"
            .to_owned();
    }
    if geometry_rejection_count > 0 {
        return "open pointer_probe_panel and inspect geometry rejection reasons".to_owned();
    }
    if rejected_count > 0 || occluded_hit_count > 0 {
        return "open pointer_probe_panel to compare the accepted target with rejected candidates"
            .to_owned();
    }
    if passive_layout_count > 0 {
        return "enable pointer input or action bindings only on the nodes intended to route clicks"
            .to_owned();
    }
    "no point-resolution action needed".to_owned()
}

