fn debug_inspect_node_overlap_record(
    explanation: &DebugNodeExplanation,
    overlaps: &[DebugOverlapRecord],
) -> DebugInspectNodeRecord {
    let Some(overlap) = overlaps.first() else {
        return DebugInspectNodeRecord {
            source: DebugInspectNodeSource::Overlap,
            status: DebugFrameTraceStatus::Ok,
            summary: format!("{} has no overlap records", explanation.name),
            cause: "overlap report did not find paint, layout, or hitbox intersections for the selected node"
                .to_owned(),
            fix: "no overlap action needed".to_owned(),
        };
    };
    let status = match overlap.kind {
        DebugOverlapKind::InteractiveHitbox => DebugFrameTraceStatus::Warning,
        DebugOverlapKind::Paint | DebugOverlapKind::Layout => DebugFrameTraceStatus::Info,
    };
    let other = if overlap.back.id == explanation.node {
        &overlap.front.name
    } else {
        &overlap.back.name
    };
    DebugInspectNodeRecord {
        source: DebugInspectNodeSource::Overlap,
        status,
        summary: format!(
            "{} overlap{}; top {} with {}; {:.0}px2",
            overlaps.len(),
            debug_plural_s(overlaps.len()),
            debug_overlap_kind_label(overlap.kind),
            other,
            rect_area(overlap.overlap_rect)
        ),
        cause: debug_overlap_issue_cause(overlap),
        fix: debug_overlap_issue_fix(overlap),
    }
}

