fn debug_layout_movement_status_rank(status: DebugFrameTraceStatus) -> u8 {
    match status {
        DebugFrameTraceStatus::Error => 0,
        DebugFrameTraceStatus::Warning => 1,
        DebugFrameTraceStatus::Info => 2,
        DebugFrameTraceStatus::Ok => 3,
    }
}

fn rects_differ(left: UiRect, right: UiRect) -> bool {
    !float_close(left.x, right.x)
        || !float_close(left.y, right.y)
        || !float_close(left.width, right.width)
        || !float_close(left.height, right.height)
}

fn optional_rects_differ(left: Option<UiRect>, right: Option<UiRect>) -> bool {
    match (left, right) {
        (Some(left), Some(right)) => rects_differ(left, right),
        (None, None) => false,
        _ => true,
    }
}

fn sizes_differ(left: UiSize, right: UiSize) -> bool {
    !float_close(left.width, right.width) || !float_close(left.height, right.height)
}

fn optional_sizes_differ(left: Option<UiSize>, right: Option<UiSize>) -> bool {
    match (left, right) {
        (Some(left), Some(right)) => sizes_differ(left, right),
        (None, None) => false,
        _ => true,
    }
}

fn float_close(left: f32, right: f32) -> bool {
    (left - right).abs() <= 0.01
}

fn debug_rect_label(rect: UiRect) -> String {
    format!(
        "{:.0},{:.0} {:.0}x{:.0}",
        rect.x, rect.y, rect.width, rect.height
    )
}

fn debug_point_label(point: UiPoint) -> String {
    format!("{:.0},{:.0}", point.x, point.y)
}

fn debug_optional_rect_label(rect: Option<UiRect>) -> String {
    rect.map(debug_rect_label)
        .unwrap_or_else(|| "none".to_owned())
}

fn paint_stats_by_node(paint: &PaintList) -> HashMap<UiNodeId, DebugPaintStats> {
    let mut stats = HashMap::new();
    for item in &paint.items {
        stats
            .entry(item.node)
            .or_insert_with(DebugPaintStats::default)
            .record(item);
    }
    stats
}

fn paint_visible_bounds_by_node(paint: &PaintList) -> HashMap<UiNodeId, UiRect> {
    let mut bounds = HashMap::new();
    for item in &paint.items {
        let Some(visible) = paint_item_debug_bounds(item).intersection(item.clip_rect) else {
            continue;
        };
        bounds
            .entry(item.node)
            .and_modify(|rect| *rect = union_debug_rect(*rect, visible))
            .or_insert(visible);
    }
    bounds
}

fn layout_names_by_node(snapshot: &LayoutSnapshot) -> HashMap<UiNodeId, String> {
    let mut names = HashMap::new();
    collect_layout_names(snapshot, &mut names);
    names
}

fn collect_layout_names(snapshot: &LayoutSnapshot, names: &mut HashMap<UiNodeId, String>) {
    names.insert(snapshot.id, snapshot.name.clone());
    for child in &snapshot.children {
        collect_layout_names(child, names);
    }
}

fn push_layout_dump_line(snapshot: &LayoutSnapshot, depth: usize, lines: &mut Vec<String>) {
    lines.push(format!(
        "{}{}#{} rect={:.1},{:.1},{:.1},{:.1} clip={:.1},{:.1},{:.1},{:.1} visible={} pointer={} focusable={}",
        "  ".repeat(depth),
        snapshot.name,
        snapshot.id.0,
        snapshot.rect.x,
        snapshot.rect.y,
        snapshot.rect.width,
        snapshot.rect.height,
        snapshot.clip_rect.x,
        snapshot.clip_rect.y,
        snapshot.clip_rect.width,
        snapshot.clip_rect.height,
        snapshot.visible,
        snapshot.pointer,
        snapshot.focusable,
    ));
    for child in &snapshot.children {
        push_layout_dump_line(child, depth + 1, lines);
    }
}

fn paint_kind_label(kind: &PaintKind) -> &'static str {
    match kind {
        PaintKind::Rect { .. } => "rect",
        PaintKind::Text(_) => "text",
        PaintKind::Canvas(_) => "canvas",
        PaintKind::Line { .. } => "line",
        PaintKind::Circle { .. } => "circle",
        PaintKind::Polygon { .. } => "polygon",
        PaintKind::Image { .. } => "image",
        PaintKind::CompositedLayer(_) => "composited_layer",
        PaintKind::RichRect(_) => "rich_rect",
        PaintKind::SceneText(_) => "scene_text",
        PaintKind::Path(_) => "path",
        PaintKind::ImagePlacement(_) => "image_placement",
    }
}

fn debug_render_layer_item_record(
    index: usize,
    item: &DebugPaintItem,
) -> Option<DebugRenderLayerItemRecord> {
    let clipped = debug_paint_item_clipped(item);
    let transparent = debug_paint_item_transparent(item);
    let offscreen = debug_paint_item_offscreen(item);
    let shader = item.shader_key.is_some();
    if !clipped && !transparent && !offscreen && !shader {
        return None;
    }

    let status = debug_render_layer_item_status(shader, transparent, clipped, offscreen);
    let summary =
        debug_render_layer_item_summary(index, item, shader, transparent, clipped, offscreen);
    let cause = debug_render_layer_item_cause(item, shader, transparent, clipped, offscreen);
    let fix = debug_render_layer_item_fix(shader, transparent, clipped, offscreen);

    Some(DebugRenderLayerItemRecord {
        index,
        node: item.node,
        node_name: item.node_name.clone(),
        kind: item.kind.clone(),
        layer: item.layer,
        z_index: item.z_index,
        resolved_z: item.resolved_z,
        rect: item.rect,
        clip_rect: item.clip_rect,
        opacity: item.opacity,
        shader_key: item.shader_key.clone(),
        clipped,
        transparent,
        offscreen,
        status,
        summary,
        cause,
        fix,
    })
}

fn debug_paint_item_transparent(item: &DebugPaintItem) -> bool {
    item.opacity < 0.999
}

fn debug_paint_item_clipped(item: &DebugPaintItem) -> bool {
    !debug_rect_contains_rect(item.clip_rect, item.rect)
}

fn debug_paint_item_offscreen(item: &DebugPaintItem) -> bool {
    item.kind == "composited_layer"
}

fn debug_render_layer_record_status(
    item_count: usize,
    shader_count: usize,
    transparent_count: usize,
    clipped_count: usize,
    offscreen_count: usize,
) -> DebugFrameTraceStatus {
    if item_count >= 64 || offscreen_count > 0 {
        return DebugFrameTraceStatus::Warning;
    }
    if shader_count > 0 || transparent_count > 0 || clipped_count > 0 {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

#[allow(clippy::too_many_arguments)]
fn debug_render_layer_record_summary(
    layer: UiLayer,
    item_count: usize,
    node_count: usize,
    min_resolved_z: f32,
    max_resolved_z: f32,
    shader_count: usize,
    transparent_count: usize,
    clipped_count: usize,
    offscreen_count: usize,
) -> String {
    let mut parts = vec![format!(
        "{layer:?}: {item_count} items across {node_count} nodes"
    )];
    if min_resolved_z == max_resolved_z {
        parts.push(format!("z {min_resolved_z}"));
    } else {
        parts.push(format!("z {min_resolved_z}..{max_resolved_z}"));
    }
    if shader_count > 0 {
        parts.push(format!("{shader_count} shader"));
    }
    if transparent_count > 0 {
        parts.push(format!("{transparent_count} transparent"));
    }
    if clipped_count > 0 {
        parts.push(format!("{clipped_count} clipped"));
    }
    if offscreen_count > 0 {
        parts.push(format!("{offscreen_count} offscreen"));
    }
    parts.join("; ")
}

fn debug_render_layer_record_cause(
    item_count: usize,
    shader_count: usize,
    transparent_count: usize,
    clipped_count: usize,
    offscreen_count: usize,
    min_resolved_z: f32,
    max_resolved_z: f32,
) -> String {
    if offscreen_count > 0 {
        return "composited paint creates isolated offscreen work before final composition"
            .to_owned();
    }
    if item_count >= 64 {
        return "this layer has many paint primitives, so ordering and batching are worth inspecting"
            .to_owned();
    }
    if shader_count > 0 {
        return "shader-backed paint can expand bounds and add GPU work".to_owned();
    }
    if transparent_count > 0 {
        return "transparent paint requires blending with previously drawn content".to_owned();
    }
    if clipped_count > 0 {
        return "some paint rects are partially outside their clip rectangles".to_owned();
    }
    if min_resolved_z != max_resolved_z {
        return "items in this layer use multiple local z values".to_owned();
    }
    "paint in this layer is simple opaque unclipped work".to_owned()
}

fn debug_render_layer_record_fix(
    item_count: usize,
    shader_count: usize,
    transparent_count: usize,
    clipped_count: usize,
    offscreen_count: usize,
) -> String {
    if offscreen_count > 0 {
        return "inspect compositor layers, masks, filters, and isolation boundaries".to_owned();
    }
    if item_count >= 64 {
        return "collapse repeated primitives, virtualize hidden rows, or split stable regions for reuse"
            .to_owned();
    }
    if shader_count > 0 {
        return "inspect shader outsets, retained display-list reuse, and whether the effect is necessary"
            .to_owned();
    }
    if transparent_count > 0 {
        return "reduce overlapping alpha surfaces or keep opaque backgrounds behind blended content"
            .to_owned();
    }
    if clipped_count > 0 {
        return "inspect clipping ancestors and avoid painting far outside visible bounds"
            .to_owned();
    }
    "no render-layer action needed".to_owned()
}

fn debug_render_layer_item_status(
    shader: bool,
    transparent: bool,
    clipped: bool,
    offscreen: bool,
) -> DebugFrameTraceStatus {
    if offscreen {
        return DebugFrameTraceStatus::Warning;
    }
    if shader || transparent || clipped {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

fn debug_render_layer_item_summary(
    index: usize,
    item: &DebugPaintItem,
    shader: bool,
    transparent: bool,
    clipped: bool,
    offscreen: bool,
) -> String {
    let mut parts = vec![format!(
        "#{index} {} {:?} z={}",
        item.kind, item.layer, item.resolved_z
    )];
    if let Some(name) = &item.node_name {
        parts.push(name.clone());
    } else {
        parts.push(format!("node#{}", item.node.index()));
    }
    if shader {
        parts.push(format!(
            "shader={}",
            item.shader_key.as_deref().unwrap_or("unknown")
        ));
    }
    if transparent {
        parts.push(format!("opacity {:.2}", item.opacity));
    }
    if clipped {
        parts.push("clipped".to_owned());
    }
    if offscreen {
        parts.push("offscreen".to_owned());
    }
    parts.join("; ")
}

fn debug_render_layer_item_cause(
    item: &DebugPaintItem,
    shader: bool,
    transparent: bool,
    clipped: bool,
    offscreen: bool,
) -> String {
    if offscreen {
        return "this item composites a nested paint list through an offscreen layer".to_owned();
    }
    if shader {
        return "this item uses a shader effect and may expand visual bounds or GPU cost"
            .to_owned();
    }
    if transparent {
        return "this item blends with content already painted behind it".to_owned();
    }
    if clipped {
        return format!(
            "paint rect {} is not fully contained by clip {}",
            debug_rect_label(item.rect),
            debug_rect_label(item.clip_rect)
        );
    }
    "simple render-layer item".to_owned()
}

fn debug_render_layer_item_fix(
    shader: bool,
    transparent: bool,
    clipped: bool,
    offscreen: bool,
) -> String {
    if offscreen {
        return "inspect why this subtree requires isolated composition".to_owned();
    }
    if shader {
        return "check shader outsets, effect bounds, and cache reuse for this node".to_owned();
    }
    if transparent {
        return "avoid unnecessary alpha overdraw or isolate the blend to the smallest rect"
            .to_owned();
    }
    if clipped {
        return "tighten paint bounds or adjust the clipping ancestor".to_owned();
    }
    "no item action needed".to_owned()
}

fn debug_render_layer_trace_status(
    layers: &[DebugRenderLayerRecord],
    items: &[DebugRenderLayerItemRecord],
) -> DebugFrameTraceStatus {
    if layers
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Warning)
        || items
            .iter()
            .any(|record| record.status == DebugFrameTraceStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if layers
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Info)
        || items
            .iter()
            .any(|record| record.status == DebugFrameTraceStatus::Info)
    {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

#[allow(clippy::too_many_arguments)]
fn debug_render_layer_trace_summary(
    status: DebugFrameTraceStatus,
    item_count: usize,
    layer_count: usize,
    shader_item_count: usize,
    transparent_item_count: usize,
    clipped_item_count: usize,
    offscreen_item_count: usize,
) -> String {
    if item_count == 0 {
        return "no render-layer paint".to_owned();
    }
    let mut parts = vec![format!("{} render layers", status.label())];
    parts.push(format!("{item_count} items"));
    parts.push(format!("{layer_count} layers"));
    if shader_item_count > 0 {
        parts.push(format!("{shader_item_count} shader"));
    }
    if transparent_item_count > 0 {
        parts.push(format!("{transparent_item_count} transparent"));
    }
    if clipped_item_count > 0 {
        parts.push(format!("{clipped_item_count} clipped"));
    }
    if offscreen_item_count > 0 {
        parts.push(format!("{offscreen_item_count} offscreen"));
    }
    parts.join("; ")
}

fn debug_render_layer_status_rank(status: DebugFrameTraceStatus) -> u8 {
    match status {
        DebugFrameTraceStatus::Error => 0,
        DebugFrameTraceStatus::Warning => 1,
        DebugFrameTraceStatus::Info => 2,
        DebugFrameTraceStatus::Ok => 3,
    }
}

#[derive(Debug)]
struct DebugRenderLayerTimelineAccumulator {
    layer: UiLayer,
    status: DebugFrameTraceStatus,
    frame_count: usize,
    warning_frame_count: usize,
    first_frame_label: Option<String>,
    latest_frame_label: Option<String>,
    max_item_count: usize,
    latest_item_count: usize,
    max_shader_count: usize,
    latest_shader_count: usize,
    max_transparent_count: usize,
    latest_transparent_count: usize,
    max_clipped_count: usize,
    latest_clipped_count: usize,
    max_offscreen_count: usize,
    latest_offscreen_count: usize,
    min_resolved_z: f32,
    max_resolved_z: f32,
    latest_min_resolved_z: f32,
    latest_max_resolved_z: f32,
    latest_cause: String,
    latest_fix: String,
}

fn debug_render_layer_timeline_trace<'a>(
    traces: impl IntoIterator<Item = &'a DebugFrameTrace>,
) -> DebugRenderLayerTimelineTrace {
    let traces = traces.into_iter().collect::<Vec<_>>();
    let mut records = Vec::<DebugRenderLayerTimelineAccumulator>::new();
    let mut frames = Vec::new();
    let mut previous_features = HashSet::<String>::new();
    let mut has_previous = false;

    for (index, trace) in traces.iter().enumerate() {
        let layers = DebugRenderLayerTrace::from_dump(&trace.paint);
        let current_features = debug_render_layer_timeline_feature_keys(&layers.featured_items);
        let new_feature_count = if has_previous {
            current_features.difference(&previous_features).count()
        } else {
            0
        };
        let resolved_feature_count = if has_previous {
            previous_features.difference(&current_features).count()
        } else {
            0
        };
        let persistent_feature_count = if has_previous {
            current_features.intersection(&previous_features).count()
        } else {
            0
        };
        let label = debug_frame_timeline_label(trace, index);
        for layer in &layers.layers {
            debug_render_layer_timeline_merge_layer(&mut records, &label, layer);
        }
        frames.push(debug_render_layer_timeline_frame_record(
            index,
            label,
            trace.frame_index,
            &layers,
            new_feature_count,
            resolved_feature_count,
            persistent_feature_count,
        ));
        previous_features = current_features;
        has_previous = true;
    }

    let frame_count = frames.len();
    let feature_frame_count = frames
        .iter()
        .filter(|frame| {
            frame.shader_item_count > 0
                || frame.transparent_item_count > 0
                || frame.clipped_item_count > 0
                || frame.offscreen_item_count > 0
        })
        .count();
    let warning_frame_count = frames
        .iter()
        .filter(|frame| frame.status == DebugFrameTraceStatus::Warning)
        .count();
    let changed_frame_count = frames
        .iter()
        .filter(|frame| frame.new_feature_count > 0 || frame.resolved_feature_count > 0)
        .count();
    let item_count = frames.iter().map(|frame| frame.item_count).sum::<usize>();
    let layer_count = frames.iter().map(|frame| frame.layer_count).sum::<usize>();
    let shader_item_count = frames
        .iter()
        .map(|frame| frame.shader_item_count)
        .sum::<usize>();
    let transparent_item_count = frames
        .iter()
        .map(|frame| frame.transparent_item_count)
        .sum::<usize>();
    let clipped_item_count = frames
        .iter()
        .map(|frame| frame.clipped_item_count)
        .sum::<usize>();
    let offscreen_item_count = frames
        .iter()
        .map(|frame| frame.offscreen_item_count)
        .sum::<usize>();
    let new_feature_count = frames
        .iter()
        .map(|frame| frame.new_feature_count)
        .sum::<usize>();
    let resolved_feature_count = frames
        .iter()
        .map(|frame| frame.resolved_feature_count)
        .sum::<usize>();
    let persistent_feature_count = frames
        .iter()
        .map(|frame| frame.persistent_feature_count)
        .sum::<usize>();
    let max_layer_count = frames
        .iter()
        .map(|frame| frame.layer_count)
        .max()
        .unwrap_or(0);
    let max_item_count = frames
        .iter()
        .map(|frame| frame.item_count)
        .max()
        .unwrap_or(0);

    let mut records = records
        .into_iter()
        .map(|record| debug_render_layer_timeline_layer_record(record, frame_count))
        .collect::<Vec<_>>();
    records.sort_by(|left, right| {
        debug_render_layer_status_rank(left.status)
            .cmp(&debug_render_layer_status_rank(right.status))
            .then_with(|| {
                debug_render_layer_timeline_layer_feature_count(right)
                    .cmp(&debug_render_layer_timeline_layer_feature_count(left))
            })
            .then_with(|| right.max_item_count.cmp(&left.max_item_count))
            .then_with(|| left.layer.cmp(&right.layer))
    });

    let status = debug_render_layer_timeline_status(&frames);
    let top_layer = records.first().map(|record| record.layer);
    let summary = debug_render_layer_timeline_summary(
        status,
        frame_count,
        feature_frame_count,
        warning_frame_count,
        changed_frame_count,
        item_count,
        max_layer_count,
        max_item_count,
        shader_item_count,
        transparent_item_count,
        clipped_item_count,
        offscreen_item_count,
        new_feature_count,
        resolved_feature_count,
        top_layer,
    );

    DebugRenderLayerTimelineTrace {
        status,
        frame_count,
        feature_frame_count,
        warning_frame_count,
        changed_frame_count,
        item_count,
        layer_count,
        shader_item_count,
        transparent_item_count,
        clipped_item_count,
        offscreen_item_count,
        new_feature_count,
        resolved_feature_count,
        persistent_feature_count,
        max_layer_count,
        max_item_count,
        top_layer,
        records,
        frames,
        summary,
    }
}

fn debug_render_layer_timeline_feature_keys(
    records: &[DebugRenderLayerItemRecord],
) -> HashSet<String> {
    records
        .iter()
        .map(debug_render_layer_timeline_feature_key)
        .collect()
}

fn debug_render_layer_timeline_feature_key(record: &DebugRenderLayerItemRecord) -> String {
    let name = record
        .node_name
        .clone()
        .unwrap_or_else(|| format!("node#{}", record.node.index()));
    format!(
        "{name}:{}:{:?}:shader={}:transparent={}:clipped={}:offscreen={}",
        record.kind,
        record.layer,
        record.shader_key.is_some(),
        record.transparent,
        record.clipped,
        record.offscreen
    )
}

fn debug_render_layer_timeline_merge_layer(
    records: &mut Vec<DebugRenderLayerTimelineAccumulator>,
    frame_label: &str,
    record: &DebugRenderLayerRecord,
) {
    let Some(accumulator) = records
        .iter_mut()
        .find(|accumulator| accumulator.layer == record.layer)
    else {
        records.push(DebugRenderLayerTimelineAccumulator {
            layer: record.layer,
            status: record.status,
            frame_count: 1,
            warning_frame_count: usize::from(record.status == DebugFrameTraceStatus::Warning),
            first_frame_label: Some(frame_label.to_owned()),
            latest_frame_label: Some(frame_label.to_owned()),
            max_item_count: record.item_count,
            latest_item_count: record.item_count,
            max_shader_count: record.shader_count,
            latest_shader_count: record.shader_count,
            max_transparent_count: record.transparent_count,
            latest_transparent_count: record.transparent_count,
            max_clipped_count: record.clipped_count,
            latest_clipped_count: record.clipped_count,
            max_offscreen_count: record.offscreen_count,
            latest_offscreen_count: record.offscreen_count,
            min_resolved_z: record.min_resolved_z,
            max_resolved_z: record.max_resolved_z,
            latest_min_resolved_z: record.min_resolved_z,
            latest_max_resolved_z: record.max_resolved_z,
            latest_cause: record.cause.clone(),
            latest_fix: record.fix.clone(),
        });
        return;
    };

    accumulator.status = accumulator.status.max(record.status);
    accumulator.frame_count += 1;
    accumulator.warning_frame_count += usize::from(record.status == DebugFrameTraceStatus::Warning);
    accumulator.latest_frame_label = Some(frame_label.to_owned());
    accumulator.max_item_count = accumulator.max_item_count.max(record.item_count);
    accumulator.latest_item_count = record.item_count;
    accumulator.max_shader_count = accumulator.max_shader_count.max(record.shader_count);
    accumulator.latest_shader_count = record.shader_count;
    accumulator.max_transparent_count = accumulator
        .max_transparent_count
        .max(record.transparent_count);
    accumulator.latest_transparent_count = record.transparent_count;
    accumulator.max_clipped_count = accumulator.max_clipped_count.max(record.clipped_count);
    accumulator.latest_clipped_count = record.clipped_count;
    accumulator.max_offscreen_count = accumulator.max_offscreen_count.max(record.offscreen_count);
    accumulator.latest_offscreen_count = record.offscreen_count;
    accumulator.min_resolved_z = accumulator.min_resolved_z.min(record.min_resolved_z);
    accumulator.max_resolved_z = accumulator.max_resolved_z.max(record.max_resolved_z);
    accumulator.latest_min_resolved_z = record.min_resolved_z;
    accumulator.latest_max_resolved_z = record.max_resolved_z;
    accumulator.latest_cause = record.cause.clone();
    accumulator.latest_fix = record.fix.clone();
}

fn debug_render_layer_timeline_layer_record(
    record: DebugRenderLayerTimelineAccumulator,
    retained_frame_count: usize,
) -> DebugRenderLayerTimelineLayerRecord {
    let summary = debug_render_layer_timeline_layer_summary(
        record.layer,
        record.status,
        record.frame_count,
        retained_frame_count,
        record.max_item_count,
        record.max_shader_count,
        record.max_transparent_count,
        record.max_clipped_count,
        record.max_offscreen_count,
    );
    let cause = debug_render_layer_timeline_layer_cause(
        record.layer,
        record.frame_count,
        retained_frame_count,
        record.max_shader_count,
        record.latest_shader_count,
        record.max_transparent_count,
        record.latest_transparent_count,
        record.max_clipped_count,
        record.latest_clipped_count,
        record.max_offscreen_count,
        record.latest_offscreen_count,
        &record.latest_cause,
    );
    let fix = format!(
        "open render_layers_panel for {:?}; {}",
        record.layer, record.latest_fix
    );
    DebugRenderLayerTimelineLayerRecord {
        layer: record.layer,
        status: record.status,
        frame_count: record.frame_count,
        warning_frame_count: record.warning_frame_count,
        first_frame_label: record.first_frame_label,
        latest_frame_label: record.latest_frame_label,
        max_item_count: record.max_item_count,
        latest_item_count: record.latest_item_count,
        max_shader_count: record.max_shader_count,
        latest_shader_count: record.latest_shader_count,
        max_transparent_count: record.max_transparent_count,
        latest_transparent_count: record.latest_transparent_count,
        max_clipped_count: record.max_clipped_count,
        latest_clipped_count: record.latest_clipped_count,
        max_offscreen_count: record.max_offscreen_count,
        latest_offscreen_count: record.latest_offscreen_count,
        min_resolved_z: record.min_resolved_z,
        max_resolved_z: record.max_resolved_z,
        latest_min_resolved_z: record.latest_min_resolved_z,
        latest_max_resolved_z: record.latest_max_resolved_z,
        summary,
        cause,
        fix,
    }
}

#[allow(clippy::too_many_arguments)]
fn debug_render_layer_timeline_frame_record(
    index: usize,
    label: String,
    frame_index: Option<u64>,
    trace: &DebugRenderLayerTrace,
    new_feature_count: usize,
    resolved_feature_count: usize,
    persistent_feature_count: usize,
) -> DebugRenderLayerTimelineFrameRecord {
    let top_layer = trace.layers.iter().min_by(|left, right| {
        debug_render_layer_status_rank(left.status)
            .cmp(&debug_render_layer_status_rank(right.status))
            .then_with(|| {
                debug_render_layer_record_feature_count(right)
                    .cmp(&debug_render_layer_record_feature_count(left))
            })
            .then_with(|| right.item_count.cmp(&left.item_count))
            .then_with(|| left.layer.cmp(&right.layer))
    });
    let summary = debug_render_layer_timeline_frame_summary(
        &label,
        trace.status,
        trace.item_count,
        trace.layer_count,
        trace.shader_item_count,
        trace.transparent_item_count,
        trace.clipped_item_count,
        trace.offscreen_item_count,
        new_feature_count,
        resolved_feature_count,
        persistent_feature_count,
        top_layer.map(|layer| layer.layer),
    );
    let cause = debug_render_layer_timeline_frame_cause(
        trace,
        new_feature_count,
        resolved_feature_count,
        persistent_feature_count,
        top_layer.map(|layer| layer.layer),
    );
    let fix = top_layer
        .map(|layer| format!("open render_layers_panel for {:?}", layer.layer))
        .unwrap_or_else(|| "no render-layer action needed".to_owned());
    DebugRenderLayerTimelineFrameRecord {
        index,
        label,
        frame_index,
        status: trace.status,
        item_count: trace.item_count,
        layer_count: trace.layer_count,
        shader_item_count: trace.shader_item_count,
        transparent_item_count: trace.transparent_item_count,
        clipped_item_count: trace.clipped_item_count,
        offscreen_item_count: trace.offscreen_item_count,
        new_feature_count,
        resolved_feature_count,
        persistent_feature_count,
        top_layer: top_layer.map(|layer| layer.layer),
        top_layer_summary: top_layer.map(|layer| layer.summary.clone()),
        summary,
        cause,
        fix,
    }
}

fn debug_render_layer_record_feature_count(record: &DebugRenderLayerRecord) -> usize {
    record.shader_count + record.transparent_count + record.clipped_count + record.offscreen_count
}

fn debug_render_layer_timeline_layer_feature_count(
    record: &DebugRenderLayerTimelineLayerRecord,
) -> usize {
    record.max_shader_count
        + record.max_transparent_count
        + record.max_clipped_count
        + record.max_offscreen_count
}

fn debug_render_layer_timeline_status(
    frames: &[DebugRenderLayerTimelineFrameRecord],
) -> DebugFrameTraceStatus {
    if frames
        .iter()
        .any(|frame| frame.status == DebugFrameTraceStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if frames
        .iter()
        .any(|frame| frame.status == DebugFrameTraceStatus::Info)
    {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

#[allow(clippy::too_many_arguments)]
fn debug_render_layer_timeline_summary(
    status: DebugFrameTraceStatus,
    frame_count: usize,
    feature_frame_count: usize,
    warning_frame_count: usize,
    changed_frame_count: usize,
    item_count: usize,
    max_layer_count: usize,
    max_item_count: usize,
    shader_item_count: usize,
    transparent_item_count: usize,
    clipped_item_count: usize,
    offscreen_item_count: usize,
    new_feature_count: usize,
    resolved_feature_count: usize,
    top_layer: Option<UiLayer>,
) -> String {
    let mut parts = vec![format!("{} render layer timeline", status.label())];
    parts.push(format!(
        "{frame_count} frame{}",
        debug_plural_s(frame_count)
    ));
    if feature_frame_count > 0 {
        parts.push(format!(
            "{feature_frame_count} feature frame{}",
            debug_plural_s(feature_frame_count)
        ));
    }
    if warning_frame_count > 0 {
        parts.push(format!(
            "{warning_frame_count} warning frame{}",
            debug_plural_s(warning_frame_count)
        ));
    }
    if changed_frame_count > 0 {
        parts.push(format!(
            "{changed_frame_count} changed frame{}",
            debug_plural_s(changed_frame_count)
        ));
    }
    parts.push(format!(
        "{item_count} items total; max {max_item_count} items; max {max_layer_count} layers"
    ));
    if shader_item_count > 0 {
        parts.push(format!("{shader_item_count} shader"));
    }
    if transparent_item_count > 0 {
        parts.push(format!("{transparent_item_count} transparent"));
    }
    if clipped_item_count > 0 {
        parts.push(format!("{clipped_item_count} clipped"));
    }
    if offscreen_item_count > 0 {
        parts.push(format!("{offscreen_item_count} offscreen"));
    }
    if new_feature_count > 0 {
        parts.push(format!(
            "{new_feature_count} new feature{}",
            debug_plural_s(new_feature_count)
        ));
    }
    if resolved_feature_count > 0 {
        parts.push(format!(
            "{resolved_feature_count} resolved feature{}",
            debug_plural_s(resolved_feature_count)
        ));
    }
    if let Some(top_layer) = top_layer {
        parts.push(format!("top {top_layer:?}"));
    }
    parts.join("; ")
}

