fn debug_paint_items_bottom_to_top(dump: &DebugPaintDump) -> Vec<(usize, &DebugPaintItem)> {
    let mut items = dump.items.iter().enumerate().collect::<Vec<_>>();
    items.sort_by(|(left_index, left), (right_index, right)| {
        left.resolved_z
            .total_cmp(&right.resolved_z)
            .then_with(|| left.z_index.total_cmp(&right.z_index))
            .then_with(|| left_index.cmp(right_index))
    });
    items
}

fn debug_paint_overdraw_record(
    position: usize,
    ordered: &[(usize, &DebugPaintItem)],
) -> Option<DebugPaintOverdrawRecord> {
    let (item_index, item) = ordered.get(position).copied()?;
    let visible_rect = debug_paint_item_visible_rect(item)?;
    let visible_area = rect_area(visible_rect);
    if visible_area <= f32::EPSILON {
        return None;
    }

    let mut covered_area = 0.0_f32;
    let mut covering_count = 0;
    let mut largest_covering_area = 0.0_f32;
    let mut largest_covering = None;
    for (front_index, front) in ordered.iter().skip(position + 1).copied() {
        if debug_paint_item_transparent(front) {
            continue;
        }
        let Some(front_visible) = debug_paint_item_visible_rect(front) else {
            continue;
        };
        let Some(overlap) = visible_rect.intersection(front_visible) else {
            continue;
        };
        let overlap_area = rect_area(overlap);
        if overlap_area <= 0.5 {
            continue;
        }
        covering_count += 1;
        covered_area += overlap_area;
        if overlap_area > largest_covering_area {
            largest_covering_area = overlap_area;
            largest_covering = Some((front_index, front));
        }
    }

    if covering_count == 0 {
        return None;
    }

    let covered_ratio = (covered_area / visible_area).min(1.0);
    let largest_covering_index = largest_covering.map(|(index, _)| index);
    let largest_covering_node = largest_covering.map(|(_, item)| item.node);
    let largest_covering_name = largest_covering.and_then(|(_, item)| item.node_name.clone());
    let largest_covering_kind = largest_covering.map(|(_, item)| item.kind.clone());
    let status = debug_paint_overdraw_record_status(covered_ratio, covering_count);
    let summary =
        debug_paint_overdraw_record_summary(item, covered_area, covered_ratio, covering_count);
    let cause = debug_paint_overdraw_record_cause(item, largest_covering.map(|(_, item)| item));
    let fix = debug_paint_overdraw_record_fix(covered_ratio, covering_count);

    Some(DebugPaintOverdrawRecord {
        item_index,
        node: item.node,
        node_name: item.node_name.clone(),
        kind: item.kind.clone(),
        layer: item.layer,
        z_index: item.z_index,
        resolved_z: item.resolved_z,
        visible_rect,
        covered_area,
        covered_ratio,
        covering_count,
        largest_covering_index,
        largest_covering_node,
        largest_covering_name,
        largest_covering_kind,
        status,
        summary,
        cause,
        fix,
    })
}

fn debug_paint_item_visible_rect(item: &DebugPaintItem) -> Option<UiRect> {
    item.rect.intersection(item.clip_rect)
}

fn debug_paint_overdraw_record_status(
    covered_ratio: f32,
    covering_count: usize,
) -> DebugFrameTraceStatus {
    if covered_ratio >= 0.5 || covering_count >= 3 {
        DebugFrameTraceStatus::Warning
    } else {
        DebugFrameTraceStatus::Info
    }
}

fn debug_paint_overdraw_record_summary(
    item: &DebugPaintItem,
    covered_area: f32,
    covered_ratio: f32,
    covering_count: usize,
) -> String {
    format!(
        "{} {} {:.0}% covered by {} later paint item{} ({:.0}px^2)",
        item.node_name
            .clone()
            .unwrap_or_else(|| format!("node#{}", item.node.index())),
        item.kind,
        covered_ratio * 100.0,
        covering_count,
        debug_plural_s(covering_count),
        covered_area
    )
}

fn debug_paint_overdraw_record_cause(
    item: &DebugPaintItem,
    largest_covering: Option<&DebugPaintItem>,
) -> String {
    let Some(largest) = largest_covering else {
        return "this paint item is covered by later paint in the same frame".to_owned();
    };
    format!(
        "{} paints before {} at higher/equal stack order",
        item.node_name
            .as_deref()
            .unwrap_or("the covered paint item"),
        largest.node_name.as_deref().unwrap_or("a later paint item")
    )
}

fn debug_paint_overdraw_record_fix(covered_ratio: f32, covering_count: usize) -> String {
    if covered_ratio >= 0.9 {
        return "skip or defer this paint while it is almost fully covered".to_owned();
    }
    if covered_ratio >= 0.5 {
        return "clip or split this paint so covered regions are not emitted".to_owned();
    }
    if covering_count >= 3 {
        return "inspect repeated overlapping overlays or stacked descendants".to_owned();
    }
    "consider clipping, reordering, or accepting the overlap if it is intentional".to_owned()
}

fn debug_paint_overdraw_trace_status(
    records: &[DebugPaintOverdrawRecord],
) -> DebugFrameTraceStatus {
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if records.is_empty() {
        DebugFrameTraceStatus::Ok
    } else {
        DebugFrameTraceStatus::Info
    }
}

struct DebugPaintOverdrawTimelineAccumulator {
    key: String,
    node_name: Option<String>,
    kind: String,
    status: DebugFrameTraceStatus,
    frame_count: usize,
    warning_frame_count: usize,
    first_frame_label: Option<String>,
    latest_frame_label: Option<String>,
    max_covered_ratio: f32,
    latest_covered_ratio: f32,
    total_covered_area: f32,
    max_covered_area: f32,
    max_covering_count: usize,
    latest_covering_count: usize,
    latest_covering_name: Option<String>,
    latest_layer: UiLayer,
    latest_resolved_z: f32,
    latest_cause: String,
    latest_fix: String,
}

fn debug_paint_overdraw_timeline_trace<'a>(
    traces: impl IntoIterator<Item = &'a DebugFrameTrace>,
) -> DebugPaintOverdrawTimelineTrace {
    let traces = traces.into_iter().collect::<Vec<_>>();
    let mut records = Vec::<DebugPaintOverdrawTimelineAccumulator>::new();
    let mut frames = Vec::new();
    let mut previous_overdraw: Option<DebugPaintOverdrawTrace> = None;

    for (index, trace) in traces.iter().enumerate() {
        let overdraw = DebugPaintOverdrawTrace::from_dump(&trace.paint);
        let current_keys = debug_paint_overdraw_timeline_keys(&overdraw.records);
        let previous_keys = previous_overdraw
            .as_ref()
            .map(|previous| debug_paint_overdraw_timeline_keys(&previous.records))
            .unwrap_or_default();
        let has_previous = previous_overdraw.is_some();
        let new_overdraw_count = if has_previous {
            current_keys.difference(&previous_keys).count()
        } else {
            0
        };
        let resolved_overdraw_count = if has_previous {
            previous_keys.difference(&current_keys).count()
        } else {
            0
        };
        let persistent_overdraw_count = if has_previous {
            current_keys.intersection(&previous_keys).count()
        } else {
            0
        };
        let label = debug_frame_timeline_label(trace, index);
        for record in &overdraw.records {
            debug_paint_overdraw_timeline_merge_record(&mut records, &label, record);
        }
        frames.push(debug_paint_overdraw_timeline_frame_record(
            index,
            label,
            trace.frame_index,
            &overdraw,
            new_overdraw_count,
            resolved_overdraw_count,
            persistent_overdraw_count,
        ));
        previous_overdraw = Some(overdraw);
    }

    let frame_count = frames.len();
    let overdraw_frame_count = frames
        .iter()
        .filter(|frame| frame.covered_item_count > 0)
        .count();
    let warning_frame_count = frames
        .iter()
        .filter(|frame| frame.status == DebugFrameTraceStatus::Warning)
        .count();
    let changed_frame_count = frames
        .iter()
        .filter(|frame| frame.new_overdraw_count > 0 || frame.resolved_overdraw_count > 0)
        .count();
    let item_count = frames.iter().map(|frame| frame.item_count).sum();
    let covered_item_count = frames
        .iter()
        .map(|frame| frame.covered_item_count)
        .sum::<usize>();
    let new_overdraw_count = frames
        .iter()
        .map(|frame| frame.new_overdraw_count)
        .sum::<usize>();
    let resolved_overdraw_count = frames
        .iter()
        .map(|frame| frame.resolved_overdraw_count)
        .sum::<usize>();
    let persistent_overdraw_count = frames
        .iter()
        .map(|frame| frame.persistent_overdraw_count)
        .sum::<usize>();
    let total_covered_area = frames
        .iter()
        .map(|frame| frame.total_covered_area)
        .sum::<f32>();
    let max_covered_ratio = frames
        .iter()
        .map(|frame| frame.max_covered_ratio)
        .fold(0.0_f32, f32::max);

    let mut records = records
        .into_iter()
        .map(|record| debug_paint_overdraw_timeline_record(record, frame_count))
        .collect::<Vec<_>>();
    records.sort_by(|left, right| {
        debug_paint_overdraw_status_rank(left.status)
            .cmp(&debug_paint_overdraw_status_rank(right.status))
            .then_with(|| right.frame_count.cmp(&left.frame_count))
            .then_with(|| right.max_covered_ratio.total_cmp(&left.max_covered_ratio))
            .then_with(|| right.total_covered_area.total_cmp(&left.total_covered_area))
            .then_with(|| left.key.cmp(&right.key))
    });

    let status = debug_paint_overdraw_timeline_status(&frames);
    let top_key = records.first().map(|record| record.key.clone());
    let top_name = records
        .first()
        .map(|record| debug_paint_overdraw_timeline_record_name(record));
    let summary = debug_paint_overdraw_timeline_summary(
        status,
        frame_count,
        overdraw_frame_count,
        warning_frame_count,
        changed_frame_count,
        covered_item_count,
        new_overdraw_count,
        resolved_overdraw_count,
        total_covered_area,
        max_covered_ratio,
        top_name.as_deref(),
    );

    DebugPaintOverdrawTimelineTrace {
        status,
        frame_count,
        overdraw_frame_count,
        warning_frame_count,
        changed_frame_count,
        item_count,
        covered_item_count,
        new_overdraw_count,
        resolved_overdraw_count,
        persistent_overdraw_count,
        total_covered_area,
        max_covered_ratio,
        top_key,
        top_name,
        records,
        frames,
        summary,
    }
}

fn debug_paint_overdraw_timeline_keys(records: &[DebugPaintOverdrawRecord]) -> HashSet<String> {
    records
        .iter()
        .map(debug_paint_overdraw_timeline_key)
        .collect()
}

fn debug_paint_overdraw_timeline_key(record: &DebugPaintOverdrawRecord) -> String {
    format!(
        "{}:{}",
        record
            .node_name
            .clone()
            .unwrap_or_else(|| format!("node#{}", record.node.index())),
        record.kind
    )
}

fn debug_paint_overdraw_timeline_merge_record(
    records: &mut Vec<DebugPaintOverdrawTimelineAccumulator>,
    frame_label: &str,
    record: &DebugPaintOverdrawRecord,
) {
    let key = debug_paint_overdraw_timeline_key(record);
    let Some(accumulator) = records
        .iter_mut()
        .find(|accumulator| accumulator.key == key)
    else {
        records.push(DebugPaintOverdrawTimelineAccumulator {
            key,
            node_name: record.node_name.clone(),
            kind: record.kind.clone(),
            status: record.status,
            frame_count: 1,
            warning_frame_count: usize::from(record.status == DebugFrameTraceStatus::Warning),
            first_frame_label: Some(frame_label.to_owned()),
            latest_frame_label: Some(frame_label.to_owned()),
            max_covered_ratio: record.covered_ratio,
            latest_covered_ratio: record.covered_ratio,
            total_covered_area: record.covered_area,
            max_covered_area: record.covered_area,
            max_covering_count: record.covering_count,
            latest_covering_count: record.covering_count,
            latest_covering_name: record.largest_covering_name.clone(),
            latest_layer: record.layer,
            latest_resolved_z: record.resolved_z,
            latest_cause: record.cause.clone(),
            latest_fix: record.fix.clone(),
        });
        return;
    };

    accumulator.status = accumulator.status.max(record.status);
    accumulator.frame_count += 1;
    accumulator.warning_frame_count += usize::from(record.status == DebugFrameTraceStatus::Warning);
    accumulator.latest_frame_label = Some(frame_label.to_owned());
    accumulator.max_covered_ratio = accumulator.max_covered_ratio.max(record.covered_ratio);
    accumulator.latest_covered_ratio = record.covered_ratio;
    accumulator.total_covered_area += record.covered_area;
    accumulator.max_covered_area = accumulator.max_covered_area.max(record.covered_area);
    accumulator.max_covering_count = accumulator.max_covering_count.max(record.covering_count);
    accumulator.latest_covering_count = record.covering_count;
    accumulator.latest_covering_name = record.largest_covering_name.clone();
    accumulator.latest_layer = record.layer;
    accumulator.latest_resolved_z = record.resolved_z;
    accumulator.latest_cause = record.cause.clone();
    accumulator.latest_fix = record.fix.clone();
}

fn debug_paint_overdraw_timeline_record(
    record: DebugPaintOverdrawTimelineAccumulator,
    retained_frame_count: usize,
) -> DebugPaintOverdrawTimelineRecord {
    let display_name = record
        .node_name
        .clone()
        .unwrap_or_else(|| record.key.clone());
    let summary = debug_paint_overdraw_timeline_record_summary(
        &display_name,
        &record.kind,
        record.status,
        record.frame_count,
        retained_frame_count,
        record.max_covered_ratio,
        record.total_covered_area,
        record.latest_covering_name.as_deref(),
    );
    let cause = debug_paint_overdraw_timeline_record_cause(
        &display_name,
        &record.kind,
        record.frame_count,
        retained_frame_count,
        record.max_covered_ratio,
        record.latest_covered_ratio,
        record.max_covering_count,
        record.latest_covering_name.as_deref(),
        &record.latest_cause,
    );
    let fix = format!(
        "open paint_overdraw_panel for {}; {}",
        display_name, record.latest_fix
    );
    DebugPaintOverdrawTimelineRecord {
        key: record.key,
        node_name: record.node_name,
        kind: record.kind,
        status: record.status,
        frame_count: record.frame_count,
        warning_frame_count: record.warning_frame_count,
        first_frame_label: record.first_frame_label,
        latest_frame_label: record.latest_frame_label,
        max_covered_ratio: record.max_covered_ratio,
        latest_covered_ratio: record.latest_covered_ratio,
        total_covered_area: record.total_covered_area,
        max_covered_area: record.max_covered_area,
        max_covering_count: record.max_covering_count,
        latest_covering_count: record.latest_covering_count,
        latest_covering_name: record.latest_covering_name,
        latest_layer: record.latest_layer,
        latest_resolved_z: record.latest_resolved_z,
        summary,
        cause,
        fix,
    }
}

#[allow(clippy::too_many_arguments)]
fn debug_paint_overdraw_timeline_frame_record(
    index: usize,
    label: String,
    frame_index: Option<u64>,
    overdraw: &DebugPaintOverdrawTrace,
    new_overdraw_count: usize,
    resolved_overdraw_count: usize,
    persistent_overdraw_count: usize,
) -> DebugPaintOverdrawTimelineFrameRecord {
    let top = overdraw.records.first();
    let top_key = top.map(debug_paint_overdraw_timeline_key);
    let top_name = top.map(debug_paint_overdraw_record_name);
    let top_summary = top.map(|record| record.summary.clone());
    let summary = debug_paint_overdraw_timeline_frame_summary(
        &label,
        overdraw.status,
        overdraw.item_count,
        overdraw.covered_item_count,
        new_overdraw_count,
        resolved_overdraw_count,
        persistent_overdraw_count,
        overdraw.total_covered_area,
        overdraw.max_covered_ratio,
        top_name.as_deref(),
    );
    let cause = debug_paint_overdraw_timeline_frame_cause(
        overdraw,
        new_overdraw_count,
        resolved_overdraw_count,
        persistent_overdraw_count,
        top_summary.as_deref(),
    );
    let fix = debug_paint_overdraw_timeline_frame_fix(
        overdraw.status,
        overdraw.covered_item_count,
        new_overdraw_count,
        resolved_overdraw_count,
        persistent_overdraw_count,
        top_name.as_deref(),
    );
    DebugPaintOverdrawTimelineFrameRecord {
        index,
        label,
        frame_index,
        status: overdraw.status,
        item_count: overdraw.item_count,
        covered_item_count: overdraw.covered_item_count,
        new_overdraw_count,
        resolved_overdraw_count,
        persistent_overdraw_count,
        total_covered_area: overdraw.total_covered_area,
        max_covered_ratio: overdraw.max_covered_ratio,
        top_key,
        top_name,
        top_summary,
        summary,
        cause,
        fix,
    }
}

fn debug_paint_overdraw_timeline_status(
    frames: &[DebugPaintOverdrawTimelineFrameRecord],
) -> DebugFrameTraceStatus {
    if frames
        .iter()
        .any(|frame| frame.status == DebugFrameTraceStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if frames
        .iter()
        .any(|frame| frame.status == DebugFrameTraceStatus::Info)
    {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

#[allow(clippy::too_many_arguments)]
fn debug_paint_overdraw_timeline_summary(
    status: DebugFrameTraceStatus,
    frame_count: usize,
    overdraw_frame_count: usize,
    warning_frame_count: usize,
    changed_frame_count: usize,
    covered_item_count: usize,
    new_overdraw_count: usize,
    resolved_overdraw_count: usize,
    total_covered_area: f32,
    max_covered_ratio: f32,
    top_name: Option<&str>,
) -> String {
    let mut parts = vec![format!("{} paint overdraw timeline", status.label())];
    parts.push(format!(
        "{frame_count} frame{}",
        debug_plural_s(frame_count)
    ));
    if overdraw_frame_count > 0 {
        parts.push(format!(
            "{overdraw_frame_count} overdraw frame{}",
            debug_plural_s(overdraw_frame_count)
        ));
    }
    if warning_frame_count > 0 {
        parts.push(format!(
            "{warning_frame_count} warning frame{}",
            debug_plural_s(warning_frame_count)
        ));
    }
    if changed_frame_count > 0 {
        parts.push(format!(
            "{changed_frame_count} changed frame{}",
            debug_plural_s(changed_frame_count)
        ));
    }
    if covered_item_count > 0 {
        parts.push(format!(
            "{covered_item_count} covered item{}",
            debug_plural_s(covered_item_count)
        ));
    }
    if new_overdraw_count > 0 {
        parts.push(format!(
            "{new_overdraw_count} new overdraw{}",
            debug_plural_s(new_overdraw_count)
        ));
    }
    if resolved_overdraw_count > 0 {
        parts.push(format!(
            "{resolved_overdraw_count} resolved overdraw{}",
            debug_plural_s(resolved_overdraw_count)
        ));
    }
    if covered_item_count > 0 {
        parts.push(format!(
            "max {:.0}%; {:.0}px^2 covered",
            max_covered_ratio * 100.0,
            total_covered_area
        ));
    }
    if let Some(top_name) = top_name {
        parts.push(format!("top {top_name}"));
    }
    parts.join("; ")
}

#[allow(clippy::too_many_arguments)]
fn debug_paint_overdraw_timeline_record_summary(
    name: &str,
    kind: &str,
    status: DebugFrameTraceStatus,
    frame_count: usize,
    retained_frame_count: usize,
    max_covered_ratio: f32,
    total_covered_area: f32,
    latest_covering_name: Option<&str>,
) -> String {
    let mut parts = vec![format!("{} paint overdraw for {name}", status.label())];
    parts.push(kind.to_owned());
    parts.push(format!(
        "{frame_count}/{retained_frame_count} frame{}",
        debug_plural_s(retained_frame_count)
    ));
    parts.push(format!(
        "max {:.0}%; {:.0}px^2",
        max_covered_ratio * 100.0,
        total_covered_area
    ));
    if let Some(latest_covering_name) = latest_covering_name {
        parts.push(format!("covered by {latest_covering_name}"));
    }
    parts.join("; ")
}

#[allow(clippy::too_many_arguments)]
fn debug_paint_overdraw_timeline_record_cause(
    name: &str,
    kind: &str,
    frame_count: usize,
    retained_frame_count: usize,
    max_covered_ratio: f32,
    latest_covered_ratio: f32,
    max_covering_count: usize,
    latest_covering_name: Option<&str>,
    latest_cause: &str,
) -> String {
    let mut parts = vec![format!(
        "{name} {kind} was covered in {frame_count}/{retained_frame_count} retained frame{}",
        debug_plural_s(retained_frame_count)
    )];
    parts.push(format!(
        "max {:.0}% latest {:.0}%",
        max_covered_ratio * 100.0,
        latest_covered_ratio * 100.0
    ));
    parts.push(format!(
        "up to {max_covering_count} later paint item{}",
        debug_plural_s(max_covering_count)
    ));
    if let Some(latest_covering_name) = latest_covering_name {
        parts.push(format!("latest covering {latest_covering_name}"));
    }
    parts.push(format!("latest cause {latest_cause}"));
    parts.join("; ")
}

#[allow(clippy::too_many_arguments)]
fn debug_paint_overdraw_timeline_frame_summary(
    label: &str,
    status: DebugFrameTraceStatus,
    item_count: usize,
    covered_item_count: usize,
    new_overdraw_count: usize,
    resolved_overdraw_count: usize,
    persistent_overdraw_count: usize,
    total_covered_area: f32,
    max_covered_ratio: f32,
    top_name: Option<&str>,
) -> String {
    let mut parts = vec![format!("{} paint overdraw for {label}", status.label())];
    parts.push(format!("{item_count} paint items"));
    if covered_item_count > 0 {
        parts.push(format!(
            "{covered_item_count} covered{}",
            debug_plural_s(covered_item_count)
        ));
        parts.push(format!(
            "max {:.0}%; {:.0}px^2",
            max_covered_ratio * 100.0,
            total_covered_area
        ));
    } else {
        parts.push("no covered paint".to_owned());
    }
    if new_overdraw_count > 0 {
        parts.push(format!(
            "{new_overdraw_count} new{}",
            debug_plural_s(new_overdraw_count)
        ));
    }
    if resolved_overdraw_count > 0 {
        parts.push(format!(
            "{resolved_overdraw_count} resolved{}",
            debug_plural_s(resolved_overdraw_count)
        ));
    }
    if persistent_overdraw_count > 0 {
        parts.push(format!(
            "{persistent_overdraw_count} persistent{}",
            debug_plural_s(persistent_overdraw_count)
        ));
    }
    if let Some(top_name) = top_name {
        parts.push(format!("top {top_name}"));
    }
    parts.join("; ")
}

fn debug_paint_overdraw_timeline_frame_cause(
    overdraw: &DebugPaintOverdrawTrace,
    new_overdraw_count: usize,
    resolved_overdraw_count: usize,
    persistent_overdraw_count: usize,
    top_summary: Option<&str>,
) -> String {
    let mut parts = vec![overdraw.summary.clone()];
    if new_overdraw_count > 0 {
        parts.push(format!(
            "{new_overdraw_count} overdraw item{} appeared since previous frame",
            debug_plural_s(new_overdraw_count)
        ));
    }
    if resolved_overdraw_count > 0 {
        parts.push(format!(
            "{resolved_overdraw_count} overdraw item{} resolved since previous frame",
            debug_plural_s(resolved_overdraw_count)
        ));
    }
    if persistent_overdraw_count > 0 {
        parts.push(format!(
            "{persistent_overdraw_count} overdraw item{} persisted",
            debug_plural_s(persistent_overdraw_count)
        ));
    }
    if let Some(top_summary) = top_summary {
        parts.push(format!("top {top_summary}"));
    }
    parts.join("; ")
}

fn debug_paint_overdraw_timeline_frame_fix(
    status: DebugFrameTraceStatus,
    covered_item_count: usize,
    new_overdraw_count: usize,
    resolved_overdraw_count: usize,
    persistent_overdraw_count: usize,
    top_name: Option<&str>,
) -> String {
    if let Some(top_name) = top_name {
        return format!("open paint_overdraw_panel filtered to {top_name}");
    }
    if new_overdraw_count > 0 || resolved_overdraw_count > 0 {
        return "compare frame_timeline_panel with paint_order_panel to inspect changed paint stack"
            .to_owned();
    }
    if persistent_overdraw_count > 0 || covered_item_count > 0 {
        return "open paint_overdraw_panel and render_layers_panel for persistent covered paint"
            .to_owned();
    }
    if matches!(status, DebugFrameTraceStatus::Warning) {
        return "open paint_overdraw_panel for the highest severity covered paint row".to_owned();
    }
    "no overdraw action needed".to_owned()
}

fn debug_paint_overdraw_record_name(record: &DebugPaintOverdrawRecord) -> String {
    record
        .node_name
        .clone()
        .unwrap_or_else(|| format!("node#{}", record.node.index()))
}

fn debug_paint_overdraw_timeline_record_name(record: &DebugPaintOverdrawTimelineRecord) -> String {
    record
        .node_name
        .clone()
        .unwrap_or_else(|| record.key.clone())
}

fn debug_paint_overdraw_trace_summary(
    status: DebugFrameTraceStatus,
    item_count: usize,
    covered_item_count: usize,
    total_covered_area: f32,
    max_covered_ratio: f32,
) -> String {
    if covered_item_count == 0 {
        return format!(
            "{} paint overdraw; {item_count} items; no covered paint",
            status.label()
        );
    }
    format!(
        "{} paint overdraw; {}/{} items covered; max {:.0}%; {:.0}px^2 covered",
        status.label(),
        covered_item_count,
        item_count,
        max_covered_ratio * 100.0,
        total_covered_area
    )
}

fn debug_paint_overdraw_status_rank(status: DebugFrameTraceStatus) -> u8 {
    match status {
        DebugFrameTraceStatus::Error => 0,
        DebugFrameTraceStatus::Warning => 1,
        DebugFrameTraceStatus::Info => 2,
        DebugFrameTraceStatus::Ok => 3,
    }
}

fn debug_paint_batch_record(
    batch_index: usize,
    batch: &PaintBatch,
    paint: &PaintList,
    names: &HashMap<UiNodeId, String>,
) -> DebugPaintBatchRecord {
    let shader_key = batch.key.shader.as_ref().map(|shader| shader.key.clone());
    let mut node_names = BTreeSet::new();
    for item_index in &batch.item_indices {
        if let Some(item) = paint.items.get(*item_index) {
            node_names.insert(
                names
                    .get(&item.node)
                    .cloned()
                    .unwrap_or_else(|| format!("#{}", item.node.index())),
            );
        }
    }
    let status = debug_paint_batch_record_status(batch, shader_key.is_some());
    let summary = debug_paint_batch_record_summary(batch_index, batch, shader_key.as_deref());
    let cause = debug_paint_batch_record_cause(batch, shader_key.as_deref());
    let fix = debug_paint_batch_record_fix(batch, shader_key.as_deref());

    DebugPaintBatchRecord {
        batch_index,
        kind: debug_paint_batch_kind_label(batch.key.kind).to_owned(),
        layer: batch.key.layer_order.layer,
        z_index: batch.key.z_index,
        resolved_z: batch.key.layer_order.resolved_z(),
        clip_rect: batch.key.clip_rect,
        shader_key,
        item_count: batch.len(),
        item_indices: batch.item_indices.clone(),
        bounds: batch.bounds,
        node_names: node_names.into_iter().collect(),
        status,
        summary,
        cause,
        fix,
    }
}

fn debug_paint_batch_break_record(
    break_index: usize,
    from: &PaintBatch,
    to: &PaintBatch,
) -> DebugPaintBatchBreakRecord {
    let kind_changed = from.key.kind != to.key.kind;
    let layer_changed = from.key.layer_order.layer != to.key.layer_order.layer;
    let z_changed = from.key.z_index != to.key.z_index
        || from.key.layer_order.local_z != to.key.layer_order.local_z;
    let clip_changed = rects_differ(from.key.clip_rect, to.key.clip_rect);
    let shader_changed = debug_paint_batch_shader_key(from) != debug_paint_batch_shader_key(to);
    let status = DebugFrameTraceStatus::Info;
    let summary = debug_paint_batch_break_summary(
        break_index,
        from,
        to,
        kind_changed,
        layer_changed,
        z_changed,
        clip_changed,
        shader_changed,
    );
    let cause = debug_paint_batch_break_cause(
        kind_changed,
        layer_changed,
        z_changed,
        clip_changed,
        shader_changed,
    );
    let fix = debug_paint_batch_break_fix(
        kind_changed,
        layer_changed,
        z_changed,
        clip_changed,
        shader_changed,
    );

    DebugPaintBatchBreakRecord {
        from_batch: break_index,
        to_batch: break_index + 1,
        from_kind: debug_paint_batch_kind_label(from.key.kind).to_owned(),
        to_kind: debug_paint_batch_kind_label(to.key.kind).to_owned(),
        kind_changed,
        layer_changed,
        z_changed,
        clip_changed,
        shader_changed,
        status,
        summary,
        cause,
        fix,
    }
}

fn debug_paint_batch_record_status(batch: &PaintBatch, shader: bool) -> DebugFrameTraceStatus {
    if batch.len() == 1 || shader {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    }
}

fn debug_paint_batch_record_summary(
    batch_index: usize,
    batch: &PaintBatch,
    shader_key: Option<&str>,
) -> String {
    let mut parts = vec![format!(
        "batch {batch_index}: {} {} item{}",
        debug_paint_batch_kind_label(batch.key.kind),
        batch.len(),
        debug_plural_s(batch.len())
    )];
    parts.push(format!("{:?}", batch.key.layer_order.layer));
    parts.push(format!("z {}", batch.key.layer_order.resolved_z()));
    if let Some(shader) = shader_key {
        parts.push(format!("shader={shader}"));
    }
    parts.join("; ")
}

fn debug_paint_batch_record_cause(batch: &PaintBatch, shader_key: Option<&str>) -> String {
    if let Some(shader) = shader_key {
        return format!("shader {shader} requires a compatible batch key");
    }
    if batch.len() == 1 {
        return "this paint item could not merge with its adjacent paint items".to_owned();
    }
    "adjacent paint items share kind, layer, z, clip, and shader key".to_owned()
}

fn debug_paint_batch_record_fix(batch: &PaintBatch, shader_key: Option<&str>) -> String {
    if shader_key.is_some() {
        return "group shader-backed paint together or reduce unnecessary shader variation"
            .to_owned();
    }
    if batch.len() == 1 {
        return "inspect neighboring batch breaks for kind, clip, z, layer, or shader changes"
            .to_owned();
    }
    "no batch action needed".to_owned()
}

#[allow(clippy::too_many_arguments)]
fn debug_paint_batch_break_summary(
    break_index: usize,
    from: &PaintBatch,
    to: &PaintBatch,
    kind_changed: bool,
    layer_changed: bool,
    z_changed: bool,
    clip_changed: bool,
    shader_changed: bool,
) -> String {
    let mut reasons = Vec::new();
    if kind_changed {
        reasons.push("kind");
    }
    if layer_changed {
        reasons.push("layer");
    }
    if z_changed {
        reasons.push("z");
    }
    if clip_changed {
        reasons.push("clip");
    }
    if shader_changed {
        reasons.push("shader");
    }
    if reasons.is_empty() {
        reasons.push("order");
    }
    format!(
        "batch {break_index} {} -> {} split by {}",
        debug_paint_batch_kind_label(from.key.kind),
        debug_paint_batch_kind_label(to.key.kind),
        reasons.join(", ")
    )
}

fn debug_paint_batch_break_cause(
    kind_changed: bool,
    layer_changed: bool,
    z_changed: bool,
    clip_changed: bool,
    shader_changed: bool,
) -> String {
    if layer_changed {
        return "paint moved to a different UI layer, so it cannot share the previous batch"
            .to_owned();
    }
    if z_changed {
        return "local z or resolved layer order changed, so paint order must be preserved"
            .to_owned();
    }
    if clip_changed {
        return "clip rectangle changed, requiring a different scissor/bounds key".to_owned();
    }
    if shader_changed {
        return "shader key changed, so the renderer must switch shader/material state".to_owned();
    }
    if kind_changed {
        return "paint primitive kind changed, so the renderer uses a different draw path"
            .to_owned();
    }
    "paint order separated otherwise compatible items".to_owned()
}

fn debug_paint_batch_break_fix(
    kind_changed: bool,
    layer_changed: bool,
    z_changed: bool,
    clip_changed: bool,
    shader_changed: bool,
) -> String {
    if layer_changed || z_changed {
        return "only adjust layer/z if the visual stacking order is accidental".to_owned();
    }
    if clip_changed {
        return "align clipping ancestors or group similarly clipped paint together".to_owned();
    }
    if shader_changed {
        return "reuse shader keys and group shader-backed nodes when possible".to_owned();
    }
    if kind_changed {
        return "keep repeated primitive kinds adjacent when visual order allows".to_owned();
    }
    "inspect neighboring paint order and retained display-list grouping".to_owned()
}

fn debug_paint_batch_trace_status(
    item_count: usize,
    batch_count: usize,
    singleton_batch_count: usize,
    records: &[DebugPaintBatchRecord],
    breaks: &[DebugPaintBatchBreakRecord],
) -> DebugFrameTraceStatus {
    if item_count >= 8 && singleton_batch_count * 2 >= batch_count.max(1) && batch_count >= 8 {
        return DebugFrameTraceStatus::Warning;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Warning)
        || breaks
            .iter()
            .any(|record| record.status == DebugFrameTraceStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if batch_count > 1 {
        DebugFrameTraceStatus::Info
    } else {
        DebugFrameTraceStatus::Ok
    }
}

fn debug_paint_batch_trace_summary(
    status: DebugFrameTraceStatus,
    item_count: usize,
    batch_count: usize,
    singleton_batch_count: usize,
    largest_batch_len: usize,
    average_items_per_batch: f32,
) -> String {
    if item_count == 0 {
        return "no paint batches".to_owned();
    }
    format!(
        "{} paint batches; {item_count} items -> {batch_count} batches; {singleton_batch_count} singleton; largest {largest_batch_len}; avg {:.1}",
        status.label(),
        average_items_per_batch
    )
}

fn debug_paint_batch_status_rank(status: DebugFrameTraceStatus) -> u8 {
    match status {
        DebugFrameTraceStatus::Error => 0,
        DebugFrameTraceStatus::Warning => 1,
        DebugFrameTraceStatus::Info => 2,
        DebugFrameTraceStatus::Ok => 3,
    }
}

#[derive(Debug)]
struct DebugPaintBatchTimelineReasonAccumulator {
    reason: String,
    status: DebugFrameTraceStatus,
    frame_count: usize,
    break_count: usize,
    first_frame_label: Option<String>,
    latest_frame_label: Option<String>,
    max_break_count: usize,
    latest_break_count: usize,
}

fn debug_paint_batch_timeline_trace<'a>(
    traces: impl IntoIterator<Item = &'a DebugFrameTrace>,
) -> DebugPaintBatchTimelineTrace {
    let traces = traces.into_iter().collect::<Vec<_>>();
    let mut records = Vec::<DebugPaintBatchTimelineReasonAccumulator>::new();
    let mut frames = Vec::new();
    let mut previous_break_keys = HashSet::<String>::new();
    let mut has_previous = false;

    for (index, trace) in traces.iter().enumerate() {
        let batches = &trace.paint_batches;
        let current_break_keys = debug_paint_batch_timeline_break_keys(&batches.breaks);
        let new_break_count = if has_previous {
            current_break_keys.difference(&previous_break_keys).count()
        } else {
            0
        };
        let resolved_break_count = if has_previous {
            previous_break_keys.difference(&current_break_keys).count()
        } else {
            0
        };
        let persistent_break_count = if has_previous {
            current_break_keys
                .intersection(&previous_break_keys)
                .count()
        } else {
            0
        };
        let label = debug_frame_timeline_label(trace, index);
        let reason_counts = debug_paint_batch_timeline_reason_counts(&batches.breaks);
        for (reason, break_count) in &reason_counts {
            debug_paint_batch_timeline_merge_reason(
                &mut records,
                &label,
                reason,
                *break_count,
                batches.status,
            );
        }
        frames.push(debug_paint_batch_timeline_frame_record(
            index,
            label,
            trace.frame_index,
            batches,
            &reason_counts,
            new_break_count,
            resolved_break_count,
            persistent_break_count,
        ));
        previous_break_keys = current_break_keys;
        has_previous = true;
    }

    let frame_count = frames.len();
    let split_frame_count = frames
        .iter()
        .filter(|frame| frame.break_count > 0 || frame.batch_count > 1)
        .count();
    let warning_frame_count = frames
        .iter()
        .filter(|frame| frame.status == DebugFrameTraceStatus::Warning)
        .count();
    let changed_frame_count = frames
        .iter()
        .filter(|frame| frame.new_break_count > 0 || frame.resolved_break_count > 0)
        .count();
    let item_count = frames.iter().map(|frame| frame.item_count).sum::<usize>();
    let batch_count = frames.iter().map(|frame| frame.batch_count).sum::<usize>();
    let singleton_batch_count = frames
        .iter()
        .map(|frame| frame.singleton_batch_count)
        .sum::<usize>();
    let break_count = frames.iter().map(|frame| frame.break_count).sum::<usize>();
    let new_break_count = frames
        .iter()
        .map(|frame| frame.new_break_count)
        .sum::<usize>();
    let resolved_break_count = frames
        .iter()
        .map(|frame| frame.resolved_break_count)
        .sum::<usize>();
    let persistent_break_count = frames
        .iter()
        .map(|frame| frame.persistent_break_count)
        .sum::<usize>();
    let max_batch_count = frames
        .iter()
        .map(|frame| frame.batch_count)
        .max()
        .unwrap_or(0);
    let max_singleton_batch_count = frames
        .iter()
        .map(|frame| frame.singleton_batch_count)
        .max()
        .unwrap_or(0);
    let max_break_count = frames
        .iter()
        .map(|frame| frame.break_count)
        .max()
        .unwrap_or(0);
    let average_items_per_batch = if batch_count == 0 {
        0.0
    } else {
        item_count as f32 / batch_count as f32
    };

    let mut records = records
        .into_iter()
        .map(|record| debug_paint_batch_timeline_reason_record(record, frame_count))
        .collect::<Vec<_>>();
    records.sort_by(|left, right| {
        debug_paint_batch_status_rank(left.status)
            .cmp(&debug_paint_batch_status_rank(right.status))
            .then_with(|| right.break_count.cmp(&left.break_count))
            .then_with(|| right.frame_count.cmp(&left.frame_count))
            .then_with(|| left.reason.cmp(&right.reason))
    });

    let status = debug_paint_batch_timeline_status(&frames);
    let top_reason = records.first().map(|record| record.reason.clone());
    let summary = debug_paint_batch_timeline_summary(
        status,
        frame_count,
        split_frame_count,
        warning_frame_count,
        changed_frame_count,
        break_count,
        new_break_count,
        resolved_break_count,
        max_batch_count,
        max_singleton_batch_count,
        average_items_per_batch,
        top_reason.as_deref(),
    );

    DebugPaintBatchTimelineTrace {
        status,
        frame_count,
        split_frame_count,
        warning_frame_count,
        changed_frame_count,
        item_count,
        batch_count,
        singleton_batch_count,
        break_count,
        new_break_count,
        resolved_break_count,
        persistent_break_count,
        max_batch_count,
        max_singleton_batch_count,
        max_break_count,
        average_items_per_batch,
        top_reason,
        records,
        frames,
        summary,
    }
}

fn debug_paint_batch_timeline_break_keys(
    records: &[DebugPaintBatchBreakRecord],
) -> HashSet<String> {
    records
        .iter()
        .map(debug_paint_batch_timeline_break_key)
        .collect()
}

fn debug_paint_batch_timeline_break_key(record: &DebugPaintBatchBreakRecord) -> String {
    format!(
        "{}->{}:{}",
        record.from_kind,
        record.to_kind,
        debug_paint_batch_timeline_reasons(record).join("+")
    )
}

fn debug_paint_batch_timeline_reason_counts(
    records: &[DebugPaintBatchBreakRecord],
) -> BTreeMap<String, usize> {
    let mut counts = BTreeMap::new();
    for record in records {
        for reason in debug_paint_batch_timeline_reasons(record) {
            *counts.entry(reason).or_default() += 1;
        }
    }
    counts
}

fn debug_paint_batch_timeline_reasons(record: &DebugPaintBatchBreakRecord) -> Vec<String> {
    let mut reasons = Vec::new();
    if record.kind_changed {
        reasons.push("kind".to_owned());
    }
    if record.layer_changed {
        reasons.push("layer".to_owned());
    }
    if record.z_changed {
        reasons.push("z".to_owned());
    }
    if record.clip_changed {
        reasons.push("clip".to_owned());
    }
    if record.shader_changed {
        reasons.push("shader".to_owned());
    }
    if reasons.is_empty() {
        reasons.push("order".to_owned());
    }
    reasons
}

fn debug_paint_batch_timeline_merge_reason(
    records: &mut Vec<DebugPaintBatchTimelineReasonAccumulator>,
    frame_label: &str,
    reason: &str,
    break_count: usize,
    frame_status: DebugFrameTraceStatus,
) {
    let status = debug_paint_batch_timeline_reason_status(reason, break_count, frame_status);
    let Some(accumulator) = records
        .iter_mut()
        .find(|accumulator| accumulator.reason == reason)
    else {
        records.push(DebugPaintBatchTimelineReasonAccumulator {
            reason: reason.to_owned(),
            status,
            frame_count: 1,
            break_count,
            first_frame_label: Some(frame_label.to_owned()),
            latest_frame_label: Some(frame_label.to_owned()),
            max_break_count: break_count,
            latest_break_count: break_count,
        });
        return;
    };

    accumulator.status = accumulator.status.max(status);
    accumulator.frame_count += 1;
    accumulator.break_count += break_count;
    accumulator.latest_frame_label = Some(frame_label.to_owned());
    accumulator.max_break_count = accumulator.max_break_count.max(break_count);
    accumulator.latest_break_count = break_count;
}

fn debug_paint_batch_timeline_reason_status(
    reason: &str,
    break_count: usize,
    frame_status: DebugFrameTraceStatus,
) -> DebugFrameTraceStatus {
    if frame_status == DebugFrameTraceStatus::Warning {
        return DebugFrameTraceStatus::Warning;
    }
    if break_count >= 4 && matches!(reason, "shader" | "clip" | "layer" | "z") {
        return DebugFrameTraceStatus::Warning;
    }
    DebugFrameTraceStatus::Info
}

fn debug_paint_batch_timeline_reason_record(
    record: DebugPaintBatchTimelineReasonAccumulator,
    retained_frame_count: usize,
) -> DebugPaintBatchTimelineReasonRecord {
    let summary = debug_paint_batch_timeline_reason_summary(
        &record.reason,
        record.status,
        record.frame_count,
        retained_frame_count,
        record.break_count,
        record.max_break_count,
    );
    let cause = debug_paint_batch_timeline_reason_cause(
        &record.reason,
        record.frame_count,
        retained_frame_count,
        record.break_count,
        record.latest_break_count,
    );
    let fix = debug_paint_batch_timeline_reason_fix(&record.reason);
    DebugPaintBatchTimelineReasonRecord {
        reason: record.reason,
        status: record.status,
        frame_count: record.frame_count,
        break_count: record.break_count,
        first_frame_label: record.first_frame_label,
        latest_frame_label: record.latest_frame_label,
        max_break_count: record.max_break_count,
        latest_break_count: record.latest_break_count,
        summary,
        cause,
        fix,
    }
}

#[allow(clippy::too_many_arguments)]
fn debug_paint_batch_timeline_frame_record(
    index: usize,
    label: String,
    frame_index: Option<u64>,
    trace: &DebugPaintBatchTrace,
    reason_counts: &BTreeMap<String, usize>,
    new_break_count: usize,
    resolved_break_count: usize,
    persistent_break_count: usize,
) -> DebugPaintBatchTimelineFrameRecord {
    let top_reason = reason_counts
        .iter()
        .max_by(|left, right| left.1.cmp(right.1).then_with(|| right.0.cmp(left.0)))
        .map(|(reason, _)| reason.clone());
    let summary = debug_paint_batch_timeline_frame_summary(
        &label,
        trace.status,
        trace.item_count,
        trace.batch_count,
        trace.singleton_batch_count,
        trace.break_count,
        new_break_count,
        resolved_break_count,
        persistent_break_count,
        top_reason.as_deref(),
    );
    let cause = debug_paint_batch_timeline_frame_cause(
        trace,
        new_break_count,
        resolved_break_count,
        persistent_break_count,
        top_reason.as_deref(),
    );
    let fix = top_reason
        .as_deref()
        .map(debug_paint_batch_timeline_reason_fix)
        .unwrap_or_else(|| "no batch action needed".to_owned());
    DebugPaintBatchTimelineFrameRecord {
        index,
        label,
        frame_index,
        status: trace.status,
        item_count: trace.item_count,
        batch_count: trace.batch_count,
        singleton_batch_count: trace.singleton_batch_count,
        break_count: trace.break_count,
        new_break_count,
        resolved_break_count,
        persistent_break_count,
        largest_batch_len: trace.largest_batch_len,
        average_items_per_batch: trace.average_items_per_batch,
        top_reason,
        summary,
        cause,
        fix,
    }
}

fn debug_paint_batch_timeline_status(
    frames: &[DebugPaintBatchTimelineFrameRecord],
) -> DebugFrameTraceStatus {
    if frames
        .iter()
        .any(|frame| frame.status == DebugFrameTraceStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if frames.iter().any(|frame| frame.break_count > 0) {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

#[allow(clippy::too_many_arguments)]
fn debug_paint_batch_timeline_summary(
    status: DebugFrameTraceStatus,
    frame_count: usize,
    split_frame_count: usize,
    warning_frame_count: usize,
    changed_frame_count: usize,
    break_count: usize,
    new_break_count: usize,
    resolved_break_count: usize,
    max_batch_count: usize,
    max_singleton_batch_count: usize,
    average_items_per_batch: f32,
    top_reason: Option<&str>,
) -> String {
    let mut parts = vec![format!("{} paint batch timeline", status.label())];
    parts.push(format!(
        "{frame_count} frame{}",
        debug_plural_s(frame_count)
    ));
    if split_frame_count > 0 {
        parts.push(format!(
            "{split_frame_count} split frame{}",
            debug_plural_s(split_frame_count)
        ));
    }
    if warning_frame_count > 0 {
        parts.push(format!(
            "{warning_frame_count} warning frame{}",
            debug_plural_s(warning_frame_count)
        ));
    }
    if changed_frame_count > 0 {
        parts.push(format!(
            "{changed_frame_count} changed frame{}",
            debug_plural_s(changed_frame_count)
        ));
    }
    if break_count > 0 {
        parts.push(format!(
            "{break_count} split{}",
            debug_plural_s(break_count)
        ));
    }
    if new_break_count > 0 {
        parts.push(format!(
            "{new_break_count} new split{}",
            debug_plural_s(new_break_count)
        ));
    }
    if resolved_break_count > 0 {
        parts.push(format!(
            "{resolved_break_count} resolved split{}",
            debug_plural_s(resolved_break_count)
        ));
    }
    parts.push(format!(
        "max {max_batch_count} batches; max {max_singleton_batch_count} singleton; avg {:.1} items/batch",
        average_items_per_batch
    ));
    if let Some(top_reason) = top_reason {
        parts.push(format!("top {top_reason}"));
    }
    parts.join("; ")
}

fn debug_paint_batch_timeline_reason_summary(
    reason: &str,
    status: DebugFrameTraceStatus,
    frame_count: usize,
    retained_frame_count: usize,
    break_count: usize,
    max_break_count: usize,
) -> String {
    format!(
        "{} paint batch {reason} splits; {break_count} total across {frame_count}/{retained_frame_count} frame{}; max {max_break_count}",
        status.label(),
        debug_plural_s(retained_frame_count)
    )
}

fn debug_paint_batch_timeline_reason_cause(
    reason: &str,
    frame_count: usize,
    retained_frame_count: usize,
    break_count: usize,
    latest_break_count: usize,
) -> String {
    let reason_cause = match reason {
        "layer" => "paint moved between UI layers",
        "z" => "local z or resolved layer order changed",
        "clip" => "clip rectangles differed between adjacent paint",
        "shader" => "shader or material keys differed between adjacent paint",
        "kind" => "primitive kinds differed between adjacent paint",
        _ => "paint order separated otherwise compatible items",
    };
    format!(
        "{reason_cause}; {break_count} split{} across {frame_count}/{retained_frame_count} retained frame{}; latest {latest_break_count}",
        debug_plural_s(break_count),
        debug_plural_s(retained_frame_count)
    )
}

fn debug_paint_batch_timeline_frame_summary(
    label: &str,
    status: DebugFrameTraceStatus,
    item_count: usize,
    batch_count: usize,
    singleton_batch_count: usize,
    break_count: usize,
    new_break_count: usize,
    resolved_break_count: usize,
    persistent_break_count: usize,
    top_reason: Option<&str>,
) -> String {
    let mut parts = vec![format!("{} paint batches for {label}", status.label())];
    parts.push(format!("{item_count} items -> {batch_count} batches"));
    if singleton_batch_count > 0 {
        parts.push(format!(
            "{singleton_batch_count} singleton{}",
            debug_plural_s(singleton_batch_count)
        ));
    }
    if break_count > 0 {
        parts.push(format!(
            "{break_count} split{}",
            debug_plural_s(break_count)
        ));
    }
    if new_break_count > 0 {
        parts.push(format!(
            "{new_break_count} new{}",
            debug_plural_s(new_break_count)
        ));
    }
    if resolved_break_count > 0 {
        parts.push(format!(
            "{resolved_break_count} resolved{}",
            debug_plural_s(resolved_break_count)
        ));
    }
    if persistent_break_count > 0 {
        parts.push(format!(
            "{persistent_break_count} persistent{}",
            debug_plural_s(persistent_break_count)
        ));
    }
    if let Some(top_reason) = top_reason {
        parts.push(format!("top {top_reason}"));
    }
    parts.join("; ")
}

fn debug_paint_batch_timeline_frame_cause(
    trace: &DebugPaintBatchTrace,
    new_break_count: usize,
    resolved_break_count: usize,
    persistent_break_count: usize,
    top_reason: Option<&str>,
) -> String {
    let mut parts = vec![trace.summary.clone()];
    if new_break_count > 0 {
        parts.push(format!(
            "{new_break_count} batch split{} appeared since previous frame",
            debug_plural_s(new_break_count)
        ));
    }
    if resolved_break_count > 0 {
        parts.push(format!(
            "{resolved_break_count} batch split{} resolved since previous frame",
            debug_plural_s(resolved_break_count)
        ));
    }
    if persistent_break_count > 0 {
        parts.push(format!(
            "{persistent_break_count} batch split{} persisted",
            debug_plural_s(persistent_break_count)
        ));
    }
    if let Some(top_reason) = top_reason {
        parts.push(format!("top split reason {top_reason}"));
    }
    parts.join("; ")
}

fn debug_paint_batch_timeline_reason_fix(reason: &str) -> String {
    match reason {
        "layer" | "z" => "only adjust layer/z if the visual stacking order is accidental",
        "clip" => "align clipping ancestors or group similarly clipped paint together",
        "shader" => "reuse shader keys and group shader-backed nodes when visual order allows",
        "kind" => "keep repeated primitive kinds adjacent when visual order allows",
        _ => "inspect neighboring paint order and retained display-list grouping",
    }
    .to_owned()
}

fn debug_paint_batch_shader_key(batch: &PaintBatch) -> Option<&str> {
    batch.key.shader.as_ref().map(|shader| shader.key.as_str())
}

fn debug_paint_batch_kind_label(kind: PaintBatchKind) -> &'static str {
    match kind {
        PaintBatchKind::Rect => "rect",
        PaintBatchKind::Text => "text",
        PaintBatchKind::Canvas => "canvas",
        PaintBatchKind::Line => "line",
        PaintBatchKind::Circle => "circle",
        PaintBatchKind::Polygon => "polygon",
        PaintBatchKind::Image => "image",
        PaintBatchKind::CompositedLayer => "composited_layer",
        PaintBatchKind::RichRect => "rich_rect",
        PaintBatchKind::SceneText => "scene_text",
        PaintBatchKind::Path => "path",
        PaintBatchKind::ImagePlacement => "image_placement",
    }
}

fn debug_node_sort_key(node: &DebugHitboxNode) -> (LayerOrder, usize, usize) {
    (node.layer_order, node.order, node.id.0)
}

fn overlap_kind_rank(kind: DebugOverlapKind) -> u8 {
    match kind {
        DebugOverlapKind::InteractiveHitbox => 0,
        DebugOverlapKind::Paint => 1,
        DebugOverlapKind::Layout => 2,
    }
}

fn rect_overlap_at_least(left: UiRect, right: UiRect, min_area: f32) -> Option<UiRect> {
    left.intersection(right)
        .filter(|overlap| rect_area(*overlap) >= min_area.max(0.0))
}

fn optional_rect_overlap_at_least(
    left: Option<UiRect>,
    right: Option<UiRect>,
    min_area: f32,
) -> Option<UiRect> {
    rect_overlap_at_least(left?, right?, min_area)
}

fn rect_area(rect: UiRect) -> f32 {
    rect.width.max(0.0) * rect.height.max(0.0)
}

fn rect_union_area(rects: &[UiRect]) -> f32 {
    if rects.is_empty() {
        return 0.0;
    }

    let mut xs = Vec::with_capacity(rects.len() * 2);
    let mut ys = Vec::with_capacity(rects.len() * 2);
    for rect in rects.iter().copied().filter(|rect| rect_area(*rect) > 0.0) {
        xs.push(rect.x);
        xs.push(rect.right());
        ys.push(rect.y);
        ys.push(rect.bottom());
    }
    xs.sort_by(|left, right| left.total_cmp(right));
    ys.sort_by(|left, right| left.total_cmp(right));
    xs.dedup_by(|left, right| (*left - *right).abs() <= f32::EPSILON);
    ys.dedup_by(|left, right| (*left - *right).abs() <= f32::EPSILON);

    if xs.len() < 2 || ys.len() < 2 {
        return 0.0;
    }

    let mut area = 0.0_f32;
    for x_pair in xs.windows(2) {
        let x0 = x_pair[0];
        let x1 = x_pair[1];
        let width = x1 - x0;
        if width <= 0.0 {
            continue;
        }
        for y_pair in ys.windows(2) {
            let y0 = y_pair[0];
            let y1 = y_pair[1];
            let height = y1 - y0;
            if height <= 0.0 {
                continue;
            }
            if rects.iter().any(|rect| {
                x0 >= rect.x
                    && x1 <= rect.right()
                    && y0 >= rect.y
                    && y1 <= rect.bottom()
                    && rect_area(*rect) > 0.0
            }) {
                area += width * height;
            }
        }
    }
    area
}

const DEBUG_HIT_TARGET_MIN_SIZE: f32 = 24.0;

fn debug_stacking_order_relevant(hitbox: &DebugHitboxNode) -> bool {
    hitbox.pointer || hitbox.focusable || hitbox.hit_rect.is_some() || hitbox.paint_rect.is_some()
}

fn debug_stacking_order_rect(hitbox: &DebugHitboxNode) -> Option<UiRect> {
    hitbox
        .hit_rect
        .or(hitbox.paint_rect)
        .or(hitbox.visible_rect)
        .or(Some(hitbox.transformed_rect))
        .filter(|rect| rect_area(*rect) > 0.0)
}

#[allow(clippy::too_many_arguments)]
fn debug_stacking_order_record(
    hitbox: &DebugHitboxNode,
    front_index: usize,
    overlaps_in_front: usize,
    overlaps_behind: usize,
    front_neighbor: Option<String>,
    back_neighbor: Option<String>,
) -> DebugStackingOrderRecord {
    let effective_hit = hitbox.hit_eligibility.eligible && hitbox.hit_rect.is_some();
    let has_paint = hitbox.paint_rect.is_some();
    let clipped = hitbox
        .visible_rect
        .is_some_and(|visible| !debug_rect_contains_rect(visible, hitbox.transformed_rect));
    let status = debug_stacking_order_record_status(
        hitbox,
        effective_hit,
        clipped,
        overlaps_in_front,
        overlaps_behind,
    );
    let stack_rect = debug_stacking_order_rect(hitbox);
    let summary = debug_stacking_order_record_summary(
        hitbox,
        status,
        front_index,
        effective_hit,
        has_paint,
        clipped,
        overlaps_in_front,
        overlaps_behind,
    );
    let cause = debug_stacking_order_record_cause(
        hitbox,
        effective_hit,
        clipped,
        overlaps_in_front,
        overlaps_behind,
        front_neighbor.as_deref(),
        back_neighbor.as_deref(),
    );
    let fix = debug_stacking_order_record_fix(
        hitbox,
        effective_hit,
        clipped,
        overlaps_in_front,
        overlaps_behind,
    );

    DebugStackingOrderRecord {
        node: hitbox.id,
        name: hitbox.name.clone(),
        status,
        front_index,
        layer: hitbox.layer,
        layer_order: hitbox.layer_order,
        local_z: hitbox.local_z,
        resolved_z: hitbox.resolved_z,
        order: hitbox.order,
        pointer: hitbox.pointer,
        focusable: hitbox.focusable,
        visible: hitbox.visible,
        hit_testable: hitbox.hit_testable,
        effective_hit,
        has_paint,
        clipped,
        stack_rect,
        hit_rect: hitbox.hit_rect,
        paint_rect: hitbox.paint_rect,
        visible_rect: hitbox.visible_rect,
        overlaps_in_front,
        overlaps_behind,
        front_neighbor,
        back_neighbor,
        summary,
        cause,
        fix,
    }
}

fn debug_stacking_order_record_status(
    hitbox: &DebugHitboxNode,
    effective_hit: bool,
    clipped: bool,
    overlaps_in_front: usize,
    overlaps_behind: usize,
) -> DebugFrameTraceStatus {
    let interactive = hitbox.pointer || hitbox.focusable;
    if interactive && (!hitbox.visible || !hitbox.hit_testable || !effective_hit) {
        return DebugFrameTraceStatus::Error;
    }
    if interactive && (overlaps_in_front > 0 || clipped) {
        return DebugFrameTraceStatus::Warning;
    }
    if overlaps_in_front > 0 || overlaps_behind > 0 || hitbox.paint_rect.is_some() || interactive {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

#[allow(clippy::too_many_arguments)]
fn debug_stacking_order_record_summary(
    hitbox: &DebugHitboxNode,
    status: DebugFrameTraceStatus,
    front_index: usize,
    effective_hit: bool,
    has_paint: bool,
    clipped: bool,
    overlaps_in_front: usize,
    overlaps_behind: usize,
) -> String {
    let mut parts = vec![
        format!("front #{front_index}"),
        format!("{} stacking", status.label()),
        debug_stacking_order_sort_label(hitbox),
    ];
    if hitbox.pointer || hitbox.focusable {
        let mut roles = Vec::new();
        if hitbox.pointer {
            roles.push("pointer");
        }
        if hitbox.focusable {
            roles.push("focus");
        }
        parts.push(roles.join("+"));
    } else {
        parts.push("passive".to_owned());
    }
    if effective_hit {
        parts.push("hit".to_owned());
    } else if hitbox.pointer || hitbox.focusable {
        parts.push("no effective hit".to_owned());
    }
    if has_paint {
        parts.push("paint".to_owned());
    }
    if overlaps_in_front > 0 {
        parts.push(format!("{overlaps_in_front} in front"));
    }
    if overlaps_behind > 0 {
        parts.push(format!("{overlaps_behind} behind"));
    }
    if clipped {
        parts.push("clipped".to_owned());
    }
    parts.join("; ")
}

#[allow(clippy::too_many_arguments)]
fn debug_stacking_order_record_cause(
    hitbox: &DebugHitboxNode,
    effective_hit: bool,
    clipped: bool,
    overlaps_in_front: usize,
    overlaps_behind: usize,
    front_neighbor: Option<&str>,
    back_neighbor: Option<&str>,
) -> String {
    if hitbox.pointer || hitbox.focusable {
        if !hitbox.visible {
            return "interactive node is hidden before stacking is considered".to_owned();
        }
        if !hitbox.hit_testable || !effective_hit {
            return "interactive node does not have an effective hit rectangle in the stack"
                .to_owned();
        }
    }
    if let Some(front_neighbor) = front_neighbor {
        return format!(
            "{front_neighbor} sorts in front by layer/z/order; {}",
            debug_stacking_order_sort_label(hitbox)
        );
    }
    if let Some(back_neighbor) = back_neighbor {
        return format!(
            "this node sorts in front of {back_neighbor} by layer/z/order; {}",
            debug_stacking_order_sort_label(hitbox)
        );
    }
    if clipped {
        return "ancestor clipping reduces the effective stack rectangle".to_owned();
    }
    if overlaps_in_front > 0 {
        return "higher stack entries overlap this node's hit or paint rectangle".to_owned();
    }
    if overlaps_behind > 0 {
        return "this node overlaps lower stack entries".to_owned();
    }
    if hitbox.paint_rect.is_some() {
        return "node contributes paint to the frame stack".to_owned();
    }
    "node participates in hit testing without overlapping another stack entry".to_owned()
}

fn debug_stacking_order_record_fix(
    hitbox: &DebugHitboxNode,
    effective_hit: bool,
    clipped: bool,
    overlaps_in_front: usize,
    overlaps_behind: usize,
) -> String {
    let interactive = hitbox.pointer || hitbox.focusable;
    if interactive && (!hitbox.visible || !hitbox.hit_testable || !effective_hit) {
        return "inspect hitbox_map_panel, visibility_panel, and hit_target_panel before changing z"
            .to_owned();
    }
    if interactive && overlaps_in_front > 0 {
        return "make the covering node passive, move the target, or adjust layer/z/order intentionally"
            .to_owned();
    }
    if interactive && clipped {
        return "relax the clipping ancestor, portal the control, or shrink the target to visible bounds"
            .to_owned();
    }
    if overlaps_behind > 0 || overlaps_in_front > 0 {
        return "inspect overlap_autopsy_panel and paint_order_panel before changing stack order"
            .to_owned();
    }
    "no stacking action needed".to_owned()
}

fn debug_stacking_order_sort_label(hitbox: &DebugHitboxNode) -> String {
    format!(
        "{:?} z {} local {} order {}",
        hitbox.layer, hitbox.resolved_z, hitbox.local_z, hitbox.order
    )
}

fn debug_stacking_order_trace_status(
    records: &[DebugStackingOrderRecord],
) -> DebugFrameTraceStatus {
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Error)
    {
        return DebugFrameTraceStatus::Error;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Info)
    {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

#[allow(clippy::too_many_arguments)]
fn debug_stacking_order_trace_summary(
    status: DebugFrameTraceStatus,
    node_count: usize,
    interactive_count: usize,
    paint_count: usize,
    layer_count: usize,
    min_resolved_z: Option<f32>,
    max_resolved_z: Option<f32>,
    overlap_pair_count: usize,
    covered_interactive_count: usize,
) -> String {
    let mut parts = vec![
        format!("{} stacking order", status.label()),
        format!("{node_count} nodes"),
        format!("{interactive_count} interactive"),
        format!("{paint_count} painted"),
        format!("{layer_count} layers"),
    ];
    if let (Some(min_z), Some(max_z)) = (min_resolved_z, max_resolved_z) {
        if min_z == max_z {
            parts.push(format!("z {min_z}"));
        } else {
            parts.push(format!("z {min_z}..{max_z}"));
        }
    }
    if overlap_pair_count > 0 {
        parts.push(format!(
            "{overlap_pair_count} overlap pair{}",
            debug_plural_s(overlap_pair_count)
        ));
    }
    if covered_interactive_count > 0 {
        parts.push(format!("{covered_interactive_count} covered interactive"));
    }
    parts.join("; ")
}

#[derive(Debug)]
struct DebugStackingOrderTimelineAccumulator {
    name: String,
    status: DebugFrameTraceStatus,
    frame_count: usize,
    changed_frame_count: usize,
    covered_frame_count: usize,
    warning_frame_count: usize,
    first_frame_label: Option<String>,
    latest_frame_label: Option<String>,
    min_front_index: usize,
    max_front_index: usize,
    latest_front_index: usize,
    latest_layer: UiLayer,
    latest_layer_order: LayerOrder,
    min_resolved_z: f32,
    max_resolved_z: f32,
    latest_resolved_z: f32,
    latest_local_z: f32,
    latest_order: usize,
    max_overlaps_in_front: usize,
    max_overlaps_behind: usize,
    latest_front_neighbor: Option<String>,
    latest_back_neighbor: Option<String>,
    latest_summary: String,
    latest_cause: String,
    latest_fix: String,
}

fn debug_stacking_order_timeline_trace<'a>(
    traces: impl IntoIterator<Item = &'a DebugFrameTrace>,
) -> DebugStackingOrderTimelineTrace {
    let traces = traces.into_iter().collect::<Vec<_>>();
    let mut records = Vec::<DebugStackingOrderTimelineAccumulator>::new();
    let mut frames = Vec::new();
    let mut previous_stack: Option<DebugStackingOrderTrace> = None;

    for (index, trace) in traces.iter().enumerate() {
        let stack = DebugStackingOrderTrace::from_snapshot(&trace.snapshot);
        let current_covered = debug_stacking_order_timeline_covered_keys(&stack.records);
        let previous_covered = previous_stack
            .as_ref()
            .map(|previous| debug_stacking_order_timeline_covered_keys(&previous.records))
            .unwrap_or_default();
        let has_previous = previous_stack.is_some();
        let new_covered_count = if has_previous {
            current_covered.difference(&previous_covered).count()
        } else {
            0
        };
        let resolved_covered_count = if has_previous {
            previous_covered.difference(&current_covered).count()
        } else {
            0
        };
        let persistent_covered_count = if has_previous {
            current_covered.intersection(&previous_covered).count()
        } else {
            0
        };
        let changed_node_count = previous_stack
            .as_ref()
            .map(|previous| debug_stacking_order_timeline_changed_node_count(previous, &stack))
            .unwrap_or_default();
        let label = debug_frame_timeline_label(trace, index);
        for record in &stack.records {
            let changed = previous_stack
                .as_ref()
                .and_then(|previous| previous.record(&record.name))
                .map(|previous| debug_stacking_order_timeline_record_changed(previous, record))
                .unwrap_or(has_previous);
            debug_stacking_order_timeline_merge_record(&mut records, &label, record, changed);
        }
        frames.push(debug_stacking_order_timeline_frame_record(
            index,
            label,
            trace.frame_index,
            &stack,
            changed_node_count,
            new_covered_count,
            resolved_covered_count,
            persistent_covered_count,
        ));
        previous_stack = Some(stack);
    }

    let frame_count = frames.len();
    let stack_frame_count = frames.iter().filter(|frame| frame.node_count > 0).count();
    let warning_frame_count = frames
        .iter()
        .filter(|frame| {
            matches!(
                frame.status,
                DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
            )
        })
        .count();
    let changed_frame_count = frames
        .iter()
        .filter(|frame| {
            frame.changed_node_count > 0
                || frame.new_covered_count > 0
                || frame.resolved_covered_count > 0
        })
        .count();
    let node_count = frames.iter().map(|frame| frame.node_count).sum();
    let interactive_count = frames.iter().map(|frame| frame.interactive_count).sum();
    let paint_count = frames.iter().map(|frame| frame.paint_count).sum();
    let max_layer_count = frames
        .iter()
        .map(|frame| frame.layer_count)
        .max()
        .unwrap_or_default();
    let min_resolved_z = frames
        .iter()
        .filter_map(|frame| frame.min_resolved_z)
        .min_by(|left, right| left.total_cmp(right));
    let max_resolved_z = frames
        .iter()
        .filter_map(|frame| frame.max_resolved_z)
        .max_by(|left, right| left.total_cmp(right));
    let overlap_pair_count = frames.iter().map(|frame| frame.overlap_pair_count).sum();
    let covered_interactive_count = frames
        .iter()
        .map(|frame| frame.covered_interactive_count)
        .sum();
    let changed_node_count = frames.iter().map(|frame| frame.changed_node_count).sum();
    let new_covered_count = frames.iter().map(|frame| frame.new_covered_count).sum();
    let resolved_covered_count = frames
        .iter()
        .map(|frame| frame.resolved_covered_count)
        .sum();
    let persistent_covered_count = frames
        .iter()
        .map(|frame| frame.persistent_covered_count)
        .sum();

    let mut records = records
        .into_iter()
        .map(|record| debug_stacking_order_timeline_record(record, frame_count))
        .collect::<Vec<_>>();
    records.sort_by(|left, right| {
        debug_stacking_order_status_rank(left.status)
            .cmp(&debug_stacking_order_status_rank(right.status))
            .then_with(|| right.covered_frame_count.cmp(&left.covered_frame_count))
            .then_with(|| right.changed_frame_count.cmp(&left.changed_frame_count))
            .then_with(|| right.max_overlaps_in_front.cmp(&left.max_overlaps_in_front))
            .then_with(|| left.name.cmp(&right.name))
    });

    let status = debug_stacking_order_timeline_status(&frames);
    let top_node_name = records.first().map(|record| record.name.clone());
    let summary = debug_stacking_order_timeline_summary(
        status,
        frame_count,
        stack_frame_count,
        warning_frame_count,
        changed_frame_count,
        node_count,
        overlap_pair_count,
        covered_interactive_count,
        changed_node_count,
        new_covered_count,
        resolved_covered_count,
        min_resolved_z,
        max_resolved_z,
        top_node_name.as_deref(),
    );

    DebugStackingOrderTimelineTrace {
        status,
        frame_count,
        stack_frame_count,
        warning_frame_count,
        changed_frame_count,
        node_count,
        interactive_count,
        paint_count,
        max_layer_count,
        min_resolved_z,
        max_resolved_z,
        overlap_pair_count,
        covered_interactive_count,
        changed_node_count,
        new_covered_count,
        resolved_covered_count,
        persistent_covered_count,
        top_node_name,
        records,
        frames,
        summary,
    }
}

fn debug_stacking_order_timeline_covered_keys(
    records: &[DebugStackingOrderRecord],
) -> HashSet<String> {
    records
        .iter()
        .filter(|record| debug_stacking_order_timeline_record_covered(record))
        .map(|record| record.name.clone())
        .collect()
}

fn debug_stacking_order_timeline_record_covered(record: &DebugStackingOrderRecord) -> bool {
    (record.pointer || record.focusable) && record.effective_hit && record.overlaps_in_front > 0
}

fn debug_stacking_order_timeline_changed_node_count(
    previous: &DebugStackingOrderTrace,
    current: &DebugStackingOrderTrace,
) -> usize {
    let previous_names = previous
        .records
        .iter()
        .map(|record| record.name.clone())
        .collect::<HashSet<_>>();
    let current_names = current
        .records
        .iter()
        .map(|record| record.name.clone())
        .collect::<HashSet<_>>();
    let added_removed_count = previous_names.difference(&current_names).count()
        + current_names.difference(&previous_names).count();
    let changed_existing_count = current
        .records
        .iter()
        .filter(|record| {
            previous.record(&record.name).is_some_and(|previous| {
                debug_stacking_order_timeline_record_changed(previous, record)
            })
        })
        .count();
    added_removed_count + changed_existing_count
}

fn debug_stacking_order_timeline_record_changed(
    previous: &DebugStackingOrderRecord,
    current: &DebugStackingOrderRecord,
) -> bool {
    previous.front_index != current.front_index
        || previous.layer != current.layer
        || previous.layer_order != current.layer_order
        || previous.local_z != current.local_z
        || previous.resolved_z != current.resolved_z
        || previous.order != current.order
        || previous.overlaps_in_front != current.overlaps_in_front
        || previous.overlaps_behind != current.overlaps_behind
        || previous.front_neighbor != current.front_neighbor
        || previous.back_neighbor != current.back_neighbor
}

fn debug_stacking_order_timeline_merge_record(
    records: &mut Vec<DebugStackingOrderTimelineAccumulator>,
    frame_label: &str,
    record: &DebugStackingOrderRecord,
    changed: bool,
) {
    let covered = debug_stacking_order_timeline_record_covered(record);
    let warning = matches!(
        record.status,
        DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
    );
    let Some(accumulator) = records
        .iter_mut()
        .find(|accumulator| accumulator.name == record.name)
    else {
        records.push(DebugStackingOrderTimelineAccumulator {
            name: record.name.clone(),
            status: record.status,
            frame_count: 1,
            changed_frame_count: usize::from(changed),
            covered_frame_count: usize::from(covered),
            warning_frame_count: usize::from(warning),
            first_frame_label: Some(frame_label.to_owned()),
            latest_frame_label: Some(frame_label.to_owned()),
            min_front_index: record.front_index,
            max_front_index: record.front_index,
            latest_front_index: record.front_index,
            latest_layer: record.layer,
            latest_layer_order: record.layer_order,
            min_resolved_z: record.resolved_z,
            max_resolved_z: record.resolved_z,
            latest_resolved_z: record.resolved_z,
            latest_local_z: record.local_z,
            latest_order: record.order,
            max_overlaps_in_front: record.overlaps_in_front,
            max_overlaps_behind: record.overlaps_behind,
            latest_front_neighbor: record.front_neighbor.clone(),
            latest_back_neighbor: record.back_neighbor.clone(),
            latest_summary: record.summary.clone(),
            latest_cause: record.cause.clone(),
            latest_fix: record.fix.clone(),
        });
        return;
    };

    accumulator.status = accumulator.status.max(record.status);
    accumulator.frame_count += 1;
    accumulator.changed_frame_count += usize::from(changed);
    accumulator.covered_frame_count += usize::from(covered);
    accumulator.warning_frame_count += usize::from(warning);
    accumulator.latest_frame_label = Some(frame_label.to_owned());
    accumulator.min_front_index = accumulator.min_front_index.min(record.front_index);
    accumulator.max_front_index = accumulator.max_front_index.max(record.front_index);
    accumulator.latest_front_index = record.front_index;
    accumulator.latest_layer = record.layer;
    accumulator.latest_layer_order = record.layer_order;
    accumulator.min_resolved_z = accumulator.min_resolved_z.min(record.resolved_z);
    accumulator.max_resolved_z = accumulator.max_resolved_z.max(record.resolved_z);
    accumulator.latest_resolved_z = record.resolved_z;
    accumulator.latest_local_z = record.local_z;
    accumulator.latest_order = record.order;
    accumulator.max_overlaps_in_front = accumulator
        .max_overlaps_in_front
        .max(record.overlaps_in_front);
    accumulator.max_overlaps_behind = accumulator.max_overlaps_behind.max(record.overlaps_behind);
    accumulator.latest_front_neighbor = record.front_neighbor.clone();
    accumulator.latest_back_neighbor = record.back_neighbor.clone();
    accumulator.latest_summary = record.summary.clone();
    accumulator.latest_cause = record.cause.clone();
    accumulator.latest_fix = record.fix.clone();
}

fn debug_stacking_order_timeline_record(
    record: DebugStackingOrderTimelineAccumulator,
    retained_frame_count: usize,
) -> DebugStackingOrderTimelineRecord {
    let summary = debug_stacking_order_timeline_record_summary(
        &record.name,
        record.status,
        record.frame_count,
        retained_frame_count,
        record.changed_frame_count,
        record.covered_frame_count,
        record.warning_frame_count,
        record.min_front_index,
        record.max_front_index,
        record.min_resolved_z,
        record.max_resolved_z,
    );
    let cause = debug_stacking_order_timeline_record_cause(
        &record.name,
        record.changed_frame_count,
        record.covered_frame_count,
        record.latest_front_neighbor.as_deref(),
        record.latest_back_neighbor.as_deref(),
        &record.latest_cause,
    );
    let fix = debug_stacking_order_timeline_record_fix(
        &record.name,
        record.changed_frame_count,
        record.covered_frame_count,
        record.warning_frame_count,
        &record.latest_fix,
    );

    DebugStackingOrderTimelineRecord {
        name: record.name,
        status: record.status,
        frame_count: record.frame_count,
        changed_frame_count: record.changed_frame_count,
        covered_frame_count: record.covered_frame_count,
        warning_frame_count: record.warning_frame_count,
        first_frame_label: record.first_frame_label,
        latest_frame_label: record.latest_frame_label,
        min_front_index: record.min_front_index,
        max_front_index: record.max_front_index,
        latest_front_index: record.latest_front_index,
        latest_layer: record.latest_layer,
        latest_layer_order: record.latest_layer_order,
        min_resolved_z: record.min_resolved_z,
        max_resolved_z: record.max_resolved_z,
        latest_resolved_z: record.latest_resolved_z,
        latest_local_z: record.latest_local_z,
        latest_order: record.latest_order,
        max_overlaps_in_front: record.max_overlaps_in_front,
        max_overlaps_behind: record.max_overlaps_behind,
        latest_front_neighbor: record.latest_front_neighbor,
        latest_back_neighbor: record.latest_back_neighbor,
        latest_summary: record.latest_summary,
        summary,
        cause,
        fix,
    }
}

fn debug_stacking_order_timeline_frame_record(
    index: usize,
    label: String,
    frame_index: Option<u64>,
    trace: &DebugStackingOrderTrace,
    changed_node_count: usize,
    new_covered_count: usize,
    resolved_covered_count: usize,
    persistent_covered_count: usize,
) -> DebugStackingOrderTimelineFrameRecord {
    let top_record = trace.records.iter().min_by(|left, right| {
        debug_stacking_order_status_rank(left.status)
            .cmp(&debug_stacking_order_status_rank(right.status))
            .then_with(|| right.overlaps_in_front.cmp(&left.overlaps_in_front))
            .then_with(|| right.overlaps_behind.cmp(&left.overlaps_behind))
            .then_with(|| left.front_index.cmp(&right.front_index))
            .then_with(|| left.name.cmp(&right.name))
    });
    let top_node_name = top_record.map(|record| record.name.clone());
    let summary = debug_stacking_order_timeline_frame_summary(
        &label,
        trace.status,
        trace.node_count,
        trace.interactive_count,
        trace.layer_count,
        trace.overlap_pair_count,
        trace.covered_interactive_count,
        changed_node_count,
        new_covered_count,
        resolved_covered_count,
        top_node_name.as_deref(),
    );
    let cause = debug_stacking_order_timeline_frame_cause(
        changed_node_count,
        trace.covered_interactive_count,
        new_covered_count,
        resolved_covered_count,
        top_node_name.as_deref(),
    );
    let fix = debug_stacking_order_timeline_frame_fix(
        changed_node_count,
        trace.covered_interactive_count,
        new_covered_count,
        resolved_covered_count,
        top_node_name.as_deref(),
    );

    DebugStackingOrderTimelineFrameRecord {
        index,
        label,
        frame_index,
        status: trace.status,
        node_count: trace.node_count,
        interactive_count: trace.interactive_count,
        paint_count: trace.paint_count,
        layer_count: trace.layer_count,
        min_resolved_z: trace.min_resolved_z,
        max_resolved_z: trace.max_resolved_z,
        overlap_pair_count: trace.overlap_pair_count,
        covered_interactive_count: trace.covered_interactive_count,
        changed_node_count,
        new_covered_count,
        resolved_covered_count,
        persistent_covered_count,
        top_node_name,
        summary,
        cause,
        fix,
    }
}

fn debug_stacking_order_status_rank(status: DebugFrameTraceStatus) -> u8 {
    match status {
        DebugFrameTraceStatus::Error => 0,
        DebugFrameTraceStatus::Warning => 1,
        DebugFrameTraceStatus::Info => 2,
        DebugFrameTraceStatus::Ok => 3,
    }
}

fn debug_stacking_order_timeline_status(
    frames: &[DebugStackingOrderTimelineFrameRecord],
) -> DebugFrameTraceStatus {
    if frames
        .iter()
        .any(|frame| frame.status == DebugFrameTraceStatus::Error)
    {
        return DebugFrameTraceStatus::Error;
    }
    if frames
        .iter()
        .any(|frame| frame.status == DebugFrameTraceStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if frames.iter().any(|frame| {
        frame.status == DebugFrameTraceStatus::Info
            || frame.changed_node_count > 0
            || frame.new_covered_count > 0
            || frame.resolved_covered_count > 0
    }) {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

#[allow(clippy::too_many_arguments)]
fn debug_stacking_order_timeline_summary(
    status: DebugFrameTraceStatus,
    frame_count: usize,
    stack_frame_count: usize,
    warning_frame_count: usize,
    changed_frame_count: usize,
    node_count: usize,
    overlap_pair_count: usize,
    covered_interactive_count: usize,
    changed_node_count: usize,
    new_covered_count: usize,
    resolved_covered_count: usize,
    min_resolved_z: Option<f32>,
    max_resolved_z: Option<f32>,
    top_node_name: Option<&str>,
) -> String {
    let mut parts = vec![format!("{} stacking order timeline", status.label())];
    parts.push(format!(
        "{frame_count} frame{}",
        debug_plural_s(frame_count)
    ));
    if stack_frame_count > 0 {
        parts.push(format!("{stack_frame_count} stack frames"));
    }
    if warning_frame_count > 0 {
        parts.push(format!("{warning_frame_count} warning frames"));
    }
    if changed_frame_count > 0 {
        parts.push(format!("{changed_frame_count} changed frames"));
    }
    if node_count > 0 {
        parts.push(format!("{node_count} stack records"));
    }
    if overlap_pair_count > 0 {
        parts.push(format!("{overlap_pair_count} overlap pairs"));
    }
    if covered_interactive_count > 0 {
        parts.push(format!("{covered_interactive_count} covered interactive"));
    }
    if changed_node_count > 0 {
        parts.push(format!("{changed_node_count} changed nodes"));
    }
    if new_covered_count > 0 {
        parts.push(format!("{new_covered_count} new covered"));
    }
    if resolved_covered_count > 0 {
        parts.push(format!("{resolved_covered_count} resolved covered"));
    }
    if let (Some(min_z), Some(max_z)) = (min_resolved_z, max_resolved_z) {
        if min_z == max_z {
            parts.push(format!("z {min_z}"));
        } else {
            parts.push(format!("z {min_z}..{max_z}"));
        }
    }
    if let Some(top) = top_node_name {
        parts.push(format!("top {top}"));
    }
    parts.join("; ")
}

#[allow(clippy::too_many_arguments)]
fn debug_stacking_order_timeline_record_summary(
    name: &str,
    status: DebugFrameTraceStatus,
    frame_count: usize,
    retained_frame_count: usize,
    changed_frame_count: usize,
    covered_frame_count: usize,
    warning_frame_count: usize,
    min_front_index: usize,
    max_front_index: usize,
    min_resolved_z: f32,
    max_resolved_z: f32,
) -> String {
    let mut parts = vec![format!("{} stack {name}", status.label())];
    parts.push(format!(
        "{frame_count}/{retained_frame_count} frame{}",
        debug_plural_s(retained_frame_count)
    ));
    if changed_frame_count > 0 {
        parts.push(format!("{changed_frame_count} changed"));
    }
    if covered_frame_count > 0 {
        parts.push(format!("{covered_frame_count} covered"));
    }
    if warning_frame_count > 0 {
        parts.push(format!("{warning_frame_count} warning"));
    }
    if min_front_index == max_front_index {
        parts.push(format!("front #{min_front_index}"));
    } else {
        parts.push(format!("front #{min_front_index}..#{max_front_index}"));
    }
    if min_resolved_z == max_resolved_z {
        parts.push(format!("z {min_resolved_z}"));
    } else {
        parts.push(format!("z {min_resolved_z}..{max_resolved_z}"));
    }
    parts.join("; ")
}

fn debug_stacking_order_timeline_record_cause(
    name: &str,
    changed_frame_count: usize,
    covered_frame_count: usize,
    latest_front_neighbor: Option<&str>,
    latest_back_neighbor: Option<&str>,
    latest_cause: &str,
) -> String {
    if covered_frame_count > 0 {
        return format!(
            "{name} was covered in {covered_frame_count} retained frame{}; latest cover {}; {latest_cause}",
            debug_plural_s(covered_frame_count),
            latest_front_neighbor.unwrap_or("unknown")
        );
    }
    if changed_frame_count > 0 {
        return format!(
            "{name} changed stack position in {changed_frame_count} retained frame{}; latest {latest_cause}",
            debug_plural_s(changed_frame_count)
        );
    }
    if let Some(back) = latest_back_neighbor {
        return format!("{name} stayed in front of {back}; {latest_cause}");
    }
    "stack order stayed stable for this retained node".to_owned()
}

fn debug_stacking_order_timeline_record_fix(
    name: &str,
    changed_frame_count: usize,
    covered_frame_count: usize,
    warning_frame_count: usize,
    latest_fix: &str,
) -> String {
    if covered_frame_count > 0 || warning_frame_count > 0 {
        return format!(
            "open stacking_order_panel and overlap_autopsy_panel for {name}; {latest_fix}"
        );
    }
    if changed_frame_count > 0 {
        return format!(
            "compare adjacent frame_timeline_panel captures for {name} and verify layer/z/order inputs"
        );
    }
    "no stacking timeline action needed".to_owned()
}

