fn debug_stacking_order_timeline_frame_cause(
    changed_node_count: usize,
    covered_interactive_count: usize,
    new_covered_count: usize,
    resolved_covered_count: usize,
    top_node_name: Option<&str>,
) -> String {
    if new_covered_count > 0 || resolved_covered_count > 0 {
        return format!(
            "interactive coverage changed: {new_covered_count} new, {resolved_covered_count} resolved"
        );
    }
    if covered_interactive_count > 0 {
        return format!(
            "{covered_interactive_count} interactive target{} covered; top {}",
            debug_plural_s(covered_interactive_count),
            top_node_name.unwrap_or("unknown")
        );
    }
    if changed_node_count > 0 {
        return format!(
            "{changed_node_count} stack participant{} changed layer/z/order",
            debug_plural_s(changed_node_count)
        );
    }
    "frame stack order stayed stable".to_owned()
}

fn debug_stacking_order_timeline_frame_fix(
    changed_node_count: usize,
    covered_interactive_count: usize,
    new_covered_count: usize,
    resolved_covered_count: usize,
    top_node_name: Option<&str>,
) -> String {
    if covered_interactive_count > 0 || new_covered_count > 0 {
        return format!(
            "open stacking_order_panel for {} and inspect overlap_autopsy_panel before changing z",
            top_node_name.unwrap_or("the covered target")
        );
    }
    if resolved_covered_count > 0 {
        return "compare adjacent frames to confirm the stack-order fix resolved the cover"
            .to_owned();
    }
    if changed_node_count > 0 {
        return "compare layer, z, and document order in stacking_order_panel".to_owned();
    }
    "no stacking timeline action needed".to_owned()
}

fn debug_hitbox_map_record(
    hitbox: &DebugHitboxNode,
    action: Option<String>,
    action_mode: Option<WidgetActionMode>,
) -> DebugHitboxMapRecord {
    let has_paint = hitbox.paint_rect.is_some();
    let effective_hit = hitbox.hit_eligibility.eligible && hitbox.hit_rect.is_some();
    let clipped = hitbox
        .visible_rect
        .is_some_and(|visible| !debug_rect_contains_rect(visible, hitbox.transformed_rect));
    let status = debug_hitbox_map_record_status(hitbox, effective_hit, clipped);
    let summary = debug_hitbox_map_record_summary(hitbox, status, effective_hit, clipped, &action);
    let cause = debug_hitbox_map_record_cause(hitbox, effective_hit, clipped, &action);
    let fix = debug_hitbox_map_record_fix(hitbox, effective_hit, clipped, action.as_deref());
    DebugHitboxMapRecord {
        node: hitbox.id,
        name: hitbox.name.clone(),
        status,
        pointer: hitbox.pointer,
        focusable: hitbox.focusable,
        action,
        action_mode,
        visible: hitbox.visible,
        hit_testable: hitbox.hit_testable,
        effective_hit,
        has_paint,
        clipped,
        rect: hitbox.rect,
        visible_rect: hitbox.visible_rect,
        hit_rect: hitbox.hit_rect,
        paint_rect: hitbox.paint_rect,
        hit_shape: hitbox.hit_shape.clone(),
        clip_chain_len: hitbox.clip_chain.len(),
        layer: hitbox.layer,
        resolved_z: hitbox.resolved_z,
        order: hitbox.order,
        rejection_count: hitbox.hit_eligibility.rejections.len(),
        rejections: hitbox.hit_eligibility.rejections.clone(),
        summary,
        cause,
        fix,
    }
}

fn debug_hitbox_map_record_status(
    hitbox: &DebugHitboxNode,
    effective_hit: bool,
    clipped: bool,
) -> DebugFrameTraceStatus {
    let interactive = hitbox.pointer || hitbox.focusable;
    if interactive && (!hitbox.visible || !hitbox.hit_testable || !effective_hit) {
        return DebugFrameTraceStatus::Error;
    }
    if interactive && clipped {
        return DebugFrameTraceStatus::Warning;
    }
    if interactive || hitbox.paint_rect.is_some() || hitbox.hit_rect.is_some() {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

fn debug_hitbox_map_record_summary(
    hitbox: &DebugHitboxNode,
    status: DebugFrameTraceStatus,
    effective_hit: bool,
    clipped: bool,
    action: &Option<String>,
) -> String {
    let mut parts = vec![format!("{} hitbox {}", hitbox.name, status.label())];
    if hitbox.pointer || hitbox.focusable {
        let mut roles = Vec::new();
        if hitbox.pointer {
            roles.push("pointer");
        }
        if hitbox.focusable {
            roles.push("focus");
        }
        parts.push(roles.join("+"));
    } else {
        parts.push("passive".to_owned());
    }
    if effective_hit {
        if let Some(rect) = hitbox.hit_rect {
            parts.push(format!("hit {:.0}x{:.0}", rect.width, rect.height));
        }
    } else {
        parts.push("no effective hit".to_owned());
    }
    if let Some(action) = action {
        parts.push(action.clone());
    }
    if hitbox.paint_rect.is_some() {
        parts.push("paint".to_owned());
    }
    if clipped {
        parts.push("clipped".to_owned());
    }
    if !hitbox.hit_eligibility.rejections.is_empty() {
        parts.push(format!(
            "{} rejection{}",
            hitbox.hit_eligibility.rejections.len(),
            debug_plural_s(hitbox.hit_eligibility.rejections.len())
        ));
    }
    parts.push(format!("z {}", hitbox.resolved_z));
    parts.join("; ")
}

fn debug_hitbox_map_record_cause(
    hitbox: &DebugHitboxNode,
    effective_hit: bool,
    clipped: bool,
    action: &Option<String>,
) -> String {
    if !hitbox.visible {
        return "node is hidden before effective hit testing".to_owned();
    }
    if !hitbox.hit_testable {
        return "effective geometry marked this node as not hit-testable".to_owned();
    }
    if (hitbox.pointer || hitbox.focusable) && !effective_hit {
        if hitbox.hit_eligibility.rejections.is_empty() {
            return "interactive node has no effective hit rect".to_owned();
        }
        return format!(
            "effective hit rejected by {}",
            hitbox
                .hit_eligibility
                .rejections
                .iter()
                .map(|rejection| format!("{rejection:?}"))
                .collect::<Vec<_>>()
                .join(", ")
        );
    }
    if clipped {
        return "ancestor clipping reduced this node's visible or hit region".to_owned();
    }
    if hitbox.pointer || hitbox.focusable {
        return "interactive node has an effective hitbox in the current geometry map".to_owned();
    }
    if let Some(action) = action {
        return format!("{action} is bound, but the node is not pointer or focus interactive");
    }
    if hitbox.paint_rect.is_some() {
        return "node paints but does not participate in pointer/focus hit targeting".to_owned();
    }
    "node has effective geometry but no visible paint or interactive input".to_owned()
}

fn debug_hitbox_map_record_fix(
    hitbox: &DebugHitboxNode,
    effective_hit: bool,
    clipped: bool,
    action: Option<&str>,
) -> String {
    if !hitbox.visible {
        return "inspect visibility_panel, ancestor clips, and conditional rendering".to_owned();
    }
    if !hitbox.hit_testable || ((hitbox.pointer || hitbox.focusable) && !effective_hit) {
        return "inspect hit shape, clip chain, visibility, disabled state, and hit_target_panel"
            .to_owned();
    }
    if clipped && (hitbox.pointer || hitbox.focusable) {
        return "relax the clipping ancestor, move the target, or portal the interactive overlay"
            .to_owned();
    }
    if action.is_some() && !(hitbox.pointer || hitbox.focusable) {
        return "enable pointer/focus input for the action or move the binding to an interactive node"
            .to_owned();
    }
    if hitbox.paint_rect.is_some() && hitbox.hit_rect.is_none() {
        return "open paint_hit_mismatch_panel if visible pixels should be clickable".to_owned();
    }
    "no hitbox action needed".to_owned()
}

fn debug_hitbox_map_trace_status(records: &[DebugHitboxMapRecord]) -> DebugFrameTraceStatus {
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Error)
    {
        return DebugFrameTraceStatus::Error;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Info)
    {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

#[allow(clippy::too_many_arguments)]
fn debug_hitbox_map_trace_summary(
    status: DebugFrameTraceStatus,
    node_count: usize,
    interactive_count: usize,
    action_count: usize,
    effective_hit_count: usize,
    missing_hit_count: usize,
    clipped_count: usize,
    paint_only_count: usize,
    issue_count: usize,
) -> String {
    let mut parts = vec![format!("{} hitbox map", status.label())];
    parts.push(format!("{node_count} nodes"));
    parts.push(format!("{interactive_count} interactive"));
    parts.push(format!("{effective_hit_count} effective hits"));
    if action_count > 0 {
        parts.push(format!("{action_count} actions"));
    }
    if issue_count > 0 {
        parts.push(format!("{issue_count} issues"));
    }
    if missing_hit_count > 0 {
        parts.push(format!("{missing_hit_count} missing hits"));
    }
    if clipped_count > 0 {
        parts.push(format!("{clipped_count} clipped"));
    }
    if paint_only_count > 0 {
        parts.push(format!("{paint_only_count} paint-only"));
    }
    parts.join("; ")
}

fn debug_hitbox_map_status_rank(status: DebugFrameTraceStatus) -> u8 {
    match status {
        DebugFrameTraceStatus::Error => 0,
        DebugFrameTraceStatus::Warning => 1,
        DebugFrameTraceStatus::Info => 2,
        DebugFrameTraceStatus::Ok => 3,
    }
}

fn debug_bool_rank(value: bool) -> u8 {
    if value {
        0
    } else {
        1
    }
}

fn debug_hit_target_record(hitbox: &DebugHitboxNode) -> DebugHitTargetRecord {
    let (hit_width, hit_height, hit_area, min_dimension) = hitbox
        .hit_rect
        .map(|rect| {
            let width = rect.width.max(0.0);
            let height = rect.height.max(0.0);
            (width, height, width * height, width.min(height))
        })
        .unwrap_or((0.0, 0.0, 0.0, 0.0));
    let clipped = hitbox
        .visible_rect
        .is_some_and(|visible| !debug_rect_contains_rect(visible, hitbox.transformed_rect));
    let status = debug_hit_target_record_status(hitbox, min_dimension, clipped);
    let summary = debug_hit_target_record_summary(hitbox, status, min_dimension, clipped);
    let cause = debug_hit_target_record_cause(hitbox, min_dimension, clipped);
    let fix = debug_hit_target_record_fix(hitbox, min_dimension, clipped);

    DebugHitTargetRecord {
        node: hitbox.id,
        name: hitbox.name.clone(),
        status,
        pointer: hitbox.pointer,
        focusable: hitbox.focusable,
        visible: hitbox.visible,
        hit_testable: hitbox.hit_testable,
        effective_hit: hitbox.hit_eligibility.eligible,
        rect: hitbox.rect,
        visible_rect: hitbox.visible_rect,
        hit_rect: hitbox.hit_rect,
        paint_rect: hitbox.paint_rect,
        hit_width,
        hit_height,
        hit_area,
        min_dimension,
        clipped,
        clip_chain_len: hitbox.clip_chain.len(),
        rejections: hitbox.hit_eligibility.rejections.clone(),
        summary,
        cause,
        fix,
    }
}

fn debug_hit_target_record_status(
    hitbox: &DebugHitboxNode,
    min_dimension: f32,
    clipped: bool,
) -> DebugFrameTraceStatus {
    if !hitbox.visible || !hitbox.hit_testable || hitbox.hit_rect.is_none() {
        return DebugFrameTraceStatus::Error;
    }
    if min_dimension < DEBUG_HIT_TARGET_MIN_SIZE || clipped {
        return DebugFrameTraceStatus::Warning;
    }
    DebugFrameTraceStatus::Ok
}

fn debug_hit_target_record_summary(
    hitbox: &DebugHitboxNode,
    status: DebugFrameTraceStatus,
    min_dimension: f32,
    clipped: bool,
) -> String {
    let mut parts = vec![format!("{} hit target {}", hitbox.name, status.label())];
    if let Some(rect) = hitbox.hit_rect {
        parts.push(format!("{:.0}x{:.0}", rect.width, rect.height));
    } else {
        parts.push("no hit rect".to_owned());
    }
    if min_dimension > 0.0 && min_dimension < DEBUG_HIT_TARGET_MIN_SIZE {
        parts.push(format!("min {:.0}px", min_dimension));
    }
    if clipped {
        parts.push("clipped".to_owned());
    }
    if !hitbox.hit_eligibility.eligible && !hitbox.hit_eligibility.rejections.is_empty() {
        parts.push(format!(
            "{} rejections",
            hitbox.hit_eligibility.rejections.len()
        ));
    }
    parts.join("; ")
}

fn debug_hit_target_record_cause(
    hitbox: &DebugHitboxNode,
    min_dimension: f32,
    clipped: bool,
) -> String {
    if !hitbox.visible {
        return "interactive node is not visible after layout".to_owned();
    }
    if !hitbox.hit_testable {
        return "interactive node is not hit-testable in the effective geometry pass".to_owned();
    }
    if hitbox.hit_rect.is_none() {
        if hitbox.hit_eligibility.rejections.is_empty() {
            return "interactive node produced no effective hit rect".to_owned();
        }
        return format!(
            "effective hit rejected by {}",
            hitbox
                .hit_eligibility
                .rejections
                .iter()
                .map(|rejection| format!("{rejection:?}"))
                .collect::<Vec<_>>()
                .join(", ")
        );
    }
    if min_dimension < DEBUG_HIT_TARGET_MIN_SIZE {
        return format!(
            "smallest hit dimension {:.0}px is below the {:.0}px debug threshold",
            min_dimension, DEBUG_HIT_TARGET_MIN_SIZE
        );
    }
    if clipped {
        return "ancestor clipping reduces the interactive region".to_owned();
    }
    "interactive node has an effective hit target".to_owned()
}

fn debug_hit_target_record_fix(
    hitbox: &DebugHitboxNode,
    min_dimension: f32,
    clipped: bool,
) -> String {
    if !hitbox.visible {
        return "inspect visibility, parent clips, and conditional render state".to_owned();
    }
    if !hitbox.hit_testable || hitbox.hit_rect.is_none() {
        return "inspect input behavior, hit shape, transform, clip chain, visibility, and disabled state".to_owned();
    }
    if min_dimension < DEBUG_HIT_TARGET_MIN_SIZE {
        return "increase width/height, add padding or hit outset, or combine with a larger parent target"
            .to_owned();
    }
    if clipped {
        return "relax the clipping ancestor, move the control inside the viewport, or portal the overlay".to_owned();
    }
    "no hit target action needed".to_owned()
}

fn debug_paint_hit_mismatch_trace(snapshot: &DebugInspectorSnapshot) -> DebugPaintHitMismatchTrace {
    let hitboxes = snapshot
        .hitboxes
        .iter()
        .map(|hitbox| (hitbox.id, hitbox))
        .collect::<HashMap<_, _>>();
    let mut records = snapshot
        .nodes
        .iter()
        .filter(|node| node.parent.is_some())
        .flat_map(|node| debug_paint_hit_mismatch_records(node, hitboxes.get(&node.id).copied()))
        .collect::<Vec<_>>();
    records.sort_by(|left, right| {
        debug_paint_hit_mismatch_status_rank(left.status)
            .cmp(&debug_paint_hit_mismatch_status_rank(right.status))
            .then_with(|| {
                debug_paint_hit_mismatch_kind_rank(left.kind)
                    .cmp(&debug_paint_hit_mismatch_kind_rank(right.kind))
            })
            .then_with(|| right.mismatch_area.total_cmp(&left.mismatch_area))
            .then_with(|| left.name.cmp(&right.name))
    });
    let interactive_count = snapshot
        .nodes
        .iter()
        .filter(|node| node.parent.is_some() && (node.input.pointer || node.input.focusable))
        .count();
    let record_count = records.len();
    let visible_without_hit_count = records
        .iter()
        .filter(|record| record.kind == DebugPaintHitMismatchKind::VisibleWithoutHit)
        .count();
    let hit_without_paint_count = records
        .iter()
        .filter(|record| record.kind == DebugPaintHitMismatchKind::HitWithoutVisiblePaint)
        .count();
    let paint_outside_hit_count = records
        .iter()
        .filter(|record| record.kind == DebugPaintHitMismatchKind::PaintOutsideHit)
        .count();
    let hit_outside_paint_count = records
        .iter()
        .filter(|record| record.kind == DebugPaintHitMismatchKind::HitOutsidePaint)
        .count();
    let warning_count = records
        .iter()
        .filter(|record| {
            matches!(
                record.status,
                DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
            )
        })
        .count();
    let status = debug_paint_hit_mismatch_trace_status(&records);
    let summary = debug_paint_hit_mismatch_trace_summary(
        status,
        snapshot.nodes.len(),
        interactive_count,
        record_count,
        visible_without_hit_count,
        hit_without_paint_count,
        paint_outside_hit_count,
        hit_outside_paint_count,
    );
    DebugPaintHitMismatchTrace {
        status,
        node_count: snapshot.nodes.len(),
        interactive_count,
        record_count,
        visible_without_hit_count,
        hit_without_paint_count,
        paint_outside_hit_count,
        hit_outside_paint_count,
        warning_count,
        records,
        summary,
    }
}

fn debug_paint_hit_mismatch_records(
    node: &DebugLayoutInspectorNode,
    hitbox: Option<&DebugHitboxNode>,
) -> Vec<DebugPaintHitMismatchRecord> {
    let Some(hitbox) = hitbox else {
        return Vec::new();
    };
    if !node.input.pointer && !node.input.focusable {
        return Vec::new();
    }

    let opacity = node.style.opacity.parse::<f32>().unwrap_or(1.0);
    let visible_paint_rect = (node.visible && opacity > f32::EPSILON)
        .then_some(hitbox.paint_rect)
        .flatten();
    let hit_rect = hitbox.hit_rect;
    let mut records = Vec::new();

    if visible_paint_rect.is_some() && hit_rect.is_none() {
        records.push(debug_paint_hit_mismatch_record(
            node,
            hitbox,
            DebugPaintHitMismatchKind::VisibleWithoutHit,
        ));
    }
    if hit_rect.is_some() && visible_paint_rect.is_none() {
        records.push(debug_paint_hit_mismatch_record(
            node,
            hitbox,
            DebugPaintHitMismatchKind::HitWithoutVisiblePaint,
        ));
    }
    if let (Some(paint_rect), Some(hit_rect)) = (visible_paint_rect, hit_rect) {
        if !debug_rect_contains_rect(hit_rect, paint_rect) {
            records.push(debug_paint_hit_mismatch_record(
                node,
                hitbox,
                DebugPaintHitMismatchKind::PaintOutsideHit,
            ));
        }
        if !debug_rect_contains_rect(paint_rect, hit_rect) {
            records.push(debug_paint_hit_mismatch_record(
                node,
                hitbox,
                DebugPaintHitMismatchKind::HitOutsidePaint,
            ));
        }
    }

    records
}

fn debug_paint_hit_mismatch_record(
    node: &DebugLayoutInspectorNode,
    hitbox: &DebugHitboxNode,
    kind: DebugPaintHitMismatchKind,
) -> DebugPaintHitMismatchRecord {
    let mismatch_area = debug_paint_hit_mismatch_area(kind, hitbox);
    let status = debug_paint_hit_mismatch_record_status(kind, hitbox);
    let summary = debug_paint_hit_mismatch_record_summary(node, kind, status, mismatch_area);
    let cause = debug_paint_hit_mismatch_record_cause(kind, hitbox);
    let fix = debug_paint_hit_mismatch_record_fix(kind, hitbox);

    DebugPaintHitMismatchRecord {
        node: node.id,
        name: node.name.clone(),
        status,
        kind,
        pointer: node.input.pointer,
        focusable: node.input.focusable,
        hit_testable: hitbox.hit_testable,
        effective_hit: hitbox.hit_eligibility.eligible,
        rect: node.rect,
        visible_rect: hitbox.visible_rect,
        hit_rect: hitbox.hit_rect,
        paint_rect: hitbox.paint_rect,
        mismatch_area,
        summary,
        cause,
        fix,
    }
}

fn debug_paint_hit_mismatch_record_status(
    kind: DebugPaintHitMismatchKind,
    hitbox: &DebugHitboxNode,
) -> DebugFrameTraceStatus {
    match kind {
        DebugPaintHitMismatchKind::VisibleWithoutHit
        | DebugPaintHitMismatchKind::HitWithoutVisiblePaint => DebugFrameTraceStatus::Error,
        DebugPaintHitMismatchKind::PaintOutsideHit => DebugFrameTraceStatus::Warning,
        DebugPaintHitMismatchKind::HitOutsidePaint => {
            if hitbox.pointer {
                DebugFrameTraceStatus::Info
            } else {
                DebugFrameTraceStatus::Ok
            }
        }
    }
}

fn debug_paint_hit_mismatch_record_summary(
    node: &DebugLayoutInspectorNode,
    kind: DebugPaintHitMismatchKind,
    status: DebugFrameTraceStatus,
    mismatch_area: f32,
) -> String {
    let mut parts = vec![format!("{} {} {}", node.name, kind.label(), status.label())];
    if mismatch_area > 0.5 {
        parts.push(format!("{mismatch_area:.0}px2 mismatch"));
    }
    parts.join("; ")
}

fn debug_paint_hit_mismatch_record_cause(
    kind: DebugPaintHitMismatchKind,
    hitbox: &DebugHitboxNode,
) -> String {
    match kind {
        DebugPaintHitMismatchKind::VisibleWithoutHit => {
            if hitbox.hit_eligibility.rejections.is_empty() {
                "visible paint exists, but the effective geometry pass produced no hit rect"
                    .to_owned()
            } else {
                format!(
                    "visible paint exists, but hit testing was rejected by {}",
                    hitbox
                        .hit_eligibility
                        .rejections
                        .iter()
                        .map(debug_effective_hit_rejection_label)
                        .collect::<Vec<_>>()
                        .join(", ")
                )
            }
        }
        DebugPaintHitMismatchKind::HitWithoutVisiblePaint => {
            "an effective hit region exists where this node has no visible paint".to_owned()
        }
        DebugPaintHitMismatchKind::PaintOutsideHit => {
            "visible paint extends beyond the effective hit region".to_owned()
        }
        DebugPaintHitMismatchKind::HitOutsidePaint => {
            "the effective hit region extends beyond visible paint".to_owned()
        }
    }
}

fn debug_paint_hit_mismatch_record_fix(
    kind: DebugPaintHitMismatchKind,
    hitbox: &DebugHitboxNode,
) -> String {
    match kind {
        DebugPaintHitMismatchKind::VisibleWithoutHit => {
            "inspect hit shape, clip chain, visibility, disabled state, and hit_target_panel"
                .to_owned()
        }
        DebugPaintHitMismatchKind::HitWithoutVisiblePaint => {
            "add visible affordance, remove pointer input, or mark the blank hit region intentional"
                .to_owned()
        }
        DebugPaintHitMismatchKind::PaintOutsideHit => {
            if hitbox.pointer {
                "increase hit shape/outset or reduce visual/material/shader paint outset".to_owned()
            } else {
                "align visual and hit geometry if this region should be interactive".to_owned()
            }
        }
        DebugPaintHitMismatchKind::HitOutsidePaint => {
            "align paint and hit geometry, or keep the extra hit area intentional for touch ergonomics"
                .to_owned()
        }
    }
}

fn debug_paint_hit_mismatch_area(kind: DebugPaintHitMismatchKind, hitbox: &DebugHitboxNode) -> f32 {
    match kind {
        DebugPaintHitMismatchKind::VisibleWithoutHit => {
            hitbox.paint_rect.map(rect_area).unwrap_or_default()
        }
        DebugPaintHitMismatchKind::HitWithoutVisiblePaint => {
            hitbox.hit_rect.map(rect_area).unwrap_or_default()
        }
        DebugPaintHitMismatchKind::PaintOutsideHit => match (hitbox.paint_rect, hitbox.hit_rect) {
            (Some(paint_rect), Some(hit_rect)) => debug_rect_outside_area(paint_rect, hit_rect),
            _ => 0.0,
        },
        DebugPaintHitMismatchKind::HitOutsidePaint => match (hitbox.hit_rect, hitbox.paint_rect) {
            (Some(hit_rect), Some(paint_rect)) => debug_rect_outside_area(hit_rect, paint_rect),
            _ => 0.0,
        },
    }
}

fn debug_rect_outside_area(rect: UiRect, container: UiRect) -> f32 {
    let area = rect_area(rect);
    let inside = rect.intersection(container).map(rect_area).unwrap_or(0.0);
    (area - inside).max(0.0)
}

fn debug_paint_hit_mismatch_trace_status(
    records: &[DebugPaintHitMismatchRecord],
) -> DebugFrameTraceStatus {
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Error)
    {
        return DebugFrameTraceStatus::Error;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Info)
    {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

fn debug_paint_hit_mismatch_trace_summary(
    status: DebugFrameTraceStatus,
    node_count: usize,
    interactive_count: usize,
    record_count: usize,
    visible_without_hit_count: usize,
    hit_without_paint_count: usize,
    paint_outside_hit_count: usize,
    hit_outside_paint_count: usize,
) -> String {
    let mut parts = vec![format!("{} paint/hit mismatch", status.label())];
    parts.push(format!("{node_count} nodes"));
    parts.push(format!("{interactive_count} interactive"));
    parts.push(format!(
        "{record_count} mismatch{}",
        debug_plural_s(record_count)
    ));
    if visible_without_hit_count > 0 {
        parts.push(format!("{visible_without_hit_count} visible-without-hit"));
    }
    if hit_without_paint_count > 0 {
        parts.push(format!("{hit_without_paint_count} hit-without-paint"));
    }
    if paint_outside_hit_count > 0 {
        parts.push(format!("{paint_outside_hit_count} paint-outside-hit"));
    }
    if hit_outside_paint_count > 0 {
        parts.push(format!("{hit_outside_paint_count} hit-outside-paint"));
    }
    parts.join("; ")
}

fn debug_paint_hit_mismatch_status_rank(status: DebugFrameTraceStatus) -> u8 {
    match status {
        DebugFrameTraceStatus::Error => 0,
        DebugFrameTraceStatus::Warning => 1,
        DebugFrameTraceStatus::Info => 2,
        DebugFrameTraceStatus::Ok => 3,
    }
}

fn debug_paint_hit_mismatch_kind_rank(kind: DebugPaintHitMismatchKind) -> u8 {
    match kind {
        DebugPaintHitMismatchKind::VisibleWithoutHit => 0,
        DebugPaintHitMismatchKind::HitWithoutVisiblePaint => 1,
        DebugPaintHitMismatchKind::PaintOutsideHit => 2,
        DebugPaintHitMismatchKind::HitOutsidePaint => 3,
    }
}

#[derive(Debug)]
struct DebugPaintHitMismatchTimelineAccumulator {
    key: String,
    name: String,
    kind: DebugPaintHitMismatchKind,
    status: DebugFrameTraceStatus,
    frame_count: usize,
    warning_frame_count: usize,
    first_frame_label: Option<String>,
    latest_frame_label: Option<String>,
    max_mismatch_area: f32,
    latest_mismatch_area: f32,
    latest_pointer: bool,
    latest_focusable: bool,
    latest_hit_testable: bool,
    latest_effective_hit: bool,
    latest_hit_rect: Option<UiRect>,
    latest_paint_rect: Option<UiRect>,
    latest_summary: String,
    latest_cause: String,
    latest_fix: String,
}

fn debug_paint_hit_mismatch_timeline_trace<'a>(
    traces: impl IntoIterator<Item = &'a DebugFrameTrace>,
) -> DebugPaintHitMismatchTimelineTrace {
    let traces = traces.into_iter().collect::<Vec<_>>();
    let mut records = Vec::<DebugPaintHitMismatchTimelineAccumulator>::new();
    let mut frames = Vec::new();
    let mut previous_keys = HashSet::<String>::new();
    let mut has_previous = false;

    for (index, trace) in traces.iter().enumerate() {
        let mismatch = DebugPaintHitMismatchTrace::from_snapshot(&trace.snapshot);
        let current_keys = debug_paint_hit_mismatch_timeline_keys(&mismatch.records);
        let new_mismatch_count = if has_previous {
            current_keys.difference(&previous_keys).count()
        } else {
            0
        };
        let resolved_mismatch_count = if has_previous {
            previous_keys.difference(&current_keys).count()
        } else {
            0
        };
        let persistent_mismatch_count = if has_previous {
            current_keys.intersection(&previous_keys).count()
        } else {
            0
        };
        let label = debug_frame_timeline_label(trace, index);
        for record in &mismatch.records {
            debug_paint_hit_mismatch_timeline_merge_record(&mut records, &label, record);
        }
        frames.push(debug_paint_hit_mismatch_timeline_frame_record(
            index,
            label,
            trace.frame_index,
            &mismatch,
            new_mismatch_count,
            resolved_mismatch_count,
            persistent_mismatch_count,
        ));
        previous_keys = current_keys;
        has_previous = true;
    }

    let frame_count = frames.len();
    let mismatch_frame_count = frames
        .iter()
        .filter(|frame| frame.mismatch_count > 0)
        .count();
    let warning_frame_count = frames
        .iter()
        .filter(|frame| {
            matches!(
                frame.status,
                DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
            )
        })
        .count();
    let changed_frame_count = frames
        .iter()
        .filter(|frame| frame.new_mismatch_count > 0 || frame.resolved_mismatch_count > 0)
        .count();
    let node_count = frames.iter().map(|frame| frame.node_count).sum();
    let interactive_count = frames.iter().map(|frame| frame.interactive_count).sum();
    let mismatch_count = frames.iter().map(|frame| frame.mismatch_count).sum();
    let visible_without_hit_count = frames
        .iter()
        .map(|frame| frame.visible_without_hit_count)
        .sum();
    let hit_without_paint_count = frames
        .iter()
        .map(|frame| frame.hit_without_paint_count)
        .sum();
    let paint_outside_hit_count = frames
        .iter()
        .map(|frame| frame.paint_outside_hit_count)
        .sum();
    let hit_outside_paint_count = frames
        .iter()
        .map(|frame| frame.hit_outside_paint_count)
        .sum();
    let warning_count = frames.iter().map(|frame| frame.warning_count).sum();
    let new_mismatch_count = frames.iter().map(|frame| frame.new_mismatch_count).sum();
    let resolved_mismatch_count = frames
        .iter()
        .map(|frame| frame.resolved_mismatch_count)
        .sum();
    let persistent_mismatch_count = frames
        .iter()
        .map(|frame| frame.persistent_mismatch_count)
        .sum();
    let max_mismatch_area = frames
        .iter()
        .map(|frame| frame.max_mismatch_area)
        .fold(0.0_f32, f32::max);

    let mut records = records
        .into_iter()
        .map(|record| debug_paint_hit_mismatch_timeline_record(record, frame_count))
        .collect::<Vec<_>>();
    records.sort_by(|left, right| {
        debug_paint_hit_mismatch_status_rank(left.status)
            .cmp(&debug_paint_hit_mismatch_status_rank(right.status))
            .then_with(|| {
                debug_paint_hit_mismatch_kind_rank(left.kind)
                    .cmp(&debug_paint_hit_mismatch_kind_rank(right.kind))
            })
            .then_with(|| right.frame_count.cmp(&left.frame_count))
            .then_with(|| right.max_mismatch_area.total_cmp(&left.max_mismatch_area))
            .then_with(|| left.key.cmp(&right.key))
    });

    let status = debug_paint_hit_mismatch_timeline_status(&frames);
    let top_mismatch_key = records.first().map(|record| record.key.clone());
    let top_mismatch_name = records.first().map(|record| record.name.clone());
    let summary = debug_paint_hit_mismatch_timeline_summary(
        status,
        frame_count,
        mismatch_frame_count,
        warning_frame_count,
        changed_frame_count,
        mismatch_count,
        visible_without_hit_count,
        hit_without_paint_count,
        paint_outside_hit_count,
        hit_outside_paint_count,
        new_mismatch_count,
        resolved_mismatch_count,
        max_mismatch_area,
        top_mismatch_name.as_deref(),
    );

    DebugPaintHitMismatchTimelineTrace {
        status,
        frame_count,
        mismatch_frame_count,
        warning_frame_count,
        changed_frame_count,
        node_count,
        interactive_count,
        mismatch_count,
        visible_without_hit_count,
        hit_without_paint_count,
        paint_outside_hit_count,
        hit_outside_paint_count,
        warning_count,
        new_mismatch_count,
        resolved_mismatch_count,
        persistent_mismatch_count,
        max_mismatch_area,
        top_mismatch_key,
        top_mismatch_name,
        records,
        frames,
        summary,
    }
}

fn debug_paint_hit_mismatch_timeline_keys(
    records: &[DebugPaintHitMismatchRecord],
) -> HashSet<String> {
    records
        .iter()
        .map(debug_paint_hit_mismatch_timeline_key)
        .collect()
}

fn debug_paint_hit_mismatch_timeline_key(record: &DebugPaintHitMismatchRecord) -> String {
    format!("{}:{}", record.name, record.kind.label())
}

fn debug_paint_hit_mismatch_timeline_merge_record(
    records: &mut Vec<DebugPaintHitMismatchTimelineAccumulator>,
    frame_label: &str,
    record: &DebugPaintHitMismatchRecord,
) {
    let key = debug_paint_hit_mismatch_timeline_key(record);
    let warning = matches!(
        record.status,
        DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
    );
    let Some(accumulator) = records
        .iter_mut()
        .find(|accumulator| accumulator.key == key)
    else {
        records.push(DebugPaintHitMismatchTimelineAccumulator {
            key,
            name: record.name.clone(),
            kind: record.kind,
            status: record.status,
            frame_count: 1,
            warning_frame_count: usize::from(warning),
            first_frame_label: Some(frame_label.to_owned()),
            latest_frame_label: Some(frame_label.to_owned()),
            max_mismatch_area: record.mismatch_area,
            latest_mismatch_area: record.mismatch_area,
            latest_pointer: record.pointer,
            latest_focusable: record.focusable,
            latest_hit_testable: record.hit_testable,
            latest_effective_hit: record.effective_hit,
            latest_hit_rect: record.hit_rect,
            latest_paint_rect: record.paint_rect,
            latest_summary: record.summary.clone(),
            latest_cause: record.cause.clone(),
            latest_fix: record.fix.clone(),
        });
        return;
    };

    accumulator.status = accumulator.status.max(record.status);
    accumulator.frame_count += 1;
    accumulator.warning_frame_count += usize::from(warning);
    accumulator.latest_frame_label = Some(frame_label.to_owned());
    accumulator.max_mismatch_area = accumulator.max_mismatch_area.max(record.mismatch_area);
    accumulator.latest_mismatch_area = record.mismatch_area;
    accumulator.latest_pointer = record.pointer;
    accumulator.latest_focusable = record.focusable;
    accumulator.latest_hit_testable = record.hit_testable;
    accumulator.latest_effective_hit = record.effective_hit;
    accumulator.latest_hit_rect = record.hit_rect;
    accumulator.latest_paint_rect = record.paint_rect;
    accumulator.latest_summary = record.summary.clone();
    accumulator.latest_cause = record.cause.clone();
    accumulator.latest_fix = record.fix.clone();
}

fn debug_paint_hit_mismatch_timeline_record(
    record: DebugPaintHitMismatchTimelineAccumulator,
    retained_frame_count: usize,
) -> DebugPaintHitMismatchTimelineRecord {
    let summary = debug_paint_hit_mismatch_timeline_record_summary(
        &record.name,
        record.kind,
        record.status,
        record.frame_count,
        retained_frame_count,
        record.warning_frame_count,
        record.max_mismatch_area,
    );
    let cause = debug_paint_hit_mismatch_timeline_record_cause(
        &record.name,
        record.kind,
        record.frame_count,
        retained_frame_count,
        record.latest_mismatch_area,
        &record.latest_cause,
    );
    let fix = format!(
        "open paint_hit_mismatch_panel for {}; {}",
        record.name, record.latest_fix
    );

    DebugPaintHitMismatchTimelineRecord {
        key: record.key,
        name: record.name,
        kind: record.kind,
        status: record.status,
        frame_count: record.frame_count,
        warning_frame_count: record.warning_frame_count,
        first_frame_label: record.first_frame_label,
        latest_frame_label: record.latest_frame_label,
        max_mismatch_area: record.max_mismatch_area,
        latest_mismatch_area: record.latest_mismatch_area,
        latest_pointer: record.latest_pointer,
        latest_focusable: record.latest_focusable,
        latest_hit_testable: record.latest_hit_testable,
        latest_effective_hit: record.latest_effective_hit,
        latest_hit_rect: record.latest_hit_rect,
        latest_paint_rect: record.latest_paint_rect,
        latest_summary: record.latest_summary,
        summary,
        cause,
        fix,
    }
}

fn debug_paint_hit_mismatch_timeline_frame_record(
    index: usize,
    label: String,
    frame_index: Option<u64>,
    trace: &DebugPaintHitMismatchTrace,
    new_mismatch_count: usize,
    resolved_mismatch_count: usize,
    persistent_mismatch_count: usize,
) -> DebugPaintHitMismatchTimelineFrameRecord {
    let top_record = trace.records.iter().min_by(|left, right| {
        debug_paint_hit_mismatch_status_rank(left.status)
            .cmp(&debug_paint_hit_mismatch_status_rank(right.status))
            .then_with(|| {
                debug_paint_hit_mismatch_kind_rank(left.kind)
                    .cmp(&debug_paint_hit_mismatch_kind_rank(right.kind))
            })
            .then_with(|| right.mismatch_area.total_cmp(&left.mismatch_area))
            .then_with(|| left.name.cmp(&right.name))
    });
    let top_mismatch_key = top_record.map(debug_paint_hit_mismatch_timeline_key);
    let top_mismatch_name = top_record.map(|record| record.name.clone());
    let top_mismatch_kind = top_record.map(|record| record.kind);
    let max_mismatch_area = trace
        .records
        .iter()
        .map(|record| record.mismatch_area)
        .fold(0.0_f32, f32::max);
    let summary = debug_paint_hit_mismatch_timeline_frame_summary(
        &label,
        trace.status,
        trace.record_count,
        trace.visible_without_hit_count,
        trace.hit_without_paint_count,
        trace.paint_outside_hit_count,
        trace.hit_outside_paint_count,
        new_mismatch_count,
        resolved_mismatch_count,
        max_mismatch_area,
        top_mismatch_name.as_deref(),
    );
    let cause = debug_paint_hit_mismatch_timeline_frame_cause(
        trace.record_count,
        new_mismatch_count,
        resolved_mismatch_count,
        top_mismatch_kind,
        top_mismatch_name.as_deref(),
    );
    let fix = debug_paint_hit_mismatch_timeline_frame_fix(
        trace.record_count,
        new_mismatch_count,
        resolved_mismatch_count,
        top_mismatch_name.as_deref(),
    );

    DebugPaintHitMismatchTimelineFrameRecord {
        index,
        label,
        frame_index,
        status: trace.status,
        node_count: trace.node_count,
        interactive_count: trace.interactive_count,
        mismatch_count: trace.record_count,
        visible_without_hit_count: trace.visible_without_hit_count,
        hit_without_paint_count: trace.hit_without_paint_count,
        paint_outside_hit_count: trace.paint_outside_hit_count,
        hit_outside_paint_count: trace.hit_outside_paint_count,
        warning_count: trace.warning_count,
        new_mismatch_count,
        resolved_mismatch_count,
        persistent_mismatch_count,
        max_mismatch_area,
        top_mismatch_key,
        top_mismatch_name,
        top_mismatch_kind,
        summary,
        cause,
        fix,
    }
}

fn debug_paint_hit_mismatch_timeline_status(
    frames: &[DebugPaintHitMismatchTimelineFrameRecord],
) -> DebugFrameTraceStatus {
    if frames
        .iter()
        .any(|frame| frame.status == DebugFrameTraceStatus::Error)
    {
        return DebugFrameTraceStatus::Error;
    }
    if frames
        .iter()
        .any(|frame| frame.status == DebugFrameTraceStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if frames.iter().any(|frame| {
        frame.status == DebugFrameTraceStatus::Info
            || frame.new_mismatch_count > 0
            || frame.resolved_mismatch_count > 0
    }) {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

#[allow(clippy::too_many_arguments)]
fn debug_paint_hit_mismatch_timeline_summary(
    status: DebugFrameTraceStatus,
    frame_count: usize,
    mismatch_frame_count: usize,
    warning_frame_count: usize,
    changed_frame_count: usize,
    mismatch_count: usize,
    visible_without_hit_count: usize,
    hit_without_paint_count: usize,
    paint_outside_hit_count: usize,
    hit_outside_paint_count: usize,
    new_mismatch_count: usize,
    resolved_mismatch_count: usize,
    max_mismatch_area: f32,
    top_mismatch_name: Option<&str>,
) -> String {
    let mut parts = vec![format!("{} paint/hit mismatch timeline", status.label())];
    parts.push(format!(
        "{frame_count} frame{}",
        debug_plural_s(frame_count)
    ));
    if mismatch_frame_count > 0 {
        parts.push(format!("{mismatch_frame_count} mismatch frames"));
    }
    if warning_frame_count > 0 {
        parts.push(format!("{warning_frame_count} warning frames"));
    }
    if changed_frame_count > 0 {
        parts.push(format!("{changed_frame_count} changed frames"));
    }
    if mismatch_count > 0 {
        parts.push(format!("{mismatch_count} mismatches"));
    }
    if visible_without_hit_count > 0 {
        parts.push(format!("{visible_without_hit_count} visible-without-hit"));
    }
    if hit_without_paint_count > 0 {
        parts.push(format!("{hit_without_paint_count} hit-without-paint"));
    }
    if paint_outside_hit_count > 0 {
        parts.push(format!("{paint_outside_hit_count} paint-outside-hit"));
    }
    if hit_outside_paint_count > 0 {
        parts.push(format!("{hit_outside_paint_count} hit-outside-paint"));
    }
    if new_mismatch_count > 0 {
        parts.push(format!("{new_mismatch_count} new"));
    }
    if resolved_mismatch_count > 0 {
        parts.push(format!("{resolved_mismatch_count} resolved"));
    }
    if max_mismatch_area > 0.5 {
        parts.push(format!("max area {max_mismatch_area:.0}px2"));
    }
    if let Some(top) = top_mismatch_name {
        parts.push(format!("top {top}"));
    }
    parts.join("; ")
}

fn debug_paint_hit_mismatch_timeline_record_summary(
    name: &str,
    kind: DebugPaintHitMismatchKind,
    status: DebugFrameTraceStatus,
    frame_count: usize,
    retained_frame_count: usize,
    warning_frame_count: usize,
    max_mismatch_area: f32,
) -> String {
    let mut parts = vec![format!("{} {} {}", status.label(), name, kind.label())];
    parts.push(format!(
        "{frame_count}/{retained_frame_count} frame{}",
        debug_plural_s(retained_frame_count)
    ));
    if warning_frame_count > 0 {
        parts.push(format!("{warning_frame_count} warning"));
    }
    if max_mismatch_area > 0.5 {
        parts.push(format!("max area {max_mismatch_area:.0}px2"));
    }
    parts.join("; ")
}

fn debug_paint_hit_mismatch_timeline_record_cause(
    name: &str,
    kind: DebugPaintHitMismatchKind,
    frame_count: usize,
    retained_frame_count: usize,
    latest_mismatch_area: f32,
    latest_cause: &str,
) -> String {
    let mut parts = vec![format!(
        "{name} had {} in {frame_count}/{retained_frame_count} retained frame{}",
        kind.label(),
        debug_plural_s(retained_frame_count)
    )];
    if latest_mismatch_area > 0.5 {
        parts.push(format!("latest area {latest_mismatch_area:.0}px2"));
    }
    parts.push(format!("latest cause {latest_cause}"));
    parts.join("; ")
}

#[allow(clippy::too_many_arguments)]
fn debug_paint_hit_mismatch_timeline_frame_summary(
    label: &str,
    status: DebugFrameTraceStatus,
    mismatch_count: usize,
    visible_without_hit_count: usize,
    hit_without_paint_count: usize,
    paint_outside_hit_count: usize,
    hit_outside_paint_count: usize,
    new_mismatch_count: usize,
    resolved_mismatch_count: usize,
    max_mismatch_area: f32,
    top_mismatch_name: Option<&str>,
) -> String {
    let mut parts = vec![format!("{} paint/hit for {label}", status.label())];
    parts.push(format!("{mismatch_count} mismatches"));
    if visible_without_hit_count > 0 {
        parts.push(format!("{visible_without_hit_count} visible-without-hit"));
    }
    if hit_without_paint_count > 0 {
        parts.push(format!("{hit_without_paint_count} hit-without-paint"));
    }
    if paint_outside_hit_count > 0 {
        parts.push(format!("{paint_outside_hit_count} paint-outside-hit"));
    }
    if hit_outside_paint_count > 0 {
        parts.push(format!("{hit_outside_paint_count} hit-outside-paint"));
    }
    if new_mismatch_count > 0 {
        parts.push(format!("{new_mismatch_count} new"));
    }
    if resolved_mismatch_count > 0 {
        parts.push(format!("{resolved_mismatch_count} resolved"));
    }
    if max_mismatch_area > 0.5 {
        parts.push(format!("max area {max_mismatch_area:.0}px2"));
    }
    if let Some(top) = top_mismatch_name {
        parts.push(format!("top {top}"));
    }
    parts.join("; ")
}

fn debug_paint_hit_mismatch_timeline_frame_cause(
    mismatch_count: usize,
    new_mismatch_count: usize,
    resolved_mismatch_count: usize,
    top_mismatch_kind: Option<DebugPaintHitMismatchKind>,
    top_mismatch_name: Option<&str>,
) -> String {
    if new_mismatch_count > 0 || resolved_mismatch_count > 0 {
        return format!(
            "paint/hit mismatch set changed: {new_mismatch_count} new, {resolved_mismatch_count} resolved"
        );
    }
    if mismatch_count > 0 {
        return format!(
            "{mismatch_count} paint/hit mismatch{} active; top {} {}",
            debug_plural_s(mismatch_count),
            top_mismatch_name.unwrap_or("unknown"),
            top_mismatch_kind
                .map(DebugPaintHitMismatchKind::label)
                .unwrap_or("mismatch")
        );
    }
    "frame had no paint/hit mismatch".to_owned()
}

fn debug_paint_hit_mismatch_timeline_frame_fix(
    mismatch_count: usize,
    new_mismatch_count: usize,
    resolved_mismatch_count: usize,
    top_mismatch_name: Option<&str>,
) -> String {
    if mismatch_count > 0 || new_mismatch_count > 0 {
        return format!(
            "open paint_hit_mismatch_panel for {} and compare hitbox_map_panel",
            top_mismatch_name.unwrap_or("the top mismatch")
        );
    }
    if resolved_mismatch_count > 0 {
        return "compare adjacent frames to confirm paint and hit geometry now agree".to_owned();
    }
    "no paint/hit mismatch timeline action needed".to_owned()
}

