#[allow(clippy::too_many_arguments)]
fn debug_visibility_timeline_frame_summary(
    label: &str,
    status: DebugFrameTraceStatus,
    issue_count: usize,
    new_issue_count: usize,
    resolved_issue_count: usize,
    persistent_issue_count: usize,
    top_name: Option<&str>,
    top_issue: Option<DebugVisibilityIssueKind>,
) -> String {
    let mut parts = vec![format!("{} visibility for {label}", status.label())];
    if issue_count > 0 {
        parts.push(format!(
            "{issue_count} issue{}",
            debug_plural_s(issue_count)
        ));
    } else {
        parts.push("no visibility issues".to_owned());
    }
    if new_issue_count > 0 {
        parts.push(format!(
            "{new_issue_count} new{}",
            debug_plural_s(new_issue_count)
        ));
    }
    if resolved_issue_count > 0 {
        parts.push(format!(
            "{resolved_issue_count} resolved{}",
            debug_plural_s(resolved_issue_count)
        ));
    }
    if persistent_issue_count > 0 {
        parts.push(format!(
            "{persistent_issue_count} persistent{}",
            debug_plural_s(persistent_issue_count)
        ));
    }
    if let (Some(top_name), Some(top_issue)) = (top_name, top_issue) {
        parts.push(format!("top {top_name} {}", top_issue.label()));
    }
    parts.join("; ")
}

fn debug_visibility_timeline_frame_cause(
    visibility: &DebugVisibilityTrace,
    new_issue_count: usize,
    resolved_issue_count: usize,
    persistent_issue_count: usize,
    top_summary: Option<&str>,
) -> String {
    let mut parts = vec![visibility.summary.clone()];
    if new_issue_count > 0 {
        parts.push(format!(
            "{new_issue_count} visibility issue{} appeared since previous frame",
            debug_plural_s(new_issue_count)
        ));
    }
    if resolved_issue_count > 0 {
        parts.push(format!(
            "{resolved_issue_count} visibility issue{} resolved since previous frame",
            debug_plural_s(resolved_issue_count)
        ));
    }
    if persistent_issue_count > 0 {
        parts.push(format!(
            "{persistent_issue_count} visibility issue{} persisted",
            debug_plural_s(persistent_issue_count)
        ));
    }
    if let Some(top_summary) = top_summary {
        parts.push(format!("top {top_summary}"));
    }
    parts.join("; ")
}

fn debug_visibility_timeline_frame_fix(
    status: DebugFrameTraceStatus,
    issue_count: usize,
    new_issue_count: usize,
    resolved_issue_count: usize,
    persistent_issue_count: usize,
    top_name: Option<&str>,
) -> String {
    if let Some(top_name) = top_name {
        return format!("open visibility_panel filtered to {top_name}");
    }
    if new_issue_count > 0 || resolved_issue_count > 0 {
        return "compare with frame_timeline_panel and inspect changed layout, clip, and paint inputs"
            .to_owned();
    }
    if persistent_issue_count > 0 || issue_count > 0 {
        return "open visibility_panel and clip_chain_panel for persistent visibility causes"
            .to_owned();
    }
    if matches!(
        status,
        DebugFrameTraceStatus::Error | DebugFrameTraceStatus::Warning
    ) {
        return "open visibility_panel for the highest severity row".to_owned();
    }
    "no visibility action needed".to_owned()
}

fn debug_visibility_trace_summary(
    status: DebugFrameTraceStatus,
    node_count: usize,
    issue_count: usize,
    hidden_count: usize,
    transparent_count: usize,
    clipped_count: usize,
    no_paint_count: usize,
) -> String {
    if issue_count == 0 {
        return format!(
            "{} visibility; {node_count} nodes; no visibility issues",
            status.label()
        );
    }
    let mut parts = vec![format!("{} visibility", status.label())];
    parts.push(format!("{node_count} nodes"));
    parts.push(format!("{issue_count} issues"));
    if hidden_count > 0 {
        parts.push(format!("{hidden_count} hidden"));
    }
    if transparent_count > 0 {
        parts.push(format!("{transparent_count} transparent"));
    }
    if clipped_count > 0 {
        parts.push(format!("{clipped_count} clipped"));
    }
    if no_paint_count > 0 {
        parts.push(format!("{no_paint_count} no paint"));
    }
    parts.join("; ")
}

fn debug_visibility_issue_rank(issue: DebugVisibilityIssueKind) -> u8 {
    match issue {
        DebugVisibilityIssueKind::Hidden => 0,
        DebugVisibilityIssueKind::Transparent => 1,
        DebugVisibilityIssueKind::ZeroLayout => 2,
        DebugVisibilityIssueKind::EmptyClip => 3,
        DebugVisibilityIssueKind::FullyClipped => 4,
        DebugVisibilityIssueKind::NoPaint => 5,
        DebugVisibilityIssueKind::PartiallyClipped => 6,
    }
}

fn debug_visibility_status_rank(status: DebugFrameTraceStatus) -> u8 {
    match status {
        DebugFrameTraceStatus::Error => 0,
        DebugFrameTraceStatus::Warning => 1,
        DebugFrameTraceStatus::Info => 2,
        DebugFrameTraceStatus::Ok => 3,
    }
}

fn debug_responsive_viewport_record(
    viewport: UiSize,
    snapshot: &DebugInspectorSnapshot,
) -> DebugResponsiveViewportRecord {
    let constraints = DebugConstraintReport::from_snapshot(snapshot);
    let constraint_issue_count = constraints.issues.len();
    let overlap_count = snapshot.overlaps.len();
    let interactive_overlap_count = snapshot
        .overlaps
        .iter()
        .filter(|overlap| overlap.kind == DebugOverlapKind::InteractiveHitbox)
        .count();
    let hit_targets = DebugHitTargetTrace::from_snapshot(snapshot);
    let hit_target_issue_count = hit_targets.issue_count;
    let scroll = DebugScrollRangeTrace::from_snapshot(snapshot);
    let scroll_issue_count = scroll
        .records
        .iter()
        .filter(|record| record.status != DebugFrameTraceStatus::Ok)
        .count();
    let clipped_node_count = snapshot
        .nodes
        .iter()
        .filter(|node| {
            node.visible
                && node.rect.width > f32::EPSILON
                && node.rect.height > f32::EPSILON
                && !debug_rect_contains_rect(node.clip_rect, node.rect)
        })
        .count();
    let warning_count = constraint_issue_count
        + interactive_overlap_count
        + hit_target_issue_count
        + scroll_issue_count
        + clipped_node_count;
    let status = debug_responsive_viewport_status(
        constraint_issue_count,
        interactive_overlap_count,
        hit_target_issue_count,
        overlap_count,
        scroll_issue_count,
        clipped_node_count,
    );
    let summary = debug_responsive_viewport_summary(
        viewport,
        status,
        constraint_issue_count,
        overlap_count,
        interactive_overlap_count,
        hit_target_issue_count,
        scroll_issue_count,
        clipped_node_count,
    );
    let cause = debug_responsive_viewport_cause(
        constraint_issue_count,
        interactive_overlap_count,
        hit_target_issue_count,
        overlap_count,
        scroll_issue_count,
        clipped_node_count,
    );
    let fix = debug_responsive_viewport_fix(
        constraint_issue_count,
        interactive_overlap_count,
        hit_target_issue_count,
        scroll_issue_count,
        clipped_node_count,
    );

    DebugResponsiveViewportRecord {
        viewport,
        status,
        node_count: snapshot.nodes.len(),
        constraint_issue_count,
        overlap_count,
        interactive_overlap_count,
        hit_target_issue_count,
        scroll_issue_count,
        clipped_node_count,
        warning_count,
        summary,
        cause,
        fix,
    }
}

fn debug_responsive_viewport_status(
    constraint_issue_count: usize,
    interactive_overlap_count: usize,
    hit_target_issue_count: usize,
    overlap_count: usize,
    scroll_issue_count: usize,
    clipped_node_count: usize,
) -> DebugFrameTraceStatus {
    if constraint_issue_count > 0 || interactive_overlap_count > 0 || hit_target_issue_count > 0 {
        return DebugFrameTraceStatus::Warning;
    }
    if overlap_count > 0 || scroll_issue_count > 0 || clipped_node_count > 0 {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

#[allow(clippy::too_many_arguments)]
fn debug_responsive_viewport_summary(
    viewport: UiSize,
    status: DebugFrameTraceStatus,
    constraint_issue_count: usize,
    overlap_count: usize,
    interactive_overlap_count: usize,
    hit_target_issue_count: usize,
    scroll_issue_count: usize,
    clipped_node_count: usize,
) -> String {
    let mut parts = vec![format!(
        "{} viewport {}",
        status.label(),
        debug_size_label(viewport)
    )];
    if constraint_issue_count > 0 {
        parts.push(format!("{constraint_issue_count} constraints"));
    }
    if overlap_count > 0 {
        parts.push(format!("{overlap_count} overlaps"));
    }
    if interactive_overlap_count > 0 {
        parts.push(format!("{interactive_overlap_count} interactive"));
    }
    if hit_target_issue_count > 0 {
        parts.push(format!("{hit_target_issue_count} hit targets"));
    }
    if scroll_issue_count > 0 {
        parts.push(format!("{scroll_issue_count} scroll"));
    }
    if clipped_node_count > 0 {
        parts.push(format!("{clipped_node_count} clipped"));
    }
    parts.join("; ")
}

fn debug_responsive_viewport_cause(
    constraint_issue_count: usize,
    interactive_overlap_count: usize,
    hit_target_issue_count: usize,
    overlap_count: usize,
    scroll_issue_count: usize,
    clipped_node_count: usize,
) -> String {
    if constraint_issue_count > 0 {
        return "layout audits or derived constraint diagnostics fail at this viewport".to_owned();
    }
    if interactive_overlap_count > 0 {
        return "interactive hitboxes overlap at this viewport".to_owned();
    }
    if hit_target_issue_count > 0 {
        return "one or more interactive targets are missing, tiny, clipped, or not hit-testable"
            .to_owned();
    }
    if overlap_count > 0 {
        return "visual or layout overlaps appear at this viewport".to_owned();
    }
    if scroll_issue_count > 0 {
        return "scroll ranges, overflow, or scrollbar state changed at this viewport".to_owned();
    }
    if clipped_node_count > 0 {
        return "visible nodes extend outside their effective clip rect at this viewport"
            .to_owned();
    }
    "no responsive layout issue detected for this viewport".to_owned()
}

fn debug_responsive_viewport_fix(
    constraint_issue_count: usize,
    interactive_overlap_count: usize,
    hit_target_issue_count: usize,
    scroll_issue_count: usize,
    clipped_node_count: usize,
) -> String {
    if constraint_issue_count > 0 {
        return "open constraint_issues_panel and inspect the first failing node at this viewport"
            .to_owned();
    }
    if interactive_overlap_count > 0 {
        return "open overlap_report_panel and separate or disable overlapping interactive regions"
            .to_owned();
    }
    if hit_target_issue_count > 0 {
        return "open hit_target_panel and increase or unclip the failing interactive targets"
            .to_owned();
    }
    if scroll_issue_count > 0 {
        return "open scroll_range_panel and decide whether overflow needs scroll, wrap, or resize"
            .to_owned();
    }
    if clipped_node_count > 0 {
        return "open clip_scroll_panel or layout_cause_panel for the clipped node".to_owned();
    }
    "no responsive layout action needed".to_owned()
}

fn debug_responsive_trace_status(
    records: &[DebugResponsiveViewportRecord],
) -> DebugFrameTraceStatus {
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Error)
    {
        return DebugFrameTraceStatus::Error;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Warning)
    {
        return DebugFrameTraceStatus::Warning;
    }
    if records
        .iter()
        .any(|record| record.status == DebugFrameTraceStatus::Info)
    {
        return DebugFrameTraceStatus::Info;
    }
    DebugFrameTraceStatus::Ok
}

fn debug_responsive_trace_summary(
    status: DebugFrameTraceStatus,
    viewport_count: usize,
    issue_viewport_count: usize,
    records: &[DebugResponsiveViewportRecord],
) -> String {
    let mut parts = vec![format!("{} responsive layout", status.label())];
    parts.push(format!("{viewport_count} viewports"));
    if issue_viewport_count > 0 {
        parts.push(format!("{issue_viewport_count} with issues"));
    }
    if let Some(worst) = records
        .iter()
        .find(|record| record.status != DebugFrameTraceStatus::Ok)
    {
        parts.push(format!("worst {}", debug_size_label(worst.viewport)));
    }
    parts.join("; ")
}

fn debug_responsive_status_rank(status: DebugFrameTraceStatus) -> u8 {
    match status {
        DebugFrameTraceStatus::Error => 0,
        DebugFrameTraceStatus::Warning => 1,
        DebugFrameTraceStatus::Info => 2,
        DebugFrameTraceStatus::Ok => 3,
    }
}

fn debug_hitbox_contains_point(node: &DebugHitboxNode, point: UiPoint) -> bool {
    if !node.hit_eligibility.eligible {
        return false;
    }
    if !node
        .clip_chain
        .iter()
        .copied()
        .all(|clip| clip.contains_point(point))
    {
        return false;
    }
    node.transform
        .inverse_transform_point(point)
        .is_some_and(|local| node.hit_shape.contains_point(node.rect, local))
}

fn paint_item_debug_bounds(item: &crate::PaintItem) -> UiRect {
    let material_outset = item
        .material
        .as_ref()
        .map(|material| material.visual_outset_for_rect(item.rect))
        .unwrap_or(0.0);
    let shader_outset = item.shader.as_ref().map(shader_debug_outset).unwrap_or(0.0);
    let bounds = expand_debug_rect(item.rect, material_outset.max(shader_outset));
    EffectiveTransform::from(item.transform).transform_rect_bounds(bounds)
}

fn shader_debug_outset(shader: &ShaderEffect) -> f32 {
    let is_glow = shader.key == ShaderEffect::GLOW || shader.key.ends_with(".glow");
    if is_glow {
        shader_debug_uniform(
            shader,
            "outset",
            shader_debug_uniform(shader, "radius", 8.0),
        )
        .clamp(0.0, 64.0)
    } else {
        0.0
    }
}

fn shader_debug_uniform(shader: &ShaderEffect, name: &str, fallback: f32) -> f32 {
    shader
        .uniforms
        .iter()
        .find(|uniform| uniform.name == name)
        .map(|uniform| uniform.value)
        .unwrap_or(fallback)
}

fn expand_debug_rect(rect: UiRect, outset: f32) -> UiRect {
    let outset = outset.max(0.0);
    UiRect::new(
        rect.x - outset,
        rect.y - outset,
        rect.width + outset * 2.0,
        rect.height + outset * 2.0,
    )
}

fn union_debug_rect(left: UiRect, right: UiRect) -> UiRect {
    let x = left.x.min(right.x);
    let y = left.y.min(right.y);
    let right_edge = left.right().max(right.right());
    let bottom = left.bottom().max(right.bottom());
    UiRect::new(x, y, (right_edge - x).max(0.0), (bottom - y).max(0.0))
}

fn ancestor_descendant_overlap(
    left: &DebugHitboxNode,
    right: &DebugHitboxNode,
    nodes: &[DebugHitboxNode],
) -> bool {
    is_ancestor_in_debug_nodes(left.id, right.id, nodes)
        || is_ancestor_in_debug_nodes(right.id, left.id, nodes)
}

fn is_ancestor_in_debug_nodes(
    ancestor: UiNodeId,
    descendant: UiNodeId,
    nodes: &[DebugHitboxNode],
) -> bool {
    let parents = nodes
        .iter()
        .map(|node| (node.id, node.parent))
        .collect::<HashMap<_, _>>();
    let mut current = parents.get(&descendant).copied().flatten();
    while let Some(parent) = current {
        if parent == ancestor {
            return true;
        }
        current = parents.get(&parent).copied().flatten();
    }
    false
}

fn overlap_reasons(
    document: &UiDocument,
    back: &DebugHitboxNode,
    front: &DebugHitboxNode,
    nodes: &[DebugHitboxNode],
) -> Vec<DebugOverlapReason> {
    let mut reasons = Vec::new();

    if let Some((ancestor, descendant)) = overlap_ancestor_descendant(back, front, nodes) {
        reasons.push(DebugOverlapReason::AncestorDescendant {
            ancestor,
            descendant,
        });
    } else if back.parent == front.parent {
        if let Some(parent) = back.parent {
            reasons.push(DebugOverlapReason::SharedParent { parent });
        }
    } else {
        reasons.push(DebugOverlapReason::DifferentParents {
            back_parent: back.parent,
            front_parent: front.parent,
        });
    }

    if document.node(back.id).style().layout_style().is_absolute() {
        reasons.push(DebugOverlapReason::AbsolutePositioning { node: back.id });
    }
    if document.node(front.id).style().layout_style().is_absolute() {
        reasons.push(DebugOverlapReason::AbsolutePositioning { node: front.id });
    }
    if back.layer != front.layer {
        reasons.push(DebugOverlapReason::LayerOrdering {
            back_layer: back.layer,
            front_layer: front.layer,
        });
    }
    if back.resolved_z != front.resolved_z {
        reasons.push(DebugOverlapReason::ZOrdering {
            back_resolved_z: back.resolved_z,
            front_resolved_z: front.resolved_z,
        });
    }
    if back.pointer && front.pointer {
        reasons.push(DebugOverlapReason::BothPointerInteractive);
    }
    if back
        .paint_rect
        .is_some_and(|paint| !rect_contains_with_epsilon(back.rect, paint))
    {
        reasons.push(DebugOverlapReason::PaintExtendsOutsideLayout { node: back.id });
    }
    if front
        .paint_rect
        .is_some_and(|paint| !rect_contains_with_epsilon(front.rect, paint))
    {
        reasons.push(DebugOverlapReason::PaintExtendsOutsideLayout { node: front.id });
    }
    if back
        .visible_rect
        .is_some_and(|visible| !rect_eq_with_epsilon(visible, back.rect))
    {
        reasons.push(DebugOverlapReason::ClipReducesVisibleHitbox { node: back.id });
    }
    if front
        .visible_rect
        .is_some_and(|visible| !rect_eq_with_epsilon(visible, front.rect))
    {
        reasons.push(DebugOverlapReason::ClipReducesVisibleHitbox { node: front.id });
    }

    reasons
}

fn overlap_ancestor_descendant(
    left: &DebugHitboxNode,
    right: &DebugHitboxNode,
    nodes: &[DebugHitboxNode],
) -> Option<(UiNodeId, UiNodeId)> {
    if is_ancestor_in_debug_nodes(left.id, right.id, nodes) {
        Some((left.id, right.id))
    } else if is_ancestor_in_debug_nodes(right.id, left.id, nodes) {
        Some((right.id, left.id))
    } else {
        None
    }
}

fn rect_contains_with_epsilon(outer: UiRect, inner: UiRect) -> bool {
    const EPSILON: f32 = 0.5;
    inner.x >= outer.x - EPSILON
        && inner.y >= outer.y - EPSILON
        && inner.right() <= outer.right() + EPSILON
        && inner.bottom() <= outer.bottom() + EPSILON
}

fn rect_eq_with_epsilon(left: UiRect, right: UiRect) -> bool {
    const EPSILON: f32 = 0.5;
    (left.x - right.x).abs() <= EPSILON
        && (left.y - right.y).abs() <= EPSILON
        && (left.width - right.width).abs() <= EPSILON
        && (left.height - right.height).abs() <= EPSILON
}

