    fn fixed_style(width: f32, height: f32) -> UiNodeStyle {
        UiNodeStyle {
            layout: LayoutStyle::from_taffy_style(Style {
                size: TaffySize {
                    width: length(width),
                    height: length(height),
                },
                ..Default::default()
            })
            .style,
            ..Default::default()
        }
    }

    fn layered_absolute_style(z_index: f32, width: f32, height: f32) -> UiNodeStyle {
        absolute_style_at(0.0, 0.0, z_index, width, height)
    }

    fn absolute_layout_at(x: f32, y: f32, width: f32, height: f32) -> LayoutStyle {
        LayoutStyle::from_taffy_style(Style {
            position: Position::Absolute,
            inset: Rect {
                left: LengthPercentageAuto::length(x),
                top: LengthPercentageAuto::length(y),
                ..Rect::length(0.0_f32)
            },
            size: TaffySize {
                width: length(width),
                height: length(height),
            },
            ..Default::default()
        })
    }

    fn absolute_style_at(x: f32, y: f32, z_index: f32, width: f32, height: f32) -> UiNodeStyle {
        UiNodeStyle {
            layout: absolute_layout_at(x, y, width, height).style,
            z_index,
            ..Default::default()
        }
    }

    #[test]
    fn debug_overlay_snapshot_combines_layout_paint_and_host_state() {
        let mut doc = UiDocument::new(fixed_style(240.0, 160.0));
        let button = doc.add_child(
            doc.root,
            UiNode::container("play", fixed_style(80.0, 32.0))
                .with_input(InputBehavior::BUTTON)
                .with_visual(UiVisual::panel(
                    ColorRgba::new(20, 30, 40, 255),
                    Some(StrokeStyle::new(ColorRgba::new(80, 90, 100, 255), 1.0)),
                    4.0,
                )),
        );
        doc.compute_layout(UiSize::new(240.0, 160.0), &mut ApproxTextMeasurer)
            .expect("layout");

        let mut host = HostInteractionState {
            hovered: Some(button),
            focused: Some(button),
            active_shortcut_scopes: vec![CommandScope::Workspace],
            ..Default::default()
        };
        host.shortcut_route = Some(crate::host::HostShortcutRoute {
            shortcut: crate::Shortcut::ctrl('p'),
            active_scopes: vec![CommandScope::Workspace],
            target: Some(button),
            command: Some(CommandId::new("transport.play")),
        });
        let wheel = GestureEvent::WheelTargeted {
            target: Some(button),
            event: RawWheelEvent {
                position: UiPoint::new(10.0, 10.0),
                delta: UiPoint::new(0.0, -1.0),
                unit: WheelDeltaUnit::Line,
                phase: WheelPhase::Moved,
                modifiers: crate::KeyModifiers::NONE,
                timestamp_millis: 10,
            },
        };

        let snapshot = DebugOverlaySnapshot::from_document(
            &doc,
            DebugOverlayContext::new(host)
                .active_gesture(&wheel)
                .dirty_flags(DirtyFlags {
                    paint: true,
                    ..DirtyFlags::NONE
                })
                .repaint_reason("hover changed")
                .timings(FrameTiming::new().section("layout", std::time::Duration::from_millis(2))),
            DebugOverlayOptions::default(),
        );

        let button_debug = snapshot
            .nodes
            .iter()
            .find(|node| node.id == button)
            .unwrap();
        assert!(button_debug.interaction.hovered);
        assert!(button_debug.interaction.focused);
        assert_eq!(button_debug.paint.count, 1);
        assert_eq!(
            snapshot.routed_command,
            Some(CommandId::new("transport.play"))
        );
        assert_eq!(snapshot.shortcut, Some(crate::Shortcut::ctrl('p')));
        assert_eq!(snapshot.shortcut_target, Some(button));
        assert_eq!(
            snapshot.active_shortcut_scopes,
            vec![CommandScope::Workspace]
        );
        assert_eq!(snapshot.repaint_reason.as_deref(), Some("hover changed"));
        assert_eq!(
            snapshot.active_gesture.as_ref().unwrap().kind,
            DebugGestureKind::Wheel
        );
        assert_eq!(
            snapshot.timings.duration("layout"),
            Some(std::time::Duration::from_millis(2))
        );
    }

    #[test]
    fn debug_interaction_state_trace_explains_active_host_roles() {
        let mut doc = UiDocument::new(fixed_style(240.0, 160.0));
        let button = doc.add_child(
            doc.root,
            UiNode::container("play", fixed_style(80.0, 32.0))
                .with_input(InputBehavior::BUTTON)
                .with_visual(UiVisual::panel(
                    ColorRgba::new(20, 30, 40, 255),
                    Some(StrokeStyle::new(ColorRgba::new(80, 90, 100, 255), 1.0)),
                    4.0,
                ))
                .with_accessibility(
                    AccessibilityMeta::new(AccessibilityRole::Button)
                        .label("Play")
                        .focusable(),
                ),
        );
        doc.compute_layout(UiSize::new(240.0, 160.0), &mut ApproxTextMeasurer)
            .expect("layout");

        let mut host = HostInteractionState {
            hovered: Some(button),
            pressed: Some(button),
            focused: Some(button),
            input_consumed: true,
            input_consumed_by: Some(button),
            active_shortcut_scopes: vec![CommandScope::Workspace],
            ..Default::default()
        };
        host.shortcut_route = Some(crate::host::HostShortcutRoute {
            shortcut: crate::Shortcut::ctrl('p'),
            active_scopes: vec![CommandScope::Workspace],
            target: Some(button),
            command: Some(CommandId::new("transport.play")),
        });
        let wheel = GestureEvent::WheelTargeted {
            target: Some(button),
            event: RawWheelEvent {
                position: UiPoint::new(10.0, 10.0),
                delta: UiPoint::new(0.0, -1.0),
                unit: WheelDeltaUnit::Line,
                phase: WheelPhase::Moved,
                modifiers: crate::KeyModifiers::NONE,
                timestamp_millis: 10,
            },
        };

        let trace = DebugInteractionStateTrace::from_document(
            &doc,
            DebugOverlayContext::new(host).active_gesture(&wheel),
            DebugOverlayOptions::default(),
        );

        assert_eq!(trace.status, DebugFrameTraceStatus::Info);
        assert_eq!(trace.active_node_count, 1);
        assert_eq!(trace.hovered, Some(button));
        assert_eq!(trace.hovered_name.as_deref(), Some("play"));
        assert_eq!(trace.pressed_name.as_deref(), Some("play"));
        assert_eq!(trace.focused_name.as_deref(), Some("play"));
        assert_eq!(
            trace.routed_command.as_ref().map(CommandId::as_str),
            Some("transport.play")
        );
        assert!(trace
            .shortcut_label
            .as_deref()
            .is_some_and(|label| label.contains("Ctrl") && label.contains('P')));
        assert_eq!(trace.shortcut_target, Some(button));
        assert_eq!(trace.shortcut_target_name.as_deref(), Some("play"));
        assert!(trace
            .gesture_summary
            .as_deref()
            .is_some_and(|summary| summary.contains("wheel")));
        assert!(trace.summary.contains("interaction state"));

        let record = trace.record("play").expect("play interaction record");
        assert_eq!(record.status, DebugFrameTraceStatus::Info);
        assert!(record.hovered);
        assert!(record.pressed);
        assert!(record.focused);
        assert!(record.shortcut_targeted);
        assert!(record.input_consumed);
        assert!(record.roles.iter().any(|role| role == "hovered"));
        assert!(record.roles.iter().any(|role| role == "shortcut target"));
    }

    #[test]
    fn debug_widget_state_retention_trace_ranks_orphaned_keepalive_state() {
        let mut store =
            crate::state::RetainedWidgetStateStore::new(crate::state::WidgetStateRetention::new(2));
        let search = crate::state::WidgetKey::document("doc", "search");
        let popover = crate::state::WidgetKey::document("doc", "popover");
        let popover_key = crate::state::WidgetStateKey::new(popover.clone(), "overlay");

        store.begin_frame([search.clone(), popover.clone()]);
        store
            .ensure(
                search,
                crate::state::WidgetStateSlotDescriptor::edit(),
                crate::state::WidgetStateValue::edit("query", 5),
            )
            .expect("search edit state");
        store
            .set(
                popover.clone(),
                crate::state::WidgetStateSlotDescriptor::overlay(),
                crate::state::WidgetStateValue::overlay(true),
            )
            .expect("popover overlay state");
        assert!(store.set_keepalive(&popover_key, true));

        store.begin_frame([crate::state::WidgetKey::document("doc", "search")]);
        let trace = DebugWidgetStateRetentionTrace::from_store(&store);

        assert_eq!(trace.status, DebugFrameTraceStatus::Warning);
        assert_eq!(trace.entry_count, 2);
        assert_eq!(trace.active_count, 1);
        assert_eq!(trace.stale_count, 1);
        assert_eq!(trace.keepalive_count, 1);
        assert_eq!(trace.orphaned_count, 1);
        assert!(trace.summary.contains("orphaned"));

        let stale = trace
            .record("document:doc::popover.overlay")
            .expect("popover state record");
        assert_eq!(stale.status, DebugFrameTraceStatus::Warning);
        assert_eq!(stale.lifecycle.as_deref(), Some("orphaned"));
        assert_eq!(stale.stale_generations, Some(1));
        assert!(stale.keepalive);
        assert_eq!(stale.value.as_deref(), Some("open=true"));
        assert!(stale.cause.contains("not seen"));
        assert!(stale.fix.contains("widget tree"));

        let search = trace
            .record("document:doc::search.edit")
            .expect("search state record");
        assert_eq!(search.lifecycle.as_deref(), Some("reused"));
        assert_eq!(search.status, DebugFrameTraceStatus::Info);
        assert!(search
            .value
            .as_deref()
            .is_some_and(|value| value.contains("5 chars")));
    }

    #[test]
    fn debug_widget_state_retention_trace_includes_expired_keys() {
        let mut store =
            crate::state::RetainedWidgetStateStore::new(crate::state::WidgetStateRetention::new(0));
        let toast = crate::state::WidgetKey::document("doc", "toast");
        store.begin_frame([toast.clone()]);
        store
            .ensure(
                toast,
                crate::state::WidgetStateSlotDescriptor::overlay(),
                crate::state::WidgetStateValue::overlay(true),
            )
            .expect("toast state");
        store.begin_frame(Vec::<crate::state::WidgetKey>::new());
        store.begin_frame(Vec::<crate::state::WidgetKey>::new());

        let trace = DebugWidgetStateRetentionTrace::from_store(&store);

        assert_eq!(trace.status, DebugFrameTraceStatus::Warning);
        assert_eq!(trace.entry_count, 0);
        assert_eq!(trace.expired_count, 1);
        let expired = trace
            .record("document:doc::toast.overlay")
            .expect("expired toast record");
        assert_eq!(expired.lifecycle.as_deref(), Some("expired"));
        assert_eq!(expired.kind, "unknown");
        assert!(expired.summary.contains("expired"));
        assert!(expired.fix.contains("widget id and scope"));
    }

    #[test]
    fn debug_interaction_state_timeline_tracks_capture_and_resolved_roles() {
        fn frame(mode: &str, frame_index: u64) -> DebugFrameTrace {
            let mut doc = UiDocument::new(fixed_style(240.0, 160.0));
            let button = doc.add_child(
                doc.root,
                UiNode::container("play", fixed_style(80.0, 32.0))
                    .with_input(InputBehavior::BUTTON)
                    .with_visual(UiVisual::panel(
                        ColorRgba::new(20, 30, 40, 255),
                        Some(StrokeStyle::new(ColorRgba::new(80, 90, 100, 255), 1.0)),
                        4.0,
                    ))
                    .with_accessibility(
                        AccessibilityMeta::new(AccessibilityRole::Button)
                            .label("Play")
                            .focusable(),
                    ),
            );
            doc.compute_layout(UiSize::new(240.0, 160.0), &mut ApproxTextMeasurer)
                .expect("layout");
            let mut context = DebugFrameTraceContext::new("interaction", UiSize::new(240.0, 160.0))
                .frame_index(frame_index);
            if mode == "press" {
                let press = GestureEvent::Press {
                    target: Some(button),
                    pointer_id: crate::PointerId::MOUSE,
                    position: UiPoint::new(10.0, 10.0),
                    button: crate::PointerButton::Primary,
                    modifiers: crate::KeyModifiers::NONE,
                };
                let mut host = HostInteractionState::default();
                host.apply_gesture(&press);
                host.focused = Some(button);
                host.input_consumed = true;
                host.input_consumed_by = Some(button);
                context = context.interaction_state_from_overlay(
                    &doc,
                    DebugOverlayContext::new(host).active_gesture(&press),
                    DebugOverlayOptions::default(),
                );
            } else if mode == "idle" {
                context = context.interaction_state_from_overlay(
                    &doc,
                    DebugOverlayContext::new(HostInteractionState::default()),
                    DebugOverlayOptions::default(),
                );
            }
            DebugFrameTrace::from_document(&doc, &mut ApproxTextMeasurer, context)
        }

        let idle = frame("idle", 1);
        let pressed = frame("press", 2);
        let resolved = frame("idle", 3);
        let missing = frame("missing", 4);
        let trace =
            DebugInteractionStateTimelineTrace::from_traces([&idle, &pressed, &resolved, &missing]);
        let play = trace.record("play").expect("play interaction timeline");

        assert_eq!(trace.frame_count, 4);
        assert_eq!(trace.captured_frame_count, 3);
        assert_eq!(trace.missing_frame_count, 1);
        assert_eq!(trace.new_active_count, 1);
        assert_eq!(trace.resolved_active_count, 1);
        assert_eq!(trace.gesture_frame_count, 1);
        assert_eq!(trace.drag_capture_frame_count, 1);
        assert!(trace.summary.contains("interaction state timeline"));
        assert_eq!(play.frame_count, 1);
        assert_eq!(play.drag_captured_frame_count, 1);
        assert!(play.fix.contains("interaction_state_panel"));
        assert_eq!(trace.frame(1).map(|frame| frame.new_active_count), Some(1));
        assert_eq!(
            trace.frame(2).map(|frame| frame.resolved_active_count),
            Some(1)
        );

        let mut recorder = DebugFrameRecorder::new(4);
        recorder.record_frame(idle);
        recorder.record_frame(pressed);
        recorder.record_frame(resolved);
        recorder.record_frame(missing);
        assert_eq!(recorder.interaction_state_timeline().frame_count, 4);
    }

    #[test]
    fn debug_shortcut_route_trace_explains_scope_resolution_and_disabled_bindings() {
        let mut registry = CommandRegistry::new();
        registry
            .register(crate::CommandMeta::new("global.save", "Global Save"))
            .unwrap();
        registry
            .register(crate::CommandMeta::new("editor.save", "Editor Save"))
            .unwrap();
        registry
            .bind_shortcut(CommandScope::Global, Shortcut::ctrl('s'), "global.save")
            .unwrap();
        registry
            .bind_shortcut(CommandScope::Editor, Shortcut::ctrl('s'), "editor.save")
            .unwrap();
        registry
            .disable("editor.save", "editor is read-only")
            .unwrap();

        let trace = DebugShortcutRouteTrace::from_registry(
            &registry,
            Shortcut::ctrl('s'),
            &[CommandScope::Workspace, CommandScope::Editor],
        );
        let editor = trace
            .record(&CommandScope::Editor)
            .expect("editor route record");
        let global = trace
            .record(&CommandScope::Global)
            .expect("global route record");

        assert_eq!(trace.status, DebugFrameTraceStatus::Warning);
        assert_eq!(
            trace.command.as_ref().map(CommandId::as_str),
            Some("global.save")
        );
        assert_eq!(trace.selected_scope, Some(CommandScope::Global));
        assert_eq!(trace.disabled_binding_count, 1);
        assert!(trace.summary.contains("disabled"));
        assert_eq!(editor.status, DebugFrameTraceStatus::Warning);
        assert_eq!(
            editor.command.as_ref().map(CommandId::as_str),
            Some("editor.save")
        );
        assert!(!editor.command_enabled);
        assert!(editor.cause.contains("disabled"));
        assert!(global.selected);
        assert_eq!(
            global.command.as_ref().map(CommandId::as_str),
            Some("global.save")
        );

        let missing = DebugShortcutRouteTrace::from_registry(
            &registry,
            Shortcut::ctrl('x'),
            &[CommandScope::Editor],
        );
        assert_eq!(missing.status, DebugFrameTraceStatus::Ok);
        assert_eq!(missing.command, None);
        assert!(missing.summary.contains("no command"));
    }

    #[test]
    fn debug_animation_activity_trace_ranks_active_animation_inputs() {
        let mut doc = UiDocument::new(fixed_style(240.0, 140.0));
        doc.add_child(
            doc.root,
            UiNode::container("animated", fixed_style(80.0, 32.0)).with_animation(
                AnimationMachine::new(
                    vec![
                        AnimationState::new(
                            "idle",
                            AnimatedValues::new(1.0, UiPoint::new(0.0, 0.0), 1.0),
                        ),
                        AnimationState::new(
                            "open",
                            AnimatedValues::new(1.0, UiPoint::new(20.0, 0.0), 1.1),
                        ),
                    ],
                    vec![AnimationTransition::when(
                        "idle",
                        "open",
                        AnimationCondition::bool("expanded", true),
                        0.25,
                    )],
                    "idle",
                )
                .expect("animation")
                .with_bool_input("expanded", true)
                .with_number_input("hover", 0.5)
                .with_blend_binding(AnimationBlendBinding::new("hover", "idle", "open")),
            ),
        );
        doc.compute_layout(UiSize::new(240.0, 140.0), &mut ApproxTextMeasurer)
            .expect("layout");
        let snapshot = DebugInspectorSnapshot::from_document(&doc, &mut ApproxTextMeasurer);

        let trace = DebugAnimationActivityTrace::from_snapshot(&snapshot);
        let record = trace.record("animated").expect("animated activity");

        assert_eq!(trace.status, DebugFrameTraceStatus::Info);
        assert_eq!(trace.animation_count, 1);
        assert_eq!(trace.active_count, 1);
        assert_eq!(record.status, DebugFrameTraceStatus::Info);
        assert_eq!(record.current_state, "open");
        assert_eq!(record.target_state.as_deref(), Some("open"));
        assert!(record.active_transition.is_some());
        assert!(record.active_input_count >= 2);
        assert!(record.active_edge_count >= 1);
        assert!(record.summary.contains("animation"));
    }

    #[test]
    fn debug_animation_activity_timeline_tracks_active_and_resolved_animation_work() {
        fn frame(active: bool, frame_index: u64) -> DebugFrameTrace {
            let mut doc = UiDocument::new(fixed_style(240.0, 140.0));
            if active {
                doc.add_child(
                    doc.root,
                    UiNode::container("animated", fixed_style(80.0, 32.0)).with_animation(
                        AnimationMachine::new(
                            vec![
                                AnimationState::new(
                                    "idle",
                                    AnimatedValues::new(1.0, UiPoint::new(0.0, 0.0), 1.0),
                                ),
                                AnimationState::new(
                                    "open",
                                    AnimatedValues::new(1.0, UiPoint::new(20.0, 0.0), 1.1),
                                ),
                            ],
                            vec![AnimationTransition::when(
                                "idle",
                                "open",
                                AnimationCondition::bool("expanded", true),
                                0.25,
                            )],
                            "idle",
                        )
                        .expect("animation")
                        .with_bool_input("expanded", true)
                        .with_number_input("hover", 0.5)
                        .with_blend_binding(AnimationBlendBinding::new("hover", "idle", "open")),
                    ),
                );
            }
            doc.compute_layout(UiSize::new(240.0, 140.0), &mut ApproxTextMeasurer)
                .expect("layout");
            DebugFrameTrace::from_document(
                &doc,
                &mut ApproxTextMeasurer,
                DebugFrameTraceContext::new("animation", UiSize::new(240.0, 140.0))
                    .frame_index(frame_index),
            )
        }

        let idle = frame(false, 1);
        let active = frame(true, 2);
        let resolved = frame(false, 3);
        let trace = DebugAnimationActivityTimelineTrace::from_traces([&idle, &active, &resolved]);
        let record = trace.record("animated").expect("animated record");

        assert_eq!(trace.status, DebugFrameTraceStatus::Info);
        assert_eq!(trace.frame_count, 3);
        assert_eq!(trace.animation_frame_count, 1);
        assert_eq!(trace.active_frame_count, 1);
        assert_eq!(trace.new_active_count, 1);
        assert_eq!(trace.resolved_active_count, 1);
        assert_eq!(record.active_frame_count, 1);
        assert_eq!(record.latest_state, "open");
        assert!(record.max_score > 0);
        assert_eq!(
            trace
                .frame(1)
                .and_then(|frame| frame.top_animation_name.as_deref()),
            Some("animated")
        );
        assert_eq!(
            trace.frame(2).map(|frame| frame.resolved_active_count),
            Some(1)
        );

        let mut recorder = DebugFrameRecorder::new(4);
        recorder.record_frame(idle);
        recorder.record_frame(active);
        recorder.record_frame(resolved);
        assert_eq!(recorder.animation_activity_timeline().frame_count, 3);
    }

