    #[test]
    fn debug_paint_overdraw_timeline_tracks_persistent_new_and_resolved_overdraw() {
        fn overdraw_frame(front: bool, frame_index: u64) -> DebugFrameTrace {
            let mut doc = UiDocument::new(fixed_style(200.0, 120.0));
            doc.add_child(
                doc.root,
                UiNode::container("back", absolute_style_at(0.0, 0.0, 0.0, 90.0, 40.0))
                    .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0)),
            );
            if front {
                doc.add_child(
                    doc.root,
                    UiNode::container("front", absolute_style_at(10.0, 0.0, 8.0, 90.0, 40.0))
                        .with_visual(UiVisual::panel(ColorRgba::new(180, 40, 40, 255), None, 0.0)),
                );
            }
            doc.compute_layout(UiSize::new(200.0, 120.0), &mut ApproxTextMeasurer)
                .expect("overdraw timeline layout");
            DebugFrameTrace::from_document(
                &doc,
                &mut ApproxTextMeasurer,
                DebugFrameTraceContext::new("overdraw", UiSize::new(200.0, 120.0))
                    .frame_index(frame_index),
            )
        }

        let clean = overdraw_frame(false, 1);
        let covered = overdraw_frame(true, 2);
        let restored = overdraw_frame(false, 3);

        let trace = DebugPaintOverdrawTimelineTrace::from_traces([&clean, &covered, &restored]);
        let back = trace.record_name("back").expect("back overdraw timeline");
        let appeared = trace.frame("overdraw #2").expect("appeared frame");
        let resolved = trace.frame("overdraw #3").expect("resolved frame");

        assert_eq!(trace.status, DebugFrameTraceStatus::Warning);
        assert_eq!(trace.frame_count, 3);
        assert_eq!(trace.overdraw_frame_count, 1);
        assert_eq!(trace.new_overdraw_count, 1);
        assert_eq!(trace.resolved_overdraw_count, 1);
        assert_eq!(trace.persistent_overdraw_count, 0);
        assert!(trace.summary.contains("paint overdraw timeline"));
        assert_eq!(back.frame_count, 1);
        assert!(back.max_covered_ratio > 0.8);
        assert_eq!(back.latest_covering_name.as_deref(), Some("front"));
        assert_eq!(appeared.new_overdraw_count, 1);
        assert_eq!(resolved.resolved_overdraw_count, 1);

        let mut recorder = DebugFrameRecorder::new(3);
        recorder.push(clean);
        recorder.push(covered);
        recorder.push(restored);
        let recorded = recorder.paint_overdraw_timeline();
        assert_eq!(recorded.frame_count, 3);
        assert!(recorded.record_name("back").is_some());
    }

    #[test]
    fn debug_paint_batch_trace_explains_batch_groups_and_breaks() {
        let mut doc = UiDocument::new(fixed_style(200.0, 120.0));
        doc.add_child(
            doc.root,
            UiNode::container("left", absolute_style_at(0.0, 0.0, 0.0, 20.0, 20.0))
                .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0)),
        );
        doc.add_child(
            doc.root,
            UiNode::container("right", absolute_style_at(24.0, 0.0, 0.0, 20.0, 20.0))
                .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0)),
        );
        doc.add_child(
            doc.root,
            UiNode::container("glow", absolute_style_at(48.0, 0.0, 0.0, 20.0, 20.0))
                .with_shader(crate::ShaderEffect::new("debug.glow"))
                .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0)),
        );
        doc.compute_layout(UiSize::new(200.0, 120.0), &mut ApproxTextMeasurer)
            .expect("layout");
        let layout = doc.layout_snapshot();
        let paint = doc.paint_list();

        let trace = DebugPaintBatchTrace::from_parts(&layout, &paint);
        let first = trace.batch(0).expect("first batch");
        let split = trace.breaks.first().expect("batch break");

        assert_eq!(trace.status, DebugFrameTraceStatus::Info);
        assert_eq!(trace.item_count, 3);
        assert_eq!(trace.batch_count, 2);
        assert_eq!(trace.singleton_batch_count, 1);
        assert_eq!(trace.largest_batch_len, 2);
        assert!(trace.summary.contains("paint batches"));
        assert_eq!(first.item_count, 2);
        assert!(first.node_names.contains(&"left".to_owned()));
        assert!(first.node_names.contains(&"right".to_owned()));
        assert!(split.shader_changed);
        assert!(split.cause.contains("shader"));
    }

    #[test]
    fn debug_paint_batch_timeline_tracks_new_and_resolved_split_reasons() {
        fn batch_frame(shader: bool, frame_index: u64) -> DebugFrameTrace {
            let mut doc = UiDocument::new(fixed_style(200.0, 120.0));
            doc.add_child(
                doc.root,
                UiNode::container("left", absolute_style_at(0.0, 0.0, 0.0, 20.0, 20.0))
                    .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0)),
            );
            doc.add_child(
                doc.root,
                UiNode::container("middle", absolute_style_at(24.0, 0.0, 0.0, 20.0, 20.0))
                    .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0)),
            );
            let mut glow = UiNode::container("glow", absolute_style_at(48.0, 0.0, 0.0, 20.0, 20.0))
                .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0));
            if shader {
                glow = glow.with_shader(crate::ShaderEffect::new("debug.glow"));
            }
            doc.add_child(doc.root, glow);
            doc.compute_layout(UiSize::new(200.0, 120.0), &mut ApproxTextMeasurer)
                .expect("batch timeline layout");
            DebugFrameTrace::from_document(
                &doc,
                &mut ApproxTextMeasurer,
                DebugFrameTraceContext::new("batches", UiSize::new(200.0, 120.0))
                    .frame_index(frame_index),
            )
        }

        let clean = batch_frame(false, 1);
        let split = batch_frame(true, 2);
        let restored = batch_frame(false, 3);

        let trace = DebugPaintBatchTimelineTrace::from_traces([&clean, &split, &restored]);
        let shader = trace.record("shader").expect("shader split reason");
        let split_frame = trace.frame("batches #2").expect("split frame");
        let restored_frame = trace.frame("batches #3").expect("restored frame");

        assert_eq!(trace.status, DebugFrameTraceStatus::Info);
        assert_eq!(trace.frame_count, 3);
        assert_eq!(trace.split_frame_count, 1);
        assert_eq!(trace.new_break_count, 1);
        assert_eq!(trace.resolved_break_count, 1);
        assert_eq!(trace.top_reason.as_deref(), Some("shader"));
        assert!(trace.summary.contains("paint batch timeline"));
        assert_eq!(shader.frame_count, 1);
        assert_eq!(shader.break_count, 1);
        assert_eq!(split_frame.new_break_count, 1);
        assert_eq!(split_frame.top_reason.as_deref(), Some("shader"));
        assert_eq!(restored_frame.resolved_break_count, 1);

        let mut recorder = DebugFrameRecorder::new(3);
        recorder.push(clean);
        recorder.push(split);
        recorder.push(restored);
        let recorded = recorder.paint_batch_timeline();
        assert_eq!(recorded.frame_count, 3);
        assert!(recorded.record("shader").is_some());
    }

    #[test]
    fn debug_action_map_trace_lists_bindings_and_unbound_interactive_nodes() {
        let mut doc = UiDocument::new(fixed_style(220.0, 140.0));
        doc.add_child(
            doc.root,
            UiNode::container("button", absolute_style_at(0.0, 0.0, 0.0, 60.0, 24.0))
                .with_input(InputBehavior::BUTTON)
                .with_action("button.activate")
                .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0)),
        );
        doc.add_child(
            doc.root,
            UiNode::container("command", absolute_style_at(0.0, 30.0, 0.0, 60.0, 24.0))
                .with_input(InputBehavior::BUTTON)
                .with_action(WidgetActionBinding::command(CommandId::new(
                    "debug.command",
                )))
                .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0)),
        );
        doc.add_child(
            doc.root,
            UiNode::container(
                "passive_action",
                absolute_style_at(0.0, 60.0, 0.0, 60.0, 24.0),
            )
            .with_action("passive.activate")
            .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0)),
        );
        doc.add_child(
            doc.root,
            UiNode::container("unbound", absolute_style_at(0.0, 90.0, 0.0, 60.0, 24.0))
                .with_input(InputBehavior::BUTTON)
                .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0)),
        );
        doc.compute_layout(UiSize::new(220.0, 140.0), &mut ApproxTextMeasurer)
            .expect("layout");

        let trace = DebugActionMapTrace::from_document(&doc);
        let button = trace.record("button").expect("button action record");
        let command = trace.record("command").expect("command action record");
        let passive = trace
            .record("passive_action")
            .expect("passive action record");

        assert_eq!(trace.status, DebugFrameTraceStatus::Warning);
        assert_eq!(trace.binding_count, 3);
        assert_eq!(trace.action_count, 2);
        assert_eq!(trace.command_count, 1);
        assert_eq!(trace.interactive_without_binding_count, 1);
        assert_eq!(trace.passive_binding_count, 1);
        assert!(trace.summary.contains("action map"));
        assert_eq!(button.status, DebugFrameTraceStatus::Ok);
        assert!(button.hit_testable);
        assert_eq!(command.binding_kind.as_deref(), Some("command"));
        assert_eq!(passive.status, DebugFrameTraceStatus::Warning);
        assert!(passive.cause.contains("needs compatible input"));

        let snapshot = DebugInspectorSnapshot::from_document(&doc, &mut ApproxTextMeasurer);
        let retained = DebugActionMapTrace::from_snapshot(&snapshot);
        assert_eq!(retained.binding_count, trace.binding_count);
        assert_eq!(retained.command_count, trace.command_count);
        assert_eq!(
            retained
                .record("button")
                .and_then(|record| record.binding.as_deref()),
            Some("action:button.activate")
        );
    }

    #[test]
    fn debug_action_dispatch_trace_summarizes_queued_actions() {
        let mut queue = WidgetActionQueue::new();
        queue.push(WidgetAction::pointer_activate(
            UiNodeId::from_index(4),
            "button.activate",
            2,
        ));
        queue.push(WidgetAction::value_edit(
            UiNodeId::from_index(5),
            WidgetActionBinding::command(CommandId::new("volume.commit")),
            WidgetValueEditPhase::Commit,
        ));

        let trace = DebugActionDispatchTrace::from_queue(&queue);
        let activation = trace.record(0).expect("activation dispatch");
        let edit = trace.record(1).expect("edit dispatch");

        assert_eq!(trace.status, DebugFrameTraceStatus::Ok);
        assert_eq!(trace.queued_count, 2);
        assert_eq!(trace.warning_count, 0);
        assert_eq!(trace.action_count, 1);
        assert_eq!(trace.command_count, 1);
        assert_eq!(trace.activation_count, 1);
        assert_eq!(trace.edit_count, 1);
        assert!(trace.summary.contains("action dispatch"));
        assert_eq!(activation.action_id.as_deref(), Some("button.activate"));
        assert_eq!(activation.trigger.as_deref(), Some("pointer.primary"));
        assert!(activation.detail.contains("count 2"));
        assert_eq!(edit.command_id.as_deref(), Some("volume.commit"));
        assert_eq!(edit.action_kind, "value-edit");
        assert_eq!(edit.phase.as_deref(), Some("commit"));
    }

    #[test]
    fn debug_action_dispatch_trace_marks_disabled_registry_commands() {
        let mut queue = WidgetActionQueue::new();
        queue.push(WidgetAction::keyboard_activate(
            UiNodeId::from_index(6),
            WidgetActionBinding::command(CommandId::new("debug.disabled")),
        ));
        queue.push(WidgetAction::keyboard_activate(
            UiNodeId::from_index(7),
            WidgetActionBinding::command(CommandId::new("debug.missing")),
        ));
        let mut registry = CommandRegistry::new();
        registry
            .register(crate::CommandMeta::new(
                "debug.disabled",
                "Disabled debug command",
            ))
            .expect("register command");
        registry
            .disable("debug.disabled", "requires selection")
            .expect("disable command");

        let trace = DebugActionDispatchTrace::from_queue_with_registry(&queue, &registry);
        let disabled = trace.record(0).expect("disabled command dispatch");
        let missing = trace.record(1).expect("missing command dispatch");

        assert_eq!(trace.status, DebugFrameTraceStatus::Warning);
        assert_eq!(trace.warning_count, 2);
        assert_eq!(disabled.command_enabled, Some(false));
        assert_eq!(
            disabled.disabled_reason.as_deref(),
            Some("requires selection")
        );
        assert_eq!(
            disabled.command_label.as_deref(),
            Some("Disabled debug command")
        );
        assert_eq!(missing.command_enabled, Some(false));
        assert_eq!(
            missing.disabled_reason.as_deref(),
            Some("unregistered command")
        );
        assert!(trace.summary.contains("warnings"));
        assert!(trace.fix.contains("register or enable"));
    }

