    #[cfg(feature = "widgets")]
    #[test]
    fn debug_text_input_state_trace_summarizes_selection_composition_and_history() {
        let mut state = TextInputState::new("alpha\nbeta").multiline(true);
        state.paste_text_with_outcome("!");
        state.set_selection(0, 5);
        state.set_composing(Some("preedit".to_owned()));

        let trace = DebugTextInputStateTrace::from_state(&state);

        assert_eq!(trace.status, DebugFrameTraceStatus::Info);
        assert_eq!(trace.text_preview, "alpha\\nbeta!");
        assert_eq!(trace.byte_len, "alpha\nbeta!".len());
        assert_eq!(trace.char_count, 11);
        assert_eq!(trace.line_count, 2);
        assert!(trace.multiline);
        assert_eq!(trace.caret, 5);
        assert_eq!(trace.caret_line, 0);
        assert_eq!(trace.caret_column, 5);
        assert_eq!(trace.selection_anchor, Some(0));
        assert_eq!(trace.selection_range, Some((0, 5)));
        assert_eq!(trace.selected_char_count, 5);
        assert_eq!(trace.selected_text_preview.as_deref(), Some("alpha"));
        assert_eq!(trace.composing_text.as_deref(), Some("preedit"));
        assert_eq!(trace.composing_char_count, 7);
        assert_eq!(trace.undo_depth, 1);
        assert_eq!(trace.redo_depth, 0);
        assert!(trace.can_undo);
        assert!(!trace.can_redo);
        assert!(!trace.collapsed_selection_anchor);
        assert!(trace.summary.contains("selection 0..5"));
        assert!(trace.summary.contains("composition 7 chars"));
        assert!(trace.summary.contains("undo 1 redo 0"));
    }

