    #[test]
    fn debug_text_localization_trace_ranks_dynamic_text_without_intrinsic_measurement() {
        let style = TextStyle::default();
        let policy = LocalizationPolicy::new(LocaleId::new("ar-EG").expect("locale"))
            .with_bidi(BidiPolicy::Embed);
        let mut doc = UiDocument::new(fixed_style(240.0, 140.0));
        doc.add_child(
            doc.root,
            UiNode::localized_text(
                "missing",
                DynamicLabelMeta::dynamic("toolbar.save", "Save", 7).with_bidi(BidiPolicy::Embed),
                Some(&policy),
                style.clone(),
                LayoutStyle::size(80.0, 18.0),
            ),
        );
        let ready = doc.add_child(
            doc.root,
            UiNode::localized_text(
                "ready",
                DynamicLabelMeta::keyed("toolbar.settings", "Settings")
                    .with_bidi(BidiPolicy::Embed),
                Some(&policy),
                style,
                LayoutStyle::size(120.0, 18.0),
            ),
        );
        if let UiContent::Text(text) = &mut doc.node_mut(ready).content {
            text.intrinsic_text = Some("Localized settings label".to_owned());
        }

        let trace = DebugTextLocalizationTrace::from_document(&doc);
        let missing = trace
            .record("missing")
            .expect("missing localization record");
        let ready = trace.record("ready").expect("ready localization record");

        assert_eq!(trace.status, DebugFrameTraceStatus::Warning);
        assert_eq!(trace.text_node_count, 2);
        assert_eq!(trace.localized_count, 2);
        assert_eq!(trace.rtl_count, 2);
        assert_eq!(trace.dynamic_label_count, 2);
        assert_eq!(trace.intrinsic_text_count, 1);
        assert_eq!(trace.missing_intrinsic_count, 1);
        assert!(trace.summary.contains("text localization"));
        assert_eq!(trace.records[0].name, "missing");
        assert_eq!(missing.status, DebugFrameTraceStatus::Warning);
        assert_eq!(missing.locale.as_deref(), Some("ar-EG"));
        assert_eq!(missing.direction, "Rtl");
        assert_eq!(missing.bidi, "Embed");
        assert_eq!(missing.dynamic_key.as_deref(), Some("toolbar.save"));
        assert!(missing.fix.contains("intrinsic_text"));
        assert_eq!(ready.status, DebugFrameTraceStatus::Info);
        assert!(ready.uses_intrinsic_text);
        assert_eq!(ready.measurement_text, "Localized settings label");
    }

    #[test]
    fn debug_text_contrast_trace_ranks_low_contrast_text() {
        let mut low_style = TextStyle::default();
        low_style.font_size = 13.0;
        low_style.line_height = 16.0;
        low_style.color = ColorRgba::new(78, 84, 92, 255);
        let mut good_style = low_style.clone();
        good_style.color = ColorRgba::new(235, 242, 250, 255);
        let mut doc = UiDocument::new(fixed_style(220.0, 140.0));
        let panel = doc.add_child(
            doc.root,
            UiNode::container("panel", fixed_style(180.0, 80.0)).with_visual(UiVisual::panel(
                ColorRgba::new(44, 50, 58, 255),
                None,
                0.0,
            )),
        );
        doc.add_child(
            panel,
            UiNode::text(
                "low",
                "Muted label",
                low_style,
                LayoutStyle::size(120.0, 18.0),
            ),
        );
        doc.add_child(
            panel,
            UiNode::text(
                "good",
                "Readable label",
                good_style,
                LayoutStyle::size(130.0, 18.0),
            ),
        );
        doc.compute_layout(UiSize::new(220.0, 140.0), &mut ApproxTextMeasurer)
            .expect("layout");

        let trace = DebugTextContrastTrace::from_document(&doc);
        let low = trace.record("low").expect("low contrast record");
        let good = trace.record("good").expect("good contrast record");

        assert_eq!(trace.status, DebugFrameTraceStatus::Warning);
        assert_eq!(trace.text_node_count, 2);
        assert_eq!(trace.checked_count, 2);
        assert_eq!(trace.low_contrast_count, 1);
        assert_eq!(trace.missing_background_count, 0);
        assert!(trace.summary.contains("text contrast"));
        assert_eq!(trace.records[0].name, "low");
        assert_eq!(low.status, DebugFrameTraceStatus::Warning);
        assert!(low
            .contrast_ratio
            .is_some_and(|ratio| ratio < low.required_ratio));
        assert!(low.deficit > 0.0);
        assert!(low.fix.contains("contrast"));
        assert_eq!(good.status, DebugFrameTraceStatus::Ok);
        assert!(good
            .contrast_ratio
            .is_some_and(|ratio| ratio >= good.required_ratio));
    }

