    #[test]
    fn debug_text_fit_timeline_tracks_new_and_resolved_overflow() {
        fn text_frame(width: f32, frame_index: u64) -> DebugFrameTrace {
            let mut style = TextStyle::default();
            style.font_size = 14.0;
            style.line_height = 16.0;
            style.wrap = TextWrap::None;
            let mut doc = UiDocument::new(fixed_style(320.0, 120.0));
            doc.add_child(
                doc.root,
                UiNode::text(
                    "long",
                    "A very long debug label",
                    style,
                    LayoutStyle::size(width, 18.0),
                ),
            );
            doc.compute_layout(UiSize::new(320.0, 120.0), &mut ApproxTextMeasurer)
                .expect("layout");
            DebugFrameTrace::from_document(
                &doc,
                &mut ApproxTextMeasurer,
                DebugFrameTraceContext::new("text", UiSize::new(320.0, 120.0))
                    .frame_index(frame_index),
            )
        }

        let clean = text_frame(240.0, 1);
        let overflow = text_frame(48.0, 2);
        let restored = text_frame(240.0, 3);
        let trace = DebugTextFitTimelineTrace::from_traces([&clean, &overflow, &restored]);
        let record = trace.record("long").expect("long text timeline record");
        let overflow_frame = trace.frame("text #2").expect("overflow frame");
        let restored_frame = trace.frame("text #3").expect("restored frame");

        assert_eq!(trace.status, DebugFrameTraceStatus::Warning);
        assert_eq!(trace.frame_count, 3);
        assert_eq!(trace.text_frame_count, 3);
        assert_eq!(trace.issue_frame_count, 1);
        assert_eq!(trace.changed_frame_count, 2);
        assert_eq!(trace.new_issue_count, 1);
        assert_eq!(trace.resolved_issue_count, 1);
        assert!(trace.summary.contains("text fit timeline"));
        assert_eq!(record.status, DebugFrameTraceStatus::Warning);
        assert_eq!(record.frame_count, 3);
        assert_eq!(record.issue_frame_count, 1);
        assert_eq!(record.overflow_frame_count, 1);
        assert!(record.max_horizontal_overflow_by > 0.0);
        assert_eq!(record.latest_horizontal_overflow_by, 0.0);
        assert!(record.fix.contains("text_fit_panel"));
        assert_eq!(overflow_frame.status, DebugFrameTraceStatus::Warning);
        assert_eq!(overflow_frame.new_issue_count, 1);
        assert_eq!(overflow_frame.overflow_count, 1);
        assert_ne!(restored_frame.status, DebugFrameTraceStatus::Warning);
        assert_eq!(restored_frame.resolved_issue_count, 1);

        let mut recorder = DebugFrameRecorder::new(3);
        recorder.push(clean);
        recorder.push(overflow);
        recorder.push(restored);
        assert_eq!(
            recorder.text_fit_timeline().resolved_issue_count,
            trace.resolved_issue_count
        );
    }

    #[test]
    fn debug_inspector_snapshot_combines_layout_animation_and_accessibility() {
        let mut doc = UiDocument::new(fixed_style(240.0, 160.0));
        let button = doc.add_child(
            doc.root,
            UiNode::container("play", fixed_style(96.0, 36.0))
                .with_input(InputBehavior::BUTTON)
                .with_accessibility(
                    crate::AccessibilityMeta::new(crate::AccessibilityRole::Button)
                        .label("Play")
                        .focusable()
                        .action(crate::AccessibilityAction::new("activate", "Activate")),
                )
                .with_animation(
                    crate::AnimationMachine::new(
                        vec![
                            crate::AnimationState::new(
                                "idle",
                                crate::AnimatedValues::new(1.0, crate::UiPoint::new(0.0, 0.0), 1.0),
                            ),
                            crate::AnimationState::new(
                                "armed",
                                crate::AnimatedValues::new(1.0, crate::UiPoint::new(4.0, 0.0), 1.0),
                            ),
                        ],
                        Vec::new(),
                        "idle",
                    )
                    .expect("animation")
                    .with_number_input("hover", 0.25)
                    .with_blend_binding(crate::AnimationBlendBinding::new(
                        "hover", "idle", "armed",
                    )),
                )
                .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 4.0)),
        );
        doc.compute_layout(UiSize::new(240.0, 160.0), &mut ApproxTextMeasurer)
            .expect("layout");

        let snapshot = DebugInspectorSnapshot::from_document(&doc, &mut ApproxTextMeasurer);
        let node = snapshot.node("play").expect("play inspector node");
        let hitbox = snapshot.hitbox("play").expect("play hitbox node");

        assert_eq!(node.id, button);
        assert_eq!(hitbox.id, button);
        assert!(hitbox.hit_eligibility.eligible);
        assert_eq!(node.final_size, UiSize::new(96.0, 36.0));
        assert!(node.intrinsic_size.is_some());
        assert_eq!(
            node.accessibility
                .as_ref()
                .and_then(|meta| meta.label.as_deref()),
            Some("Play")
        );
        assert!(snapshot
            .accessibility_overlay
            .iter()
            .any(|overlay| overlay.id == button && overlay.focus_index == Some(0)));

        let animation = snapshot.animation("play").expect("animation inspector");
        assert_eq!(animation.current_state, "idle");
        assert_eq!(animation.inputs[0].0, "hover");
        assert_eq!(animation.states.len(), 2);
        assert_eq!(animation.blend_bindings.len(), 1);
    }

