    #[test]
    fn debug_render_layer_timeline_tracks_new_and_resolved_layer_features() {
        fn layer_frame(effect: bool, frame_index: u64) -> DebugFrameTrace {
            let mut doc = UiDocument::new(fixed_style(200.0, 120.0));
            doc.add_child(
                doc.root,
                UiNode::container("base", absolute_style_at(0.0, 0.0, 0.0, 64.0, 28.0))
                    .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0)),
            );
            let mut accent_style = absolute_style_at(72.0, 0.0, 0.0, 64.0, 28.0);
            if effect {
                accent_style = accent_style.with_opacity(0.5);
            }
            let mut accent = UiNode::container("accent", accent_style).with_visual(
                UiVisual::panel(ColorRgba::new(120, 70, 180, 255), None, 0.0),
            );
            if effect {
                accent = accent.with_shader(crate::ShaderEffect::new("debug.glow"));
            }
            doc.add_child(doc.root, accent);
            doc.compute_layout(UiSize::new(200.0, 120.0), &mut ApproxTextMeasurer)
                .expect("render layer timeline layout");
            DebugFrameTrace::from_document(
                &doc,
                &mut ApproxTextMeasurer,
                DebugFrameTraceContext::new("layers", UiSize::new(200.0, 120.0))
                    .frame_index(frame_index),
            )
        }

        let clean = layer_frame(false, 1);
        let featured = layer_frame(true, 2);
        let restored = layer_frame(false, 3);

        let trace = DebugRenderLayerTimelineTrace::from_traces([&clean, &featured, &restored]);
        let app_layer = trace
            .layer(UiLayer::AppContent)
            .expect("app content layer timeline");
        let featured_frame = trace.frame("layers #2").expect("featured frame");
        let restored_frame = trace.frame("layers #3").expect("restored frame");

        assert_eq!(trace.status, DebugFrameTraceStatus::Info);
        assert_eq!(trace.frame_count, 3);
        assert_eq!(trace.feature_frame_count, 1);
        assert_eq!(trace.new_feature_count, 1);
        assert_eq!(trace.resolved_feature_count, 1);
        assert_eq!(trace.top_layer, Some(UiLayer::AppContent));
        assert!(trace.summary.contains("render layer timeline"));
        assert_eq!(app_layer.frame_count, 3);
        assert_eq!(app_layer.max_shader_count, 1);
        assert_eq!(app_layer.max_transparent_count, 1);
        assert_eq!(featured_frame.new_feature_count, 1);
        assert_eq!(featured_frame.shader_item_count, 1);
        assert_eq!(restored_frame.resolved_feature_count, 1);

        let mut recorder = DebugFrameRecorder::new(3);
        recorder.push(clean);
        recorder.push(featured);
        recorder.push(restored);
        let recorded = recorder.render_layer_timeline();
        assert_eq!(recorded.frame_count, 3);
        assert!(recorded.layer(UiLayer::AppContent).is_some());
    }

