    #[test]
    fn debug_event_route_trace_explains_target_and_occluded_candidates() {
        let mut doc = UiDocument::new(fixed_style(200.0, 120.0));
        let back = doc.add_child(
            doc.root,
            UiNode::container("back", layered_absolute_style(0.0, 90.0, 40.0))
                .with_input(InputBehavior::BUTTON)
                .with_action("back.activate")
                .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0)),
        );
        let front = doc.add_child(
            doc.root,
            UiNode::container("front", layered_absolute_style(8.0, 90.0, 40.0))
                .with_input(InputBehavior::BUTTON)
                .with_action("front.activate")
                .with_visual(UiVisual::panel(ColorRgba::new(180, 40, 40, 255), None, 0.0)),
        );
        doc.compute_layout(UiSize::new(200.0, 120.0), &mut ApproxTextMeasurer)
            .expect("layout");

        let trace = DebugEventRouteTrace::pointer_down(&doc, UiPoint::new(10.0, 10.0));

        assert_eq!(trace.hit, Some(front));
        assert_eq!(trace.target, Some(front));
        assert_eq!(trace.pressed_after, Some(front));
        assert_eq!(trace.consumed_by, Some(front));
        assert!(trace
            .target_candidate()
            .is_some_and(|candidate| candidate.name == "front" && candidate.selected));
        let back_candidate = trace.candidate("back").expect("back candidate");
        assert_eq!(back_candidate.id, back);
        assert!(back_candidate.rejections.iter().any(|rejection| {
            matches!(
                rejection,
                DebugEventRouteRejection::BehindHigherTarget { target } if *target == front
            )
        }));
    }

