    #[test]
    fn debug_pointer_session_trace_tracks_target_changes_and_rejections() {
        let mut first_doc = UiDocument::new(fixed_style(200.0, 120.0));
        first_doc.add_child(
            first_doc.root,
            UiNode::container("back", layered_absolute_style(0.0, 90.0, 40.0))
                .with_input(InputBehavior::BUTTON)
                .with_action("back.activate")
                .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0)),
        );
        first_doc
            .compute_layout(UiSize::new(200.0, 120.0), &mut ApproxTextMeasurer)
            .expect("first layout");
        let first_route = DebugEventRouteTrace::pointer_down(&first_doc, UiPoint::new(10.0, 10.0));
        let first = DebugFrameTrace::from_document(
            &first_doc,
            &mut ApproxTextMeasurer,
            DebugFrameTraceContext::new("pointer", UiSize::new(200.0, 120.0))
                .frame_index(1)
                .route(first_route),
        );

        let mut second_doc = UiDocument::new(fixed_style(200.0, 120.0));
        second_doc.add_child(
            second_doc.root,
            UiNode::container("back", layered_absolute_style(0.0, 90.0, 40.0))
                .with_input(InputBehavior::BUTTON)
                .with_action("back.activate")
                .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0)),
        );
        second_doc.add_child(
            second_doc.root,
            UiNode::container("front", layered_absolute_style(8.0, 90.0, 40.0))
                .with_input(InputBehavior::BUTTON)
                .with_action("front.activate")
                .with_visual(UiVisual::panel(ColorRgba::new(180, 40, 40, 255), None, 0.0)),
        );
        second_doc
            .compute_layout(UiSize::new(200.0, 120.0), &mut ApproxTextMeasurer)
            .expect("second layout");
        let second_route =
            DebugEventRouteTrace::pointer_down(&second_doc, UiPoint::new(10.0, 10.0));
        let second = DebugFrameTrace::from_document(
            &second_doc,
            &mut ApproxTextMeasurer,
            DebugFrameTraceContext::new("pointer", UiSize::new(200.0, 120.0))
                .frame_index(2)
                .route(second_route),
        );

        let trace = DebugPointerSessionTrace::from_traces([&first, &second]);
        let changed = trace
            .record("pointer #2 pointer-down")
            .expect("changed route");
        let mut recorder = DebugFrameRecorder::new(4);
        recorder.record_frame(first);
        recorder.record_frame(second);
        let recorded = recorder.pointer_session();

        assert_eq!(trace.status, DebugFrameTraceStatus::Warning);
        assert_eq!(trace.frame_count, 2);
        assert_eq!(trace.route_count, 2);
        assert_eq!(trace.target_change_count, 1);
        assert!(trace.rejected_candidate_count >= 1);
        assert_eq!(trace.latest_target_name.as_deref(), Some("front"));
        assert!(trace.summary.contains("pointer session"));
        assert_eq!(changed.previous_target_name.as_deref(), Some("back"));
        assert_eq!(changed.target_name.as_deref(), Some("front"));
        assert!(changed.target_changed);
        assert!(changed.occluded_count >= 1);
        assert_eq!(changed.panel, "point_autopsy_panel");
        assert!(changed.fix.contains("open"));
        assert_eq!(recorded.route_count, 2);
        assert!(recorded.record("pointer #2 pointer-down").is_some());
    }

