    #[test]
    fn debug_clip_chain_timeline_tracks_new_and_resolved_clipping() {
        fn clip_frame(target_x: f32, frame_index: u64) -> DebugFrameTrace {
            let mut clip_style = fixed_style(80.0, 40.0);
            clip_style.set_clip(ClipBehavior::Clip);
            let mut doc = UiDocument::new(fixed_style(220.0, 140.0));
            let clipper = doc.add_child(doc.root, UiNode::container("clipper", clip_style));
            doc.add_child(
                clipper,
                UiNode::container("target", absolute_style_at(target_x, 6.0, 0.0, 48.0, 24.0))
                    .with_input(InputBehavior::BUTTON)
                    .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0)),
            );
            doc.compute_layout(UiSize::new(220.0, 140.0), &mut ApproxTextMeasurer)
                .expect("clip timeline layout");
            DebugFrameTrace::from_document(
                &doc,
                &mut ApproxTextMeasurer,
                DebugFrameTraceContext::new("clip", UiSize::new(220.0, 140.0))
                    .frame_index(frame_index),
            )
        }

        let clean = clip_frame(10.0, 1);
        let clipped = clip_frame(60.0, 2);
        let restored = clip_frame(10.0, 3);

        let trace = DebugClipChainTimelineTrace::from_traces([&clean, &clipped, &restored]);
        let target = trace.record("target").expect("target clip timeline");
        let clipped_frame = trace.frame("clip #2").expect("clipped frame");
        let restored_frame = trace.frame("clip #3").expect("restored frame");

        assert_eq!(trace.status, DebugFrameTraceStatus::Warning);
        assert_eq!(trace.frame_count, 3);
        assert_eq!(trace.clipped_frame_count, 1);
        assert_eq!(trace.new_clip_count, 1);
        assert_eq!(trace.resolved_clip_count, 1);
        assert_eq!(trace.top_name.as_deref(), Some("target"));
        assert!(trace.summary.contains("clip chain timeline"));
        assert_eq!(target.frame_count, 1);
        assert_eq!(target.latest_clipped_by_name.as_deref(), Some("clipper"));
        assert!(target.max_clipped_ratio > 0.0);
        assert_eq!(clipped_frame.new_clip_count, 1);
        assert_eq!(clipped_frame.interactive_clipped_count, 1);
        assert_eq!(restored_frame.resolved_clip_count, 1);

        let mut recorder = DebugFrameRecorder::new(3);
        recorder.push(clean);
        recorder.push(clipped);
        recorder.push(restored);
        let recorded = recorder.clip_chain_timeline();
        assert_eq!(recorded.frame_count, 3);
        assert!(recorded.record("target").is_some());
    }

