    #[test]
    fn debug_wheel_route_trace_explains_blocked_scroll_scope() {
        let mut back_style = absolute_style_at(20.0, 20.0, 1.0, 100.0, 60.0);
        back_style.set_clip(ClipBehavior::Clip);
        let mut doc = UiDocument::new(fixed_style(160.0, 140.0));
        let back_scroll = doc.add_child(
            doc.root,
            UiNode::container("back.scroll", back_style).with_scroll(ScrollAxes::VERTICAL),
        );
        doc.add_child(
            back_scroll,
            UiNode::container("back.content", fixed_style(100.0, 140.0)),
        );
        let mut front_style = absolute_style_at(10.0, 10.0, 10.0, 120.0, 90.0);
        front_style.set_clip(ClipBehavior::Clip);
        let front = doc.add_child(
            doc.root,
            UiNode::container("front.panel", front_style).with_visual(UiVisual::panel(
                ColorRgba::new(28, 34, 44, 255),
                None,
                0.0,
            )),
        );
        doc.compute_layout(UiSize::new(160.0, 140.0), &mut ApproxTextMeasurer)
            .expect("layout");

        let trace = DebugWheelRouteTrace::from_document(
            &doc,
            UiWheelEvent::pixels(UiPoint::new(30.0, 30.0), UiPoint::new(0.0, 30.0)),
        );
        let front_record = trace.record("front.panel").expect("front wheel record");
        let back_record = trace.record("back.scroll").expect("back wheel record");

        assert_eq!(trace.status, DebugFrameTraceStatus::Warning);
        assert_eq!(trace.scope, Some(front));
        assert_eq!(trace.scope_name.as_deref(), Some("front.panel"));
        assert_eq!(trace.target, None);
        assert_eq!(trace.consumed_by, Some(front));
        assert!(trace.summary.contains("wheel route"));
        assert!(trace.cause.contains("consumed"));
        assert_eq!(front_record.status, DebugFrameTraceStatus::Warning);
        assert!(front_record.blocks_wheel);
        assert!(front_record.fix.contains("passthrough"));
        assert!(back_record.scrollable);
        assert!(!back_record.in_scope);
        assert!(back_record
            .cause
            .contains("outside the topmost wheel scope"));
    }

