        let mut after_doc = UiDocument::new(fixed_style(200.0, 120.0));
        after_doc.add_child(
            after_doc.root,
            UiNode::container("added", fixed_style(40.0, 20.0)).with_input(InputBehavior::BUTTON),
        );
        after_doc
            .compute_layout(UiSize::new(200.0, 120.0), &mut ApproxTextMeasurer)
            .expect("after layout");
