    #[test]
    fn debug_layout_movement_trace_explains_resizes_and_flow_movement() {
        fn snapshot(preview_height: f32) -> DebugInspectorSnapshot {
            let mut doc = UiDocument::new(fixed_style(220.0, 140.0));
            let stack = doc.add_child(
                doc.root,
                UiNode::container(
                    "stack",
                    LayoutStyle::column()
                        .with_width(140.0)
                        .with_height(120.0)
                        .gap(4.0),
                ),
            );
            doc.add_child(
                stack,
                UiNode::container("preview", LayoutStyle::size(90.0, preview_height)),
            );
            doc.add_child(
                stack,
                UiNode::container("label", LayoutStyle::size(80.0, 18.0)),
            );
            doc.compute_layout(UiSize::new(220.0, 140.0), &mut ApproxTextMeasurer)
                .expect("layout");
            DebugInspectorSnapshot::from_document(&doc, &mut ApproxTextMeasurer)
        }

        let before = snapshot(20.0);
        let after = snapshot(44.0);

        let trace = DebugLayoutMovementTrace::from_snapshots(&before, &after);
        let preview = trace.record("preview").expect("preview movement");
        let label = trace.record("label").expect("label movement");

        assert_eq!(trace.status, DebugFrameTraceStatus::Info);
        assert_eq!(trace.resized_count, 1);
        assert!(trace.moved_count >= 1);
        assert!(trace.summary.contains("layout movement"));
        assert!(preview.kinds.contains(&DebugLayoutMovementKind::Resized));
        assert!(preview.cause.contains("style inputs changed"));
        assert!(label.kinds.contains(&DebugLayoutMovementKind::Moved));
        assert!(label
            .kinds
            .contains(&DebugLayoutMovementKind::SiblingChanged));
        assert!(label.cause.contains("previous sibling preview"));
    }

    #[test]
    fn debug_layout_jank_timeline_ranks_recurring_movement() {
        fn frame(preview_height: f32, frame_index: u64) -> DebugFrameTrace {
            let mut doc = UiDocument::new(fixed_style(220.0, 140.0));
            let stack = doc.add_child(
                doc.root,
                UiNode::container(
                    "stack",
                    LayoutStyle::column()
                        .with_width(140.0)
                        .with_height(120.0)
                        .gap(4.0),
                ),
            );
            doc.add_child(
                stack,
                UiNode::container("preview", LayoutStyle::size(90.0, preview_height)),
            );
            doc.add_child(
                stack,
                UiNode::container("label", LayoutStyle::size(80.0, 18.0)),
            );
            doc.compute_layout(UiSize::new(220.0, 140.0), &mut ApproxTextMeasurer)
                .expect("layout");
            DebugFrameTrace::from_document(
                &doc,
                &mut ApproxTextMeasurer,
                DebugFrameTraceContext::new("jank", UiSize::new(220.0, 140.0))
                    .frame_index(frame_index),
            )
        }

        let first = frame(20.0, 1);
        let second = frame(44.0, 2);
        let third = frame(28.0, 3);
        let timeline = DebugLayoutJankTimelineTrace::from_traces([&first, &second, &third]);
        let preview = timeline.record("preview").expect("preview jank");
        let label = timeline.record("label").expect("label jank");
        let third_frame = timeline.frame("jank #3").expect("third frame jank");

        assert_eq!(timeline.frame_count, 3);
        assert_eq!(timeline.comparison_count, 2);
        assert_eq!(timeline.movement_frame_count, 2);
        assert!(timeline.node_count >= 2);
        assert!(timeline.movement_count >= 4);
        assert!(timeline.resized_count >= 2);
        assert!(timeline.moved_count >= 2);
        assert!(timeline.total_distance > 0.0);
        assert!(timeline.summary.contains("layout jank timeline"));
        assert!(preview.resized_count >= 2);
        assert!(preview.summary.contains("preview"));
        assert!(preview.fix.contains("style") || preview.fix.contains("layout"));
        assert!(label.moved_count >= 2);
        assert!(label
            .kinds
            .contains(&DebugLayoutMovementKind::SiblingChanged));
        assert!(third_frame.summary.contains("layout jank"));
        assert!(third_frame.top_node.is_some());
    }

