    #[test]
    fn debug_constraint_timeline_tracks_new_and_resolved_issues() {
        let mut clean_doc = UiDocument::new(fixed_style(220.0, 120.0));
        clean_doc.add_child(
            clean_doc.root,
            UiNode::container("back", absolute_style_at(0.0, 0.0, 0.0, 72.0, 32.0))
                .with_input(InputBehavior::BUTTON)
                .with_action("back.activate")
                .with_accessibility(
                    AccessibilityMeta::new(AccessibilityRole::Button)
                        .label("Back")
                        .focusable()
                        .action(AccessibilityAction::new("activate", "Activate")),
                )
                .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 4.0)),
        );
        clean_doc.add_child(
            clean_doc.root,
            UiNode::container("front", absolute_style_at(120.0, 0.0, 8.0, 72.0, 32.0))
                .with_input(InputBehavior::BUTTON)
                .with_action("front.activate")
                .with_accessibility(
                    AccessibilityMeta::new(AccessibilityRole::Button)
                        .label("Front")
                        .focusable()
                        .action(AccessibilityAction::new("activate", "Activate")),
                )
                .with_visual(UiVisual::panel(ColorRgba::new(140, 80, 30, 255), None, 4.0)),
        );
        clean_doc
            .compute_layout(UiSize::new(220.0, 120.0), &mut ApproxTextMeasurer)
            .expect("clean layout");
        let clean = DebugFrameTrace::from_document(
            &clean_doc,
            &mut ApproxTextMeasurer,
            DebugFrameTraceContext::new("constraints", UiSize::new(220.0, 120.0)).frame_index(1),
        );

        let mut bad_doc = UiDocument::new(fixed_style(220.0, 120.0));
        bad_doc.add_child(
            bad_doc.root,
            UiNode::container("back", absolute_style_at(0.0, 0.0, 0.0, 72.0, 32.0))
                .with_input(InputBehavior::BUTTON)
                .with_action("back.activate")
                .with_accessibility(
                    AccessibilityMeta::new(AccessibilityRole::Button)
                        .label("Back")
                        .focusable()
                        .action(AccessibilityAction::new("activate", "Activate")),
                )
                .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 4.0)),
        );
        bad_doc.add_child(
            bad_doc.root,
            UiNode::container("front", absolute_style_at(24.0, 4.0, 8.0, 72.0, 32.0))
                .with_input(InputBehavior::BUTTON)
                .with_action("front.activate")
                .with_accessibility(
                    AccessibilityMeta::new(AccessibilityRole::Button)
                        .label("Front")
                        .focusable()
                        .action(AccessibilityAction::new("activate", "Activate")),
                )
                .with_visual(UiVisual::panel(ColorRgba::new(140, 80, 30, 255), None, 4.0)),
        );
        bad_doc
            .compute_layout(UiSize::new(220.0, 120.0), &mut ApproxTextMeasurer)
            .expect("bad layout");
        let bad = DebugFrameTrace::from_document(
            &bad_doc,
            &mut ApproxTextMeasurer,
            DebugFrameTraceContext::new("constraints", UiSize::new(220.0, 120.0)).frame_index(2),
        );

        let restored = DebugFrameTrace::from_document(
            &clean_doc,
            &mut ApproxTextMeasurer,
            DebugFrameTraceContext::new("constraints", UiSize::new(220.0, 120.0)).frame_index(3),
        );

        let timeline = DebugConstraintTimelineTrace::from_traces([&clean, &bad, &restored]);
        let bad_record = timeline.record("constraints #2").expect("bad frame");
        let restored_record = timeline.record("constraints #3").expect("restored frame");

        assert!(matches!(
            timeline.status,
            DebugFrameTraceStatus::Warning | DebugFrameTraceStatus::Error
        ));
        assert_eq!(timeline.frame_count, 3);
        assert!(timeline.issue_frame_count >= 1);
        assert!(timeline.changed_frame_count >= 2);
        assert!(timeline.new_issue_count >= 1);
        assert!(timeline.resolved_issue_count >= 1);
        assert!(timeline.summary.contains("constraint timeline"));
        assert!(bad_record.new_issue_count >= 1);
        assert!(bad_record.top_kind.is_some());
        assert!(bad_record.summary.contains("new"));
        assert!(restored_record.resolved_issue_count >= 1);
        assert!(restored_record.fix.contains("known-good"));

        let mut recorder = DebugFrameRecorder::new(4);
        recorder.record_frame(clean);
        recorder.record_frame(bad);
        recorder.record_frame(restored);
        assert_eq!(recorder.constraint_timeline().frame_count, 3);
    }

    #[test]
