    #[test]
    fn debug_visual_effect_timeline_tracks_new_and_resolved_effect_bounds() {
        fn frame(with_effect: bool, frame_index: u64) -> DebugFrameTrace {
            let mut doc = UiDocument::new(fixed_style(180.0, 120.0));
            let mut node =
                UiNode::container("glow", absolute_style_at(16.0, 16.0, 0.0, 56.0, 28.0))
                    .with_input(InputBehavior::BUTTON)
                    .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 4.0));
            if with_effect {
                node = node.with_material(
                    ElementMaterial::shader(ShaderEffect::glow(
                        ColorRgba::new(80, 180, 255, 255),
                        0.85,
                        6.0,
                    ))
                    .with_paint_outset(LayoutInsets::points(8.0))
                    .with_geometry_effect(GeometryEffect::wave(4.0)),
                );
            }
            doc.add_child(doc.root, node);
            doc.compute_layout(UiSize::new(180.0, 120.0), &mut ApproxTextMeasurer)
                .expect("layout");
            DebugFrameTrace::from_document(
                &doc,
                &mut ApproxTextMeasurer,
                DebugFrameTraceContext::new("effects", UiSize::new(180.0, 120.0))
                    .frame_index(frame_index),
            )
        }

        let clean = frame(false, 1);
        let glow = frame(true, 2);
        let restored = frame(false, 3);
        let trace = DebugVisualEffectTimelineTrace::from_traces([&clean, &glow, &restored]);
        let record = trace.record("glow").expect("glow timeline record");
        let effect_frame = trace.frame(1).expect("effect frame");
        let restored_frame = trace.frame(2).expect("restored frame");

        assert_eq!(trace.status, DebugFrameTraceStatus::Warning);
        assert_eq!(trace.frame_count, 3);
        assert_eq!(trace.effect_frame_count, 1);
        assert_eq!(trace.issue_frame_count, 1);
        assert_eq!(trace.new_issue_count, 1);
        assert_eq!(trace.resolved_issue_count, 1);
        assert_eq!(record.issue_frame_count, 1);
        assert_eq!(record.paint_outside_hit_frame_count, 1);
        assert_eq!(
            record.latest_shader_key.as_deref(),
            Some(ShaderEffect::GLOW)
        );
        assert!(record.max_declared_visual_outset >= 7.5);
        assert_eq!(effect_frame.new_issue_count, 1);
        assert_eq!(effect_frame.top_effect_name.as_deref(), Some("glow"));
        assert_eq!(restored_frame.resolved_issue_count, 1);

        let mut recorder = DebugFrameRecorder::new(4);
        recorder.record_frame(clean);
        recorder.record_frame(glow);
        recorder.record_frame(restored);
        assert_eq!(recorder.visual_effect_timeline().frame_count, 3);
    }

    #[test]
    fn debug_bounds_autopsy_separates_layout_paint_hit_and_effect_bounds() {
        let mut doc = UiDocument::new(fixed_style(180.0, 120.0));
        doc.add_child(
            doc.root,
            UiNode::container("glow", absolute_style_at(16.0, 16.0, 0.0, 56.0, 28.0))
                .with_input(InputBehavior::BUTTON)
                .with_material(
                    ElementMaterial::shader(ShaderEffect::glow(
                        ColorRgba::new(80, 180, 255, 255),
                        0.85,
                        6.0,
                    ))
                    .with_paint_outset(LayoutInsets::points(8.0))
                    .with_geometry_effect(GeometryEffect::wave(4.0)),
                )
                .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 4.0)),
        );
        doc.compute_layout(UiSize::new(180.0, 120.0), &mut ApproxTextMeasurer)
            .expect("layout");
        let snapshot = DebugInspectorSnapshot::from_document(&doc, &mut ApproxTextMeasurer);

        let trace = DebugBoundsAutopsyTrace::from_snapshot(&snapshot, Some("glow"))
            .expect("bounds autopsy");
        let paint = trace
            .record(DebugBoundsAutopsySource::Paint)
            .expect("paint bounds row");
        let hit = trace
            .record(DebugBoundsAutopsySource::Hit)
            .expect("hit bounds row");
        let effect = trace
            .record(DebugBoundsAutopsySource::EffectOutset)
            .expect("effect bounds row");

        assert_eq!(trace.name, "glow");
        assert_eq!(trace.status, DebugFrameTraceStatus::Warning);
        assert_eq!(trace.layout_rect, UiRect::new(16.0, 16.0, 56.0, 28.0));
        assert!(trace.paint_rect.is_some());
        assert!(trace.hit_rect.is_some());
        assert!(trace.declared_visual_outset >= 7.5);
        assert!(trace.measured_paint_outset.left >= 7.5);
        assert!(trace.summary.contains("bounds autopsy"));
        assert_eq!(paint.status, DebugFrameTraceStatus::Warning);
        assert!(paint.summary.contains("outside hit"));
        assert_eq!(hit.status, DebugFrameTraceStatus::Info);
        assert!(hit.summary.contains("pointer"));
        assert_eq!(effect.status, DebugFrameTraceStatus::Info);
        assert!(effect.summary.contains("declared"));
    }

