    #[test]
    fn debug_inspect_node_trace_combines_selected_node_evidence() {
        let mut style = TextStyle::default();
        style.font_size = 14.0;
        style.line_height = 16.0;
        style.wrap = TextWrap::None;
        let mut doc = UiDocument::new(fixed_style(220.0, 140.0));
        let target = doc.add_child(
            doc.root,
            UiNode::container("target", absolute_style_at(0.0, 0.0, 0.0, 90.0, 40.0))
                .with_input(InputBehavior::BUTTON)
                .with_action("target.activate")
                .with_visual(UiVisual::panel(ColorRgba::new(30, 90, 150, 255), None, 0.0)),
        );
        doc.add_child(
            target,
            UiNode::text(
                "target.label",
                "A very long debug label",
                style,
                LayoutStyle::size(48.0, 16.0),
            ),
        );
        doc.add_child(
            doc.root,
            UiNode::container("cover", absolute_style_at(10.0, 0.0, 8.0, 90.0, 40.0))
                .with_input(InputBehavior::BUTTON)
                .with_action("cover.activate")
                .with_visual(UiVisual::panel(ColorRgba::new(180, 40, 40, 255), None, 0.0)),
        );
        doc.compute_layout(UiSize::new(220.0, 140.0), &mut ApproxTextMeasurer)
            .expect("layout");
        let snapshot = DebugInspectorSnapshot::from_document(&doc, &mut ApproxTextMeasurer);
        let route = DebugEventRouteTrace::pointer_down(&doc, UiPoint::new(12.0, 10.0));
        let slow_nodes = DebugSlowNodeTrace::from_document(&doc, &mut ApproxTextMeasurer);
        let text_fit = DebugTextFitTrace::from_document(&doc, &mut ApproxTextMeasurer);

        let inspect = DebugInspectNodeTrace::from_context_with_traces(
            &snapshot,
            Some("target"),
            Some(&route),
            None,
            Some(&slow_nodes),
            Some(&text_fit),
        )
        .expect("inspect node trace");
        let label_inspect = DebugInspectNodeTrace::from_context_with_traces(
            &snapshot,
            Some("target.label"),
            Some(&route),
            None,
            Some(&slow_nodes),
            Some(&text_fit),
        )
        .expect("inspect label trace");
        let next = inspect
            .record(DebugInspectNodeSource::NextStep)
            .expect("next step record");

        assert_eq!(inspect.selected, target);
        assert_eq!(inspect.selected_name, "target");
        assert_eq!(inspect.status, DebugFrameTraceStatus::Warning);
        assert!(inspect.summary.contains("inspect node"));
        assert!(inspect
            .record(DebugInspectNodeSource::Explanation)
            .is_some());
        assert!(inspect.record(DebugInspectNodeSource::Visibility).is_some());
        assert!(inspect.record(DebugInspectNodeSource::Bounds).is_some());
        assert!(inspect.record(DebugInspectNodeSource::Layout).is_some());
        assert!(inspect.record(DebugInspectNodeSource::Clip).is_some());
        assert!(inspect.record(DebugInspectNodeSource::Hitbox).is_some());
        assert!(inspect.record(DebugInspectNodeSource::PaintHit).is_some());
        assert!(inspect.record(DebugInspectNodeSource::Overlap).is_some());
        assert!(inspect.record(DebugInspectNodeSource::TextFit).is_some());
        assert!(inspect.record(DebugInspectNodeSource::Provenance).is_some());
        assert!(inspect
            .record(DebugInspectNodeSource::Performance)
            .is_some());
        assert!(inspect.hitbox.is_some());
        assert!(!inspect.overlaps.is_empty());
        assert!(label_inspect.text_fit.is_some());
        assert_eq!(
            label_inspect
                .record(DebugInspectNodeSource::TextFit)
                .expect("text fit row")
                .status,
            DebugFrameTraceStatus::Warning
        );
        assert!(inspect
            .bounds
            .as_ref()
            .is_some_and(|trace| trace.name == "target"));
        assert!(inspect
            .layout
            .as_ref()
            .is_some_and(|trace| trace.selected_name == "target"));
        assert!(inspect
            .provenance
            .as_ref()
            .is_some_and(|trace| trace.name == "target"));
        assert!(inspect.slow_node.is_some());
        assert_eq!(next.status, DebugFrameTraceStatus::Warning);
        assert!(!next.fix.is_empty());

        let why = DebugWhyTrace::from_inspect_node(&inspect);
        let why_node = why
            .record(DebugWhySource::InspectNode)
            .expect("inspect-node why record");
        assert_eq!(why.scope, DebugWhyScope::Node);
        assert_eq!(why.subject, "target");
        assert_eq!(why.status, DebugFrameTraceStatus::Warning);
        assert_eq!(why_node.node_name.as_deref(), Some("target"));
        assert!(!why_node.panel.is_empty());
        let first_step = why.first_step().expect("node why step");
        let overlay_plan = why.overlay_plan();
        assert_eq!(first_step.scope, DebugWhyScope::Node);
        assert_eq!(first_step.subject, "target");
        assert!(first_step
            .overlays
            .iter()
            .any(|layer| matches!(layer, DebugWhyOverlayLayer::LayoutBounds)));
        assert!(overlay_plan
            .record(DebugWhyOverlayLayer::LayoutBounds)
            .is_some());
        assert!(why.step(&first_step.action).is_some());
    }

    #[test]
    fn debug_frame_trace_packages_timing_dirty_route_resources_and_selected_node() {
        let mut doc = UiDocument::new(fixed_style(160.0, 100.0));
        doc.add_child(
            doc.root,
            UiNode::image(
                "target",
                crate::ImageContent::app("diagnostics.missing"),
                absolute_layout_at(0.0, 0.0, 4.0, 4.0),
            )
            .with_input(InputBehavior::BUTTON)
            .with_action("target.activate"),
        );
        doc.add_child(
            doc.root,
            UiNode::container("cover", absolute_style_at(0.0, 0.0, 8.0, 40.0, 24.0))
                .with_input(InputBehavior::BUTTON)
                .with_action("cover.activate")
                .with_visual(UiVisual::panel(ColorRgba::new(180, 40, 40, 255), None, 0.0)),
        );
        doc.compute_layout(UiSize::new(160.0, 100.0), &mut ApproxTextMeasurer)
            .expect("layout");
        let route = DebugEventRouteTrace::pointer_down(&doc, UiPoint::new(2.0, 2.0));
        let resources = DebugResourceReport::from_paint_and_updates(&doc.paint_list(), &[]);
        let timing = FrameTiming::new()
            .section("layout", std::time::Duration::from_millis(4))
            .section("render", std::time::Duration::from_millis(19));

        let trace = DebugFrameTrace::from_document(
            &doc,
            &mut ApproxTextMeasurer,
            DebugFrameTraceContext::new("test-frame", UiSize::new(160.0, 100.0))
                .frame_index(7)
                .timing(timing)
                .timing_budget(std::time::Duration::from_millis(16))
                .dirty_flags(DirtyFlags {
                    layout: true,
                    input: true,
                    paint: true,
                    ..DirtyFlags::NONE
                })
                .route(route)
                .resources(resources)
                .selected_node("target"),
        );

        assert_eq!(trace.label, "test-frame");
        assert_eq!(trace.frame_index, Some(7));
        assert_eq!(trace.summary.status, DebugFrameTraceStatus::Warning);
        assert_eq!(trace.summary.route_count, 1);
        assert_eq!(trace.summary.selected_node.as_deref(), Some("target"));
        assert_eq!(trace.summary.slowest_stage.as_deref(), Some("backend-draw"));
        assert_eq!(trace.summary.over_budget, Some(true));
        assert!(trace.selected_node.is_some());
        assert!(trace.resources.missing_count() >= 1);
        assert!(trace
            .dirty
            .recompute_order
            .contains(&crate::diagnostics::DirtyStateSubsystem::Layout));
    }

    #[test]
    fn debug_frame_timeline_trace_ranks_slow_frames() {
        let mut doc = UiDocument::new(fixed_style(160.0, 100.0));
        doc.add_child(
            doc.root,
            UiNode::container("target", fixed_style(80.0, 32.0)).with_visual(UiVisual::panel(
                ColorRgba::new(20, 80, 140, 255),
                None,
                0.0,
            )),
        );
        doc.compute_layout(UiSize::new(160.0, 100.0), &mut ApproxTextMeasurer)
            .expect("layout");
        let clean = DebugFrameTrace::from_document(
            &doc,
            &mut ApproxTextMeasurer,
            DebugFrameTraceContext::new("timeline", UiSize::new(160.0, 100.0))
                .frame_index(1)
                .timing(
                    FrameTiming::new()
                        .section("layout", std::time::Duration::from_millis(2))
                        .section("render", std::time::Duration::from_millis(4)),
                )
                .timing_budget(std::time::Duration::from_millis(16)),
        );
        let mut slow_doc = UiDocument::new(fixed_style(160.0, 100.0));
        slow_doc.add_child(
            slow_doc.root,
            UiNode::container("target", fixed_style(120.0, 36.0)).with_visual(UiVisual::panel(
                ColorRgba::new(20, 80, 140, 255),
                None,
                0.0,
            )),
        );
        slow_doc
            .compute_layout(UiSize::new(160.0, 100.0), &mut ApproxTextMeasurer)
            .expect("slow layout");
        let slow = DebugFrameTrace::from_document(
            &slow_doc,
            &mut ApproxTextMeasurer,
            DebugFrameTraceContext::new("timeline", UiSize::new(160.0, 100.0))
                .frame_index(2)
                .timing(
                    FrameTiming::new()
                        .section("layout", std::time::Duration::from_millis(6))
                        .section("render", std::time::Duration::from_millis(18)),
                )
                .timing_budget(std::time::Duration::from_millis(16))
                .dirty_flags(DirtyFlags {
                    layout: true,
                    paint: true,
                    ..DirtyFlags::NONE
                }),
        );

        let timeline = DebugFrameTimelineTrace::from_traces([&clean, &slow]);
        let why_timeline = DebugWhyTimelineTrace::from_traces([&clean, &slow]);

        assert_eq!(timeline.status, DebugFrameTraceStatus::Warning);
        assert_eq!(timeline.frame_count, 2);
        assert_eq!(timeline.slow_frame_count, 1);
        assert_eq!(timeline.max_duration_label.as_deref(), Some("timeline #2"));
        assert!(timeline.summary.contains("frame timeline"));
        assert_eq!(timeline.records[0].frame_index, Some(2));
        assert_eq!(timeline.records[0].status, DebugFrameTraceStatus::Warning);
        assert_eq!(
            timeline.records[0].over_budget_by,
            Some(std::time::Duration::from_millis(8))
        );
        let change = timeline.records[0]
            .previous_change
            .as_ref()
            .expect("slow frame change summary");
        assert_eq!(change.changed_node_count, 1);
        assert_eq!(change.layout_change_count, 1);
        assert!(timeline.records[0].summary.contains("changed nodes"));
        assert!(timeline.records[0].cause.contains("after 1 changed nodes"));
        assert_eq!(
            timeline.record("timeline #1").map(|record| record.status),
            Some(DebugFrameTraceStatus::Info)
        );
        assert!(matches!(
            why_timeline.status,
            DebugFrameTraceStatus::Warning | DebugFrameTraceStatus::Error
        ));
        assert_eq!(why_timeline.frame_count, 2);
        assert!(why_timeline.warning_frame_count >= 1);
        assert!(why_timeline.why_record_count > 0);
        assert!(why_timeline.overlay_layer_count > 0);
        assert!(why_timeline.summary.contains("why timeline"));
        let why_record = why_timeline
            .record("timeline #2")
            .expect("slow frame why row");
        assert_eq!(why_record.frame_index, Some(2));
        assert!(why_record.top_panel.is_some());
        assert!(why_record.primary_overlay.is_some());
        assert!(why_record.primary_surface.is_some());
    }

