    #[test]
    fn debug_frame_budget_trace_ranks_over_budget_stages_and_dirty_causes() {
        let timing = FrameTiming::new()
            .section("layout", std::time::Duration::from_millis(5))
            .section("render", std::time::Duration::from_millis(18))
            .section("gpu-render", std::time::Duration::from_millis(3));
        let invalidations = [
            crate::runtime::RuntimeInvalidation::new(
                crate::runtime::RuntimeInvalidationReason::Resize,
            )
            .detail("viewport"),
            crate::runtime::RuntimeInvalidation::new(
                crate::runtime::RuntimeInvalidationReason::Resource,
            )
            .detail("atlas"),
        ];
        let dirty = DirtyStateExplanation::from_invalidations(&invalidations);

        let trace = DebugFrameBudgetTrace::from_frame_timing(
            &timing,
            Some(std::time::Duration::from_millis(16)),
            dirty,
        );

        assert_eq!(trace.status, DebugFrameTraceStatus::Warning);
        assert_eq!(
            trace.over_budget_by,
            Some(std::time::Duration::from_millis(10))
        );
        assert_eq!(trace.slowest_stage.as_deref(), Some("backend-draw"));
        assert_eq!(
            trace.primary_dirty_cause.as_deref(),
            Some("Window resize: viewport")
        );
        assert_eq!(trace.stages[0].label, "backend-draw");
        assert!(trace.stages[0].dominant);
        assert!(trace.stages[0].over_budget);
        assert!(trace.stages[0]
            .action
            .contains("paint stack, shader outsets"));
        assert!(trace
            .stages
            .iter()
            .any(|stage| stage.label == "layout" && stage.cause.contains("layout was dirty")));
        assert!(trace.summary.contains("over by 10.00ms"));
    }

