    #[test]
    fn debug_invalidation_blast_trace_pivots_dirty_work_by_subsystem() {
        let invalidations = [
            crate::runtime::RuntimeInvalidation::new(
                crate::runtime::RuntimeInvalidationReason::Input,
            )
            .detail("pointer moved"),
            crate::runtime::RuntimeInvalidation::new(
                crate::runtime::RuntimeInvalidationReason::Resize,
            )
            .detail("viewport"),
            crate::runtime::RuntimeInvalidation::new(
                crate::runtime::RuntimeInvalidationReason::Resource,
            )
            .detail("atlas"),
        ];
        let dirty = DirtyStateExplanation::from_invalidations(&invalidations);

        let trace = DebugInvalidationBlastTrace::from_dirty_state(&dirty);
        let layout = trace
            .record(DirtyStateSubsystem::Layout)
            .expect("layout blast record");
        let paint = trace
            .record(DirtyStateSubsystem::Paint)
            .expect("paint blast record");

        assert_eq!(trace.status, DebugFrameTraceStatus::Warning);
        assert_eq!(trace.invalidation_count, 3);
        assert!(trace.summary.contains("invalidation blast radius"));
        assert!(trace.active_subsystem_count >= 4);
        assert!(trace.max_score >= layout.score);
        assert_eq!(layout.status, DebugFrameTraceStatus::Warning);
        assert_eq!(layout.trigger_count, 1);
        assert_eq!(layout.broad_trigger_count, 1);
        assert!(layout
            .trigger_labels
            .iter()
            .any(|label| label.contains("viewport")));
        assert!(layout
            .recompute_steps
            .iter()
            .any(|step| step.contains("layout")));
        assert!(layout.downstream.iter().any(|step| step.contains("paint")));
        assert!(layout.fix.contains("broad") || layout.fix.contains("layout"));
        assert!(paint.trigger_count >= 3);
        assert!(paint.summary.contains("Paint"));
    }

    #[test]
    fn debug_invalidation_timeline_tracks_recurring_dirty_reasons() {
        let first_invalidations = [
            crate::runtime::RuntimeInvalidation::new(
                crate::runtime::RuntimeInvalidationReason::Resize,
            )
            .detail("viewport"),
            crate::runtime::RuntimeInvalidation::new(
                crate::runtime::RuntimeInvalidationReason::Input,
            )
            .detail("pointer moved"),
        ];
        let second_invalidations = [
            crate::runtime::RuntimeInvalidation::new(
                crate::runtime::RuntimeInvalidationReason::Resize,
            )
            .detail("viewport"),
            crate::runtime::RuntimeInvalidation::new(
                crate::runtime::RuntimeInvalidationReason::Resource,
            )
            .detail("atlas"),
        ];
        let third_invalidations = [
            crate::runtime::RuntimeInvalidation::new(
                crate::runtime::RuntimeInvalidationReason::Animation,
            )
            .detail("hover glow"),
            crate::runtime::RuntimeInvalidation::new(
                crate::runtime::RuntimeInvalidationReason::Resource,
            )
            .detail("atlas"),
        ];
        let first = DirtyStateExplanation::from_invalidations(&first_invalidations);
        let second = DirtyStateExplanation::from_invalidations(&second_invalidations);
        let third = DirtyStateExplanation::from_invalidations(&third_invalidations);

        let trace = DebugInvalidationTimelineTrace::from_dirty_states([
            ("dirty #1", Some(1), &first),
            ("dirty #2", Some(2), &second),
            ("dirty #3", Some(3), &third),
        ]);
        let resize = trace
            .record(crate::runtime::RuntimeInvalidationReason::Resize)
            .expect("resize timeline record");
        let second_frame = trace.frame("dirty #2").expect("second frame record");

        assert_eq!(trace.status, DebugFrameTraceStatus::Warning);
        assert_eq!(trace.frame_count, 3);
        assert_eq!(trace.invalidation_count, 6);
        assert_eq!(
            trace.top_reason,
            Some(crate::runtime::RuntimeInvalidationReason::Resize)
        );
        assert!(trace.summary.contains("invalidation timeline"));
        assert_eq!(resize.frame_count, 2);
        assert_eq!(resize.invalidation_count, 2);
        assert_eq!(resize.broad_count, 2);
        assert_eq!(resize.latest_frame_label.as_deref(), Some("dirty #2"));
        assert!(resize.details.iter().any(|detail| detail == "viewport"));
        assert!(resize
            .subsystems
            .contains(&DirtyStateSubsystem::TextMeasurement));
        assert_eq!(
            second_frame.top_reason,
            Some(crate::runtime::RuntimeInvalidationReason::Resize)
        );
        assert_eq!(second_frame.broad_count, 1);

        let mut doc = UiDocument::new(fixed_style(120.0, 80.0));
        doc.compute_layout(UiSize::new(120.0, 80.0), &mut ApproxTextMeasurer)
            .expect("timeline document layout");
        let mut recorder = DebugFrameRecorder::new(2);
        recorder.record_document(
            &doc,
            &mut ApproxTextMeasurer,
            DebugFrameTraceContext::new("recorded", UiSize::new(120.0, 80.0))
                .frame_index(9)
                .invalidations(&second_invalidations),
        );
        let recorded = recorder.invalidation_timeline();
        assert_eq!(recorded.frame_count, 1);
        assert_eq!(recorded.invalidation_count, 2);
        assert!(
            recorded
                .record(crate::runtime::RuntimeInvalidationReason::Resize)
                .is_some(),
            "recorder timeline should preserve context invalidation causes"
        );
    }

    #[test]
    fn debug_cache_reuse_trace_explains_cache_misses_and_display_list_reuse() {
        let performance = crate::diagnostics::PerformanceSnapshot::new(9)
            .cache(
                crate::diagnostics::CacheDiagnostic::new("layout")
                    .lookup(true)
                    .lookup(false)
                    .lookup(false),
            )
            .cache(crate::diagnostics::CacheDiagnostic::new("shaped-text").lookup(true))
            .cache(crate::diagnostics::CacheDiagnostic::new("image").lookup(true))
            .cache(crate::diagnostics::CacheDiagnostic::new("canvas-texture").lookup(true))
            .cache(
                crate::diagnostics::CacheDiagnostic::new("display-list")
                    .lookup(true)
                    .lookup(false)
                    .eviction(),
            );
        let reports = [
            crate::display::DisplayListReuseReport {
                key: crate::display::DisplayListKey::editor_background("main", 1),
                outcome: crate::display::DisplayListReuseOutcome::Reused,
                dirty_flags: DirtyFlags::NONE,
                frame: 9,
                kind: Some(crate::display::DisplayListKind::StaticBackground),
                invalidation: Some(
                    crate::display::DisplayListInvalidation::STATIC_EDITOR_BACKGROUND,
                ),
                item_count: Some(4),
                created_frame: Some(4),
                last_used_frame: Some(8),
            },
            crate::display::DisplayListReuseReport {
                key: crate::display::DisplayListKey::node(UiNodeId(3), "panel", 2),
                outcome: crate::display::DisplayListReuseOutcome::MissDirty,
                dirty_flags: DirtyFlags {
                    paint: true,
                    ..DirtyFlags::NONE
                },
                frame: 9,
                kind: Some(crate::display::DisplayListKind::StaticPanel),
                invalidation: Some(crate::display::DisplayListInvalidation::STATIC_PANEL),
                item_count: Some(7),
                created_frame: Some(6),
                last_used_frame: Some(8),
            },
        ];

        let trace =
            DebugCacheReuseTrace::from_performance_and_display_lists(&performance, &reports);
        let layout = trace.record("layout").expect("layout cache record");

        assert_eq!(trace.status, DebugFrameTraceStatus::Warning);
        assert_eq!(trace.missing_required_count, 0);
        assert_eq!(trace.total_lookups, 8);
        assert_eq!(trace.total_hits, 5);
        assert_eq!(trace.total_misses, 3);
        assert_eq!(trace.total_evictions, 1);
        assert!(trace.summary.contains("cache reuse"));
        assert_eq!(layout.status, DebugFrameTraceStatus::Warning);
        assert!(layout.cause.contains("missed"));
        assert!(trace.display_lists.iter().any(|record| {
            record.outcome == crate::display::DisplayListReuseOutcome::MissDirty
                && record.cause.contains("dirty flags")
                && record.fix.contains("split static paint")
        }));
    }

