    #[test]
    fn debug_layout_cost_timeline_tracks_recurring_and_resolved_cost() {
        fn frame(with_cost: bool, frame_index: u64) -> DebugFrameTrace {
            let mut doc = UiDocument::new(fixed_style(220.0, 140.0));
            if with_cost {
                let list = doc.add_child(
                    doc.root,
                    UiNode::container(
                        "wrapped.list",
                        UiNodeStyle::from(
                            crate::layout::with_flex_wrap(LayoutStyle::row(), LayoutFlexWrap::Wrap)
                                .with_width(120.0)
                                .with_height(70.0)
                                .gap(4.0),
                        ),
                    )
                    .with_scroll(ScrollAxes::VERTICAL),
                );
                for index in 0..10 {
                    doc.add_child(
                        list,
                        UiNode::text(
                            format!("wrapped.label.{index}"),
                            format!("Label {index}"),
                            TextStyle::default(),
                            LayoutStyle::new().with_width(54.0).with_height(18.0),
                        ),
                    );
                }
            } else {
                doc.add_child(
                    doc.root,
                    UiNode::container("stable.panel", fixed_style(80.0, 32.0)),
                );
            }
            doc.compute_layout(UiSize::new(220.0, 140.0), &mut ApproxTextMeasurer)
                .expect("layout");
            DebugFrameTrace::from_document(
                &doc,
                &mut ApproxTextMeasurer,
                DebugFrameTraceContext::new("layout-cost", UiSize::new(220.0, 140.0))
                    .frame_index(frame_index),
            )
        }

        let clean = frame(false, 1);
        let costly = frame(true, 2);
        let restored = frame(false, 3);
        let trace = DebugLayoutCostTimelineTrace::from_traces([&clean, &costly, &restored]);

        assert_eq!(trace.frame_count, 3);
        assert!(trace.cost_frame_count >= 1);
        assert!(trace.cost_count >= 1);
        assert!(trace.max_score > 0);
        assert!(trace.new_cost_count >= 1);
        assert!(trace.resolved_cost_count >= 1);
        assert!(trace.summary.contains("layout cost timeline"));
        let list = trace
            .record("wrapped.list")
            .expect("wrapped list layout cost timeline");
        assert!(list.max_score >= 80);
        assert!(list.fix.contains("layout_cost_panel"));
        assert!(trace
            .frame(1)
            .is_some_and(|frame| frame.new_cost_count >= 1));
        assert!(trace
            .frame(2)
            .is_some_and(|frame| frame.resolved_cost_count >= 1));

        let mut recorder = DebugFrameRecorder::new(4);
        recorder.record_frame(clean);
        recorder.record_frame(costly);
        recorder.record_frame(restored);
        assert_eq!(recorder.layout_cost_timeline().frame_count, 3);
    }

    #[test]
    fn debug_layout_pressure_trace_ranks_overflow_constraints_and_overlaps() {
        let mut doc = UiDocument::new(fixed_style(220.0, 140.0));
        let viewport = doc.add_child(
            doc.root,
            UiNode::container("viewport", fixed_style(80.0, 40.0))
                .with_scroll(ScrollAxes::VERTICAL),
        );
        doc.add_child(
            viewport,
            UiNode::container(
                "content",
                UiNodeStyle::from(
                    LayoutStyle::new()
                        .with_width(60.0)
                        .with_height(96.0)
                        .with_flex_shrink(0.0),
                ),
            ),
        );
        doc.add_child(
            doc.root,
            UiNode::container("tiny", absolute_style_at(104.0, 0.0, 0.0, 4.0, 4.0))
                .with_input(InputBehavior::BUTTON),
        );
        doc.add_child(
            doc.root,
            UiNode::container("paint.back", absolute_style_at(0.0, 72.0, 0.0, 70.0, 32.0))
                .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0)),
        );
        doc.add_child(
            doc.root,
            UiNode::container(
                "paint.front",
                absolute_style_at(24.0, 72.0, 4.0, 70.0, 32.0),
            )
            .with_visual(UiVisual::panel(ColorRgba::new(180, 50, 40, 255), None, 0.0)),
        );
        doc.compute_layout(UiSize::new(220.0, 140.0), &mut ApproxTextMeasurer)
            .expect("layout");

        let trace = DebugLayoutPressureTrace::from_document(&doc, &mut ApproxTextMeasurer);
        let viewport = trace.record("viewport").expect("viewport pressure");
        let tiny = trace.record("tiny").expect("tiny pressure");
        let overlap = trace
            .records
            .iter()
            .find(|record| record.name.starts_with("paint.") && record.overlap_count > 0)
            .expect("paint overlap pressure");

        assert_eq!(trace.status, DebugFrameTraceStatus::Warning);
        assert!(trace.summary.contains("layout pressure"));
        assert!(trace.overflow_count >= 1);
        assert!(trace.constraint_count >= 1);
        assert!(trace.overlap_count >= 1);
        assert_eq!(viewport.kind, DebugLayoutPressureKind::ContentOverflow);
        assert!(viewport.content_overflow_y > 0.0);
        assert!(viewport.scroll_range_y > 0.0);
        assert_eq!(tiny.kind, DebugLayoutPressureKind::Constraint);
        assert!(tiny.constraint_count >= 1);
        assert_eq!(overlap.kind, DebugLayoutPressureKind::Overlap);
        assert!(overlap.cause.contains("overlaps"));
    }

