    #[test]
    fn debug_layout_cost_autopsy_explains_selected_subtree_pressure() {
        let mut doc = UiDocument::new(fixed_style(220.0, 140.0));
        let list = doc.add_child(
            doc.root,
            UiNode::container(
                "wrapped.list",
                UiNodeStyle::from(
                    crate::layout::with_flex_wrap(LayoutStyle::row(), LayoutFlexWrap::Wrap)
                        .with_width(120.0)
                        .with_height(70.0)
                        .gap(4.0),
                ),
            )
            .with_scroll(ScrollAxes::VERTICAL),
        );
        for index in 0..8 {
            doc.add_child(
                list,
                UiNode::text(
                    format!("wrapped.label.{index}"),
                    format!("Label {index}"),
                    TextStyle::default(),
                    LayoutStyle::new().with_width(54.0).with_height(18.0),
                ),
            );
        }
        doc.compute_layout(UiSize::new(220.0, 140.0), &mut ApproxTextMeasurer)
            .expect("layout");
        let snapshot = DebugInspectorSnapshot::from_document(&doc, &mut ApproxTextMeasurer);
        let trace = DebugLayoutCostTrace::from_snapshot(&snapshot);

        let autopsy =
            DebugLayoutCostAutopsyTrace::from_layout_cost_trace(&trace, Some("wrapped.list"))
                .expect("layout cost autopsy");
        let text = autopsy
            .record(DebugLayoutCostAutopsySource::TextMeasurement)
            .expect("text source");
        let wrapping = autopsy
            .record(DebugLayoutCostAutopsySource::Wrapping)
            .expect("wrapping source");
        let scroll = autopsy
            .record(DebugLayoutCostAutopsySource::ScrollOverflow)
            .expect("scroll source");

        assert_eq!(autopsy.name, "wrapped.list");
        assert_eq!(autopsy.status, DebugFrameTraceStatus::Warning);
        assert!(autopsy.total_score >= 80);
        assert!(autopsy.summary.contains("layout cost autopsy"));
        assert!(autopsy.warning_count >= 1);
        assert_eq!(text.status, DebugFrameTraceStatus::Warning);
        assert!(text.score > 0);
        assert!(text.count >= 8);
        assert!(text.summary.contains("text nodes"));
        assert_eq!(wrapping.count, 1);
        assert!(wrapping.summary.contains("wrapping flex"));
        assert!(scroll.count >= 1);
        assert!(scroll.summary.contains("scroll nodes"));
    }

