    #[test]
    fn debug_hitbox_map_trace_lists_interactive_passive_and_action_regions() {
        let mut doc = UiDocument::new(fixed_style(220.0, 140.0));
        doc.add_child(
            doc.root,
            UiNode::container("good", layered_absolute_style(0.0, 72.0, 32.0))
                .with_input(InputBehavior::BUTTON)
                .with_action("good.activate")
                .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0)),
        );
        let mut clip_style =
            UiNodeStyle::from(LayoutStyle::new().with_width(36.0).with_height(24.0));
        clip_style.set_clip(ClipBehavior::Clip);
        let clipper = doc.add_child(doc.root, UiNode::container("clipper", clip_style));
        doc.add_child(
            clipper,
            UiNode::container("clipped", absolute_style_at(0.0, 0.0, 0.0, 80.0, 24.0))
                .with_input(InputBehavior::BUTTON)
                .with_visual(UiVisual::panel(ColorRgba::new(180, 40, 40, 255), None, 0.0)),
        );
        doc.add_child(
            doc.root,
            UiNode::container("paint.only", absolute_style_at(96.0, 0.0, 0.0, 48.0, 24.0))
                .with_visual(UiVisual::panel(
                    ColorRgba::new(70, 100, 130, 255),
                    None,
                    0.0,
                )),
        );
        doc.compute_layout(UiSize::new(220.0, 140.0), &mut ApproxTextMeasurer)
            .expect("layout");

        let trace = DebugHitboxMapTrace::from_document(&doc);
        let good = trace.record("good").expect("good hitbox map row");
        let clipped = trace.record("clipped").expect("clipped hitbox map row");
        let paint = trace
            .record("paint.only")
            .expect("paint-only hitbox map row");

        assert_eq!(trace.status, DebugFrameTraceStatus::Warning);
        assert!(trace.summary.contains("hitbox map"));
        assert!(trace.node_count >= 4);
        assert_eq!(trace.action_count, 1);
        assert!(trace.interactive_count >= 2);
        assert!(trace.effective_hit_count >= 2);
        assert!(trace.clipped_count >= 1);
        assert!(trace.paint_only_count >= 1);
        assert_eq!(good.action.as_deref(), Some("action:good.activate"));
        assert_eq!(good.status, DebugFrameTraceStatus::Info);
        assert!(good.summary.contains("pointer"));
        assert_eq!(clipped.status, DebugFrameTraceStatus::Warning);
        assert!(clipped.clipped);
        assert!(clipped.fix.contains("clipping"));
        assert!(!paint.pointer);
        assert!(paint.has_paint);
        assert!(paint.summary.contains("passive"));
    }

    #[test]
    fn debug_hitbox_timeline_tracks_added_removed_and_occluded_hitboxes() {
        fn hitbox_frame(with_cover: bool, frame_index: u64) -> DebugFrameTrace {
            let mut doc = UiDocument::new(fixed_style(220.0, 140.0));
            doc.add_child(
                doc.root,
                UiNode::container("target", absolute_style_at(0.0, 0.0, 0.0, 88.0, 40.0))
                    .with_input(InputBehavior::BUTTON)
                    .with_action("target.activate")
                    .with_visual(UiVisual::panel(ColorRgba::new(20, 80, 140, 255), None, 0.0)),
            );
            if with_cover {
                doc.add_child(
                    doc.root,
                    UiNode::container("cover", absolute_style_at(12.0, 0.0, 12.0, 88.0, 40.0))
                        .with_input(InputBehavior::BUTTON)
                        .with_action("cover.activate")
                        .with_visual(UiVisual::panel(ColorRgba::new(180, 40, 40, 255), None, 0.0)),
                );
            }
            doc.compute_layout(UiSize::new(220.0, 140.0), &mut ApproxTextMeasurer)
                .expect("hitbox timeline layout");
            DebugFrameTrace::from_document(
                &doc,
                &mut ApproxTextMeasurer,
                DebugFrameTraceContext::new("hitbox", UiSize::new(220.0, 140.0))
                    .frame_index(frame_index)
                    .dirty_flags(DirtyFlags {
                        layout: true,
                        paint: true,
                        ..DirtyFlags::NONE
                    }),
            )
        }

        let clean = hitbox_frame(false, 1);
        let covered = hitbox_frame(true, 2);
        let restored = hitbox_frame(false, 3);

        let trace = DebugHitboxTimelineTrace::from_traces([&clean, &covered, &restored]);
        let covered_record = trace.record("hitbox #2").expect("covered hitbox frame");
        let restored_record = trace.record("hitbox #3").expect("restored hitbox frame");

        assert_eq!(trace.status, DebugFrameTraceStatus::Warning);
        assert_eq!(trace.frame_count, 3);
        assert_eq!(trace.issue_frame_count, 1);
        assert!(trace.changed_frame_count >= 2);
        assert_eq!(trace.occluded_count, 1);
        assert_eq!(trace.added_hitbox_count, 1);
        assert_eq!(trace.removed_hitbox_count, 1);
        assert!(trace.summary.contains("hitbox timeline"));
        assert_eq!(covered_record.status, DebugFrameTraceStatus::Warning);
        assert_eq!(covered_record.added_hitbox_count, 1);
        assert_eq!(covered_record.occluded_count, 1);
        assert_eq!(covered_record.top_issue_name.as_deref(), Some("target"));
        assert!(covered_record.fix.contains("hitbox_occlusion_panel"));
        assert_eq!(restored_record.removed_hitbox_count, 1);
        assert!(restored_record.fix.contains("frame_timeline_panel"));
    }

