        doc.compute_layout(UiSize::new(260.0, 160.0), &mut ApproxTextMeasurer)
            .expect("layout");

        let trace = DebugInvariantTrace::from_document(&doc, &mut ApproxTextMeasurer);

        assert_eq!(trace.invariant_count, 5);
